(window.SB_FULLC=window.SB_FULLC||{})["nona"]={c:"[{\"w\":\"nonchalant\",\"d\":\"is coolly unconcerned unexcited\",\"p\":\"n-ah-n-sh-uh-l-AH-n-t\",\"o\":\"French\",\"y\":6,\"bp\":70,\"m\":\"nonchalent\",\"nt\":\"Advanced\",\"ps\":\"adjective\",\"t\":[\"ofrench\"]},{\"w\":\"nondescript\",\"d\":\"lacking distinguishing characteristics or a distinctive character\",\"s\":\"Women dressed in nondescript clothes.\",\"p\":\"n-AH-n-d-ih-s-k-r-IH-p-t\",\"o\":\"Latin\",\"y\":5,\"bp\":45,\"m\":\"nondiscript\",\"nt\":\"Primary\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonchalance\",\"d\":\"the trait of remaining calm and seeming not to care; a casual lack of concern\",\"s\":\"With remarkable nonchalance, the experienced surgeon walked into the operating room as if it were just another ordinary Tuesday.\",\"p\":\"nah-nshuh-LAHNS\",\"o\":\"French\",\"y\":8,\"bp\":34,\"m\":\"nonchalanse\",\"sy\":\"non.cha.lance\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"ofrench\"]},{\"w\":\"nonage\",\"d\":\"any age prior to the legal age\",\"s\":\"During his nonage, the prince could not make any official decisions for the kingdom without the advice of the royal council.\",\"p\":\"NON-ij\",\"o\":\"Latin\",\"y\":8,\"bp\":63,\"m\":\"nonnage\",\"sy\":\"non.age\",\"nt\":\"Senior\",\"ps\":\"noun\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"nonce\",\"d\":\"the present occasion\",\"s\":\"The teacher created a nonce word specifically for the grammar lesson, explaining that it existed only for the nonce and would not appear in any dictionary the students might search later.\",\"p\":\"NAHNS\",\"o\":\"Middle English\",\"y\":5,\"bp\":23,\"m\":\"nonse\",\"sy\":\"naa.ns\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"ooldeng\"]},{\"w\":\"nonalcoholic\",\"d\":\"characterized by the absence of alcohol\",\"p\":\"nah-na-lkuh-HAH-lihk\",\"o\":\"Latin\",\"y\":6,\"bp\":38,\"m\":\"nonalcohlic\",\"sy\":\"naa.nae.lkah.hhaa.lih.k\",\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"food\",\"drink\",\"olatin\"]},{\"w\":\"nonchalantly\",\"d\":\"in a composed and unconcerned manner\",\"p\":\"nah-nshuh-LAH-ntlee\",\"o\":\"French\",\"y\":7,\"bp\":37,\"m\":\"nonchalently\",\"sy\":\"naa.nshah.laa.ntliy\",\"nt\":\"Open\",\"ps\":\"adverb\",\"t\":[\"ofrench\"]},{\"w\":\"noncommittal\",\"d\":\"refusing to bind oneself to a particular course of action or view or the like\",\"s\":\"Her boyfriend was noncommittal about their future together.\",\"p\":\"nah-nkuh-MIH-tuhl\",\"o\":\"Latin\",\"y\":7,\"bp\":37,\"m\":\"noncommital\",\"sy\":\"naa.nkah.mih.tah.l\",\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonaggression\",\"d\":\"a policy of not initiating hostilities\",\"s\":\"They signed a nonaggression pact.\",\"p\":\"nah-nuh-GREH-shuhn\",\"o\":\"French\",\"y\":7,\"bp\":37,\"m\":\"nonaggresion\",\"sy\":\"naa.nah.greh.shah.n\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"politics\",\"ofrench\"]},{\"w\":\"noncombatants\",\"d\":\"a member of the armed forces who does not participate in combat (e.g. a chaplain or surgeon)\",\"s\":\"International law requires that noncombatants, such as medics and civilians, be protected during armed conflicts.\",\"p\":\"nah-nkuh-MBA-tuhnts\",\"o\":\"Latin\",\"y\":7,\"bp\":37,\"m\":\"noncombattants\",\"sy\":\"naa.nkah.mbae.tah.nts\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"war\",\"military\",\"olatin\"]},{\"w\":\"noncommercial\",\"d\":\"not connected with or engaged in commercial enterprises\",\"s\":\"The documentary was produced by a noncommercial organization dedicated solely to raising environmental awareness.\",\"p\":\"nah-nkuh-MUR-shuhl\",\"o\":\"Latin\",\"y\":6,\"bp\":37,\"m\":\"noncomercial\",\"sy\":\"naa.nkah.mer.shah.l\",\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"noncompetitive\",\"d\":\"not involving competition or competitiveness\",\"p\":\"nah-nkuh-MPEH-tuh-tihv\",\"o\":\"Latin\",\"y\":8,\"bp\":40,\"m\":\"noncompetative\",\"sy\":\"naa.nkah.mpeh.tah.tih.v\",\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"sports\",\"olatin\"]},{\"w\":\"noncompliance\",\"d\":\"the failure to obey\",\"s\":\"The factory faced heavy fines for its noncompliance with the new safety regulations.\",\"p\":\"nah-nkuh-MPLEYE-uhns\",\"o\":\"Latin\",\"y\":7,\"bp\":37,\"m\":\"noncompliancy\",\"sy\":\"naa.nkah.mplay.ah.ns\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonconformist\",\"d\":\"a person who does not follow the usual ways of behaving or thinking\",\"s\":\"Their rabidly nonconformist deportment has made them legendary.\",\"p\":\"nah-nkuh-NFAW-rmihst\",\"o\":\"Latin\",\"y\":6,\"bp\":37,\"m\":\"nonconformest\",\"sy\":\"naa.nkah.nfao.rmih.st\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"religion\",\"olatin\"]},{\"w\":\"nonconformists\",\"d\":\"people who do not follow the usual ways of behaving or thinking\",\"s\":\"The small town was rattled when a group of nonconformists arrived and challenged every established tradition.\",\"p\":\"nah-nkuh-NFAW-rmuhsts\",\"o\":\"Latin\",\"y\":7,\"bp\":38,\"m\":\"nonconformests\",\"sy\":\"naa.nkah.nfao.rmah.sts\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"religion\",\"olatin\"]},{\"w\":\"nonconformity\",\"d\":\"lack of harmony or correspondence\",\"s\":\"Her bold fashion choices were a clear act of nonconformity in a school that prized uniformity above all else.\",\"p\":\"nah-nkuh-NFAW-rmuh-tee\",\"o\":\"Latin\",\"y\":6,\"bp\":39,\"m\":\"nonconformaty\",\"sy\":\"naa.nkah.nfao.rmah.tiy\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"noncontroversial\",\"d\":\"not likely to arouse controversy\",\"s\":\"The principal chose a noncontroversial topic for the school assembly so that every student could enjoy it.\",\"p\":\"nah-nkah-ntruh-VUR-shuhl\",\"o\":\"Latin\",\"y\":8,\"bp\":41,\"sy\":\"naa.nkaa.ntrah.ver.shah.l\",\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondeductible\",\"d\":\"not allowable as a deduction\",\"s\":\"Her accountant reminded her that the personal vacation expenses were nondeductible and could not lower her tax bill.\",\"p\":\"nah-ndih-DUH-ktih-buhl\",\"o\":\"Latin\",\"y\":8,\"bp\":39,\"m\":\"nondeductable\",\"sy\":\"naa.ndih.dah.ktih.bah.l\",\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncom\",\"d\":\"a military officer appointed from enlisted personnel\",\"s\":\"The experienced noncom kept the young soldiers calm during their first field exercise.\",\"p\":\"NON-kom\",\"o\":\"Latin\",\"y\":6,\"bp\":29,\"m\":\"noncomm\",\"sy\":\"non.com\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"war\",\"olatin\"]},{\"w\":\"nonages\",\"d\":\"any age prior to the legal age\",\"s\":\"During their nonages, neither of the heirs was permitted to manage the family estate.\",\"p\":\"NON-ih-jez\",\"o\":\"French\",\"y\":8,\"bp\":31,\"m\":\"nonnages\",\"sy\":\"non.ag.es\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"law\",\"ofrench\"]},{\"w\":\"nonagon\",\"d\":\"a nine-sided polygon\",\"s\":\"The art teacher challenged students to draw a perfect nonagon without a protractor.\",\"p\":\"NON-ah-gon\",\"o\":\"Latin\",\"y\":6,\"bp\":31,\"m\":\"nonogon\",\"sy\":\"non.a.gon\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonagons\",\"d\":\"a nine-sided polygon\",\"s\":\"The architect tiled the floor with colorful nonagons that fit together in a striking pattern.\",\"p\":\"NON-ah-gonz\",\"o\":\"Latin\",\"y\":8,\"bp\":32,\"m\":\"nonogons\",\"sy\":\"non.a.gons\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonbeing\",\"d\":\"the state of not being\",\"s\":\"The philosopher argued that we cannot truly imagine nonbeing because thought itself requires existence.\",\"p\":\"non-BEE-ing\",\"o\":\"Latin\",\"y\":7,\"bp\":32,\"m\":\"nonbeeing\",\"sy\":\"non.be.ing\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonbeings\",\"d\":\"the state of not being\",\"s\":\"The ancient text described the gods as rising from infinite nonbeings before creation began.\",\"p\":\"non-BEE-ingz\",\"o\":\"Old English\",\"y\":8,\"bp\":29,\"m\":\"nonbeeings\",\"sy\":\"non.be.ings\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"ooldeng\"]},{\"w\":\"noncausal\",\"d\":\"not causative\",\"s\":\"The researcher stressed that the link between the two factors was noncausal and merely coincidental.\",\"p\":\"non-KAW-zul\",\"o\":\"Latin\",\"y\":8,\"bp\":33,\"m\":\"noncausual\",\"sy\":\"non.caus.al\",\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncoms\",\"d\":\"a military officer appointed from enlisted personnel\",\"s\":\"The noncoms organized the training drills while the commissioned officers reviewed the battle plans.\",\"p\":\"NON-komz\",\"o\":\"Latin\",\"y\":7,\"bp\":30,\"m\":\"noncomms\",\"sy\":\"non.coms\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"war\",\"olatin\"]},{\"w\":\"noncyclic\",\"d\":\"Describing something that does not follow a repeating cycle or circular pattern; occurring in a linear or irregular sequence rather than returning to its starting point.\",\"s\":\"Unlike the seasons, the pattern of the disease was noncyclic and appeared without any predictable rhythm.\",\"p\":\"non-SY-klik\",\"o\":\"Latin\",\"y\":9,\"bp\":33,\"m\":\"noncyclical\",\"sy\":\"non.cy.clic\",\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondriver\",\"d\":\"a person who is not a driver\",\"s\":\"As a nondriver, she relied on the subway and her bicycle to get everywhere around the city.\",\"p\":\"non-DRY-ver\",\"o\":\"Latin\",\"y\":8,\"bp\":33,\"m\":\"nondrivor\",\"sy\":\"non.driv.er\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nonaligned\",\"d\":\"not affiliated with any faction, party, or cause\",\"s\":\"The nonaligned countries refused to take sides with either superpower during the Cold War.\",\"p\":\"NAH-nuh-leyend\",\"o\":\"Latin\",\"y\":7,\"bp\":34,\"m\":\"nonallined\",\"sy\":\"naa.nah.lay.nd\",\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonbeliever\",\"d\":\"someone who refuses to believe (as in a divinity)\",\"s\":\"The preacher welcomed the nonbeliever into the church, hoping to answer his questions about faith.\",\"p\":\"nah-nbuh-LEE-ver\",\"o\":\"Latin\",\"y\":7,\"bp\":36,\"m\":\"nonbeleiver\",\"sy\":\"naa.nbah.liy.ver\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonbelievers\",\"d\":\"someone who refuses to believe (as in a divinity)\",\"s\":\"The religious ceremony was open to nonbelievers who were curious about the traditions.\",\"p\":\"nah-nbuh-LEE-verz\",\"o\":\"Latin\",\"y\":6,\"bp\":37,\"m\":\"nonbeleivers\",\"sy\":\"naa.nbah.liy.ver.z\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"noncombatant\",\"d\":\"a member of the armed forces who does not participate in combat (e.g. a chaplain or surgeon)\",\"s\":\"The army chaplain was a noncombatant who offered comfort to soldiers without ever carrying a weapon.\",\"p\":\"nah-nkuh-MBA-tuhnt\",\"o\":\"Latin\",\"y\":7,\"bp\":37,\"m\":\"noncombattant\",\"sy\":\"naa.nkah.mbae.tah.nt\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"war\",\"olatin\"]},{\"w\":\"nonachlorobiphenyl\",\"d\":\"A polychlorinated biphenyl compound in which nine chlorine atoms are attached to the biphenyl ring structure; one of the more heavily chlorinated PCB congeners found as environmental pollutants.\",\"s\":\"The lab report confirmed traces of nonachlorobiphenyl in the contaminated river sediment.\",\"p\":\"non-ah-klor-oh-BY-fen-il\",\"o\":\"Greek\",\"y\":9,\"bp\":26,\"sy\":\"nonachloro.biphenyl\",\"ps\":\"noun\",\"t\":[\"chemistry\",\"ecology\",\"ogreek\"]},{\"w\":\"nonagonistic\",\"d\":\"Not involving conflict, competition, or hostile struggle; describing an interaction or relationship that is cooperative or peaceful rather than combative.\",\"s\":\"The debate was refreshingly nonagonistic, with both sides calmly sharing their views.\",\"p\":\"non-ag-oh-NIS-tik\",\"o\":\"Greek\",\"y\":8,\"bp\":38,\"sy\":\"nonag.o.nis.tic\",\"ps\":\"adjective\",\"t\":[\"war\",\"sports\",\"ogreek\"]},{\"w\":\"nonalethic\",\"d\":\"Not relating to or concerned with truth or the concept of truth; describing logical or linguistic statements that do not make truth-value claims.\",\"s\":\"The logician classified the statement as nonalethic because it didn't deal with truth or falsity.\",\"p\":\"non-ah-LEE-thik\",\"o\":\"Greek\",\"y\":8,\"bp\":27,\"sy\":\"nonaleth.ic\",\"ps\":\"adjective\",\"t\":[\"logic\",\"wordwords\",\"ogreek\"]},{\"w\":\"nonamer\",\"d\":\"A molecule or biological structure composed of nine subunits or monomers linked together, as in certain protein complexes or chemical polymers.\",\"s\":\"The biologist identified the protein as a nonamer, composed of nine identical subunits.\",\"p\":\"NON-ah-mer\",\"o\":\"Greek\",\"y\":8,\"bp\":19,\"sy\":\"non.amer\",\"ps\":\"noun\",\"t\":[\"chemistry\",\"ogreek\"]},{\"w\":\"nonamphibian\",\"d\":\"Not belonging to or characteristic of the class Amphibia; describing an organism or substance that does not share the traits of amphibians, such as living both on land and in water.\",\"s\":\"The field guide helped students identify nonamphibian wetland species like turtles and water snakes.\",\"p\":\"non-am-FIB-ee-an\",\"o\":\"Greek\",\"y\":8,\"bp\":38,\"sy\":\"non.am.phib.ian\",\"ps\":\"adjective\",\"t\":[\"animals\",\"ogreek\"]},{\"w\":\"nonamphoteric\",\"d\":\"Not amphoteric; describing a chemical substance that can act only as either an acid or a base, but not both, in a chemical reaction.\",\"s\":\"The chemist noted that the compound was nonamphoteric, unable to act as both acid and base.\",\"p\":\"non-am-foh-TER-ik\",\"o\":\"Greek\",\"y\":9,\"bp\":28,\"sy\":\"non.am.pho.ter.ic\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"ogreek\"]},{\"w\":\"nonanthrax\",\"d\":\"Not related to or caused by anthrax; describing a skin lesion, infection, or condition that resembles anthrax symptoms but is produced by a different organism or cause.\",\"s\":\"The doctor reassured the patient that the skin lesion was nonanthrax and posed no serious threat.\",\"p\":\"non-AN-thraks\",\"o\":\"Greek\",\"y\":8,\"bp\":27,\"sy\":\"nonan.thrax\",\"ps\":\"adjective\",\"t\":[\"body\",\"disease\",\"ogreek\"]},{\"w\":\"nonapocalyptic\",\"d\":\"Not related to or characteristic of an apocalypse or catastrophic end-of-world scenario; describing a situation, story, or outlook that does not involve disaster or total destruction.\",\"s\":\"Her novel offered a nonapocalyptic vision of the future, where technology improved everyday life.\",\"p\":\"non-ah-pok-ah-LIP-tik\",\"o\":\"Greek\",\"y\":9,\"bp\":29,\"sy\":\"non.apoc.a.lyp.tic\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"ogreek\"]},{\"w\":\"nonascetic\",\"d\":\"Not practicing or relating to strict self-denial or extreme austerity; describing a lifestyle or approach that does not reject physical comfort or worldly pleasures.\",\"s\":\"His nonascetic lifestyle included rich food, comfortable furniture, and frequent entertainment.\",\"p\":\"non-ah-SET-ik\",\"o\":\"Greek\",\"y\":8,\"bp\":26,\"ps\":\"adjective\",\"t\":[\"ogreek\"]},{\"w\":\"nonasthma\",\"d\":\"Not caused by or related to asthma; describing wheezing, breathing difficulties, or respiratory symptoms that arise from causes other than true asthmatic disease.\",\"s\":\"The pulmonologist confirmed that the child's breathing difficulties were of nonasthma origin.\",\"p\":\"non-AZ-mah\",\"o\":\"Greek\",\"y\":9,\"bp\":26,\"sy\":\"nonasth.ma\",\"ps\":\"adjective\",\"t\":[\"disease\",\"ogreek\"]},{\"w\":\"nonathlete\",\"d\":\"A person who does not regularly participate in organized sports or athletic activities; someone who does not identify as athletically trained or competitive.\",\"s\":\"As a self-described nonathlete, she preferred reading in the library over joining any sports team.\",\"p\":\"non-ATH-leet\",\"o\":\"Greek\",\"y\":9,\"bp\":27,\"sy\":\"nonath.lete\",\"ps\":\"noun\",\"t\":[\"sports\",\"ogreek\"]},{\"w\":\"nonatopic\",\"d\":\"Not related to atopy; describing allergic reactions or hypersensitivity conditions that are not mediated by the inherited tendency to develop classic allergic diseases such as asthma or eczema.\",\"s\":\"The allergist determined the rash was nonatopic, unrelated to any typical allergy response.\",\"p\":\"non-ah-TOP-ik\",\"o\":\"Greek\",\"y\":8,\"bp\":25,\"ps\":\"adjective\",\"t\":[\"disease\",\"ogreek\"]},{\"w\":\"nonauthentic\",\"d\":\"Not genuine, real, or original; describing something that is false, imitated, or does not accurately represent what it claims to be.\",\"s\":\"The museum curator rejected the painting as nonauthentic after carbon dating proved it was a forgery.\",\"p\":\"non-aw-THEN-tik\",\"o\":\"Greek\",\"y\":8,\"bp\":36,\"sy\":\"nonau.then.tic\",\"ps\":\"adjective\",\"t\":[\"ogreek\"]},{\"w\":\"nonauto\",\"d\":\"Not involving or relating to automobiles or self-propelled motor vehicles; describing transportation, policies, or infrastructure that excludes cars.\",\"s\":\"She chose a nonauto commute, cycling and taking the train to reduce her carbon footprint.\",\"p\":\"non-AW-toh\",\"o\":\"Greek\",\"y\":9,\"bp\":19,\"sy\":\"nonau.to\",\"ps\":\"adjective\",\"t\":[\"politics\",\"vehicles\",\"tools\",\"ogreek\"]},{\"w\":\"nonautonomy\",\"d\":\"The absence or lack of self-governance or independence; a state in which an individual, group, or system is directed by external rules or authorities rather than its own will.\",\"s\":\"The colony's nonautonomy meant every major decision had to be approved by the distant government.\",\"p\":\"non-aw-TON-oh-mee\",\"o\":\"Greek\",\"y\":8,\"bp\":37,\"sy\":\"nonau.ton.o.my\",\"ps\":\"noun\",\"t\":[\"poetry\",\"ogreek\"]},{\"w\":\"nonauxetic\",\"d\":\"Not exhibiting auxetic behavior; describing a material that does not expand laterally when stretched, behaving in the conventional way most materials do under tension.\",\"s\":\"Unlike rubber, the nonauxetic material did not expand sideways when stretched lengthwise.\",\"p\":\"non-awk-SET-ik\",\"o\":\"Greek\",\"y\":8,\"bp\":29,\"sy\":\"nonaux.et.ic\",\"ps\":\"adjective\",\"t\":[\"ogreek\"]},{\"w\":\"nonauxin\",\"d\":\"A chemical compound that is not a plant growth hormone of the auxin class; describing substances that do not promote cell elongation or the directional growth responses characteristic of auxins.\",\"s\":\"The researchers tested whether the nonauxin compound could still promote plant cell growth.\",\"p\":\"non-AWK-sin\",\"o\":\"Greek\",\"y\":8,\"bp\":25,\"sy\":\"nonaux.in\",\"ps\":\"noun\",\"t\":[\"botany\",\"chemistry\",\"ogreek\"]},{\"w\":\"nonaxiomatic\",\"d\":\"Not based on or derivable from self-evident axioms; describing a statement, system, or approach that requires proof, evidence, or assumptions that are not universally accepted.\",\"s\":\"The philosopher argued that ethics is inherently nonaxiomatic and cannot be reduced to simple rules.\",\"p\":\"non-ak-see-oh-MAT-ik\",\"o\":\"Greek\",\"y\":8,\"bp\":38,\"sy\":\"non.ax.iomat.ic\",\"ps\":\"adjective\",\"t\":[\"ogreek\"]},{\"w\":\"noncadmium\",\"d\":\"Not containing or involving cadmium; describing products, batteries, or industrial processes that are manufactured without the use of the toxic heavy metal cadmium.\",\"s\":\"The manufacturer advertised noncadmium batteries as safer for both consumers and the environment.\",\"p\":\"non-KAD-mee-um\",\"o\":\"Greek\",\"y\":8,\"bp\":30,\"sy\":\"non.cad.mi.um\",\"ps\":\"adjective\",\"t\":[\"culinary\",\"ogreek\"]},{\"w\":\"noncardiac\",\"d\":\"Not relating to, caused by, or affecting the heart; describing symptoms, conditions, or chest pain that originate from sources other than the cardiovascular system.\",\"s\":\"The doctor explained that her chest pain was noncardiac and likely caused by acid reflux.\",\"p\":\"non-KAR-dee-ak\",\"o\":\"Greek\",\"y\":7,\"bp\":29,\"sy\":\"non.car.diac\",\"ps\":\"adjective\",\"t\":[\"body\",\"disease\",\"ogreek\"]},{\"w\":\"nonceramic\",\"d\":\"Not made of or relating to ceramic materials; describing products or components manufactured from substances other than clay-based or fired mineral compounds.\",\"s\":\"The engineer chose a nonceramic material for the component because it needed to flex without cracking.\",\"p\":\"non-suh-RAM-ik\",\"o\":\"Greek\",\"y\":8,\"bp\":30,\"sy\":\"non.ce.ram.ic\",\"ps\":\"adjective\",\"t\":[\"minerals\",\"ogreek\"]},{\"w\":\"noncharacteristic\",\"d\":\"Not typical or representative of a particular person, thing, or group; describing behavior, features, or qualities that are unexpected or unusual for a given subject.\",\"s\":\"It was noncharacteristic of her to arrive late, since she was usually the first one in the room.\",\"p\":\"non-kair-ik-ter-IS-tik\",\"o\":\"Greek\",\"y\":9,\"bp\":32,\"sy\":\"non.char.ac.ter.is.tic\",\"ps\":\"adjective\",\"t\":[\"ogreek\"]},{\"w\":\"noncharacteristically\",\"d\":\"In a manner that is not typical or expected of a particular person, thing, or group; used to describe an action or behavior that departs from established patterns or norms.\",\"s\":\"He noncharacteristically skipped breakfast, leaving everyone at the table puzzled.\",\"p\":\"non-kair-ik-ter-IS-tik-lee\",\"o\":\"Greek\",\"y\":9,\"bp\":35,\"sy\":\"non.char.ac.ter.is.ti.cal.ly\",\"ps\":\"adverb\",\"t\":[\"ogreek\"]},{\"w\":\"nonchlorine\",\"d\":\"Not containing or involving chlorine; describing water treatment processes, cleaning products, or chemical compounds that do not use chlorine as an ingredient or disinfectant.\",\"s\":\"The pool used a nonchlorine sanitizer that was gentler on swimmers' eyes and skin.\",\"p\":\"non-KLOR-een\",\"o\":\"Greek\",\"y\":9,\"bp\":34,\"sy\":\"nonchlo.rine\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"ogreek\"]},{\"w\":\"nonchromatic\",\"d\":\"Not relating to or involving color; in music, not using the chromatic scale; in art or optics, describing something that lacks hue and exists only in shades of black, white, or gray.\",\"s\":\"The artist's minimalist sketch was nonchromatic, using only shades of black, white, and gray.\",\"p\":\"non-kroh-MAT-ik\",\"o\":\"Greek\",\"y\":9,\"bp\":36,\"sy\":\"nonchro.mat.ic\",\"ps\":\"adjective\",\"t\":[\"physics\",\"music\",\"colors\",\"ogreek\"]},{\"w\":\"nonchromatically\",\"d\":\"In a manner that does not involve color or the chromatic scale; describing the production of art, music, or optical effects without the use of distinct hues or chromatic tones.\",\"s\":\"The designer worked nonchromatically, deliberately avoiding all color in the poster layout.\",\"p\":\"non-kroh-MAT-ik-lee\",\"o\":\"Greek\",\"y\":9,\"bp\":30,\"sy\":\"nonchro.mat.i.cal.ly\",\"ps\":\"adverb\",\"t\":[\"physics\",\"music\",\"colors\",\"ogreek\"]},{\"w\":\"noncoral\",\"d\":\"Not composed of or built by coral organisms; describing reef structures, marine habitats, or formations that are created by organisms or geological processes other than coral polyps.\",\"s\":\"The marine biologist distinguished noncoral reef structures built by worms and mollusks.\",\"p\":\"non-KOR-ul\",\"o\":\"Greek\",\"y\":8,\"bp\":27,\"sy\":\"non.co.ral\",\"ps\":\"adjective\",\"t\":[\"marine\",\"minerals\",\"ecology\",\"ogreek\"]},{\"w\":\"noncrisis\",\"d\":\"A situation or period that does not involve an emergency, critical turning point, or urgent problem; describing conditions that are stable, routine, and free from serious difficulty.\",\"s\":\"The manager handled the supply delay as a noncrisis situation, calmly adjusting the schedule.\",\"p\":\"non-KRY-sis\",\"o\":\"Greek\",\"y\":8,\"bp\":28,\"sy\":\"non.cri.sis\",\"ps\":\"noun\",\"t\":[\"ogreek\"]},{\"w\":\"nondialect\",\"d\":\"Not constituting or belonging to a regional or social dialect; describing language use that does not reflect the distinctive vocabulary, grammar, or pronunciation of a particular community.\",\"s\":\"The linguist studied nondialect speech patterns found in formal broadcasting and official documents.\",\"p\":\"non-DY-ah-lekt\",\"o\":\"Greek\",\"y\":8,\"bp\":29,\"sy\":\"non.di.alect\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"ogreek\"]},{\"w\":\"nondialectic\",\"d\":\"Not involving or based on dialectical reasoning; describing an argument, approach, or method of inquiry that does not rely on the back-and-forth exchange of opposing ideas to reach a conclusion.\",\"s\":\"Her argument was criticized for being nondialectic, refusing to engage with opposing viewpoints.\",\"p\":\"non-dy-ah-LEK-tik\",\"o\":\"Greek\",\"y\":8,\"bp\":38,\"sy\":\"non.di.alec.tic\",\"ps\":\"adjective\",\"t\":[\"logic\",\"wordwords\",\"ogreek\"]},{\"w\":\"nondidactic\",\"d\":\"Not intended to teach a moral lesson or convey instruction; describing writing, art, or speech that does not aim to preach or educate the audience.\",\"s\":\"The creative writing teacher encouraged nondidactic stories that entertained without lecturing the reader.\",\"p\":\"non-dih-DAK-tik\",\"o\":\"Greek\",\"y\":8,\"bp\":37,\"sy\":\"non.di.dac.tic\",\"ps\":\"adjective\",\"t\":[\"logic\",\"ogreek\"]},{\"w\":\"nondoxastic\",\"d\":\"Not relating to or based on belief or opinion; describing mental states or processes that do not involve holding a belief about something.\",\"s\":\"The philosopher classified certain mental states as nondoxastic because they involve feelings rather than beliefs.\",\"p\":\"non-dok-SAS-tik\",\"o\":\"Greek\",\"y\":8,\"bp\":37,\"sy\":\"non.dox.as.tic\",\"ps\":\"adjective\",\"t\":[\"logic\",\"ogreek\"]},{\"w\":\"nondrama\",\"d\":\"A work or form of expression that lacks the essential elements of drama, such as conflict, character development, or theatrical action.\",\"s\":\"The documentary was praised as pure nondrama, presenting facts without sensational storytelling.\",\"p\":\"non-DRAH-muh\",\"o\":\"Greek\",\"y\":9,\"bp\":27,\"sy\":\"non.dra.ma\",\"ps\":\"noun\",\"t\":[\"stage\",\"ogreek\"]},{\"w\":\"nonauthor\",\"d\":\"A person who is not an author; someone who has not written or created a literary or published work.\",\"s\":\"The copyright form required all nonauthor contributors to sign a separate agreement.\",\"p\":\"non-AW-ther\",\"o\":\"Anglo-Norman\",\"y\":8,\"bp\":22,\"sy\":\"nonau.thor\",\"ps\":\"noun\",\"t\":[\"poetry\",\"character\",\"ofrench\"]},{\"w\":\"noncounterfeit\",\"d\":\"Describing something that is genuine and not a fake or fraudulent imitation of the real thing.\",\"s\":\"The bank's scanner confirmed that all the bills in the drawer were noncounterfeit.\",\"p\":\"non-KOWN-ter-fit\",\"o\":\"Anglo-Norman\",\"y\":9,\"bp\":23,\"sy\":\"non.coun.ter.feit\",\"ps\":\"adjective\",\"t\":[\"ofrench\"]},{\"w\":\"nonboom\",\"d\":\"A period or situation characterized by the absence of rapid economic growth or expansion; the lack of a boom in a market or economy.\",\"s\":\"Economists described the sluggish decade as a nonboom period with little growth.\",\"p\":\"NON-boom\",\"o\":\"Dutch\",\"y\":8,\"bp\":15,\"sy\":\"non.boom\",\"ps\":\"noun\",\"t\":[\"economy\",\"character\",\"odutch\"]},{\"w\":\"nondollar\",\"d\":\"Referring to any currency, asset, or financial transaction that is not denominated in or related to the United States dollar.\",\"s\":\"Travelers found that nondollar currencies were often more accepted in rural European markets.\",\"p\":\"NAH-NDAH-ler\",\"o\":\"Dutch\",\"y\":9,\"bp\":24,\"sy\":\"naa.ndaa.ler\",\"ps\":\"adjective\",\"t\":[\"economy\",\"odutch\"]},{\"w\":\"nonacid\",\"d\":\"Not acidic; lacking the properties of an acid, such as a sour taste or the ability to turn litmus paper red.\",\"s\":\"The chemist confirmed that the solution was nonacid after testing it with litmus paper, which remained blue and indicated a neutral or basic chemical composition.\",\"p\":\"non-AS-id\",\"o\":\"French\",\"y\":8,\"bp\":17,\"ps\":\"adjective\",\"t\":[\"chemistry\",\"ofrench\"]},{\"w\":\"nonacidity\",\"d\":\"The state or quality of lacking acidity; the absence of acidic properties in a substance.\",\"s\":\"The nonacidity of the mineral water made it ideal for patients with sensitive stomachs, since doctors had recommended they avoid any beverages that might irritate their digestive lining.\",\"p\":\"non-uh-SID-ih-tee\",\"o\":\"French\",\"y\":8,\"bp\":29,\"sy\":\"nonacid.i.ty\",\"ps\":\"noun\",\"t\":[\"ofrench\"]},{\"w\":\"nonacquiescence\",\"d\":\"The refusal to accept, comply with, or go along with something passively; a state of not yielding or consenting to a demand or situation.\",\"s\":\"Her nonacquiescence to the unfair school policy inspired other students to speak up, and together they successfully petitioned the administration to revise the outdated and restrictive dress code.\",\"p\":\"non-ak-wee-ES-unts\",\"o\":\"French\",\"y\":9,\"bp\":28,\"sy\":\"nonac.qui.es.cence\",\"ps\":\"noun\",\"t\":[\"ofrench\"]},{\"w\":\"nonadhesive\",\"d\":\"not tending to adhere\",\"s\":\"The cook used a nonadhesive pan so the eggs would slide out without sticking.\",\"p\":\"non-ad-HEE-siv\",\"o\":\"French\",\"y\":9,\"bp\":37,\"sy\":\"non.ad.he.sive\",\"ps\":\"adjective\",\"t\":[\"character\",\"ofrench\"]},{\"w\":\"nonadic\",\"d\":\"Relating to or having a structure based on nine elements or a nine-part system; having nine components or arguments.\",\"s\":\"The mathematician introduced a nonadic numbering system during the lecture, explaining how a base-nine structure could be applied to solve certain complex computational problems more efficiently.\",\"p\":\"non-AD-ik\",\"o\":\"French\",\"y\":8,\"bp\":17,\"ps\":\"adjective\",\"t\":[\"logic\",\"ofrench\"]},{\"w\":\"nonadult\",\"d\":\"A person or organism that has not yet reached the stage of full adulthood; a child, adolescent, or juvenile.\",\"s\":\"The study focused on nonadult participants between the ages of ten and seventeen to better understand how early experiences shape long-term emotional development and social behavior patterns.\",\"p\":\"non-uh-DULT\",\"o\":\"French\",\"y\":8,\"bp\":18,\"ps\":\"noun\",\"t\":[\"stage\",\"kinship\",\"ofrench\"]},{\"w\":\"nonaerobic\",\"d\":\"Not requiring or using oxygen for energy production; describing biological processes or organisms that function without the presence of oxygen.\",\"s\":\"The biology teacher explained that certain bacteria are nonaerobic, thriving in oxygen-free environments like deep mud or the interior of sealed food containers where aerobic life cannot survive.\",\"p\":\"non-air-OH-bik\",\"o\":\"French\",\"y\":8,\"bp\":30,\"sy\":\"non.aer.o.bic\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"physics\",\"ofrench\"]},{\"w\":\"nonaffluent\",\"d\":\"Not wealthy or prosperous; lacking financial resources or material abundance.\",\"s\":\"The nonprofit organization dedicated its resources to providing after-school tutoring programs specifically for nonaffluent students who lacked access to private lessons and educational support at home.\",\"p\":\"non-AF-loo-unt\",\"o\":\"French\",\"y\":9,\"bp\":37,\"sy\":\"non.af.flu.ent\",\"ps\":\"adjective\",\"t\":[\"economy\",\"ofrench\"]},{\"w\":\"nonalignment\",\"d\":\"people (or countries) who are not aligned with other people (or countries) in a pact or treaty\",\"s\":\"During the Cold War, India pursued a policy of nonalignment, refusing to side with either the United States or the Soviet Union.\",\"p\":\"non-uh-LYN-munt\",\"o\":\"French\",\"y\":8,\"bp\":36,\"sy\":\"non.align.ment\",\"ps\":\"noun\",\"t\":[\"politics\",\"ofrench\"]},{\"w\":\"nonambulance\",\"d\":\"The absence or lack of ambulances in a given area or situation, leaving emergency medical transportation unavailable.\",\"s\":\"Emergency planners identified a dangerous nonambulance zone in the remote mountain region, where injured hikers often had to wait hours for any form of medical evacuation to arrive.\",\"p\":\"non-AM-byoo-luns\",\"o\":\"French\",\"y\":9,\"bp\":38,\"sy\":\"non.am.bu.lance\",\"ps\":\"noun\",\"t\":[\"body\",\"ofrench\"]},{\"w\":\"nonamputee\",\"d\":\"A person who has not undergone an amputation and retains all of their natural limbs.\",\"s\":\"The prosthetics researcher compared mobility data from amputee participants alongside nonamputee volunteers to determine how closely the new artificial limb replicated the movement of a natural leg.\",\"p\":\"non-am-pyoo-TEE\",\"o\":\"French\",\"y\":9,\"bp\":29,\"sy\":\"non.am.putee\",\"ps\":\"noun\",\"t\":[\"body\",\"ofrench\"]},{\"w\":\"nonanalyst\",\"d\":\"A person who is not a trained or professional analyst; someone who does not perform analysis as part of their role or expertise.\",\"s\":\"The report was deliberately written in plain language so that a nonanalyst could understand the findings without needing specialized training in data science or statistical interpretation methods.\",\"p\":\"non-AN-uh-list\",\"o\":\"French\",\"y\":9,\"bp\":30,\"sy\":\"non.an.a.lyst\",\"ps\":\"noun\",\"t\":[\"character\",\"ofrench\"]},{\"w\":\"nonanarchist\",\"d\":\"A person who does not hold anarchist beliefs and instead supports some form of organized government, authority, or social structure.\",\"s\":\"During the heated political debate, the nonanarchist argued passionately that structured laws and elected institutions were essential to protecting individual rights and maintaining a functioning, peaceful society.\",\"p\":\"non-AN-ur-kist\",\"o\":\"French\",\"y\":9,\"bp\":38,\"sy\":\"nona.n.ar.chist\",\"ps\":\"noun\",\"t\":[\"poetry\",\"politics\",\"logic\",\"ofrench\"]},{\"w\":\"nonantibiotic\",\"d\":\"Not functioning as an antibiotic; describing a substance or treatment that does not kill or inhibit the growth of bacteria.\",\"s\":\"The researcher emphasized that the new compound was nonantibiotic, meaning it would not contribute to antibiotic resistance while still helping the body's immune system fight off certain bacterial infections.\",\"p\":\"non-an-tee-by-OT-ik\",\"o\":\"French\",\"y\":9,\"bp\":38,\"sy\":\"nonan.tibi.ot.ic\",\"ps\":\"adjective\",\"t\":[\"disease\",\"pharmacy\",\"ofrench\"]},{\"w\":\"nonantique\",\"d\":\"Not old or ancient; describing an object that lacks the age or historical character required to be classified as an antique.\",\"s\":\"The appraiser carefully examined the furniture and concluded it was entirely nonantique, having been manufactured no more than thirty years ago despite its deliberately old-fashioned and weathered appearance.\",\"p\":\"non-an-TEEK\",\"o\":\"French\",\"y\":9,\"bp\":27,\"sy\":\"nonan.tique\",\"ps\":\"adjective\",\"t\":[\"ancient\",\"ofrench\"]},{\"w\":\"nonapologetic\",\"d\":\"Showing no remorse or regret; openly unashamed and unwilling to apologize for one's actions, beliefs, or statements.\",\"s\":\"The artist was completely nonapologetic about her bold and provocative paintings, stating in every interview that she created work meant to challenge comfortable assumptions and spark difficult conversations.\",\"p\":\"non-uh-pol-uh-JET-ik\",\"o\":\"French\",\"y\":9,\"bp\":38,\"sy\":\"non.apolo.get.ic\",\"ps\":\"adjective\",\"t\":[\"logic\",\"ofrench\"]},{\"w\":\"nonapology\",\"d\":\"A statement disguised as an apology that fails to take genuine responsibility, often shifting blame or minimizing the offense rather than expressing true remorse.\",\"s\":\"Many viewers criticized the celebrity's televised nonapology, pointing out that saying 'I'm sorry you feel that way' is a classic way of avoiding real accountability for hurtful actions.\",\"p\":\"non-uh-POL-oh-jee\",\"o\":\"French\",\"y\":8,\"bp\":30,\"sy\":\"non.apol.o.gy\",\"ps\":\"noun\",\"t\":[\"ofrench\"]},{\"w\":\"nonapparent\",\"d\":\"Not easily seen, noticed, or understood; not obvious or evident to observation or inspection.\",\"s\":\"The damage to the bridge's internal steel supports was completely nonapparent from the outside, which is exactly why engineers insisted on regular internal inspections using advanced imaging technology and sensors.\",\"p\":\"non-uh-PAIR-unt\",\"o\":\"French\",\"y\":9,\"bp\":37,\"sy\":\"non.ap.par.ent\",\"ps\":\"adjective\",\"t\":[\"ofrench\"]},{\"w\":\"nonappreciable\",\"d\":\"Too small or slight to be noticed, measured, or considered significant; not large enough to be appreciated or valued.\",\"s\":\"The difference in temperature between the two rooms was nonappreciable, so neither felt warmer than the other.\",\"p\":\"non-uh-PREE-shuh-bul\",\"o\":\"French\",\"y\":9,\"bp\":29,\"sy\":\"non.ap.pre.cia.ble\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"ofrench\"]},{\"w\":\"nonarchitect\",\"d\":\"A person who is not a trained or licensed architect; someone who lacks the professional credentials to design buildings.\",\"s\":\"The building was surprisingly well-designed despite being planned by a nonarchitect with no formal training.\",\"p\":\"non-AR-kih-tekt\",\"o\":\"French\",\"y\":9,\"bp\":36,\"sy\":\"nonar.chi.tect\",\"ps\":\"noun\",\"t\":[\"buildings\",\"character\",\"ofrench\"]},{\"w\":\"nonaristocrat\",\"d\":\"A person who does not belong to the aristocracy or nobility; someone without noble birth or rank.\",\"s\":\"The revolution was led largely by nonaristocrats who resented the privilege enjoyed by the noble class.\",\"p\":\"non-uh-RIS-tuh-krat\",\"o\":\"French\",\"y\":9,\"bp\":38,\"sy\":\"nonar.is.to.crat\",\"ps\":\"noun\",\"t\":[\"royalty\",\"ofrench\"]},{\"w\":\"nonaristocratic\",\"d\":\"Not related to or characteristic of the aristocracy; lacking the qualities, privileges, or status associated with nobility.\",\"s\":\"The king surprised his court by adopting a nonaristocratic lifestyle, eating simple food and wearing plain clothes.\",\"p\":\"non-uh-ris-tuh-KRAT-ik\",\"o\":\"French\",\"y\":9,\"bp\":30,\"sy\":\"nonar.is.to.crat.ic\",\"ps\":\"adjective\",\"t\":[\"royalty\",\"ofrench\"]},{\"w\":\"nonartist\",\"d\":\"A person who is not an artist and does not engage in or practice the creative arts professionally or by training.\",\"s\":\"As a nonartist, Marcus struggled to appreciate why the blank canvas sold for thousands of dollars.\",\"p\":\"non-AR-tist\",\"o\":\"French\",\"y\":8,\"bp\":25,\"ps\":\"noun\",\"t\":[\"character\",\"ofrench\"]},{\"w\":\"nonartistic\",\"d\":\"Not related to or characteristic of art or artistic expression; lacking aesthetic creativity or artistic quality.\",\"s\":\"The judges agreed the bridge design was purely nonartistic, built for function rather than beauty.\",\"p\":\"non-ar-TIS-tik\",\"o\":\"French\",\"y\":8,\"bp\":34,\"sy\":\"nonartis.tic\",\"ps\":\"adjective\",\"t\":[\"painting\",\"ofrench\"]},{\"w\":\"nonaspirant\",\"d\":\"A person who does not aspire to or seek a particular goal, position, or achievement; one who has no strong ambition for something.\",\"s\":\"Unlike his ambitious classmates, Derek was a nonaspirant who simply wanted a quiet life on the farm.\",\"p\":\"non-AS-puh-runt\",\"o\":\"French\",\"y\":8,\"bp\":34,\"sy\":\"nonaspi.rant\",\"ps\":\"noun\",\"t\":[\"sports\",\"ofrench\"]},{\"w\":\"nonatheist\",\"d\":\"A person who is not an atheist; someone who holds some form of belief in a deity or supernatural power.\",\"s\":\"As a nonatheist, she believed in some form of higher power, even if she couldn't define it.\",\"p\":\"non-AY-thee-ist\",\"o\":\"French\",\"y\":8,\"bp\":27,\"sy\":\"nonathe.ist\",\"ps\":\"noun\",\"t\":[\"myth\",\"character\",\"logic\",\"ofrench\"]},{\"w\":\"nonattachment\",\"d\":\"The state of not being emotionally or physically attached to something or someone; a lack of strong personal connection or dependence.\",\"s\":\"The monk practiced nonattachment, letting go of his desire for possessions without any regret.\",\"p\":\"non-uh-TACH-munt\",\"o\":\"French\",\"y\":9,\"bp\":37,\"sy\":\"nonat.tach.ment\",\"ps\":\"noun\",\"t\":[\"emotions\",\"ofrench\"]},{\"w\":\"nonattack\",\"d\":\"An absence of aggression or offensive action; a deliberate choice not to attack or engage in hostile behavior.\",\"s\":\"The treaty guaranteed a nonattack policy, meaning neither country would strike first.\",\"p\":\"non-uh-TAK\",\"o\":\"French\",\"y\":9,\"bp\":26,\"sy\":\"nonat.tack\",\"ps\":\"noun\",\"t\":[\"ofrench\"]},{\"w\":\"nonautomatic\",\"d\":\"Not operating automatically or by itself; requiring manual control or human intervention to function.\",\"s\":\"The nonautomatic door required passengers to push it open themselves.\",\"p\":\"non-aw-tuh-MAT-ik\",\"o\":\"French\",\"y\":8,\"bp\":38,\"sy\":\"nonau.to.mat.ic\",\"ps\":\"adjective\",\"t\":[\"ofrench\"]},{\"w\":\"nonautomatically\",\"d\":\"In a manner that is not automatic; requiring deliberate human action or manual steps rather than self-operating processes.\",\"s\":\"The gate nonautomatically closed only when a guard physically pushed it shut each evening.\",\"p\":\"non-aw-tuh-MAT-ik-lee\",\"o\":\"French\",\"y\":9,\"bp\":32,\"sy\":\"nonau.to.mat.i.cal.ly\",\"ps\":\"adverb\",\"t\":[\"ofrench\"]},{\"w\":\"nonaviation\",\"d\":\"Not related to or involving aviation, aircraft, or the activity of flying; pertaining to areas or industries outside of air travel.\",\"s\":\"The conference covered nonaviation transportation, focusing on trains and ships instead of planes.\",\"p\":\"non-ay-vee-AY-shun\",\"o\":\"French\",\"y\":8,\"bp\":37,\"sy\":\"non.avi.a.tion\",\"ps\":\"adjective\",\"t\":[\"vehicles\",\"ofrench\"]},{\"w\":\"nonballet\",\"d\":\"Not related to or characteristic of ballet; referring to dance forms or performances that are outside the tradition of classical ballet.\",\"s\":\"The dance school offered nonballet options like hip-hop and jazz for students who didn't like tutus.\",\"p\":\"non-ba-LAY\",\"o\":\"French\",\"y\":9,\"bp\":28,\"sy\":\"non.bal.let\",\"ps\":\"adjective\",\"t\":[\"stage\",\"festivals\",\"ofrench\"]},{\"w\":\"nonbloc\",\"d\":\"Not affiliated with or belonging to a political or economic bloc; describing a nation or group that remains independent of established alliances.\",\"s\":\"The small country declared itself nonbloc, refusing to ally with any major political group.\",\"p\":\"non-BLOK\",\"o\":\"French\",\"y\":8,\"bp\":19,\"sy\":\"non.bloc\",\"ps\":\"adjective\",\"t\":[\"nations\",\"politics\",\"economy\",\"ofrench\"]},{\"w\":\"nonbromine\",\"d\":\"Not containing or relating to bromine; describing a substance or compound that is free of the chemical element bromine.\",\"s\":\"The scientist confirmed the compound was nonbromine, containing no trace of the reddish chemical element.\",\"p\":\"non-BROH-meen\",\"o\":\"French\",\"y\":9,\"bp\":27,\"sy\":\"non.bromine\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"ofrench\"]},{\"w\":\"nonbureaucrat\",\"d\":\"A person who is not a bureaucrat and does not work within a formal governmental or institutional administrative system.\",\"s\":\"The startup founder was a proud nonbureaucrat who hated filling out endless government forms.\",\"p\":\"non-BYOOR-oh-krat\",\"o\":\"French\",\"y\":9,\"bp\":38,\"sy\":\"non.bu.reau.crat\",\"ps\":\"noun\",\"t\":[\"politics\",\"character\",\"ofrench\"]},{\"w\":\"noncampaign\",\"d\":\"An effort or approach that deliberately avoids the tactics, methods, or style of a traditional political or advertising campaign.\",\"s\":\"The senator's noncampaign approach meant she never ran ads or asked for donations.\",\"p\":\"non-kam-PAYN\",\"o\":\"French\",\"y\":9,\"bp\":35,\"sy\":\"non.cam.paign\",\"ps\":\"noun\",\"t\":[\"festivals\",\"politics\",\"ofrench\"]},{\"w\":\"noncapitalism\",\"d\":\"An economic system or ideology that is not based on capitalism; any approach to organizing society and production that rejects private ownership and free markets.\",\"s\":\"The professor argued that noncapitalism systems, like barter economies, still thrive in some villages.\",\"p\":\"non-KAP-ih-tul-iz-um\",\"o\":\"French\",\"y\":9,\"bp\":40,\"sy\":\"non.cap.i.tal.ism\",\"ps\":\"noun\",\"t\":[\"economy\",\"ofrench\"]},{\"w\":\"noncapricious\",\"d\":\"Not given to sudden, unpredictable changes of mood or behavior; steady, consistent, and not impulsive.\",\"s\":\"Her noncapricious personality made her a reliable leader who never changed plans on a whim.\",\"p\":\"non-kuh-PRISH-us\",\"o\":\"French\",\"y\":9,\"bp\":37,\"sy\":\"non.capri.cious\",\"ps\":\"adjective\",\"t\":[\"emotions\",\"ofrench\"]},{\"w\":\"noncarbonate\",\"d\":\"Not containing or composed of carbonate; describing a rock, mineral, or compound that lacks carbonate chemical groups.\",\"s\":\"The geologist labeled the rock sample noncarbonate because it contained no limestone or chalk.\",\"p\":\"non-KAR-buh-nit\",\"o\":\"French\",\"y\":9,\"bp\":38,\"sy\":\"non.car.bon.ate\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"minerals\",\"ofrench\"]},{\"w\":\"noncardinal\",\"d\":\"Not serving as a primary, essential, or fundamental point of reference; not one of the main directional or guiding principles.\",\"s\":\"The noncardinal directions like northeast and southwest are also called ordinal directions.\",\"p\":\"non-KAR-duh-nul\",\"o\":\"French\",\"y\":8,\"bp\":37,\"sy\":\"non.car.di.nal\",\"ps\":\"adjective\",\"t\":[\"logic\",\"ofrench\"]},{\"w\":\"noncassette\",\"d\":\"Not using or relating to a cassette format; describing audio, video, or other media that does not rely on cassette tape technology.\",\"s\":\"The music teacher used noncassette recordings, playing everything straight from a digital file.\",\"p\":\"non-kuh-SET\",\"o\":\"French\",\"y\":9,\"bp\":35,\"sy\":\"non.cas.sette\",\"ps\":\"adjective\",\"t\":[\"ofrench\"]},{\"w\":\"noncereal\",\"d\":\"Not made from or relating to cereal grains; describing foods or agricultural products that do not come from grasses such as wheat, rice, or corn.\",\"s\":\"My little brother chose a noncereal breakfast, preferring eggs and toast over cornflakes.\",\"p\":\"non-SEER-ee-ul\",\"o\":\"French\",\"y\":8,\"bp\":29,\"sy\":\"non.ce.re.al\",\"ps\":\"adjective\",\"t\":[\"botany\",\"farming\",\"ofrench\"]},{\"w\":\"noncerebral\",\"d\":\"Not involving or requiring the use of the brain or intellect; not intellectual or mentally demanding in nature.\",\"s\":\"Soccer coaches often say the game has both cerebral strategy and noncerebral physical instinct.\",\"p\":\"non-suh-REE-brul\",\"o\":\"French\",\"y\":8,\"bp\":35,\"sy\":\"non.cere.bral\",\"ps\":\"adjective\",\"t\":[\"body\",\"ofrench\"]},{\"w\":\"noncigarette\",\"d\":\"Not involving or relating to cigarettes; describing tobacco products, delivery methods, or habits that do not include traditional cigarettes.\",\"s\":\"The smoke shop surprisingly sold many noncigarette items, like pipes, candles, and lighters.\",\"p\":\"non-sig-uh-RET\",\"o\":\"French\",\"y\":9,\"bp\":36,\"sy\":\"non.ci.garette\",\"ps\":\"adjective\",\"t\":[\"festivals\",\"ofrench\"]},{\"w\":\"noncinema\",\"d\":\"Not related to or produced for the cinema; describing visual or storytelling media that exists outside the tradition of theatrical filmmaking.\",\"s\":\"The film festival celebrated noncinema storytelling, including virtual reality experiences and video games.\",\"p\":\"non-SIN-uh-muh\",\"o\":\"French\",\"y\":9,\"bp\":28,\"sy\":\"noncin.e.ma\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"festivals\",\"ofrench\"]},{\"w\":\"nonclandestine\",\"d\":\"Not secret, hidden, or conducted in a concealed manner; open and transparent rather than covert or secretive.\",\"s\":\"The government promised that all future meetings would be nonclandestine and open to the press.\",\"p\":\"non-klan-DES-tin\",\"o\":\"French\",\"y\":9,\"bp\":27,\"sy\":\"non.clan.des.tine\",\"ps\":\"adjective\",\"t\":[\"ofrench\"]},{\"w\":\"nonclass\",\"d\":\"Something that does not qualify as a class or category; an entity or group that falls outside standard classification systems.\",\"s\":\"The school set aside time for nonclass activities like clubs, art, and free reading.\",\"p\":\"non-KLAS\",\"o\":\"French\",\"y\":8,\"bp\":19,\"sy\":\"non.class\",\"ps\":\"noun\",\"t\":[\"ofrench\"]},{\"w\":\"noncoalition\",\"d\":\"Not formed by or involving a coalition; describing a government, group, or action that operates without an alliance of different parties or factions.\",\"s\":\"The noncoalition government stood alone, refusing to join forces with any other political party.\",\"p\":\"non-koh-uh-LI-shun\",\"o\":\"French\",\"y\":8,\"bp\":36,\"sy\":\"non.coali.tion\",\"ps\":\"adjective\",\"t\":[\"politics\",\"ofrench\"]},{\"w\":\"noncohesion\",\"d\":\"A lack of cohesion or unity; the state of elements or members failing to stick together or act as a unified whole.\",\"s\":\"The team's noncohesion was obvious during the game, as players rarely passed to each other.\",\"p\":\"non-koh-HEE-zhun\",\"o\":\"French\",\"y\":8,\"bp\":37,\"sy\":\"non.co.he.sion\",\"ps\":\"noun\",\"t\":[\"ofrench\"]},{\"w\":\"noncompaction\",\"d\":\"The absence of compaction; a state in which materials such as soil or sediment have not been compressed or densely packed together.\",\"s\":\"The engineer reported noncompaction in the soil, meaning it was too loose to support the building.\",\"p\":\"non-kum-PAK-shun\",\"o\":\"French\",\"y\":9,\"bp\":37,\"sy\":\"non.com.paction\",\"ps\":\"noun\",\"t\":[\"minerals\",\"ofrench\"]},{\"w\":\"noncomplex\",\"d\":\"Not complex or complicated; simple and straightforward in nature, structure, or design.\",\"s\":\"The teacher asked for a noncomplex explanation that even a younger student could understand.\",\"p\":\"non-KOM-pleks\",\"o\":\"French\",\"y\":8,\"bp\":29,\"sy\":\"non.com.plex\",\"ps\":\"adjective\",\"t\":[\"ofrench\"]},{\"w\":\"nonconceptualizable\",\"d\":\"Impossible to form into a clear mental concept or idea; too abstract or undefined to be thought of in concrete terms.\",\"s\":\"The philosopher argued that true infinity is nonconceptualizable because the human mind cannot fully grasp it.\",\"p\":\"non-kun-SEP-choo-ul-eye-zuh-bul\",\"o\":\"French\",\"y\":9,\"bp\":33,\"sy\":\"non.con.cep.tu.al.iz.able\",\"ps\":\"adjective\",\"t\":[\"ofrench\"]},{\"w\":\"nonconcert\",\"d\":\"A performance or event that does not follow the traditional format of a concert; an informal or unconventional musical gathering.\",\"s\":\"The band's nonconcert event was a casual meet-and-greet where no music was performed.\",\"p\":\"non-KON-surt\",\"o\":\"French\",\"y\":8,\"bp\":29,\"sy\":\"non.con.cert\",\"ps\":\"noun\",\"t\":[\"music\",\"festivals\",\"ofrench\"]},{\"w\":\"nonconsultant\",\"d\":\"A person who is not a professional consultant; someone who does not provide expert advice or guidance in a formal capacity.\",\"s\":\"As a nonconsultant employee, she worked directly in the store rather than advising from the outside.\",\"p\":\"non-kun-SUL-tunt\",\"o\":\"French\",\"y\":9,\"bp\":38,\"sy\":\"non.con.sul.tant\",\"ps\":\"noun\",\"t\":[\"character\",\"ofrench\"]},{\"w\":\"nonconversation\",\"d\":\"An exchange between people that lacks the qualities of a real conversation, such as genuine dialogue, meaning, or mutual engagement.\",\"s\":\"The two rivals sat in awkward nonconversation, staring at their phones rather than speaking.\",\"p\":\"non-kon-ver-SAY-shun\",\"o\":\"French\",\"y\":9,\"bp\":30,\"sy\":\"non.con.ver.sa.tion\",\"ps\":\"noun\",\"t\":[\"ofrench\"]},{\"w\":\"noncoralline\",\"d\":\"Not composed of or related to coral; describing marine or geological structures that are not made up of coral organisms or their remains.\",\"s\":\"The marine biologist identified the reef structure as noncoralline, built from rock rather than coral.\",\"p\":\"non-KOR-uh-lin\",\"o\":\"French\",\"y\":9,\"bp\":36,\"sy\":\"non.co.ralline\",\"ps\":\"adjective\",\"t\":[\"marine\",\"minerals\",\"ofrench\"]},{\"w\":\"noncoupon\",\"d\":\"Not involving or requiring a coupon; describing a sale, offer, or transaction that does not use discount vouchers or clipped certificates.\",\"s\":\"The store's noncoupon policy meant all prices were already discounted and no clipping was needed.\",\"p\":\"non-KOO-pon\",\"o\":\"French\",\"y\":9,\"bp\":26,\"sy\":\"non.coupon\",\"ps\":\"adjective\",\"t\":[\"ofrench\"]},{\"w\":\"noncult\",\"d\":\"Not belonging to or characteristic of a cult; describing a group, organization, or belief system that does not display controlling or extremist cult behaviors.\",\"s\":\"The spiritual group worked hard to prove it was a noncult organization with transparent leadership.\",\"p\":\"non-KULT\",\"o\":\"French\",\"y\":8,\"bp\":19,\"sy\":\"non.cult\",\"ps\":\"adjective\",\"t\":[\"logic\",\"ofrench\"]},{\"w\":\"nondeficit\",\"d\":\"Describing a financial situation or budget that does not have a shortfall or deficit; referring to something that operates without a spending gap.\",\"s\":\"The treasurer celebrated the nondeficit budget, proving the school had spent less than it earned.\",\"p\":\"non-DEF-ih-sit\",\"o\":\"French\",\"y\":8,\"bp\":29,\"sy\":\"non.d.eficit\",\"ps\":\"adjective\",\"t\":[\"ofrench\"]},{\"w\":\"nondemocrat\",\"d\":\"A person who does not belong to or support the Democratic Party, or more broadly, someone who does not believe in democratic principles or governance.\",\"s\":\"As a nondemocrat, he supported a system of government that didn't rely on elections.\",\"p\":\"non-DEM-oh-krat\",\"o\":\"French\",\"y\":8,\"bp\":35,\"sy\":\"non.demo.crat\",\"ps\":\"noun\",\"t\":[\"politics\",\"logic\",\"ofrench\"]},{\"w\":\"nondentist\",\"d\":\"A person who is not a licensed or trained dentist; someone who does not practice dentistry as a profession.\",\"s\":\"The nondentist health workers at the clinic could clean teeth but couldn't perform procedures.\",\"p\":\"non-DEN-tist\",\"o\":\"French\",\"y\":8,\"bp\":29,\"sy\":\"non.den.tist\",\"ps\":\"noun\",\"t\":[\"jobs\",\"character\",\"ofrench\"]},{\"w\":\"nondepot\",\"d\":\"A location or facility that does not function as a depot; a place that is not used for storing or distributing goods or as a transportation hub.\",\"s\":\"The packages were sent to a nondepot location, meaning they were delivered straight to homes.\",\"p\":\"non-DEE-poh\",\"o\":\"French\",\"y\":8,\"bp\":21,\"sy\":\"non.de.pot\",\"ps\":\"adjective\",\"t\":[\"ofrench\"]},{\"w\":\"nondesert\",\"d\":\"A region or area that is not classified as a desert; land that receives enough rainfall and supports vegetation rather than being arid and barren.\",\"s\":\"The researchers studied plants that thrive in nondesert climates where rainfall is plentiful.\",\"p\":\"non-DEZ-ert\",\"o\":\"French\",\"y\":8,\"bp\":26,\"sy\":\"non.desert\",\"ps\":\"adjective\",\"t\":[\"weather\",\"landforms\",\"ofrench\"]},{\"w\":\"nondessert\",\"d\":\"A food item or course that is not a sweet dessert; referring to any dish served that does not function as a sugary after-dinner treat.\",\"s\":\"She ordered a nondessert item from the menu, choosing a salad instead of cake.\",\"p\":\"non-deh-ZERT\",\"o\":\"French\",\"y\":9,\"bp\":27,\"sy\":\"non.dessert\",\"ps\":\"adjective\",\"t\":[\"culinary\",\"ofrench\"]},{\"w\":\"nondiplomat\",\"d\":\"A person who is not a trained or official diplomat; someone who does not represent a government in formal international relations.\",\"s\":\"As a nondiplomat, she was surprised to be invited to the international peace summit.\",\"p\":\"non-DIP-loh-mat\",\"o\":\"French\",\"y\":8,\"bp\":34,\"sy\":\"nondiplo.mat\",\"ps\":\"noun\",\"t\":[\"politics\",\"character\",\"ofrench\"]},{\"w\":\"nondisastrous\",\"d\":\"Describing a situation or outcome that does not result in disaster or extreme harm; not catastrophic or severely damaging.\",\"s\":\"Thankfully, the small mistake during the presentation was nondisastrous and everyone kept calm.\",\"p\":\"non-dih-ZAS-trus\",\"o\":\"French\",\"y\":9,\"bp\":37,\"sy\":\"nondis.as.trous\",\"ps\":\"adjective\",\"t\":[\"ofrench\"]},{\"w\":\"nondiscussion\",\"d\":\"A situation in which a topic or issue is deliberately not talked about or debated; the absence of open conversation or formal discussion.\",\"s\":\"The teacher's nondiscussion policy on certain sensitive topics frustrated many curious students.\",\"p\":\"non-dih-SKUS-shun\",\"o\":\"French\",\"y\":9,\"bp\":37,\"sy\":\"nondis.cus.sion\",\"ps\":\"noun\",\"t\":[\"ofrench\"]},{\"w\":\"nondoctrinal\",\"d\":\"Not based on or relating to a specific doctrine or set of established beliefs; free from rigid ideological or religious teachings.\",\"s\":\"The pastor took a nondoctrinal approach, focusing on personal stories rather than strict church rules.\",\"p\":\"non-DOK-trih-nul\",\"o\":\"French\",\"y\":8,\"bp\":38,\"sy\":\"non.doc.tri.nal\",\"ps\":\"adjective\",\"t\":[\"religion\",\"logic\",\"ofrench\"]},{\"w\":\"nondogmatic\",\"d\":\"Not insisting on fixed, unquestioned beliefs or rules; open-minded and willing to consider different ideas rather than following a strict doctrine.\",\"s\":\"Her nondogmatic teaching style encouraged students to question ideas and form their own opinions.\",\"p\":\"non-dog-MAT-ik\",\"o\":\"French\",\"y\":8,\"bp\":37,\"sy\":\"non.dog.mat.ic\",\"ps\":\"adjective\",\"t\":[\"logic\",\"ofrench\"]},{\"w\":\"nonallergy\",\"d\":\"The absence of an allergic response; a condition in which the immune system does not react abnormally to a substance that might cause allergies in others.\",\"s\":\"The doctor confirmed a nonallergy reaction, meaning the rash was caused by irritation rather than an immune response.\",\"p\":\"non-AL-er-jee\",\"o\":\"German\",\"y\":9,\"bp\":26,\"sy\":\"non.al.ler.gy\",\"ps\":\"noun\",\"t\":[\"disease\",\"onordic\"]},{\"w\":\"nonchromatin\",\"d\":\"Material within the cell nucleus that does not stain with standard chromatin dyes and is distinct from the chromatin that carries genetic information.\",\"s\":\"Researchers labeled the nonchromatin regions of the nucleus to better understand how DNA is organized.\",\"p\":\"non-KROH-mah-tin\",\"o\":\"German\",\"y\":9,\"bp\":31,\"sy\":\"nonchro.matin\",\"ps\":\"noun\",\"t\":[\"onordic\"]},{\"w\":\"noncobalt\",\"d\":\"Describing a material, compound, or alloy that does not contain cobalt as a component.\",\"s\":\"The manufacturer specified that the new blue pigment was noncobalt, making it safer and cheaper to produce.\",\"p\":\"non-KOH-bawlt\",\"o\":\"German\",\"y\":8,\"bp\":22,\"sy\":\"non.cobalt\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"onordic\"]},{\"w\":\"nonbankrupt\",\"d\":\"Describing an individual, business, or entity that has not declared bankruptcy and remains financially solvent and capable of meeting its financial obligations.\",\"s\":\"After years of careful budgeting and strategic investment, the small family business proudly remained nonbankrupt while several larger competitors around them had been forced to close their doors permanently.\",\"p\":\"non-BANK-rupt\",\"o\":\"Italian\",\"y\":8,\"bp\":30,\"sy\":\"non.bankrupt\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"oiberian\"]},{\"w\":\"noncarnival\",\"d\":\"Describing something that is not associated with, characteristic of, or related to a carnival; lacking the festive, colorful, or entertainment-focused qualities of a carnival atmosphere.\",\"s\":\"The city council insisted on a quiet, noncarnival atmosphere for the memorial ceremony, requesting that vendors and street performers keep well away from the solemn gathering at the park.\",\"p\":\"non-KAR-nih-vul\",\"o\":\"Italian\",\"y\":8,\"bp\":33,\"sy\":\"non.car.ni.val\",\"ps\":\"adjective\",\"t\":[\"festivals\",\"colors\",\"oiberian\"]},{\"w\":\"noncasino\",\"d\":\"Describing a venue, environment, or activity that does not involve or is not associated with casino gambling; not related to or operated as a casino.\",\"s\":\"The resort marketed itself as a family-friendly, noncasino destination, emphasizing its hiking trails, swimming pools, and nature programs rather than any form of gambling or gaming entertainment.\",\"p\":\"non-kuh-SEE-noh\",\"o\":\"Italian\",\"y\":9,\"bp\":24,\"sy\":\"non.casi.no\",\"ps\":\"adjective\",\"t\":[\"ecology\",\"oiberian\"]},{\"w\":\"noncoffee\",\"d\":\"Describing a beverage, product, or establishment that does not contain coffee or is not associated with coffee; used to distinguish alternatives from coffee-based drinks or offerings.\",\"s\":\"The café added an entire noncoffee menu to cater to customers who preferred herbal teas, fruit smoothies, and hot chocolate over any of the espresso-based drinks it was famous for.\",\"p\":\"non-KAW-fee\",\"o\":\"Italian\",\"y\":9,\"bp\":24,\"sy\":\"non.cof.fee\",\"ps\":\"adjective\",\"t\":[\"dishes\",\"oiberian\"]},{\"w\":\"nonabandoned\",\"d\":\"Describing something or someone that has not been left behind, deserted, or given up on by those responsible for its care.\",\"s\":\"The nonabandoned building was still occupied by a family who refused to leave the old neighborhood.\",\"p\":\"non-uh-BAN-dund\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.a.ban.doned\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonabdominal\",\"d\":\"Describing something that does not relate to, originate in, or involve the abdomen or abdominal region of the body.\",\"s\":\"The doctor confirmed the pain was nonabdominal, originating from the chest rather than the belly.\",\"p\":\"non-ab-DOM-ih-nul\",\"o\":\"Latin\",\"y\":8,\"bp\":39,\"sy\":\"non.ab.dom.i.nal\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonabductive\",\"d\":\"Describing reasoning or logic that does not rely on abductive inference, which is the process of forming a probable explanation from limited evidence.\",\"s\":\"The logician classified the argument as nonabductive because it relied on strict rules rather than inference.\",\"p\":\"non-ab-DUK-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.ab.duc.tive\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonabelian\",\"d\":\"In mathematics, describing a group or algebraic structure in which the order of operations matters, meaning that combining two elements in different orders can produce different results.\",\"s\":\"In nonabelian groups, the order in which you combine elements actually changes the result.\",\"p\":\"non-ay-BEE-lee-un\",\"o\":\"Latin\",\"y\":7,\"bp\":27,\"sy\":\"non.abelian\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonability\",\"d\":\"The state or condition of lacking a particular skill, power, or capacity to perform a specific action or task.\",\"s\":\"The coach documented the player's nonability to follow the team's defensive strategy.\",\"p\":\"non-uh-BIL-ih-tee\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.abil.i.ty\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonablated\",\"d\":\"Describing material or tissue that has not been removed, worn away, or destroyed through ablation, such as by heat, surgery, or erosion.\",\"s\":\"The nonablated tissue surrounding the tumor was carefully preserved during the procedure.\",\"p\":\"non-uh-BLAY-ted\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.ab.lat.ed\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonablative\",\"d\":\"Describing a process, treatment, or material that does not involve removing or destroying surface tissue or material through burning, cutting, or erosion.\",\"s\":\"The dermatologist recommended a nonablative laser treatment that improves skin without removing any layers.\",\"p\":\"non-AB-luh-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"non.ab.la.tive\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonabnormal\",\"d\":\"Describing something that is not abnormal, meaning it falls within expected or typical parameters and does not deviate from the norm.\",\"s\":\"The test results were nonabnormal, indicating the patient's health was within expected ranges.\",\"p\":\"non-ab-NOR-mul\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.ab.nor.mal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonaboriginal\",\"d\":\"Describing people, cultures, or things that are not indigenous or native to a particular region, having arrived or developed there after the original inhabitants.\",\"s\":\"The survey compared the health outcomes of aboriginal and nonaboriginal communities across the country.\",\"p\":\"non-ab-uh-RIJ-ih-nul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.a.bo.rig.i.nal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonabortive\",\"d\":\"Describing a process or attempt that is not cut short, failed, or terminated before completion, especially one that reaches its intended outcome.\",\"s\":\"The scientists celebrated the nonabortive mission as a complete success from launch to landing.\",\"p\":\"non-uh-BOR-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"sy\":\"non.abortive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonabrasive\",\"d\":\"Describing a substance, material, or manner of interaction that does not scratch, scrape, or wear away surfaces, or that is gentle and inoffensive in tone.\",\"s\":\"The jeweler cleaned the delicate bracelet with a nonabrasive cloth to avoid scratching it.\",\"p\":\"non-uh-BRAY-siv\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"sy\":\"nonabra.sive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonabsence\",\"d\":\"The state of being present rather than absent; the condition in which someone or something is not missing from an expected place or situation.\",\"s\":\"The attendance record showed a nonabsence streak of fifty days for the dedicated student.\",\"p\":\"non-AB-suns\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.ab.sence\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonabsorbed\",\"d\":\"Describing a substance or material that has not been taken in, soaked up, or incorporated into another material or system.\",\"s\":\"The nonabsorbed liquid pooled on the waterproof jacket's surface and dripped off.\",\"p\":\"non-ab-ZORBD\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.ab.sorbed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonabsorbent\",\"d\":\"not capable of absorbing or soaking up (liquids)\",\"s\":\"Plastic wrap is nonabsorbent, which is why it keeps moisture sealed inside the package.\",\"p\":\"non-ab-ZOR-bunt\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"non.ab.sorbent\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonabsorbing\",\"d\":\"Describing a material or surface that does not take in or soak up liquids, energy, or other substances that come into contact with it.\",\"s\":\"The nonabsorbing surface of the glass table made cleanup quick and easy.\",\"p\":\"non-ab-ZOR-bing\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.ab.sorb.ing\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonabsorptive\",\"d\":\"not capable of absorbing or soaking up (liquids)\",\"s\":\"The scientist noted that the nonabsorptive membrane allowed water to pass through without retaining any.\",\"p\":\"non-ab-ZORP-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.ab.sorp.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonabstract\",\"d\":\"Describing something that is concrete, tangible, or directly observable rather than theoretical, conceptual, or difficult to define.\",\"s\":\"The teacher asked for a nonabstract example, so the student pointed to a real apple on the desk.\",\"p\":\"non-AB-strakt\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.ab.stract\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonabstractive\",\"d\":\"Describing a process or approach that does not involve abstracting, generalizing, or drawing ideas away from their concrete, specific forms.\",\"s\":\"His nonabstractive writing style used concrete details instead of vague, general ideas.\",\"p\":\"non-ab-STRAK-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.ab.strac.tive\",\"ps\":\"adjective\",\"t\":[\"painting\",\"olatin\"]},{\"w\":\"nonabused\",\"d\":\"Describing a person or thing that has not been subjected to mistreatment, misuse, harm, or exploitation by others.\",\"s\":\"Researchers compared the behavior of nonabused children with those who had experienced hardship.\",\"p\":\"non-uh-BYOOZD\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonabuser\",\"d\":\"A person who does not engage in the abuse of substances, other people, or positions of power or trust.\",\"s\":\"The counselor distinguished between users, abusers, and nonabusers in her presentation on substance education.\",\"p\":\"non-uh-BYOO-zur\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"nonabus.er\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonabusive\",\"d\":\"Describing behavior, language, or a relationship that is not harmful, cruel, or exploitative toward another person or group.\",\"s\":\"The program taught families how to maintain nonabusive communication during disagreements.\",\"p\":\"non-uh-BYOO-siv\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nonabu.sive\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonabusively\",\"d\":\"In a manner that is not harmful, cruel, or exploitative; describing actions carried out with respect and without causing injury or distress to others.\",\"s\":\"She explained her frustration nonabusively, keeping her voice calm and her words respectful.\",\"p\":\"non-uh-BYOO-siv-lee\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"nonabu.sive.ly\",\"ps\":\"adverb\",\"t\":[\"olatin\"]},{\"w\":\"nonabutting\",\"d\":\"Describing two areas, structures, or properties that do not share a common boundary or directly touch one another.\",\"s\":\"The architect designed the nonabutting walls with a gap between them to allow for ventilation.\",\"p\":\"non-uh-BUT-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"sy\":\"nonabut.ting\",\"ps\":\"adjective\",\"t\":[\"maps\",\"olatin\"]},{\"w\":\"nonacademic\",\"d\":\"Describing activities, subjects, or people that are not related to formal education, scholarly study, or the traditions and standards of academic institutions.\",\"s\":\"The principal offered nonacademic clubs like cooking and chess to engage students beyond the classroom.\",\"p\":\"nah-na-kuh-DEH-mih-k\",\"o\":\"Latin\",\"y\":7,\"bp\":26,\"sy\":\"naa.nae.kah.deh.mih.k\",\"ps\":\"adjective\",\"t\":[\"festivals\",\"olatin\"]},{\"w\":\"nonacademically\",\"d\":\"In a manner that is not related to or guided by academic standards, formal schooling, or scholarly methods of learning and inquiry.\",\"s\":\"She expressed her creativity nonacademically through painting and music rather than essays and exams.\",\"p\":\"non-ak-uh-DEM-ih-klee\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"nonaca.dem.i.cal.ly\",\"ps\":\"adverb\",\"t\":[\"olatin\"]},{\"w\":\"nonaccelerated\",\"d\":\"Describing a course, program, or process that does not move at a faster than normal pace and follows a standard or regular schedule.\",\"s\":\"The car rolled down the gentle hill at a nonaccelerated, steady pace.\",\"p\":\"non-ak-SEL-uh-ray-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"nonac.cel.er.at.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonaccelerating\",\"d\":\"Describing something that is not increasing in speed, rate, or intensity and is maintaining a steady or unchanging pace.\",\"s\":\"The train moved at a nonaccelerating speed through the quiet countryside.\",\"p\":\"non-ak-SEL-uh-ray-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"nonac.cel.er.at.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonaccented\",\"d\":\"Describing a syllable, letter, or spoken sound that does not receive stress or emphasis when a word is pronounced aloud.\",\"s\":\"The nonaccented syllables in the word 'banana' are easy to overlook when speaking quickly.\",\"p\":\"non-AK-sen-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"nonac.cent.ed\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonacceptance\",\"d\":\"the act of refusing an offer\",\"p\":\"non-ak-SEP-tuns\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nonac.cep.tance\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonaccepted\",\"d\":\"Describing a proposal, application, idea, or person that has not been approved, welcomed, or agreed upon by others.\",\"s\":\"The nonaccepted proposal was sent back to the committee for major revisions.\",\"p\":\"non-ak-SEP-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"nonac.cept.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonaccepting\",\"d\":\"Describing an attitude, policy, or entity that is unwilling to receive, approve, or welcome something or someone.\",\"s\":\"The nonaccepting attitude of the judges made the young artist feel discouraged.\",\"p\":\"non-ak-SEP-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"nonac.cept.ing\",\"ps\":\"adjective\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"nonaccidental\",\"d\":\"Describing an event, injury, or outcome that did not happen by chance but was instead caused deliberately or through negligence.\",\"s\":\"Investigators determined the fire was nonaccidental, meaning someone had started it on purpose.\",\"p\":\"non-ak-sih-DEN-tul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"nonac.ci.den.tal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonaccommodative\",\"d\":\"Describing a person, policy, or system that does not adjust, adapt, or make special provisions to meet the needs or preferences of others.\",\"s\":\"The nonaccommodative landlord refused to make any changes to the lease agreement.\",\"p\":\"non-uh-KOM-uh-day-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"nonac.com.moda.tive\",\"ps\":\"adjective\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"nonaccomplishment\",\"d\":\"an act that does not achieve its intended goal\",\"s\":\"Despite months of effort, the project ended in nonaccomplishment when the funding ran out.\",\"p\":\"non-uh-KOM-plish-munt\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"nonac.com.plish.ment\",\"ps\":\"noun\",\"t\":[\"sports\",\"olatin\"]},{\"w\":\"nonaccountability\",\"d\":\"The condition or quality of not being required to explain, justify, or take responsibility for one's actions or decisions.\",\"s\":\"The team's nonaccountability for mistakes led to repeated errors throughout the season.\",\"p\":\"non-uh-kown-tuh-BIL-ih-tee\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"nonac.count.abil.i.ty\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonaccountable\",\"d\":\"Describing a person or organization that is not required or expected to answer for their actions, decisions, or use of resources.\",\"s\":\"When leaders are nonaccountable, trust in the organization quickly disappears.\",\"p\":\"non-uh-KOWN-tuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"nonac.count.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonaccountant\",\"d\":\"A person who is not a trained or certified accountant and does not work professionally in the field of accounting or financial record-keeping.\",\"s\":\"As a nonaccountant, she needed help understanding the complex tax forms.\",\"p\":\"non-uh-KOWN-tunt\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nonac.coun.tant\",\"ps\":\"noun\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nonaccounting\",\"d\":\"Not related to or involving the practice of accounting, financial record-keeping, or the tracking of monetary transactions.\",\"s\":\"The nonaccounting staff at the firm handled customer service and marketing instead of finances.\",\"p\":\"non-uh-KOWN-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nonac.count.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonaccredited\",\"d\":\"Not officially recognized or certified by an authoritative body; lacking formal approval or accreditation.\",\"s\":\"The nonaccredited school could not issue diplomas recognized by most employers.\",\"p\":\"non-uh-KRED-ih-tid\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"nonac.cred.it.ed\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"nonaccrual\",\"d\":\"Describing a loan or financial asset on which interest or income is no longer being accumulated or recognized, typically because the borrower has defaulted.\",\"s\":\"The bank placed the loan on nonaccrual status because the borrower had missed several payments.\",\"p\":\"nah-nuh-KROO-uh-l\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"naa.nah.kruw.ah.l\",\"ps\":\"adjective\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nonaccusative\",\"d\":\"In grammar, describing a verb or construction that does not take a direct object in the accusative case; not functioning in an accusative role.\",\"s\":\"In grammar class, we studied how nonaccusative verbs behave differently from action verbs.\",\"p\":\"non-uh-KYOO-zuh-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":23,\"sy\":\"nonac.cusative\",\"ps\":\"adjective\",\"t\":[\"law\",\"wordwords\",\"olatin\"]},{\"w\":\"nonaccusatory\",\"d\":\"Not making or implying an accusation; free from blame or charges directed at another person.\",\"s\":\"The teacher's nonaccusatory tone made students feel safe admitting their mistakes.\",\"p\":\"non-uh-KYOO-zuh-tor-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nonac.cusato.ry\",\"ps\":\"adjective\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"nonacetate\",\"d\":\"A substance or material that does not contain or consist of acetate, the salt or ester of acetic acid.\",\"s\":\"The chemist chose a nonacetate solvent to avoid the sharp smell associated with acetate compounds.\",\"p\":\"non-AS-ih-tayt\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nonac.etate\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonacicular\",\"d\":\"Not needle-shaped or pointed like a needle; describing a structure or crystal that lacks a slender, sharp form.\",\"s\":\"The nonacicular crystals were rounded and smooth rather than sharp and needle-like.\",\"p\":\"non-uh-SIK-yoo-ler\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"nonaci.c.u.lar\",\"ps\":\"adjective\",\"t\":[\"minerals\",\"olatin\"]},{\"w\":\"nonacidic\",\"d\":\"Not having the properties of an acid; not sour, corrosive, or having a pH below seven.\",\"s\":\"The nonacidic shampoo was gentle enough to use on sensitive scalps every day.\",\"p\":\"non-uh-SID-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonacidotic\",\"d\":\"Not characterized by or relating to acidosis; describing a condition in which the body's fluids do not have an abnormally high acid level.\",\"s\":\"The doctor was relieved to find the patient's blood was nonacidotic after treatment.\",\"p\":\"non-as-ih-DOT-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"nonaci.dot.ic\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"character\",\"olatin\"]},{\"w\":\"nonacquired\",\"d\":\"Not obtained through learning, experience, or outside influence; present from birth rather than developed over time.\",\"s\":\"Researchers debated whether the trait was nonacquired, meaning it was present from birth.\",\"p\":\"non-uh-KWIYRD\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"sy\":\"nonac.quired\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nonacquisition\",\"d\":\"The failure or absence of acquiring something, such as property, a company, or a skill; a situation in which no purchase or takeover takes place.\",\"s\":\"The company's nonacquisition of the smaller firm disappointed investors who expected a merger.\",\"p\":\"non-ak-wih-ZIH-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nonac.qui.si.tion\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonacquisitive\",\"d\":\"Not driven by the desire to acquire or accumulate wealth, possessions, or power; lacking a greedy or materialistic nature.\",\"s\":\"Her nonacquisitive nature meant she was happiest with few possessions and simple surroundings.\",\"p\":\"non-uh-KWIZ-ih-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nonac.quis.i.tive\",\"ps\":\"adjective\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nonacrimonious\",\"d\":\"Not bitter, harsh, or resentful in tone or manner; characterized by a pleasant and agreeable attitude rather than hostility.\",\"s\":\"Their nonacrimonious divorce surprised friends who expected bitter arguments over every detail.\",\"p\":\"non-ak-rih-MOH-nee-us\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nonac.ri.mo.nious\",\"ps\":\"adjective\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nonacting\",\"d\":\"Not involved in or related to the performance of acting; describing a person or role that does not involve theatrical or dramatic performance.\",\"s\":\"The director gave the nonacting crew members credit for making the film's sets look spectacular.\",\"p\":\"non-AK-ting\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.act.ing\",\"ps\":\"adjective\",\"t\":[\"stage\",\"olatin\"]},{\"w\":\"nonactinide\",\"d\":\"Any chemical element that does not belong to the actinide series, the group of fifteen metallic elements with atomic numbers 89 through 103.\",\"s\":\"The scientist compared the radioactive actinides to nonactinide elements that are far more stable.\",\"p\":\"non-AK-tih-nyd\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.ac.tinide\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"numbers\",\"olatin\"]},{\"w\":\"nonaction\",\"d\":\"The state or condition of not taking action; deliberate or unintentional inactivity or failure to act.\",\"s\":\"Sometimes nonaction is the wisest choice, as rushing in can make a problem worse.\",\"p\":\"non-AK-shun\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.ac.tion\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonactivation\",\"d\":\"The absence of activation; the state in which something, such as a system, gene, or chemical process, has not been triggered or switched on.\",\"s\":\"The nonactivation of the alarm system during the storm was a serious safety concern.\",\"p\":\"non-ak-tih-VAY-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.ac.ti.va.tion\",\"ps\":\"noun\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonactor\",\"d\":\"A person who is not a professional actor; someone who appears in a film, play, or production without formal acting training or experience.\",\"s\":\"The documentary featured a nonactor playing himself, which made the story feel incredibly real.\",\"p\":\"non-AK-ter\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.ac.tor\",\"ps\":\"noun\",\"t\":[\"stage\",\"character\",\"olatin\"]},{\"w\":\"nonactuarial\",\"d\":\"Not based on or relating to actuarial science, which uses statistics and mathematics to assess financial risk, especially in insurance.\",\"s\":\"The insurance estimate was nonactuarial, meaning it was based on guesses rather than statistical data.\",\"p\":\"non-ak-choo-AIR-ee-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":41,\"sy\":\"non.ac.tu.ar.i.al\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonadaptable\",\"d\":\"Unable or unwilling to change or adjust to new conditions, environments, or requirements.\",\"s\":\"The nonadaptable old computer program crashed whenever the operating system was updated.\",\"p\":\"non-uh-DAP-tuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.adapt.able\",\"ps\":\"adjective\",\"t\":[\"ecology\",\"olatin\"]},{\"w\":\"nonadapting\",\"d\":\"Not in the process of adjusting or changing to suit new conditions or environments; remaining unchanged in the face of new circumstances.\",\"s\":\"The nonadapting species struggled to survive as the climate around it rapidly changed.\",\"p\":\"non-uh-DAP-ting\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.adapt.ing\",\"ps\":\"adjective\",\"t\":[\"ecology\",\"olatin\"]},{\"w\":\"nonadaptive\",\"d\":\"(of a trait or condition) failing to serve an adjustive purpose\",\"p\":\"non-uh-DAP-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.adap.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonaddict\",\"d\":\"A person who is not addicted to a substance or behavior; someone who does not exhibit the compulsive dependence characteristic of addiction.\",\"s\":\"As a nonaddict, she had never felt the pull of cigarettes that her friends described.\",\"p\":\"non-AD-ikt\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.ad.dict\",\"ps\":\"noun\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nonaddicted\",\"d\":\"Not physically or psychologically dependent on a substance or behavior; free from the compulsive need associated with addiction.\",\"s\":\"The study compared brain scans of addicted patients with those of nonaddicted volunteers.\",\"p\":\"non-uh-DIK-tid\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"non.ad.dict.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonadditive\",\"d\":\"Describing a situation in which the combined effect of two or more factors is not simply the sum of their individual effects; involving interaction rather than simple addition.\",\"s\":\"In genetics, some traits are nonadditive, meaning they don't simply stack up from both parents.\",\"p\":\"non-AD-ih-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"non.ad.di.tive\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonadditivity\",\"d\":\"The property or quality of a system in which the total effect cannot be calculated by simply adding together the individual parts or components.\",\"s\":\"The nonadditivity of certain chemical reactions makes predicting their outcomes much more complex.\",\"p\":\"non-ad-ih-TIV-ih-tee\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.ad.di.tiv.i.ty\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonaddressed\",\"d\":\"Not having a specific address assigned; describing mail, data packets, or communications that lack a designated recipient or destination.\",\"s\":\"The nonaddressed envelopes were sorted separately since no one knew where to deliver them.\",\"p\":\"non-uh-DREST\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.ad.dressed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonadenocarcinomatous\",\"d\":\"Not of or relating to adenocarcinoma, a type of cancer that originates in glandular tissue; describing a tumor or condition that lacks the characteristics of adenocarcinoma.\",\"s\":\"The pathologist confirmed the tumor was nonadenocarcinomatous, ruling out that particular cancer type.\",\"p\":\"non-ad-eh-noh-kar-sih-NOH-muh-tus\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.ade.no.car.ci.no.ma.tous\",\"ps\":\"adjective\",\"t\":[\"body\",\"disease\",\"olatin\"]},{\"w\":\"nonadherent\",\"d\":\"Not sticking or clinging to a surface; also, not following or complying with a rule, guideline, or belief.\",\"s\":\"The nonadherent bandage slipped off the wound within hours of being applied.\",\"p\":\"non-ad-HEER-ent\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.ad.her.ent\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonadiabatically\",\"d\":\"In a manner that involves the exchange of heat with the surroundings; describing a thermodynamic process that does not occur without heat transfer.\",\"s\":\"The gas expanded nonadiabatically, exchanging heat with its surroundings throughout the process.\",\"p\":\"non-ay-dee-uh-BAT-ih-kuh-lee\",\"o\":\"Latin\",\"y\":9,\"bp\":33,\"sy\":\"nona.di.a.bat.i.cal.ly\",\"ps\":\"adverb\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonadiabaticity\",\"d\":\"The property of a thermodynamic process in which heat is exchanged with the surroundings, as opposed to occurring without any heat transfer.\",\"s\":\"Scientists measured the nonadiabaticity of the reaction to determine how much heat was transferred.\",\"p\":\"non-ay-dee-uh-buh-TIS-ih-tee\",\"o\":\"Latin\",\"y\":9,\"bp\":31,\"sy\":\"nona.di.a.batic.i.ty\",\"ps\":\"noun\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonadipose\",\"d\":\"Not consisting of, relating to, or resembling fatty tissue; describing tissue or cells that are not of the adipose type.\",\"s\":\"The researcher focused on nonadipose tissue to study how non-fat cells respond to inflammation.\",\"p\":\"non-AD-ih-pohz\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nonadi.pose\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonadjacent\",\"d\":\"not adjacent; not next\",\"s\":\"The two nonadjacent classrooms were connected by a long hallway rather than sharing a wall.\",\"p\":\"non-uh-JAY-sent\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.ad.ja.cent\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonadjectival\",\"d\":\"Not functioning as or relating to an adjective; describing a word, phrase, or grammatical form that does not modify a noun.\",\"s\":\"The grammar teacher explained that the word 'quickly' has a nonadjectival function because it modifies a verb, not a noun.\",\"p\":\"non-ad-jek-TY-vul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.ad.jec.ti.val\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonadjoint\",\"d\":\"In mathematics, describing an operator or matrix that is not equal to its own adjoint, meaning it does not satisfy the condition of self-adjointness.\",\"s\":\"The mathematician noted that the operator was nonadjoint and therefore required a different solution method.\",\"p\":\"non-AD-joynt\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.ad.joint\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonadjunctive\",\"d\":\"Not serving as or relating to an adjunct; not functioning as an additional or supplementary element added to a main structure.\",\"s\":\"The clause was nonadjunctive, meaning it did not add optional extra information to the main sentence.\",\"p\":\"non-uh-JUNK-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.ad.junc.tive\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"numbers\",\"olatin\"]},{\"w\":\"nonadjusted\",\"d\":\"Not changed, corrected, or modified to account for new information, conditions, or variables; remaining in its original, unaltered state.\",\"s\":\"The nonadjusted figures showed the raw sales data before any seasonal corrections were made.\",\"p\":\"non-uh-JUS-tid\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.ad.just.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonadjusting\",\"d\":\"Not making changes or corrections in response to new conditions or information; failing or refusing to alter settings or behavior.\",\"s\":\"The nonadjusting lens kept the same focus no matter how far away the subject stood.\",\"p\":\"non-uh-JUS-ting\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.ad.just.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonadjustive\",\"d\":\"Not designed or able to make adjustments; not serving the purpose of helping something adapt or function properly in varying conditions.\",\"s\":\"Critics argued that the nonadjustive policy failed to respond to changing economic conditions.\",\"p\":\"non-uh-JUS-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.ad.jus.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonadministrator\",\"d\":\"A person who does not hold an administrative role or position; someone who lacks the authority or responsibility of an administrator.\",\"s\":\"As a nonadministrator, she couldn't access the school's restricted computer files.\",\"p\":\"non-ad-MIN-ih-stray-ter\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.ad.min.is.tra.tor\",\"ps\":\"noun\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"nonadmirer\",\"d\":\"A person who does not admire or hold a favorable opinion of someone or something; one who feels no particular respect or appreciation toward a subject.\",\"s\":\"Even as a nonadmirer of modern art, he admitted the sculpture was strikingly unusual.\",\"p\":\"non-ad-MY-rer\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.ad.mir.er\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonadmission\",\"d\":\"The state or act of not being admitted or allowed entry; a refusal or failure to grant access, membership, or acknowledgment.\",\"s\":\"The student's nonadmission to the honor society came as a surprising disappointment.\",\"p\":\"non-ad-MISH-un\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.ad.mis.sion\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonadolescent\",\"d\":\"A person who is not in the adolescent stage of development; someone who is either younger than a teenager or already past that phase of life.\",\"s\":\"The study compared the sleep habits of nonadolescent children with those of teenagers.\",\"p\":\"non-ad-uh-LES-unt\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.ado.les.cent\",\"ps\":\"noun\",\"t\":[\"stage\",\"character\",\"olatin\"]},{\"w\":\"nonadopted\",\"d\":\"Not having been taken in or chosen through a formal adoption process; describing a child or idea that was never officially adopted by another family or group.\",\"s\":\"The nonadopted proposal was shelved until the committee could review it again next year.\",\"p\":\"non-uh-DOP-ted\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.adopt.ed\",\"ps\":\"adjective\",\"t\":[\"kinship\",\"olatin\"]},{\"w\":\"nonadopter\",\"d\":\"A person or organization that does not adopt a new practice, technology, policy, or child; one who chooses not to take something on.\",\"s\":\"As a nonadopter of smartphones, my grandfather still uses a flip phone for all his calls.\",\"p\":\"non-uh-DOP-ter\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.adopter\",\"ps\":\"noun\",\"t\":[\"politics\",\"kinship\",\"olatin\"]},{\"w\":\"nonadopting\",\"d\":\"Not in the process of adopting; describing an entity that is choosing not to take on a new rule, practice, child, or idea.\",\"s\":\"The nonadopting nations refused to sign the new environmental treaty.\",\"p\":\"non-uh-DOP-ting\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.adopt.ing\",\"ps\":\"adjective\",\"t\":[\"kinship\",\"olatin\"]},{\"w\":\"nonadrenal\",\"d\":\"Not relating to or originating from the adrenal glands; describing tissues, hormones, or conditions that have no connection to those glands located above the kidneys.\",\"s\":\"The hormone was traced to a nonadrenal source, surprising the research team.\",\"p\":\"non-uh-DREE-nul\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.a.drenal\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonadrenergic\",\"d\":\"Not activated by or responding to adrenaline or similar substances; describing nerve pathways or receptors that use a different chemical signaling system.\",\"s\":\"The nonadrenergic nerve fibers used a different chemical messenger than adrenaline.\",\"p\":\"non-ad-ruh-NER-jik\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.a.dren.er.gic\",\"ps\":\"adjective\",\"t\":[\"body\",\"chemistry\",\"olatin\"]},{\"w\":\"nonadsorbed\",\"d\":\"Not collected or held onto the surface of a material; describing a substance that passes by a surface without sticking or accumulating on it.\",\"s\":\"The nonadsorbed particles passed straight through the filter without clinging to its surface.\",\"p\":\"non-ad-ZORBD\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.ad.sorbed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonadsorbent\",\"d\":\"lacking a capacity to adsorb or cause to accumulate on a surface\",\"s\":\"The nonadsorbent material was chosen because scientists didn't want any chemicals sticking to it.\",\"p\":\"non-ad-ZOR-bent\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.ad.sor.bent\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonadsorptive\",\"d\":\"lacking a capacity to adsorb or cause to accumulate on a surface\",\"s\":\"The nonadsorptive coating on the tank prevented any buildup of residue on the inner walls.\",\"p\":\"non-ad-ZORP-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.ad.sorp.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonadulterated\",\"d\":\"Not mixed with inferior, foreign, or harmful substances; describing something that remains in its pure, original, unmodified state.\",\"s\":\"The label claimed the juice was nonadulterated, meaning it contained no artificial additives.\",\"p\":\"non-uh-DUL-tuh-ray-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nonadul.ter.at.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonadvanced\",\"d\":\"Not at an advanced level or stage; describing something or someone that has not progressed beyond a basic or early point in development or skill.\",\"s\":\"Students in the nonadvanced track still covered core math skills but at a slower pace.\",\"p\":\"non-ad-VANST\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.ad.vanced\",\"ps\":\"adjective\",\"t\":[\"stage\",\"olatin\"]},{\"w\":\"nonadvantageous\",\"d\":\"Not providing any benefit, gain, or favorable outcome; describing a situation or condition that offers no particular advantage to those involved.\",\"s\":\"Signing the contract under such nonadvantageous terms would hurt the company's profits.\",\"p\":\"non-ad-van-TAY-jus\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.ad.van.ta.geous\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonadventure\",\"d\":\"An experience or activity that is completely ordinary and uneventful, lacking any excitement, risk, or exploration associated with a true adventure.\",\"s\":\"He jokingly called his uneventful camping trip a total nonadventure after nothing exciting happened.\",\"p\":\"non-ad-VEN-chur\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.ad.ven.ture\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonadventurous\",\"d\":\"Not inclined to seek out new experiences, risks, or excitement; describing a person or approach that prefers safety, routine, and the familiar over bold exploration.\",\"s\":\"Her nonadventurous personality meant she preferred cozy movie nights over hiking steep mountains.\",\"p\":\"non-ad-VEN-chur-us\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.ad.ven.tur.ous\",\"ps\":\"adjective\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nonadverbial\",\"d\":\"Not functioning as or relating to an adverb; describing a word, phrase, or clause that does not modify a verb, adjective, or another adverb.\",\"s\":\"The teacher marked the phrase as nonadverbial since it described a noun rather than modifying a verb.\",\"p\":\"non-ad-VER-bee-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.ad.ver.bial\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonadversarial\",\"d\":\"Not involving opposition, conflict, or a combative relationship between parties; describing an interaction or setting characterized by cooperation and mutual respect rather than rivalry.\",\"s\":\"The mediator encouraged a nonadversarial discussion so both sides could find common ground.\",\"p\":\"non-ad-ver-SAIR-ee-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.ad.ver.sar.i.al\",\"ps\":\"adjective\",\"t\":[\"character\",\"war\",\"olatin\"]},{\"w\":\"nonadvertised\",\"d\":\"Not publicly promoted or announced through any form of advertising; describing a product, event, or deal that has not been brought to wide public attention.\",\"s\":\"The nonadvertised sale was only available to loyal customers who had signed up for the newsletter.\",\"p\":\"non-AD-ver-tyzd\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.ad.ver.tised\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonadvertising\",\"d\":\"Not engaged in or related to the promotion of products, services, or ideas through paid or public media; describing content or organizations that avoid commercial promotion.\",\"s\":\"The nonadvertising brand relied entirely on word-of-mouth to attract new customers.\",\"p\":\"non-AD-ver-ty-zing\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.ad.ver.tis.ing\",\"ps\":\"adjective\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nonadvisory\",\"d\":\"Not limited to giving advice or recommendations; describing a role, body, or function that has actual decision-making or executive authority rather than merely suggesting courses of action.\",\"s\":\"The committee held a nonadvisory role, meaning its decisions were binding rather than merely suggested.\",\"p\":\"non-ad-VY-zuh-ree\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.ad.vi.so.ry\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"nonadvocacy\",\"d\":\"The absence of active support or promotion of a particular cause, policy, or position; describing an approach that deliberately avoids championing any specific agenda.\",\"s\":\"The organization's strict nonadvocacy policy meant it could not publicly support any political candidate.\",\"p\":\"non-AD-vuh-kuh-see\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.ad.vo.ca.cy\",\"ps\":\"noun\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"nonaerated\",\"d\":\"Not having had air or gas introduced into it; describing a liquid or substance, such as still water, that contains no added bubbles or dissolved gases.\",\"s\":\"The nonaerated water lacked the fizzing bubbles that give sparkling water its refreshing bite.\",\"p\":\"non-AIR-ay-ted\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.aer.at.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonaerial\",\"d\":\"Not existing in, coming from, or related to the air; describing roots, organisms, or structures that grow or function at or below ground level rather than above it.\",\"s\":\"The nonaerial roots grew beneath the soil rather than hanging exposed in open air.\",\"p\":\"non-AIR-ee-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.aeri.al\",\"ps\":\"adjective\",\"t\":[\"botany\",\"olatin\"]},{\"w\":\"nonaerobiotic\",\"d\":\"Not requiring oxygen or air to survive and function; describing organisms or biological processes that can exist and thrive in environments completely without oxygen.\",\"s\":\"The nonaerobiotic bacteria thrived in the oxygen-free environment deep inside the sealed tank.\",\"p\":\"non-air-oh-by-OT-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.aer.o.bi.ot.ic\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"ecology\",\"olatin\"]},{\"w\":\"nonaerodynamic\",\"d\":\"Not designed to move efficiently through the air; describing a shape or object that creates significant drag and resistance rather than flowing smoothly through airflow.\",\"s\":\"The nonaerodynamic brick-shaped vehicle struggled against wind resistance on the highway.\",\"p\":\"non-air-oh-dy-NAM-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.aero.dy.nam.ic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonaeronautical\",\"d\":\"Not related to the science, practice, or technology of flight or aircraft navigation; describing fields, objects, or activities that have no connection to aviation or aeronautics.\",\"s\":\"The engineer's background was nonaeronautical, so she had to study aviation systems from scratch.\",\"p\":\"non-air-uh-NAW-tih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.aero.nau.ti.cal\",\"ps\":\"adjective\",\"t\":[\"maps\",\"vehicles\",\"olatin\"]},{\"w\":\"nonaerosol\",\"d\":\"Not delivered or contained in a pressurized spray can; describing a product, such as a pump spray or liquid, that does not use aerosol technology to disperse its contents.\",\"s\":\"The company switched to a nonaerosol pump spray to reduce its environmental impact.\",\"p\":\"non-AIR-uh-sol\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.aerosol\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonaerospace\",\"d\":\"Not related to the design, manufacture, or operation of aircraft, spacecraft, or the industries that support them; describing technology or fields outside of aviation and space exploration.\",\"s\":\"The factory produced nonaerospace components like car parts and kitchen appliances.\",\"p\":\"non-AIR-oh-spays\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.aerospace\",\"ps\":\"adjective\",\"t\":[\"vehicles\",\"olatin\"]},{\"w\":\"nonaesthetic\",\"d\":\"Not concerned with or relating to beauty, artistic appreciation, or sensory pleasure; describing something that has no particular regard for visual or artistic quality.\",\"s\":\"The storage room was purely functional and decidedly nonaesthetic, with bare concrete walls.\",\"p\":\"non-es-THET-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.aes.thet.ic\",\"ps\":\"adjective\",\"t\":[\"painting\",\"olatin\"]},{\"w\":\"nonaffected\",\"d\":\"Not influenced, changed, or impacted by a particular force, condition, or event; describing something that remains unchanged and unaltered despite external pressures.\",\"s\":\"The regions that remained nonaffected by the storm were able to send aid quickly.\",\"p\":\"non-uh-FEK-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"non.af.fect.ed\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonaffectionate\",\"d\":\"Not showing or expressing warmth, tenderness, or loving feelings toward others; describing a person or behavior that lacks emotional closeness or physical expressions of care.\",\"s\":\"The stray cat was nonaffectionate at first but slowly warmed up to its new family.\",\"p\":\"non-uh-FEK-shun-it\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.af.fec.tion.ate\",\"ps\":\"adjective\",\"t\":[\"emotions\",\"olatin\"]},{\"w\":\"nonafferent\",\"d\":\"Not carrying nerve signals toward the brain or central nervous system; describing neural pathways that do not transmit sensory information inward from the body.\",\"s\":\"The researcher studied nonafferent nerve pathways that carry signals away from the brain.\",\"p\":\"non-AF-er-ent\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"non.af.fer.ent\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonaffiliate\",\"d\":\"A person, organization, or entity that is not officially connected to or associated with a larger group, company, or institution.\",\"s\":\"As a nonaffiliate, she had to pay a higher membership fee to use the sports facility.\",\"p\":\"non-uh-FIL-ee-it\",\"o\":\"Latin\",\"y\":9,\"bp\":39,\"sy\":\"non.af.fil.i.ate\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonaffiliated\",\"d\":\"Not formally connected, associated, or aligned with any particular organization, political group, religion, or institution; independent and unattached.\",\"s\":\"The nonaffiliated school operated independently without ties to any larger organization.\",\"p\":\"non-uh-FIL-ee-ay-ted\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.af.fil.i.at.ed\",\"ps\":\"adjective\",\"t\":[\"religion\",\"politics\",\"olatin\"]},{\"w\":\"nonaffine\",\"d\":\"Not relating to or exhibiting affine properties; in mathematics or geometry, describing a transformation or space that does not preserve parallel lines or ratios of distances in the standard affine sense.\",\"s\":\"The mathematician described the transformation as nonaffine because parallel lines did not remain parallel.\",\"p\":\"non-uh-FYN\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.affine\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonaffix\",\"d\":\"A word element, such as a root or standalone word, that is not a prefix, suffix, or infix attached to another word to modify its meaning.\",\"s\":\"The word 'run' is a nonaffix base form with no prefix or suffix attached.\",\"p\":\"non-AF-iks\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.af.fix\",\"ps\":\"noun\",\"t\":[\"botany\",\"chemistry\",\"wordwords\",\"olatin\"]},{\"w\":\"nonaficionado\",\"d\":\"A person who is not an enthusiastic devotee or knowledgeable fan of a particular subject, art form, or activity; someone who has little passion or expertise in a given area.\",\"s\":\"As a nonaficionado of jazz, Marcus still enjoyed the concert more than he expected.\",\"p\":\"non-uh-fish-ee-uh-NAH-doh\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.afi.ciona.do\",\"ps\":\"noun\",\"t\":[\"character\",\"logic\",\"olatin\"]},{\"w\":\"nonAfrican\",\"d\":\"Not originating from, native to, or characteristic of the continent of Africa or its peoples; describing a person, plant, animal, or cultural element with origins outside Africa.\",\"s\":\"The exhibit explored how nonAfrican cultures were influenced by African art and music.\",\"p\":\"non-AF-rih-kun\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.african\",\"ps\":\"adjective\",\"t\":[\"animals\",\"botany\",\"chemistry\",\"olatin\"]},{\"w\":\"nonaged\",\"d\":\"not of legal age\",\"s\":\"The judge ruled that the nonaged defendant could not be tried as an adult because he was only fourteen years old and lacked the legal standing of a mature citizen.\",\"p\":\"NON-ayjd\",\"o\":\"Latin\",\"y\":8,\"bp\":17,\"ps\":\"adjective\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"nonagency\",\"d\":\"The state or condition of having no agency, representative authority, or power to act officially on behalf of another party.\",\"s\":\"The report was issued by a nonagency group with no official government authority.\",\"p\":\"non-AY-jen-see\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"nona.gen.cy\",\"ps\":\"noun\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"nonagglutinative\",\"d\":\"Describing a language or substance that does not agglutinate, meaning words or particles are not formed by sticking multiple distinct units together into one combined form.\",\"s\":\"English is considered a nonagglutinative language because it doesn't stack many suffixes onto one root.\",\"p\":\"non-ah-GLOO-tin-ay-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"nonag.glu.ti.na.tive\",\"ps\":\"adjective\",\"t\":[\"physics\",\"wordwords\",\"olatin\"]},{\"w\":\"nonaggregated\",\"d\":\"Not gathered, clustered, or combined into a unified group or mass; remaining separate and distinct from other elements or particles.\",\"s\":\"The nonaggregated data was harder to analyze because each entry remained separate.\",\"p\":\"non-AG-reh-gay-tid\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"nonag.gre.gat.ed\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonaggregating\",\"d\":\"Not in the process of clustering, grouping, or combining separate particles or elements into a larger collected mass.\",\"s\":\"Scientists developed a nonaggregating formula so the particles stayed evenly spread in solution.\",\"p\":\"non-AG-reh-gay-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nonag.gre.gat.ing\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonaggressive\",\"d\":\"not aggressive; not given to fighting or assertiveness\",\"s\":\"The therapy dog had a calm, nonaggressive temperament that made patients feel safe.\",\"p\":\"non-ah-GRES-iv\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nonag.gres.sive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonaggressively\",\"d\":\"In a manner that is not aggressive, hostile, or forceful; behaving calmly and without the intent to intimidate or dominate others.\",\"s\":\"The negotiator approached the tense situation nonaggressively, using quiet words instead of demands.\",\"p\":\"non-ah-GRES-iv-lee\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"nonag.gres.sive.ly\",\"ps\":\"adverb\",\"t\":[\"olatin\"]},{\"w\":\"nonaggressor\",\"d\":\"A person, nation, or entity that does not initiate hostility, attack, or aggressive action against another party.\",\"s\":\"In the peace treaty, each nation pledged to remain a nonaggressor toward its neighbors.\",\"p\":\"non-ah-GRES-er\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"nonag.gres.sor\",\"ps\":\"noun\",\"t\":[\"nations\",\"olatin\"]},{\"w\":\"nonaging\",\"d\":\"Not undergoing the natural process of aging or deterioration over time; remaining stable or youthful without the typical effects of growing older.\",\"s\":\"Scientists dream of developing a nonaging material that never weakens or deteriorates over time.\",\"p\":\"non-AY-jing\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"nonag.ing\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nonagnostic\",\"d\":\"Describing a person who is not agnostic, meaning they hold a definite belief or disbelief about the existence of a god rather than claiming uncertainty or lack of knowledge.\",\"s\":\"As a nonagnostic, she held firm religious beliefs rather than remaining uncertain about God's existence.\",\"p\":\"non-ag-NOS-tik\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"nonag.nos.tic\",\"ps\":\"adjective\",\"t\":[\"character\",\"logic\",\"olatin\"]},{\"w\":\"nonagostic\",\"d\":\"Not relating to or exhibiting an agostic interaction, which in chemistry refers to an intramolecular attraction between a metal center and a nearby carbon-hydrogen bond.\",\"s\":\"The chemist labeled the bond nonagostic because it lacked the metal-hydrogen interaction typical of agostic systems.\",\"p\":\"non-ah-GOS-tik\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"nonagos.tic\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonagouti\",\"d\":\"Describing a genetic trait or animal coat in which the individual hairs lack the alternating bands of color characteristic of the agouti pattern, resulting in a solid or uniform coloring.\",\"s\":\"The nonagouti mice had uniformly black fur because their coat-color gene was switched off.\",\"p\":\"non-ah-GOO-tee\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"ps\":\"adjective\",\"t\":[\"animals\",\"fabrics\",\"colors\",\"olatin\"]},{\"w\":\"nonagreed\",\"d\":\"Not having reached mutual agreement or consensus; describing a matter or position upon which the involved parties have failed to come to terms.\",\"s\":\"The two sides remained nonagreed on the boundary dispute even after hours of talks.\",\"p\":\"non-ah-GREED\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"nona.greed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonagreeing\",\"d\":\"Not consenting to or concurring with a proposal, statement, or arrangement; failing to reach a shared understanding or accord with another party.\",\"s\":\"The nonagreeing committee members filed a written objection to the proposed policy.\",\"p\":\"non-ah-GREE-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"nona.gree.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonagricultural\",\"d\":\"Not related to, involved in, or dependent upon farming, crop production, or the raising of livestock for food or other agricultural purposes.\",\"s\":\"The town's economy was largely nonagricultural, relying on technology and tourism instead of farming.\",\"p\":\"nah-na-grih-KUH-lcher-uh-l\",\"o\":\"Latin\",\"y\":8,\"bp\":31,\"sy\":\"naa.nae.grih.kah.lcher.ah.l\",\"ps\":\"adjective\",\"t\":[\"farming\",\"olatin\"]},{\"w\":\"nonair\",\"d\":\"Not consisting of, relating to, or transmitted through the air; used to describe media, environments, or substances that do not involve the atmosphere or aerial conditions.\",\"s\":\"The engineers tested a nonair medium to see how sound traveled through liquid instead.\",\"p\":\"non-AIR\",\"o\":\"Latin\",\"y\":8,\"bp\":18,\"sy\":\"non.air\",\"ps\":\"adjective\",\"t\":[\"ecology\",\"olatin\"]},{\"w\":\"nonairborne\",\"d\":\"Not carried, transported, or spread through the air; describing particles, organisms, or forces that travel by means other than aerial suspension or flight.\",\"s\":\"The virus was nonairborne, meaning it could only spread through direct contact, not through the air.\",\"p\":\"non-AIR-born\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.air.borne\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonairbrushed\",\"d\":\"Not having been altered, smoothed, or perfected using an airbrush tool or digital editing technique; representing an authentic, unretouched image or appearance.\",\"s\":\"The magazine proudly published nonairbrushed photos to promote realistic body image.\",\"p\":\"non-AIR-brusht\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.air.brushed\",\"ps\":\"adjective\",\"t\":[\"tools\",\"olatin\"]},{\"w\":\"nonairfield\",\"d\":\"Not designated or used as an airfield; describing a location or area that lacks the runways, facilities, or infrastructure required for aircraft takeoff and landing.\",\"s\":\"The remote camp was built on nonairfield terrain where no planes could land.\",\"p\":\"non-AIR-feeld\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.air.field\",\"ps\":\"adjective\",\"t\":[\"vehicles\",\"olatin\"]},{\"w\":\"nonairline\",\"d\":\"Not associated with or operated by a commercial airline; describing travel, cargo, or aviation services that function outside the established airline industry.\",\"s\":\"The nonairline charter service offered private flights outside the major carrier network.\",\"p\":\"non-AIR-lyn\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.air.line\",\"ps\":\"adjective\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nonairport\",\"d\":\"Not functioning as or related to an official airport; describing a facility or location that does not serve as a designated hub for commercial or civilian air travel.\",\"s\":\"The rescue helicopter landed at a nonairport site in the middle of a field.\",\"p\":\"non-AIR-port\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.air.port\",\"ps\":\"adjective\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nonairtight\",\"d\":\"Not sealed or closed in a way that prevents the passage of air; having gaps, leaks, or openings through which air can freely enter or escape.\",\"s\":\"The container was nonairtight, so moisture seeped in and spoiled the crackers.\",\"p\":\"non-AIR-tyt\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.air.tight\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonalarm\",\"d\":\"Not functioning as or related to an alarm system; describing a device, signal, or situation that does not trigger or constitute a warning alert.\",\"s\":\"The sensor sent a nonalarm signal, indicating everything in the building was functioning normally.\",\"p\":\"non-ah-LARM\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.alarm\",\"ps\":\"adjective\",\"t\":[\"tools\",\"olatin\"]},{\"w\":\"nonalarmed\",\"d\":\"Not in a state of alarm, fear, or heightened alert; remaining calm and undisturbed by a potential threat or unexpected situation.\",\"s\":\"The wildlife expert remained nonalarmed when the bear approached, knowing it was just curious.\",\"p\":\"non-ah-LARMD\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.alarmed\",\"ps\":\"adjective\",\"t\":[\"emotions\",\"olatin\"]},{\"w\":\"nonalarming\",\"d\":\"Not causing alarm, fear, or concern; describing a situation, result, or piece of information that does not provoke anxiety or a sense of danger.\",\"s\":\"The doctor's report was nonalarming, which put the patient's family at ease.\",\"p\":\"non-ah-LAR-ming\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.alarm.ing\",\"ps\":\"adjective\",\"t\":[\"emotions\",\"olatin\"]},{\"w\":\"nonalarmist\",\"d\":\"Not inclined to exaggerate dangers or provoke unnecessary panic; describing a person or approach that responds to situations with measured calm rather than excessive fear.\",\"s\":\"The nonalarmist scientist presented the climate data calmly without exaggerating the danger.\",\"p\":\"non-ah-LAR-mist\",\"o\":\"Latin\",\"y\":8,\"bp\":34,\"sy\":\"non.alarmist\",\"ps\":\"adjective\",\"t\":[\"character\",\"emotions\",\"numbers\",\"olatin\"]},{\"w\":\"nonalbum\",\"d\":\"Not released as part of an official studio album; describing a song, track, or recording that exists outside the formal album format, such as a single or bonus track.\",\"s\":\"The band released several nonalbum singles that never appeared on any official studio recording.\",\"p\":\"non-AL-bum\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.al.bum\",\"ps\":\"adjective\",\"t\":[\"music\",\"olatin\"]},{\"w\":\"nonalbuminous\",\"d\":\"Not containing or relating to albumin, the water-soluble protein found in egg whites, blood serum, and other biological substances; lacking the properties of albumin.\",\"s\":\"The scientist noted that the clear liquid was nonalbuminous, containing no protein residue whatsoever.\",\"p\":\"non-al-BYOO-mih-nus\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.al.bu.minous\",\"ps\":\"adjective\",\"t\":[\"body\",\"pharmacy\",\"olatin\"]},{\"w\":\"nonalchemical\",\"d\":\"Not related to or characteristic of alchemy, the ancient practice of attempting to transform base metals into gold or discover magical elixirs through mystical processes.\",\"s\":\"The chemistry teacher explained that modern lab methods are strictly nonalchemical and based on proven science.\",\"p\":\"non-al-KEM-ih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.al.chem.i.cal\",\"ps\":\"adjective\",\"t\":[\"pharmacy\",\"ancient\",\"olatin\"]},{\"w\":\"nonalcohol\",\"d\":\"A substance or product that does not contain alcohol; used to describe beverages, solutions, or compounds that are entirely free of ethanol or other alcoholic content.\",\"s\":\"The punch served at the school dance was a nonalcohol beverage made from fruit juice and sparkling water.\",\"p\":\"non-AL-kuh-hol\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.al.co.hol\",\"ps\":\"noun\",\"t\":[\"dishes\",\"olatin\"]},{\"w\":\"nonalgal\",\"d\":\"Not related to, consisting of, or produced by algae; describing an organism, substance, or environment that lacks the presence or influence of algae.\",\"s\":\"The researchers confirmed that the green tint in the water was nonalgal and caused by dissolved minerals instead.\",\"p\":\"non-AL-gul\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.al.gal\",\"ps\":\"adjective\",\"t\":[\"botany\",\"ecology\",\"olatin\"]},{\"w\":\"nonalgorithmic\",\"d\":\"Not based on or following a defined set of step-by-step rules or procedures; describing a process, method, or system that cannot be reduced to a fixed computational algorithm.\",\"s\":\"Creative writing is a nonalgorithmic process because there is no fixed set of steps guaranteed to produce a great story.\",\"p\":\"non-al-guh-RITH-mik\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.al.go.rith.mic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonaliased\",\"d\":\"In computing and digital imaging, describing a graphic or signal that is free from aliasing, meaning it does not display the jagged staircase-like distortions caused by low resolution sampling.\",\"s\":\"The graphic designer rendered the image in nonaliased mode, which kept the edges perfectly smooth.\",\"p\":\"non-AY-lee-ayst\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.a.liased\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonalibi\",\"d\":\"The absence or lack of an alibi; a situation in which a person has no verifiable proof that they were elsewhere when a crime or incident took place.\",\"s\":\"The suspect offered a nonalibi excuse that did nothing to prove where he was during the crime.\",\"p\":\"non-AL-ih-by\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.al.i.bi\",\"ps\":\"noun\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"nonalimony\",\"d\":\"Not constituting or related to alimony; describing a financial arrangement, payment, or legal settlement that does not involve court-ordered spousal support after a divorce.\",\"s\":\"The couple signed a nonalimony agreement before their divorce, meaning neither would pay the other support.\",\"p\":\"non-AL-ih-moh-nee\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.al.imo.ny\",\"ps\":\"adjective\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"nonalive\",\"d\":\"Not living; lacking the biological characteristics of life such as growth, reproduction, and response to stimuli; inanimate or without vital functions.\",\"s\":\"The philosopher argued that a rock is nonalive because it cannot grow, reproduce, or respond to its environment.\",\"p\":\"non-ah-LYV\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.alive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonalkalic\",\"d\":\"Not having the properties of an alkali; describing a substance, rock, or solution that is not basic or alkaline in its chemical composition.\",\"s\":\"The soil test showed it was nonalkalic, making it ideal for growing blueberries that prefer acidic conditions.\",\"p\":\"non-al-KAL-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.al.ka.lic\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"minerals\",\"olatin\"]},{\"w\":\"nonalkaloidal\",\"d\":\"Not having the chemical characteristics of an alkaloid; describing a compound or substance that lacks the nitrogen-based ring structure associated with the alkaloid class of molecules.\",\"s\":\"The chemist confirmed that the substance was nonalkaloidal and therefore unlikely to act as a stimulant.\",\"p\":\"non-al-kuh-LOY-dul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.al.ka.loidal\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonallegorical\",\"d\":\"Not using or functioning as allegory; describing a text, artwork, or statement that conveys its meaning directly and literally rather than through symbolic representation or extended metaphor.\",\"s\":\"The author insisted his story was nonallegorical and was meant to be taken as a straightforward adventure tale.\",\"p\":\"non-al-eh-GOR-ih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.al.le.gor.i.cal\",\"ps\":\"adjective\",\"t\":[\"painting\",\"poetry\",\"olatin\"]},{\"w\":\"nonallergen\",\"d\":\"A substance that does not trigger an allergic reaction in the immune system, making it safe for people with sensitivities.\",\"s\":\"The doctor recommended a nonallergen pillow stuffing for the child who suffered from severe dust allergies.\",\"p\":\"non-AL-er-jen\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"non.al.ler.gen\",\"ps\":\"noun\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"nonallergenic\",\"d\":\"Describing a product or substance that is unlikely to cause an allergic reaction, often used to label hypoallergenic items.\",\"s\":\"The label said the lotion was nonallergenic, so even people with sensitive skin could use it safely.\",\"p\":\"non-al-er-JEN-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.al.ler.genic\",\"ps\":\"adjective\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"nonallergic\",\"d\":\"Not relating to or caused by an allergy; describing a person or reaction that does not involve the immune system's allergic response.\",\"s\":\"Luckily, my little brother is nonallergic to peanuts, so he can eat them without any problem.\",\"p\":\"non-ah-LER-jik\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"non.al.ler.gic\",\"ps\":\"adjective\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"nonallied\",\"d\":\"Not joined in a formal alliance or partnership with another country, group, or organization; remaining independent.\",\"s\":\"The small country remained nonallied during the conflict, refusing to join either side in the dispute.\",\"p\":\"non-ah-LIDE\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.al.lied\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonallocated\",\"d\":\"Not assigned or distributed to a specific purpose, account, or recipient; describing funds or resources left undesignated.\",\"s\":\"The school's nonallocated budget funds sat unused because no one had decided where to spend them yet.\",\"p\":\"non-AL-oh-kay-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":39,\"sy\":\"non.al.lo.cat.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonallodial\",\"d\":\"Describing land or property that is not held in absolute ownership free of any obligations, typically still subject to feudal or governmental claims.\",\"s\":\"In the feudal system, most land was nonallodial, meaning peasants held it under a lord rather than owning it freely.\",\"p\":\"non-ah-LOH-dee-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.al.lo.di.al\",\"ps\":\"adjective\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"nonallodynic\",\"d\":\"Not relating to or exhibiting allodynia, meaning ordinary touch or mild stimuli do not produce an abnormal pain response.\",\"s\":\"After treatment, the patient's skin became nonallodynic, no longer feeling pain from a gentle, harmless touch.\",\"p\":\"non-al-oh-DIN-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":39,\"sy\":\"non.al.lo.dyn.ic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonallopathic\",\"d\":\"Not based on conventional Western medical practices; relating to alternative or complementary approaches to treating disease.\",\"s\":\"The wellness center offered nonallopathic treatments like herbal remedies and acupuncture instead of conventional drugs.\",\"p\":\"non-al-oh-PATH-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.al.lo.path.ic\",\"ps\":\"adjective\",\"t\":[\"body\",\"disease\",\"olatin\"]},{\"w\":\"nonallosteric\",\"d\":\"Describing a molecule or enzyme whose activity is not regulated by the binding of a molecule at a site other than the active site.\",\"s\":\"The enzyme was nonallosteric, so its activity stayed constant regardless of any molecules binding to its outer surface.\",\"p\":\"non-al-oh-STEER-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.al.loster.ic\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonallotted\",\"d\":\"Not distributed or assigned as a share or portion; describing resources or time that has not been officially given out.\",\"s\":\"The nonallotted seats in the auditorium were open for anyone to sit in on a first-come, first-served basis.\",\"p\":\"non-ah-LOT-ed\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"non.al.lot.ted\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nonallowed\",\"d\":\"Not permitted or sanctioned; describing something that is forbidden or not approved under a given set of rules.\",\"s\":\"Bringing outside food into the theater was nonallowed according to the rules posted at the entrance.\",\"p\":\"non-ah-LOUD\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.al.lowed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonalluvial\",\"d\":\"Not formed or deposited by flowing water; describing soil or land whose composition was not created by river or flood sediment.\",\"s\":\"The geologist found that the rocky hillside soil was nonalluvial and had not been deposited by any river.\",\"p\":\"non-ah-LOO-vee-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"non.al.lu.vial\",\"ps\":\"adjective\",\"t\":[\"minerals\",\"waterways\",\"olatin\"]},{\"w\":\"nonally\",\"d\":\"A person, nation, or group that has not formed an alliance and does not provide support or cooperation to another party.\",\"s\":\"During the negotiations, the neutral nation acted as a nonally, offering to mediate without taking anyone's side.\",\"p\":\"non-AL-eye\",\"o\":\"Latin\",\"y\":9,\"bp\":20,\"sy\":\"non.al.ly\",\"ps\":\"noun\",\"t\":[\"nations\",\"olatin\"]},{\"w\":\"nonalphabetic\",\"d\":\"Not consisting of or using letters from an alphabet; describing writing systems or symbols that rely on characters other than alphabetic letters.\",\"s\":\"Mandarin characters are nonalphabetic because they represent whole words or ideas rather than individual sounds.\",\"p\":\"non-al-fah-BET-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.al.pha.bet.ic\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonalphabetical\",\"d\":\"Not arranged or organized in the standard A-to-Z order of an alphabet; describing a sequence that does not follow alphabetical sorting.\",\"s\":\"The librarian was confused because the books were filed in a nonalphabetical order that no one could figure out.\",\"p\":\"non-al-fah-BET-ih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":31,\"sy\":\"non.al.pha.bet.i.cal\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonalphabetically\",\"d\":\"In a manner that does not follow alphabetical order; used to describe how items are arranged or listed outside of A-to-Z sequence.\",\"s\":\"The teacher sorted the papers nonalphabetically by score, placing the highest grades at the top of the pile.\",\"p\":\"non-al-fah-BET-ih-klee\",\"o\":\"Latin\",\"y\":9,\"bp\":33,\"sy\":\"non.al.pha.bet.i.cal.ly\",\"ps\":\"adverb\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonalphanumeric\",\"d\":\"Not consisting of letters or numbers; referring to characters such as symbols, punctuation marks, or spaces that fall outside the standard alphanumeric set.\",\"s\":\"The password required at least one nonalphanumeric character, such as an exclamation point or dollar sign.\",\"p\":\"non-al-fah-nyoo-MER-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.al.phanu.mer.ic\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonaltruistic\",\"d\":\"Not motivated by concern for the well-being of others; acting out of self-interest rather than generosity or selflessness.\",\"s\":\"His decision to donate only when he received public praise seemed nonaltruistic and more about his reputation.\",\"p\":\"non-al-troo-IS-tik\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.al.tru.is.tic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonaluminum\",\"d\":\"Not made of or containing aluminum; describing a material or product constructed from a different metal or substance.\",\"s\":\"The engineer chose a nonaluminum alloy for the part because aluminum would corrode too quickly in salt water.\",\"p\":\"non-ah-LOO-mih-num\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.a.lu.minum\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonalveolar\",\"d\":\"Describing a speech sound that is not produced by placing the tongue near the alveolar ridge, the bony area just behind the upper front teeth.\",\"s\":\"In linguistics class, we learned that the sound 'p' is nonalveolar because it is made with the lips, not the ridge behind the teeth.\",\"p\":\"non-al-VEE-oh-ler\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.alve.o.lar\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonambient\",\"d\":\"Not relating to or forming the surrounding background environment; describing light, sound, or conditions that are directed or focused rather than diffuse.\",\"s\":\"The stage lighting was intentionally nonambient, using sharp spotlights to create dramatic shadows on the actors.\",\"p\":\"non-AM-bee-ent\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.am.bi.ent\",\"ps\":\"adjective\",\"t\":[\"ecology\",\"olatin\"]},{\"w\":\"nonambiguous\",\"d\":\"Having only one clear meaning or interpretation; free from uncertainty or vagueness, so that no confusion is possible.\",\"s\":\"The instructions were written to be completely nonambiguous so that every student could follow them without confusion.\",\"p\":\"non-am-BIG-yoo-us\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.am.bigu.ous\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonambitious\",\"d\":\"Lacking a strong desire to achieve success, power, or distinction; not driven by goals of advancement or accomplishment.\",\"s\":\"His nonambitious attitude meant he was happy staying in the same job for thirty years without ever seeking a promotion.\",\"p\":\"non-am-BISH-us\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.am.bi.tious\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonambulatory\",\"d\":\"Unable to walk or move about independently; describing a patient or condition in which walking is not possible without assistance.\",\"s\":\"After the surgery, the patient was nonambulatory for two weeks and needed a wheelchair to move around.\",\"p\":\"non-am-BYOO-lah-tor-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.am.bu.la.to.ry\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonamended\",\"d\":\"Not revised, changed, or corrected; describing a document, law, or statement that remains in its original unaltered form.\",\"s\":\"The nonamended version of the bill was voted down because lawmakers felt it needed significant changes.\",\"p\":\"non-ah-MEN-ded\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.a.mend.ed\",\"ps\":\"adjective\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"nonamino\",\"d\":\"Not containing or relating to an amino group (NH2); describing a molecule or compound that lacks this particular chemical structure found in proteins.\",\"s\":\"The biologist studied nonamino compounds to understand the molecules in cells that contain no nitrogen-based groups.\",\"p\":\"non-ah-MEE-noh\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.amino\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonaminoacylated\",\"d\":\"Describing a transfer RNA or similar molecule that does not have an amino acid chemically attached to it through an acyl bond.\",\"s\":\"The transfer RNA molecule in the experiment was nonaminoacylated, meaning no amino acid had been attached to it yet.\",\"p\":\"non-ah-mee-noh-AS-ih-lay-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.aminoa.cy.lat.ed\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonamortizable\",\"d\":\"Describing a debt, asset, or cost that cannot be gradually paid off or written down over a fixed period of time.\",\"s\":\"The accountant discovered that certain intangible assets were nonamortizable under the new tax rules.\",\"p\":\"non-ah-MOR-tih-zy-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.amor.ti.z.able\",\"ps\":\"adjective\",\"t\":[\"economy\",\"time\",\"olatin\"]},{\"w\":\"nonamortized\",\"d\":\"Not yet reduced or paid off through scheduled installment payments; describing a loan or asset whose cost has not been gradually written down.\",\"s\":\"The nonamortized loan balance remained on the books years after the company expected it to be paid down.\",\"p\":\"non-ah-MOR-tyzd\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"non.amor.tized\",\"ps\":\"adjective\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nonamphibious\",\"d\":\"Not capable of operating or living both on land and in water; restricted to a single environment rather than functioning in two.\",\"s\":\"Unlike frogs, most reptiles are nonamphibious and cannot thrive equally well on land and in water.\",\"p\":\"non-am-FIB-ee-us\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.am.phibi.ous\",\"ps\":\"adjective\",\"t\":[\"ecology\",\"olatin\"]},{\"w\":\"nonamphiphilic\",\"d\":\"Describing a molecule that does not have both a water-attracting and a water-repelling region, so it cannot interact with both water and oil.\",\"s\":\"The scientist noted that the compound was nonamphiphilic, meaning it did not have both water-loving and water-repelling parts.\",\"p\":\"non-am-fih-FIL-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.am.phiphilic\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonampliative\",\"d\":\"Describing reasoning or a statement that does not go beyond or expand upon the information already contained in its premises.\",\"s\":\"The philosopher argued that the statement was nonampliative because it added no new information beyond what was already known.\",\"p\":\"non-AM-plee-ay-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.am.plia.tive\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonamplified\",\"d\":\"Not increased in strength, volume, or magnitude; describing a signal, sound, or gene sequence that has not been boosted or enlarged.\",\"s\":\"The folk singer performed a nonamplified set in the cozy living room, relying only on her natural voice.\",\"p\":\"non-AM-plih-fyde\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.am.pli.fied\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonamylolytic\",\"d\":\"Not capable of breaking down starch molecules; describing an enzyme or organism that lacks the ability to digest amylose or amylopectin.\",\"s\":\"The enzyme was nonamylolytic, so it had no ability to break down starch in the digestion experiment.\",\"p\":\"non-am-ih-loh-LIT-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.amy.lolyt.ic\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonanalgesic\",\"d\":\"Not producing pain relief; describing a drug, treatment, or substance that does not reduce or eliminate the sensation of pain.\",\"s\":\"The researcher confirmed that the new compound was nonanalgesic and therefore useless for relieving pain.\",\"p\":\"non-an-al-JEE-zik\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"nonanal.gesic\",\"ps\":\"adjective\",\"t\":[\"pharmacy\",\"olatin\"]},{\"w\":\"nonanalog\",\"d\":\"Not using continuously varying physical signals to represent information; relating to systems or devices that use discrete digital values instead.\",\"s\":\"The engineer designed a nonanalog circuit that processed only digital signals.\",\"p\":\"non-AN-ah-log\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"nonana.log\",\"ps\":\"adjective\",\"t\":[\"tools\",\"olatin\"]},{\"w\":\"nonanalytic\",\"d\":\"Not based on or using careful logical analysis; describing a statement, method, or truth that cannot be determined solely through reasoning or definition.\",\"s\":\"Her nonanalytic approach to art meant she painted from pure emotion rather than studied technique.\",\"p\":\"non-an-ah-LIT-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.an.a.lyt.ic\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonanalytical\",\"d\":\"Not employing detailed examination or logical breakdown; describing an approach, statement, or thinker that does not rely on systematic analysis.\",\"s\":\"The teacher warned that a nonanalytical essay would receive a lower grade because it lacked critical thinking.\",\"p\":\"non-an-ah-LIT-ih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.an.a.lyt.i.cal\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonanaphoric\",\"d\":\"Describing a word or expression that does not refer back to a previously mentioned word or idea in a text or conversation.\",\"s\":\"The linguist labeled the pronoun nonanaphoric because it did not refer back to any previously mentioned noun.\",\"p\":\"non-an-ah-FOR-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":33,\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonanaplastic\",\"d\":\"Describing cells or tissue that do not show the loss of normal structural features associated with malignant or rapidly dividing cancer cells.\",\"s\":\"The biopsy results were reassuring because the cells appeared nonanaplastic and showed no signs of cancer.\",\"p\":\"non-an-ah-PLAS-tik\",\"o\":\"Latin\",\"y\":9,\"bp\":23,\"sy\":\"nonanaplas.tic\",\"ps\":\"adjective\",\"t\":[\"body\",\"disease\",\"olatin\"]},{\"w\":\"nonanatomic\",\"d\":\"Not relating to or based on the structure of the body or its parts; describing something that does not follow or correspond to the physical layout of anatomy.\",\"s\":\"The artist's sculpture was nonanatomic, distorting the human body into abstract, unrecognizable shapes.\",\"p\":\"non-an-uh-TOM-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":34,\"sy\":\"nonanatom.ic\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonancillary\",\"d\":\"Not serving a supporting or secondary role; describing something that is independent and not functioning as a helper or supplement to something else.\",\"s\":\"The board decided that the new department was nonancillary and would function independently rather than in support of others.\",\"p\":\"non-AN-sih-lair-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"nonan.cil.lary\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonandrogenic\",\"d\":\"Not producing or relating to male sex hormones such as testosterone; describing a substance or condition that does not stimulate androgenic effects in the body.\",\"s\":\"Doctors sometimes prefer nonandrogenic medications for female patients to avoid unwanted hormonal side effects.\",\"p\":\"non-an-droh-JEN-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nonan.dro.genic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonandrogynous\",\"d\":\"Not having or combining both male and female characteristics; clearly identified with one gender rather than blending traits of both.\",\"s\":\"The character's costume was clearly nonandrogynous, designed to emphasize traditionally feminine features.\",\"p\":\"non-an-DROJ-ih-nus\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nonan.drog.y.nous\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonanecdotal\",\"d\":\"Not based on personal stories or informal accounts; relying instead on systematic evidence, data, or formal research rather than individual tales.\",\"s\":\"The scientist insisted on nonanecdotal evidence, demanding controlled studies rather than personal stories.\",\"p\":\"non-an-ek-DOH-tul\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"nonanec.do.tal\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"nonanesthetic\",\"d\":\"Not involving or relating to the use of anesthesia; describing a procedure or substance that does not cause numbness, sedation, or loss of sensation.\",\"s\":\"The nonanesthetic procedure was painful, so the patient gripped the armrest tightly throughout.\",\"p\":\"non-an-es-THET-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nonanes.thet.ic\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonaneurysmal\",\"d\":\"Not relating to or caused by an aneurysm; describing a blood vessel or medical condition in which there is no abnormal bulging or weakening of vessel walls.\",\"s\":\"The scan showed a nonaneurysmal blood vessel, which meant there was no dangerous bulging to worry about.\",\"p\":\"non-an-yuh-RIZ-mul\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nona.neurys.mal\",\"ps\":\"adjective\",\"t\":[\"body\",\"seafaring\",\"olatin\"]},{\"w\":\"nonanginal\",\"d\":\"Not related to or caused by angina; describing chest discomfort or pain that does not originate from the reduced blood flow to the heart associated with angina pectoris.\",\"s\":\"The doctor determined the chest pain was nonanginal and likely caused by muscle strain rather than heart problems.\",\"p\":\"non-AN-jih-nul\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"nonang.i.nal\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonangiogenic\",\"d\":\"Not promoting or relating to the formation of new blood vessels; describing a substance or condition that does not stimulate angiogenesis in tissue.\",\"s\":\"Researchers hoped the drug would be nonangiogenic, preventing tumors from growing their own blood supply.\",\"p\":\"non-an-jee-oh-JEN-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nonan.gio.genic\",\"ps\":\"adjective\",\"t\":[\"body\",\"seafaring\",\"olatin\"]},{\"w\":\"nonangled\",\"d\":\"Not positioned at an angle; lacking corners or angular orientation, typically describing a shape or surface that is smooth, straight, or curved without sharp bends.\",\"s\":\"The designer chose a nonangled, perfectly circular table so no one would feel cornered at meetings.\",\"p\":\"non-ANG-uld\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"nonan.gled\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonangler\",\"d\":\"A person who does not fish with a rod and line; someone who does not participate in the sport or activity of angling.\",\"s\":\"As a nonangler, Maria preferred hiking near the lake to sitting quietly with a fishing rod.\",\"p\":\"non-ANG-glur\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"nonan.gler\",\"ps\":\"noun\",\"t\":[\"marine\",\"sports\",\"olatin\"]},{\"w\":\"nonangling\",\"d\":\"Not involving or relating to the activity of fishing with a rod and hook; describing a recreational or sporting pursuit other than angling.\",\"s\":\"Their nonangling vacation was filled with kayaking and swimming rather than casting fishing lines.\",\"p\":\"non-ANG-gling\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"nonan.gling\",\"ps\":\"adjective\",\"t\":[\"sports\",\"olatin\"]},{\"w\":\"nonangry\",\"d\":\"Not feeling or displaying anger; remaining calm, peaceful, or emotionally neutral rather than showing irritation or rage.\",\"s\":\"Surprisingly nonangry after missing the bus, Jake simply shrugged and called for a ride.\",\"p\":\"non-ANG-gree\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"nonan.gry\",\"ps\":\"adjective\",\"t\":[\"emotions\",\"olatin\"]},{\"w\":\"nonangular\",\"d\":\"Not having sharp angles or corners; describing a form or shape that is rounded, smooth, or curved rather than made up of distinct angular edges.\",\"s\":\"The potter shaped the clay into a smooth, nonangular bowl with perfectly rounded edges.\",\"p\":\"non-ANG-gyuh-lur\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"nonan.gu.lar\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonanimated\",\"d\":\"Not brought to life through animation techniques; describing film, media, or images that use real people, objects, or live-action footage rather than drawn or computer-generated characters.\",\"s\":\"The documentary used nonanimated footage, relying entirely on real video recordings rather than cartoons.\",\"p\":\"non-AN-ih-may-tid\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"nonan.i.mat.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonanimation\",\"d\":\"The state or quality of not using animation; the use of live-action or non-cartoon methods in film, media, or visual presentations instead of animated techniques.\",\"s\":\"The film festival had a category for nonanimation entries, celebrating live-action storytelling.\",\"p\":\"non-an-ih-MAY-shun\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"nonan.i.ma.tion\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonannealable\",\"d\":\"Not capable of being softened, strengthened, or made more workable through the process of annealing, in which a material is heated and slowly cooled.\",\"s\":\"The material was nonannealable, meaning no amount of heating and slow cooling could reduce its internal stress.\",\"p\":\"non-uh-NEEL-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nonan.neal.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonannealed\",\"d\":\"Not having undergone the annealing process; describing a material, especially metal or glass, that has not been heated and slowly cooled to reduce brittleness and internal stress.\",\"s\":\"The nonannealed glass shattered easily because it had never been properly heat-treated to reduce brittleness.\",\"p\":\"non-uh-NEELD\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"sy\":\"nonan.nealed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonannealing\",\"d\":\"Not undergoing or relating to the annealing process; describing conditions or materials in which the slow heating and cooling used to increase toughness is not applied.\",\"s\":\"The factory's nonannealing process saved time but produced metal parts that cracked under pressure.\",\"p\":\"non-uh-NEEL-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"nonan.neal.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonannexed\",\"d\":\"Not taken over or incorporated into a larger territory or political unit; describing land or property that remains independent and has not been formally annexed by another body.\",\"s\":\"The nonannexed territory remained independent and refused to be absorbed into the neighboring city's boundaries.\",\"p\":\"non-uh-NEKSD\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nonan.nexed\",\"ps\":\"adjective\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"nonannotated\",\"d\":\"Not accompanied by explanatory notes, comments, or critical remarks; describing a text, document, or edition that contains no additional annotations or margin notes.\",\"s\":\"The nonannotated edition of the novel had no footnotes or explanations, leaving readers to interpret it alone.\",\"p\":\"non-AN-uh-tay-tid\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"nonan.no.tat.ed\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonannual\",\"d\":\"Not occurring once every year; describing an event, payment, or publication that does not follow a yearly schedule or cycle.\",\"s\":\"The nonannual festival was held only once every five years, making it an especially anticipated event.\",\"p\":\"non-AN-yoo-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"nonan.nu.al\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nonannualized\",\"d\":\"Not converted or adjusted to reflect a rate or figure calculated over a full year; describing a financial or statistical figure that is reported for a shorter period without being scaled up to an annual equivalent.\",\"s\":\"The nonannualized interest rate on the loan confused borrowers who expected a yearly figure.\",\"p\":\"non-AN-yoo-uh-lyzd\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"nonan.nu.al.ized\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nonanomalous\",\"d\":\"Not deviating from what is standard, normal, or expected; describing data, behavior, or conditions that conform to established patterns without any unusual or irregular characteristics.\",\"s\":\"The data were described as nonanomalous, fitting perfectly within the expected range of results.\",\"p\":\"non-uh-NOM-uh-lus\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"nonanoma.lous\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonanonymous\",\"d\":\"Not anonymous; having a known or openly identified author, source, or participant whose name and identity are visible and acknowledged.\",\"s\":\"The petition was nonanonymous, requiring every signer to include their full name and address.\",\"p\":\"non-uh-NON-ih-mus\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"nonanony.mous\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"nonanorexic\",\"d\":\"Not affected by or related to anorexia; describing a person or eating pattern that involves a healthy or normal appetite rather than the severe restriction of food intake associated with anorexia.\",\"s\":\"The health report classified the student as nonanorexic based on her healthy eating habits and normal weight.\",\"p\":\"non-an-uh-REK-sik\",\"o\":\"Latin\",\"y\":8,\"bp\":34,\"sy\":\"nonanorex.ic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonanswer\",\"d\":\"A response that fails to actually address or answer the question asked; a statement that uses words but deliberately or accidentally avoids giving a meaningful reply.\",\"s\":\"When asked why homework was missing, the student gave a nonanswer, mumbling something completely unrelated.\",\"p\":\"non-AN-sur\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"nonan.swer\",\"ps\":\"noun\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonanswerable\",\"d\":\"Not capable of being answered; describing a question or problem for which no satisfactory or definitive response can be given.\",\"s\":\"The philosopher argued that some deep questions about consciousness are nonanswerable by science alone.\",\"p\":\"non-AN-sur-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nonan.swer.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonantagonistic\",\"d\":\"Not showing or expressing hostility, opposition, or conflict; describing a relationship, substance, or interaction that is cooperative, neutral, or mutually compatible rather than opposing.\",\"s\":\"The two rival students surprised everyone with their nonantagonistic debate, listening respectfully to each other.\",\"p\":\"non-an-tag-uh-NIS-tik\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"nonan.tag.o.nis.tic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonanterior\",\"d\":\"Not located at or toward the front; describing a position or anatomical structure that is situated away from the front surface of the body or an object.\",\"s\":\"The surgeon noted that the affected tissue was in a nonanterior region, located toward the back of the organ.\",\"p\":\"non-an-TEER-ee-ur\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"nonan.te.ri.or\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonanthropological\",\"d\":\"Not relating to the study of human societies, cultures, biology, or origins; describing an approach, method, or subject matter that does not involve anthropological inquiry.\",\"s\":\"The research took a nonanthropological approach, focusing on chemistry rather than human culture.\",\"p\":\"non-an-thruh-puh-LOJ-ih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"nonan.thro.po.log.i.cal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonanthropomorphic\",\"d\":\"Not attributing human characteristics, emotions, or forms to non-human entities such as animals, objects, or deities; describing a representation that avoids giving human qualities to things that are not human.\",\"s\":\"The alien characters in the novel were deliberately nonanthropomorphic, with no human-like features at all.\",\"p\":\"non-an-thruh-puh-MOR-fik\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"nonan.thro.po.mor.phic\",\"ps\":\"adjective\",\"t\":[\"animals\",\"myth\",\"emotions\",\"olatin\"]},{\"w\":\"nonantibacterial\",\"d\":\"Not having the property of killing or inhibiting the growth of bacteria; describing a substance, material, or treatment that does not combat bacterial infections or activity.\",\"s\":\"The doctor explained that the medication was nonantibacterial and would not help fight the patient's infection.\",\"p\":\"non-an-tee-bak-TEER-ee-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"nonan.tibac.te.ri.al\",\"ps\":\"adjective\",\"t\":[\"disease\",\"war\",\"olatin\"]},{\"w\":\"nonanticholinergic\",\"d\":\"Not blocking or inhibiting the action of acetylcholine in the nervous system; describing a drug or substance that does not interfere with the cholinergic nerve pathways that control many bodily functions.\",\"s\":\"The new drug was classified as nonanticholinergic because it did not block nerve signals the way older medications did.\",\"p\":\"non-an-tee-koh-lih-NUR-jik\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"nonan.ti.cholin.er.gic\",\"ps\":\"adjective\",\"t\":[\"body\",\"pharmacy\",\"olatin\"]},{\"w\":\"nonanticipative\",\"d\":\"Not characterized by anticipation or the tendency to look ahead and predict what is coming; describing a response, action, or mindset that does not involve forward-thinking preparation.\",\"s\":\"Her nonanticipative reaction to the surprise party showed she had no idea it was planned.\",\"p\":\"non-an-TIS-ih-pay-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"nonan.tic.i.pa.tive\",\"ps\":\"adjective\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nonanticoagulated\",\"d\":\"Not treated with or affected by anticoagulant drugs; describing blood or a patient whose clotting ability has not been suppressed by blood-thinning medication.\",\"s\":\"The nonanticoagulated blood sample clotted quickly, making the lab test difficult to perform.\",\"p\":\"non-an-tee-koh-AG-yuh-lay-tid\",\"o\":\"Latin\",\"y\":9,\"bp\":33,\"sy\":\"nonan.ti.co.ag.u.lat.ed\",\"ps\":\"adjective\",\"t\":[\"body\",\"pharmacy\",\"olatin\"]},{\"w\":\"nonantigenic\",\"d\":\"Not capable of triggering an immune response; describing a substance or material that does not act as an antigen and therefore does not cause the body to produce antibodies.\",\"s\":\"Scientists worked to create a nonantigenic coating for implants so the body would not reject them.\",\"p\":\"non-an-tih-JEN-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"nonanti.genic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonantihypertensive\",\"d\":\"Not effective in reducing or treating high blood pressure; describing a drug, therapy, or substance that does not lower hypertension or have any antihypertensive properties.\",\"s\":\"The pill was nonantihypertensive, meaning it would do nothing to lower the patient's high blood pressure.\",\"p\":\"non-an-tee-hy-pur-TEN-siv\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"nonan.ti.hy.per.ten.sive\",\"ps\":\"adjective\",\"t\":[\"body\",\"pharmacy\",\"olatin\"]},{\"w\":\"nonantimicrobial\",\"d\":\"Not capable of killing or suppressing the growth of microorganisms such as bacteria, fungi, or viruses; describing a substance or treatment that has no antimicrobial activity.\",\"s\":\"The lotion was nonantimicrobial, so it moisturized skin without killing any microbes.\",\"p\":\"non-an-tee-my-KROH-bee-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"nonan.timi.cro.bial\",\"ps\":\"adjective\",\"t\":[\"disease\",\"botany\",\"olatin\"]},{\"w\":\"nonantioxidant\",\"d\":\"Not acting as an antioxidant; describing a substance that does not neutralize free radicals or prevent oxidative damage to cells in the body.\",\"s\":\"The researcher confirmed the compound was nonantioxidant and offered no protection against cell damage from free radicals.\",\"p\":\"non-an-tee-OK-sih-dunt\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nonan.tiox.i.dant\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonantiparallel\",\"d\":\"Describing strands, structures, or forces that do not run in opposite parallel directions to each other.\",\"s\":\"The two DNA strands in this unusual structure were nonantiparallel, running in the same direction.\",\"p\":\"non-an-tee-PAIR-uh-lel\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"nonan.tipar.al.lel\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonantipseudomonal\",\"d\":\"Not effective against or not related to Pseudomonas bacteria, a group of harmful microorganisms that can cause serious infections.\",\"s\":\"The antibiotic prescribed was nonantipseudomonal, so it could not treat infections caused by Pseudomonas bacteria.\",\"p\":\"non-an-tee-soo-DOH-moh-nul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"nonan.tipseu.domon.al\",\"ps\":\"adjective\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"nonantiretroviral\",\"d\":\"Not designed or used to fight retroviruses, such as HIV, which use RNA to replicate inside host cells.\",\"s\":\"The treatment plan was nonantiretroviral, focusing on the patient's immune strength rather than attacking the virus directly.\",\"p\":\"non-an-tee-reh-troh-VY-rul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"nonan.tiretro.vi.ral\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonantisense\",\"d\":\"Not belonging to or acting upon the antisense strand of DNA or RNA, which is the template strand used in transcription.\",\"s\":\"The genetic sequence used in the experiment was nonantisense, meaning it did not block gene expression.\",\"p\":\"non-AN-tee-sens\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"nonan.tisense\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonantisocial\",\"d\":\"Not characterized by behavior that goes against social norms or harms others; generally cooperative and friendly in social settings.\",\"s\":\"Despite being quiet, Marcus was completely nonantisocial and genuinely enjoyed spending time with his classmates.\",\"p\":\"non-an-tee-SOH-shul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"nonan.ti.so.cial\",\"ps\":\"adjective\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nonantistatic\",\"d\":\"Not capable of preventing or reducing the buildup of static electricity on a surface or material.\",\"s\":\"The nonantistatic fabric caused her hair to stand up with static electricity every time she pulled off her sweater.\",\"p\":\"non-an-tee-STAT-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nonan.tistat.ic\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonantiviral\",\"d\":\"Not designed, used, or effective for fighting viral infections or inhibiting the activity of viruses.\",\"s\":\"The ointment was nonantiviral, so the doctor prescribed a separate medication to fight the virus.\",\"p\":\"non-an-tee-VY-rul\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"nonan.tivi.ral\",\"ps\":\"adjective\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"nonanxiety\",\"d\":\"The state of being free from anxiety, worry, or nervous tension; a calm and relaxed mental condition.\",\"s\":\"The campers reported a surprising sense of nonanxiety after spending a full week away from their phones.\",\"p\":\"non-ang-ZY-ih-tee\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"nonanx.i.ety\",\"ps\":\"noun\",\"t\":[\"emotions\",\"olatin\"]},{\"w\":\"nonanxiolytic\",\"d\":\"Not having the property of reducing or relieving anxiety; referring to a substance or treatment that does not calm anxious feelings.\",\"s\":\"The supplement was nonanxiolytic, so it did nothing to calm the patient's stress or worry.\",\"p\":\"non-ang-zee-oh-LIT-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"nonanx.i.olyt.ic\",\"ps\":\"adjective\",\"t\":[\"emotions\",\"olatin\"]},{\"w\":\"nonanxious\",\"d\":\"Not feeling or showing anxiety, worry, or nervousness; calm and free from apprehension or stress.\",\"s\":\"Surprisingly nonanxious before the big game, she calmly laced up her cleats and smiled at her teammates.\",\"p\":\"non-ANK-shus\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nonanx.ious\",\"ps\":\"adjective\",\"t\":[\"emotions\",\"olatin\"]},{\"w\":\"nonapathetic\",\"d\":\"Not showing apathy or indifference; genuinely interested, engaged, or caring about people, events, or ideas.\",\"s\":\"The nonapathetic crowd cheered loudly, showing they truly cared about the outcome of the election.\",\"p\":\"non-ap-uh-THET-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":41,\"sy\":\"non.a.p.a.thet.ic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonapeptide\",\"d\":\"A short protein molecule, or peptide, made up of exactly nine amino acids linked together in a chain.\",\"s\":\"The scientist synthesized a nonapeptide chain consisting of exactly nine amino acids linked together.\",\"p\":\"NOH-nuh-pep-tyd\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.apep.tide\",\"ps\":\"noun\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonapoptotic\",\"d\":\"Not undergoing or relating to apoptosis, the natural process of programmed cell death that occurs in multicellular organisms.\",\"s\":\"The nonapoptotic cancer cells refused to follow the normal self-destruction signal, allowing the tumor to keep growing.\",\"p\":\"non-ay-pop-TOT-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.apop.tot.ic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonapostolic\",\"d\":\"Not related to, derived from, or following the traditions and authority of the original apostles of Jesus Christ.\",\"s\":\"The scholars debated whether the ancient text came from a nonapostolic source outside the circle of Jesus's original disciples.\",\"p\":\"non-ay-puh-STOL-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.a.pos.tolic\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"festivals\",\"olatin\"]},{\"w\":\"nonappealing\",\"d\":\"Not attractive, interesting, or desirable; failing to capture someone's attention or positive interest.\",\"s\":\"The soggy, cold lunch looked completely nonappealing to the hungry but picky students.\",\"p\":\"non-uh-PEEL-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.ap.peal.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonappearing\",\"d\":\"Not showing up, presenting itself, or becoming visible; failing to appear in a given context or situation.\",\"s\":\"The nonappearing witness caused the trial to be delayed for an entire week.\",\"p\":\"non-uh-PEER-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.ap.pear.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonappendiceal\",\"d\":\"Not related to, originating from, or involving the appendix, the small pouch attached to the large intestine.\",\"s\":\"The doctor confirmed the pain was nonappendiceal, meaning the appendix was not the source of the problem.\",\"p\":\"non-ap-en-DIS-ee-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.ap.pen.diceal\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonappetitive\",\"d\":\"Not related to or driven by appetite, desire, or the motivation to seek out food or other rewards.\",\"s\":\"The illness left him in a completely nonappetitive state, with no desire to eat anything for days.\",\"p\":\"non-AP-ih-tih-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.ap.pet.i.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonapple\",\"d\":\"Any fruit, food, or object that is not an apple; used to distinguish items that lack the characteristics of an apple.\",\"s\":\"The fruit basket contained a surprising variety of nonapple items, including pears, mangoes, and grapes.\",\"p\":\"non-AP-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.ap.ple\",\"ps\":\"noun\",\"t\":[\"spices\",\"olatin\"]},{\"w\":\"nonapplicable\",\"d\":\"Not relevant, suitable, or able to be applied to a particular situation, rule, or set of circumstances.\",\"s\":\"She skipped the nonapplicable questions on the form that did not relate to her situation.\",\"p\":\"non-AP-lih-kuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.ap.pli.ca.ble\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonapplied\",\"d\":\"Not put into practical use or action; referring to knowledge, research, or skills that remain theoretical rather than practical.\",\"s\":\"The grant money sat unused because the nonapplied funds had no designated project to support.\",\"p\":\"non-uh-PLYD\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.ap.plied\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonappointed\",\"d\":\"Not officially selected, assigned, or designated to a position, role, or office by an authority.\",\"s\":\"The nonappointed volunteers stepped up to help organize the event without any official title or role.\",\"p\":\"non-uh-POYNT-ed\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.ap.point.ed\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"nonappreciative\",\"d\":\"Not showing gratitude, recognition, or a positive understanding of the value of something or someone.\",\"s\":\"The nonappreciative audience barely clapped after the orchestra's breathtaking performance.\",\"p\":\"non-uh-PREE-shee-ay-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.ap.pre.cia.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonapprovable\",\"d\":\"Not able to be approved, sanctioned, or accepted, especially by a regulatory body or authority.\",\"s\":\"The loan application was deemed nonapprovable because the applicant had no credit history.\",\"p\":\"non-uh-PROOV-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.ap.prov.able\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"nonapproved\",\"d\":\"Not having received official approval, authorization, or acceptance from a relevant authority or organization.\",\"s\":\"The students were warned not to use nonapproved websites as sources for their research papers.\",\"p\":\"non-uh-PROOVD\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.ap.proved\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"nonaquarium\",\"d\":\"A setting, environment, or facility that is not an aquarium and does not house or display aquatic animals and plants.\",\"s\":\"The wildlife center was a nonaquarium facility, housing only land animals like reptiles and birds.\",\"p\":\"non-uh-KWAIR-ee-um\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"non.aquar.i.um\",\"ps\":\"noun\",\"t\":[\"animals\",\"marine\",\"botany\",\"ecology\",\"olatin\"]},{\"w\":\"nonarbitrary\",\"d\":\"not subject to individual determination\",\"s\":\"The teacher's grading system was nonarbitrary, based on a clear rubric that every student could understand.\",\"p\":\"non-AR-bih-trair-ee\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"nonar.bi.trary\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonarboreal\",\"d\":\"not inhabiting or frequenting trees\",\"s\":\"The prairie dog is a nonarboreal creature that builds its home underground rather than in trees.\",\"p\":\"non-ar-BOR-ee-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"nonar.bo.re.al\",\"ps\":\"adjective\",\"t\":[\"flowers\",\"olatin\"]},{\"w\":\"nonarchaeological\",\"d\":\"Not related to or involving the scientific study of human history and prehistory through excavation and analysis of artifacts.\",\"s\":\"The historian took a nonarchaeological approach, relying on written records instead of digging up artifacts.\",\"p\":\"non-ar-kee-uh-LOJ-ih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"nonar.chae.o.log.i.cal\",\"ps\":\"adjective\",\"t\":[\"ancient\",\"olatin\"]},{\"w\":\"nonarchaeologist\",\"d\":\"A person who is not trained in or does not practice archaeology, the scientific study of ancient human cultures through physical remains.\",\"s\":\"As a nonarchaeologist, the novelist had to research ancient ruins by reading books rather than conducting digs.\",\"p\":\"non-ar-kee-OL-uh-jist\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"nonar.chae.ol.o.gist\",\"ps\":\"noun\",\"t\":[\"character\",\"ancient\",\"olatin\"]},{\"w\":\"nonarchaic\",\"d\":\"Not old-fashioned, ancient, or belonging to an early period of history; modern or current in style, language, or form.\",\"s\":\"The teacher preferred nonarchaic language in essays so that students would write in a modern, clear style.\",\"p\":\"non-ar-KAY-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"nonar.cha.ic\",\"ps\":\"adjective\",\"t\":[\"fabrics\",\"ancient\",\"wordwords\",\"olatin\"]},{\"w\":\"nonarchetypal\",\"d\":\"Not serving as a perfect or classic example of a type or category; lacking the defining features of an archetype.\",\"s\":\"The film's villain was refreshingly nonarchetypal, breaking away from the usual sneering, cape-wearing stereotype.\",\"p\":\"non-ar-kih-TY-pul\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nonar.chety.pal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonarchitectural\",\"d\":\"Not relating to architecture or the design and construction of buildings; not following architectural principles or styles.\",\"s\":\"The city planner focused on nonarchitectural factors like traffic flow and green spaces rather than building designs.\",\"p\":\"non-ar-kih-TEK-chur-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"nonar.chi.tec.tural\",\"ps\":\"adjective\",\"t\":[\"buildings\",\"logic\",\"olatin\"]},{\"w\":\"nonarchitecture\",\"d\":\"Work, design, or structures that do not follow the principles or aesthetics of formal architecture.\",\"s\":\"Critics debated whether the jumbled pile of steel beams in the museum was art or simply nonarchitecture.\",\"p\":\"non-AR-kih-tek-chur\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"nonar.chi.tec.ture\",\"ps\":\"noun\",\"t\":[\"buildings\",\"logic\",\"olatin\"]},{\"w\":\"nonarchival\",\"d\":\"Not related to, suitable for, or meeting the standards of preservation used in official archives or long-term storage.\",\"s\":\"The journalist stored her notes in a nonarchival format, which meant they would fade and crumble within decades.\",\"p\":\"non-ar-KY-vul\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"sy\":\"nonar.chival\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonarchived\",\"d\":\"Not stored, preserved, or catalogued in an archive or official records system for future access or reference.\",\"s\":\"Many old family photos remain nonarchived, tucked away in shoeboxes where no one can easily find them.\",\"p\":\"non-AR-kyvd\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"sy\":\"nonar.chived\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonarcing\",\"d\":\"Not producing or involving an electric arc, which is the luminous discharge of electricity between two conductors.\",\"s\":\"The engineer designed a nonarcing electrical switch to prevent dangerous sparks from forming during use.\",\"p\":\"non-AR-king\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"nonar.c.ing\",\"ps\":\"adjective\",\"t\":[\"physics\",\"music\",\"colors\",\"olatin\"]},{\"w\":\"nonargument\",\"d\":\"A statement, discussion, or exchange that does not constitute a real argument because it lacks logical reasoning or valid evidence.\",\"s\":\"The twins' polite chat about their weekend plans was a pleasant nonargument compared to their usual fierce debates.\",\"p\":\"non-AR-gyoo-ment\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"nonar.gu.ment\",\"ps\":\"noun\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonargumentative\",\"d\":\"Not inclined to argue or debate; describing a person, style, or statement that avoids confrontation and presents ideas calmly.\",\"s\":\"Mia was so nonargumentative that she would simply nod and smile even when she disagreed with someone.\",\"p\":\"non-ar-gyoo-MEN-tuh-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"nonar.gu.men.ta.tive\",\"ps\":\"adjective\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nonarid\",\"d\":\"Not extremely dry or lacking in moisture; describing a climate, region, or environment that has adequate rainfall or water supply.\",\"s\":\"The valley's nonarid climate, fed by mountain streams, allowed farmers to grow crops without irrigation.\",\"p\":\"non-AIR-id\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"nonar.id\",\"ps\":\"adjective\",\"t\":[\"weather\",\"ecology\",\"olatin\"]},{\"w\":\"nonarmed\",\"d\":\"Not carrying or equipped with weapons; describes a person, group, or vehicle that has no arms or weapons.\",\"s\":\"The security guard at the art museum was nonarmed, carrying only a radio and a flashlight.\",\"p\":\"non-ARMD\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.armed\",\"ps\":\"adjective\",\"t\":[\"war\",\"vehicles\",\"olatin\"]},{\"w\":\"nonarmored\",\"d\":\"Not protected by armor plating or a defensive covering; lacking the reinforced shielding typical of military vehicles.\",\"s\":\"The nonarmored jeep offered little protection in the combat zone, unlike the reinforced military vehicles nearby.\",\"p\":\"non-AR-merd\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.ar.mored\",\"ps\":\"adjective\",\"t\":[\"war\",\"vehicles\",\"olatin\"]},{\"w\":\"nonarmy\",\"d\":\"Not belonging to or associated with the army; relating to civilians or non-military organizations rather than armed forces.\",\"s\":\"The relief effort was led by a nonarmy organization made up entirely of civilian volunteers.\",\"p\":\"non-AR-mee\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.army\",\"ps\":\"adjective\",\"t\":[\"physics\",\"war\",\"olatin\"]},{\"w\":\"nonarousal\",\"d\":\"The absence of arousal or stimulation; a state in which a person or organism remains unexcited and unresponsive.\",\"s\":\"The therapist described nonarousal as a state of calm indifference that some patients experienced toward stressful situations.\",\"p\":\"non-uh-ROW-zul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonaroused\",\"d\":\"Not having been stimulated, excited, or awakened; remaining in a calm or unresponsive state.\",\"s\":\"The audience sat nonaroused through the dull presentation, barely blinking as slide after slide appeared.\",\"p\":\"non-uh-ROWZD\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonarousing\",\"d\":\"Failing to excite, stimulate, or awaken interest or attention; dull or unstimulating.\",\"s\":\"The professor's nonarousing lecture style made it hard for students to stay awake after lunch.\",\"p\":\"non-uh-ROW-zing\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"sy\":\"nonarous.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonarrested\",\"d\":\"Not having been taken into police custody; describes a person who has not been formally detained or charged by law enforcement.\",\"s\":\"Despite the chaos at the protest, most participants left nonarrested after the crowd peacefully dispersed.\",\"p\":\"non-uh-REST-ed\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"nonar.rest.ed\",\"ps\":\"adjective\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"nonarrival\",\"d\":\"The failure or absence of expected arrival; the state of not having come or reached a destination.\",\"s\":\"The nonarrival of the supply truck left the camp without food for an extra day.\",\"p\":\"non-uh-RY-vul\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nonar.rival\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonart\",\"d\":\"Something that is not considered art; an object, activity, or creation that falls outside the traditional or accepted definition of artistic work.\",\"s\":\"Some critics dismissed the randomly splattered canvas as nonart, arguing it required no skill or intention.\",\"p\":\"NON-art\",\"o\":\"Latin\",\"y\":8,\"bp\":16,\"ps\":\"noun\",\"t\":[\"painting\",\"festivals\",\"olatin\"]},{\"w\":\"nonarterial\",\"d\":\"Not relating to or functioning as a main artery; describes roads, blood vessels, or channels that are not primary routes or passages.\",\"s\":\"The town planners routed the festival traffic along nonarterial back roads to keep the main highways clear.\",\"p\":\"non-ar-TEER-ee-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"nonar.te.ri.al\",\"ps\":\"adjective\",\"t\":[\"body\",\"seafaring\",\"olatin\"]},{\"w\":\"nonarticular\",\"d\":\"Not relating to or involving the joints of the body; describes tissues, conditions, or processes that do not affect the articulations between bones.\",\"s\":\"The doctor noted that the patient's pain was nonarticular, meaning it came from the muscles rather than the joints.\",\"p\":\"non-ar-TIK-yoo-ler\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"nonar.tic.u.lar\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonarticulated\",\"d\":\"Not clearly expressed in words or structured segments; lacking distinct, well-formed expression or connected joints.\",\"s\":\"Her nonarticulated frustration showed only in her clenched jaw and silence, never in actual words.\",\"p\":\"non-ar-TIK-yoo-lay-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"nonar.tic.u.lat.ed\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonartificial\",\"d\":\"Not made or produced by human craft or technology; occurring naturally rather than being manufactured or synthetically created.\",\"s\":\"The chef prided herself on using only nonartificial ingredients, sourcing everything from local farms.\",\"p\":\"non-ar-tih-FISH-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"nonar.ti.fi.cial\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonartillery\",\"d\":\"Not involving or relating to large mounted guns or heavy weaponry; describes military units or operations that do not use artillery.\",\"s\":\"The soldiers carried nonartillery weapons such as rifles and grenades rather than heavy cannons.\",\"p\":\"non-ar-TIL-er-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"nonar.tillery\",\"ps\":\"adjective\",\"t\":[\"war\",\"olatin\"]},{\"w\":\"nonarts\",\"d\":\"Relating to fields or disciplines outside the fine or performing arts, such as sciences, trades, or technical subjects.\",\"s\":\"Students who pursued nonarts degrees in science or engineering still had to take one arts elective each year.\",\"p\":\"NON-arts\",\"o\":\"Latin\",\"y\":8,\"bp\":17,\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonAsian\",\"d\":\"Not of Asian origin, descent, or heritage; describing a person, culture, or thing that does not belong to or originate from Asia.\",\"s\":\"The cultural festival welcomed nonAsian attendees who wanted to learn about traditions from across the continent.\",\"p\":\"non-AY-zhun\",\"o\":\"Latin\",\"y\":8,\"bp\":24,\"sy\":\"nonasian\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonaspectual\",\"d\":\"Not relating to grammatical aspect, which expresses how an action extends over time; describes verb forms or linguistic structures that do not convey aspectual meaning.\",\"s\":\"The linguist explained that some verbs are nonaspectual and do not show whether an action is ongoing or completed.\",\"p\":\"non-as-PEK-choo-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"nonaspec.tu.al\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"time\",\"olatin\"]},{\"w\":\"nonaspirate\",\"d\":\"A speech sound produced without an audible puff of air; in phonetics, a consonant that lacks the breathy quality of an aspirated sound.\",\"s\":\"In some languages, a nonaspirate consonant is produced without the puff of air that English speakers naturally add.\",\"p\":\"non-AS-per-it\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"sy\":\"nonaspi.rate\",\"ps\":\"noun\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonaspirated\",\"d\":\"Produced without a puff of breath; describes a consonant sound in which no burst of air follows its release, as opposed to an aspirated sound.\",\"s\":\"The phonetics teacher demonstrated nonaspirated sounds by holding a tissue in front of her mouth that did not move.\",\"p\":\"non-AS-per-ay-ted\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"nonaspi.rat.ed\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonaspirational\",\"d\":\"Lacking ambition, high goals, or a desire for achievement; describing attitudes, content, or contexts that do not inspire or encourage lofty aims.\",\"s\":\"Critics worried that the school's nonaspirational curriculum failed to inspire students to dream big.\",\"p\":\"non-as-per-AY-shun-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nonaspi.ra.tional\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonaspirin\",\"d\":\"A pain-relieving or fever-reducing medication that does not contain aspirin; refers to analgesics such as acetaminophen or ibuprofen used as alternatives to aspirin.\",\"s\":\"The doctor recommended a nonaspirin pain reliever for the child since aspirin can be dangerous for young patients.\",\"p\":\"non-AS-per-in\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"ps\":\"adjective\",\"t\":[\"body\",\"disease\",\"pharmacy\",\"olatin\"]},{\"w\":\"nonassaulted\",\"d\":\"Not having been physically attacked or subjected to a violent assault; describes a person who has not been the victim of an assault.\",\"s\":\"Luckily, all the students remained nonassaulted after the school quickly intervened to stop the bullying.\",\"p\":\"non-uh-SAWL-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"nonas.sault.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonassertive\",\"d\":\"not forceful in pushing your own views, though not necessarily lacking confidence\",\"s\":\"He was so nonassertive that he never spoke up, even when he had the best idea in the room.\",\"p\":\"non-uh-SER-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":33,\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonassertively\",\"d\":\"In a manner that is not forceful or self-promoting; behaving quietly or passively without strongly pushing one's own opinions or desires.\",\"s\":\"She nonassertively suggested a different route, adding so many apologies that no one took her seriously.\",\"p\":\"non-uh-SER-tiv-lee\",\"o\":\"Latin\",\"y\":9,\"bp\":24,\"sy\":\"nonassertive.ly\",\"ps\":\"adverb\",\"t\":[\"olatin\"]},{\"w\":\"nonassessable\",\"d\":\"Not able to be evaluated, measured, or taxed; describes property, income, or qualities that cannot be assigned a formal value or assessment.\",\"s\":\"The damage to the ancient mural was deemed nonassessable because no one could agree on its original value.\",\"p\":\"non-uh-SES-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":23,\"sy\":\"nonassess.able\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonassigned\",\"d\":\"Not allocated, designated, or given to a particular person, task, or purpose; lacking a specific assignment.\",\"s\":\"The nonassigned seats on the flight meant passengers could sit wherever they wished when they boarded.\",\"p\":\"non-uh-SYND\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"sy\":\"nonas.signed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonassimilated\",\"d\":\"Not absorbed into or adopted by a larger cultural, social, or biological group; maintaining a distinct identity separate from the surrounding community.\",\"s\":\"The nonassimilated immigrant community kept its language, food, and customs alive for generations.\",\"p\":\"non-uh-SIM-ih-lay-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"nonas.sim.i.lat.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonassisted\",\"d\":\"Done without help, support, or aid from another person or device; accomplished entirely through one's own effort or ability.\",\"s\":\"The nonassisted climb up the mountain tested every ounce of the hiker's strength.\",\"p\":\"non-uh-SIS-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"nonas.sist.ed\",\"ps\":\"adjective\",\"t\":[\"tools\",\"olatin\"]},{\"w\":\"nonassistive\",\"d\":\"Not providing assistance or support; describing technology, methods, or approaches that are not designed to aid people with disabilities or special needs.\",\"s\":\"The nonassistive environment forced students to solve problems entirely on their own.\",\"p\":\"non-uh-SIS-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"nonas.sis.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonassociated\",\"d\":\"Not connected, linked, or affiliated with a particular group, organization, or set of ideas; existing independently without formal ties.\",\"s\":\"The two chemical compounds were nonassociated and did not bond under normal conditions.\",\"p\":\"non-uh-SOH-see-ay-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"nonas.so.ci.at.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonassociation\",\"d\":\"The lack of connection or affiliation between people, groups, or ideas; the state of not being formally linked or joined together.\",\"s\":\"The nonassociation of the rival gangs was enforced by a strict court order.\",\"p\":\"non-uh-soh-see-AY-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"nonas.so.ci.a.tion\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonassociativity\",\"d\":\"In mathematics, the property of an operation in which changing the grouping of elements produces different results; the absence of the associative property.\",\"s\":\"The mathematician explained that nonassociativity means changing grouping changes the result.\",\"p\":\"non-uh-soh-shee-uh-TIV-ih-tee\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"nonas.so.cia.tiv.i.ty\",\"ps\":\"noun\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonasterisked\",\"d\":\"Not marked or labeled with an asterisk symbol; describes text, entries, or items that carry no special notation or footnote indicator.\",\"s\":\"The nonasterisked items on the menu had no special conditions attached to them.\",\"p\":\"non-AS-ter-iskt\",\"o\":\"Latin\",\"y\":9,\"bp\":23,\"sy\":\"nonas.terisked\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonasthmatic\",\"d\":\"Not affected by or relating to asthma; describes a person who does not suffer from the respiratory condition characterized by airway constriction and wheezing.\",\"s\":\"As a nonasthmatic runner, she never needed an inhaler during races.\",\"p\":\"non-az-MAT-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"nonasth.mat.ic\",\"ps\":\"adjective\",\"t\":[\"disease\",\"character\",\"olatin\"]},{\"w\":\"nonastrological\",\"d\":\"Not based on or relating to astrology; describes fields, methods, or beliefs that do not involve the study of celestial bodies as influences on human affairs.\",\"s\":\"His nonastrological approach to decision-making relied entirely on data and logic.\",\"p\":\"non-as-truh-LOJ-ih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"nonas.tro.log.i.cal\",\"ps\":\"adjective\",\"t\":[\"astronomy\",\"logic\",\"olatin\"]},{\"w\":\"nonastronomer\",\"d\":\"A person who is not an astronomer; someone who does not professionally or formally study celestial objects and the universe.\",\"s\":\"Even as a nonastronomer, she could identify the Big Dipper in the night sky.\",\"p\":\"non-uh-STRON-uh-mer\",\"o\":\"Latin\",\"y\":9,\"bp\":23,\"sy\":\"nonas.tronomer\",\"ps\":\"noun\",\"t\":[\"astronomy\",\"character\",\"olatin\"]},{\"w\":\"nonastronomical\",\"d\":\"Not relating to astronomy or the scientific study of the universe; describes amounts, scales, or ideas that are not of the enormous magnitude associated with astronomical figures.\",\"s\":\"The cost of the repairs was high but nonastronomical, so they could afford it.\",\"p\":\"non-as-truh-NOM-ih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"nonas.tro.nom.i.cal\",\"ps\":\"adjective\",\"t\":[\"astronomy\",\"olatin\"]},{\"w\":\"nonasymptotic\",\"d\":\"Not approaching a line or value as a limit without ever reaching it; describes functions or curves that do not exhibit asymptotic behavior.\",\"s\":\"The graph followed a nonasymptotic path, eventually crossing the axis rather than approaching it forever.\",\"p\":\"non-ay-simp-TOT-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nonasymp.tot.ic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonasynchronous\",\"d\":\"Not operating or occurring at different or independent times; describes processes that are coordinated or synchronized rather than happening out of step with one another.\",\"s\":\"The nonasynchronous system required all devices to operate at exactly the same time.\",\"p\":\"non-ay-SINK-ruh-nus\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nonasyn.chronous\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nonatheistic\",\"d\":\"Not holding or relating to atheism; describes beliefs, philosophies, or worldviews that do not deny the existence of a god or gods.\",\"s\":\"Her nonatheistic worldview led her to explore several different religious traditions.\",\"p\":\"non-ay-thee-IS-tik\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"nonathe.is.tic\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonatmospheric\",\"d\":\"Not relating to or existing within the atmosphere; describing conditions, pressures, or phenomena that occur outside or independent of a planetary atmosphere.\",\"s\":\"Scientists measured nonatmospheric pressure inside the sealed vacuum chamber.\",\"p\":\"non-at-muh-SFAIR-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nonat.mo.spher.ic\",\"ps\":\"adjective\",\"t\":[\"astronomy\",\"olatin\"]},{\"w\":\"nonatomic\",\"d\":\"Not relating to atoms or atomic structure; describing a process, substance, or operation that does not involve individual atoms as its basic unit.\",\"s\":\"The nonatomic reaction involved large molecular clusters rather than individual atoms.\",\"p\":\"non-uh-TOM-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"nonatom.ic\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonatomistic\",\"d\":\"Not based on the philosophical or scientific view that reality is composed of discrete, indivisible units; rejecting the idea that wholes can be fully explained by their smallest parts.\",\"s\":\"The philosopher's nonatomistic view held that wholes are more than the sum of their parts.\",\"p\":\"non-at-uh-MIS-tik\",\"o\":\"Latin\",\"y\":8,\"bp\":33,\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonatrial\",\"d\":\"Not relating to or originating from the atria, the upper chambers of the heart; used to describe cardiac conditions or signals that arise elsewhere in the heart.\",\"s\":\"The doctor confirmed the arrhythmia was nonatrial, originating in the lower chambers of the heart.\",\"p\":\"non-AY-tree-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"nona.tri.al\",\"ps\":\"adjective\",\"t\":[\"body\",\"buildings\",\"olatin\"]},{\"w\":\"nonattached\",\"d\":\"Not fastened, connected, or affiliated with something; describing a person, object, or organization that remains independent and unbound.\",\"s\":\"The nonattached documents were lost because they weren't properly filed with the report.\",\"p\":\"non-uh-TACHT\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"sy\":\"nonat.tached\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonattacking\",\"d\":\"Not engaging in or characterized by offensive action or aggression; describing a strategy, player, or entity that refrains from initiating an attack.\",\"s\":\"In chess class, they practiced a nonattacking opening that focused on defense.\",\"p\":\"non-uh-TAK-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"nonat.tack.ing\",\"ps\":\"adjective\",\"t\":[\"character\",\"sports\",\"olatin\"]},{\"w\":\"nonattainment\",\"d\":\"The failure to reach a required standard or goal, especially used in environmental policy to describe areas that have not met federal air quality standards.\",\"s\":\"The city was placed in nonattainment status because its air quality failed federal standards.\",\"p\":\"non-uh-TAYN-munt\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nonat.tain.ment\",\"ps\":\"noun\",\"t\":[\"ecology\",\"politics\",\"sports\",\"olatin\"]},{\"w\":\"nonattender\",\"d\":\"a person who fails to show up at an event or meeting they were expected to join\",\"s\":\"The consistent nonattender was called into the principal's office to explain his absences.\",\"p\":\"non-uh-TEN-dur\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"nonat.ten.der\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonattending\",\"d\":\"Not present at or participating in a scheduled event, meeting, or obligation; describing someone or something that fails to show up.\",\"s\":\"The nonattending parent missed every school conference that semester.\",\"p\":\"non-uh-TEN-ding\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"nonat.tend.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonattention\",\"d\":\"A lack of focus, notice, or mental concentration; the state of failing to pay attention to something or someone.\",\"s\":\"His nonattention during the lesson meant he had no idea what the homework was.\",\"p\":\"non-uh-TEN-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"nonat.ten.tion\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonattenuated\",\"d\":\"Not weakened, reduced, or thinned in strength, intensity, or concentration; remaining at full power or potency without any reduction.\",\"s\":\"The nonattenuated signal was so strong it overloaded the speakers.\",\"p\":\"non-uh-TEN-yoo-ay-tid\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"nonat.ten.u.at.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonattenuative\",\"d\":\"Not having the quality or function of reducing, weakening, or diminishing something; describing a process or substance that does not cause attenuation.\",\"s\":\"The nonattenuative filter allowed all signal strengths to pass through unchanged.\",\"p\":\"non-uh-TEN-yoo-ay-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"nonat.ten.u.a.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonattitudinal\",\"d\":\"Not related to or based on a person's attitude, opinion, or mental stance; describing behavior or measurement that does not reflect underlying attitudes.\",\"s\":\"The survey used nonattitudinal questions that focused on behavior rather than opinions.\",\"p\":\"non-at-ih-TOO-dih-nul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"nonat.ti.tu.di.nal\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonattracted\",\"d\":\"Not drawn toward or interested in something or someone; lacking a feeling of attraction or appeal.\",\"s\":\"The scientist noted that the two magnets were nonattracted when their like poles faced each other.\",\"p\":\"non-uh-TRAKT-id\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"nonat.tract.ed\",\"ps\":\"adjective\",\"t\":[\"emotions\",\"olatin\"]},{\"w\":\"nonattracting\",\"d\":\"Not drawing interest, attention, or other objects toward itself; failing to exert any pull or appeal on others.\",\"s\":\"The dull window display was nonattracting, and few shoppers stopped to look.\",\"p\":\"non-uh-TRAKT-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nonat.tract.ing\",\"ps\":\"adjective\",\"t\":[\"painting\",\"olatin\"]},{\"w\":\"nonattractive\",\"d\":\"Not appealing, pleasing, or capable of drawing interest; lacking qualities that would attract attention or admiration.\",\"s\":\"The plain, nonattractive packaging made the product easy to overlook on the shelf.\",\"p\":\"non-uh-TRAK-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nonat.trac.tive\",\"ps\":\"adjective\",\"t\":[\"painting\",\"olatin\"]},{\"w\":\"nonattributive\",\"d\":\"In grammar, describing an adjective or modifier that does not directly precede and modify a noun; not functioning in an attributive grammatical position.\",\"s\":\"In grammar, a nonattributive adjective appears in the predicate rather than before the noun.\",\"p\":\"non-uh-TRIB-yuh-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"nonat.tribu.tive\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonauction\",\"d\":\"Not involving or conducted through an auction process; describing a sale or transfer of goods that takes place without competitive bidding.\",\"s\":\"The estate was settled through a nonauction sale, with prices negotiated privately.\",\"p\":\"non-AWK-shun\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"nonauc.tion\",\"ps\":\"adjective\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nonaudio\",\"d\":\"Not relating to or involving sound or the transmission of audio signals; describing media, content, or technology that has no audible component.\",\"s\":\"The nonaudio portion of the presentation relied entirely on charts and written text.\",\"p\":\"non-AW-dee-oh\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nonau.dio\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonauditory\",\"d\":\"Not relating to the sense of hearing or the organs and pathways involved in processing sound; describing stimuli or responses that do not involve hearing.\",\"s\":\"Dogs use nonauditory signals like body posture to communicate with each other.\",\"p\":\"non-AW-dih-tor-ee\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"nonau.di.to.ry\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonaugmentative\",\"d\":\"Not serving to increase, enlarge, or intensify something; describing a grammatical form or process that does not add the meaning of greater size or intensity.\",\"s\":\"The nonaugmentative suffix did not intensify the meaning of the root word at all.\",\"p\":\"non-awg-MEN-tuh-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"nonaug.men.ta.tive\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonaugmented\",\"d\":\"Not increased, enlarged, or enhanced in any way; remaining in its original, unmodified state without any additions or improvements.\",\"s\":\"The nonaugmented choir performance used no electronic enhancement whatsoever.\",\"p\":\"non-awg-MEN-tid\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"nonaug.ment.ed\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonauthenticity\",\"d\":\"The quality or state of being fake, false, or not genuine; the absence of authenticity in a person, object, or document.\",\"s\":\"The art expert's report confirmed the nonauthenticity of the painting, revealing it as a forgery.\",\"p\":\"non-aw-then-TIS-ih-tee\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"nonau.then.tic.i.ty\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonauthigenic\",\"d\":\"In geology, describing minerals or sediments that were not formed in their current location but were transported there from elsewhere.\",\"s\":\"The nonauthigenic minerals in the rock were transported from a distant source.\",\"p\":\"non-aw-thih-JEN-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nonau.thi.genic\",\"ps\":\"adjective\",\"t\":[\"minerals\",\"olatin\"]},{\"w\":\"nonauthorial\",\"d\":\"Not relating to or characteristic of an author; describing elements of a text or work that do not originate from or reflect the intentions of its creator.\",\"s\":\"The editor made so many changes that the final text felt entirely nonauthorial.\",\"p\":\"non-aw-THOR-ee-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"nonau.tho.ri.al\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"nonauthorized\",\"d\":\"Not officially approved, sanctioned, or given permission; describing an action, person, or item that lacks proper authorization.\",\"s\":\"The nonauthorized entry into the lab triggered the security alarm immediately.\",\"p\":\"non-AW-thuh-ryzd\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nonau.tho.rized\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"nonautistic\",\"d\":\"Not having or relating to autism spectrum disorder; describing a person whose neurological development does not fall on the autism spectrum.\",\"s\":\"Researchers studied how nonautistic children developed social skills at different ages.\",\"p\":\"non-aw-TIS-tik\",\"o\":\"Latin\",\"y\":8,\"bp\":34,\"sy\":\"nonautis.tic\",\"ps\":\"adjective\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"nonautobiographical\",\"d\":\"Not based on or drawn from the author's own life experiences; describing fiction, narrative, or writing that does not recount the writer's personal history.\",\"s\":\"The author insisted her novel was nonautobiographical, even though the main character shared her exact childhood.\",\"p\":\"non-aw-toh-by-oh-GRAF-ih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":33,\"sy\":\"nonau.to.bi.o.graph.i.cal\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"nonautocratic\",\"d\":\"Not governed or controlled by a single person with absolute power; describing a system or leadership style that distributes authority among many rather than concentrating it in one ruler.\",\"s\":\"The new school council was proudly nonautocratic, letting every student vote on the rules.\",\"p\":\"non-aw-toh-KRAT-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"nonau.to.crat.ic\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"nonautogenic\",\"d\":\"Not produced or generated by the organism or system itself; originating from an external source rather than being self-created.\",\"s\":\"Scientists confirmed the pollution was nonautogenic, meaning it came from an outside source rather than the environment itself.\",\"p\":\"non-aw-toh-JEN-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"nonau.to.genic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonautoimmune\",\"d\":\"Not involving or caused by the immune system attacking the body's own tissues; describing a disease or condition that has an external or non-self-directed cause.\",\"s\":\"The doctor confirmed the patient's condition was nonautoimmune, so the body was not attacking itself.\",\"p\":\"non-aw-toh-ih-MYOON\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nonau.toim.mune\",\"ps\":\"adjective\",\"t\":[\"body\",\"disease\",\"olatin\"]},{\"w\":\"nonautologous\",\"d\":\"Derived from or belonging to a different individual or species rather than the patient or organism itself; used especially in medicine to describe transplanted tissue or cells from an outside donor.\",\"s\":\"The surgeon used nonautologous tissue from a donor rather than the patient's own body.\",\"p\":\"non-aw-TOL-uh-gus\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"nonau.tol.o.gous\",\"ps\":\"adjective\",\"t\":[\"body\",\"pharmacy\",\"olatin\"]},{\"w\":\"nonautomation\",\"d\":\"The absence or avoidance of automated machinery or computerized processes; relying on human labor and manual methods rather than machines to complete tasks.\",\"s\":\"The small bakery relied on nonautomation, with every loaf shaped by hand.\",\"p\":\"non-aw-tuh-MAY-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nonau.toma.tion\",\"ps\":\"noun\",\"t\":[\"tools\",\"olatin\"]},{\"w\":\"nonautoreactive\",\"d\":\"In immunology, describing immune cells or antibodies that do not react against the body's own tissues or molecules, remaining harmlessly inactive toward the self.\",\"s\":\"The lab test showed the antibodies were nonautoreactive, meaning they targeted only foreign substances.\",\"p\":\"non-aw-toh-ree-AK-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"nonau.tore.ac.tive\",\"ps\":\"adjective\",\"t\":[\"body\",\"chemistry\",\"olatin\"]},{\"w\":\"nonautotrophic\",\"d\":\"Unable to produce its own food from inorganic substances; describing an organism that must obtain energy and nutrients by consuming other organisms or organic matter.\",\"s\":\"Unlike plants, animals are nonautotrophic because they cannot make their own food from sunlight.\",\"p\":\"non-aw-toh-TROF-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"nonau.totroph.ic\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonauxiliary\",\"d\":\"Not serving a supporting or supplementary role; describing something that functions as a primary or independent element rather than as a helper or backup.\",\"s\":\"The nonauxiliary staff members were the core teachers, not the helpers brought in for support.\",\"p\":\"non-awg-ZIL-ee-air-ee\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"nonaux.il.iary\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonavailable\",\"d\":\"Not accessible, obtainable, or ready for use; describing a resource, person, or item that cannot be reached or utilized at a given time.\",\"s\":\"The rare book was listed as nonavailable at every library in the city.\",\"p\":\"non-uh-VAY-luh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.avail.able\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nonaversive\",\"d\":\"Not causing discomfort, pain, or unpleasant sensations; describing a training method or stimulus that achieves results without punishment or negative reinforcement.\",\"s\":\"The dog trainer used only nonaversive techniques, rewarding good behavior instead of punishing bad behavior.\",\"p\":\"non-uh-VUR-siv\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.aver.sive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonavian\",\"d\":\"Not belonging to or characteristic of birds; describing animals, dinosaurs, or other organisms that are not classified within the class Aves.\",\"s\":\"Crocodiles are nonavian reptiles, meaning they are related to dinosaurs but are not birds.\",\"p\":\"non-AY-vee-un\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.a.vian\",\"ps\":\"adjective\",\"t\":[\"animals\",\"birds\",\"olatin\"]},{\"w\":\"nonawake\",\"d\":\"Not in a state of wakefulness or consciousness; describing a person or animal that is asleep, unconscious, or otherwise not alert and aware.\",\"s\":\"The baby was in a nonawake state for most of the car ride, sleeping peacefully.\",\"p\":\"non-uh-WAYK\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.awake\",\"ps\":\"adjective\",\"t\":[\"animals\",\"olatin\"]},{\"w\":\"nonaxial\",\"d\":\"Not relating to or arranged along an axis; describing a force, motion, or structure that does not align with a central axis.\",\"s\":\"The nonaxial force pushed the object sideways rather than along its central line.\",\"p\":\"non-AK-see-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.ax.i.al\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonaxisymmetric\",\"d\":\"Not having symmetry around a central axis; describing a shape or system that looks different when rotated around its axis.\",\"s\":\"The engineer noted the design was nonaxisymmetric, so it looked different from every angle.\",\"p\":\"non-ak-see-sih-MET-rik\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.ax.isym.met.ric\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonaxisymmetrical\",\"d\":\"Lacking symmetry around a central axis; used to describe objects or patterns that are not uniform when rotated about their central line.\",\"s\":\"The sculpture was intentionally nonaxisymmetrical, with no two sides matching when rotated.\",\"p\":\"non-ak-see-sih-MET-rih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.ax.isym.met.ri.cal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonazimuthal\",\"d\":\"Not relating to or measured by azimuth, which is the horizontal compass angle used in navigation and astronomy.\",\"s\":\"The telescope mount was nonazimuthal, tracking stars along a tilted path instead of the horizon.\",\"p\":\"non-az-ih-MYOO-thul\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"non.az.imuthal\",\"ps\":\"adjective\",\"t\":[\"astronomy\",\"maps\",\"numbers\",\"olatin\"]},{\"w\":\"nonback\",\"d\":\"Not located at or relating to the back; in linguistics, describing vowel sounds produced in the front of the mouth rather than the back.\",\"s\":\"The linguist described the vowel sound as nonback, produced at the front of the mouth.\",\"p\":\"non-BAK\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.back\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonbacklit\",\"d\":\"Not illuminated from behind; describing a screen or display that has no light source shining through it from the back.\",\"s\":\"The nonbacklit screen was hard to read in the dark without an extra lamp.\",\"p\":\"non-BAK-lit\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.back.lit\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonbacktracking\",\"d\":\"Not returning to a previous position or step; describing an algorithm or process that moves forward without revisiting earlier choices.\",\"s\":\"The maze-solving robot used a nonbacktracking algorithm, always moving forward without retracing its path.\",\"p\":\"non-BAK-trak-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.back.track.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonbacterial\",\"d\":\"Not caused by or related to bacteria; describing an infection, condition, or substance in which bacteria play no role.\",\"s\":\"The doctor confirmed the infection was nonbacterial, so antibiotics would not help treat it.\",\"p\":\"non-bak-TEER-ee-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":39,\"sy\":\"non.bac.te.ri.al\",\"ps\":\"adjective\",\"t\":[\"disease\",\"stage\",\"olatin\"]},{\"w\":\"nonbad\",\"d\":\"Not bad; describing something that is acceptable, neutral, or at least above a negative standard of quality.\",\"s\":\"The critic gave the movie a 'nonbad' rating, meaning it wasn't great but wasn't terrible either.\",\"p\":\"non-BAD\",\"o\":\"Latin\",\"y\":8,\"bp\":18,\"sy\":\"non.bad\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonbaited\",\"d\":\"Not containing or using bait; describing a trap, hook, or lure that has no attractant placed inside or on it.\",\"s\":\"The scientist set nonbaited traps to observe which animals explored new objects on their own.\",\"p\":\"non-BAY-tid\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.bait.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonbaked\",\"d\":\"Not subjected to baking or oven heat; describing a food or material that is prepared or set without the use of an oven.\",\"s\":\"The recipe called for a nonbaked crust made simply by pressing crushed cookies into the pan.\",\"p\":\"non-BAYKT\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.baked\",\"ps\":\"adjective\",\"t\":[\"culinary\",\"olatin\"]},{\"w\":\"nonbaking\",\"d\":\"Not intended for or involving the process of baking; describing ingredients or methods that do not require oven heat.\",\"s\":\"The nonbaking chocolate is used for melting and dipping, not for making cakes.\",\"p\":\"non-BAY-king\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.bak.ing\",\"ps\":\"adjective\",\"t\":[\"culinary\",\"olatin\"]},{\"w\":\"nonbald\",\"d\":\"Not bald; describing a person or animal that retains a full or significant amount of hair on the head.\",\"s\":\"The commercial showed nonbald men testing the shampoo, but the product was also designed for hair loss.\",\"p\":\"non-BAWLD\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.bald\",\"ps\":\"adjective\",\"t\":[\"animals\",\"olatin\"]},{\"w\":\"nonbalding\",\"d\":\"Not in the process of losing hair; describing someone whose hair is not thinning or receding.\",\"s\":\"The study compared nonbalding participants with those experiencing hair loss to find differences in scalp health.\",\"p\":\"non-BAWL-ding\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.bald.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonballistic\",\"d\":\"Not following the curved, unpowered flight path of a projectile; describing a missile or vehicle that is guided or powered throughout its trajectory.\",\"s\":\"The guided missile used nonballistic flight, adjusting its path the entire way to its target.\",\"p\":\"non-buh-LIS-tik\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.bal.lis.tic\",\"ps\":\"adjective\",\"t\":[\"vehicles\",\"olatin\"]},{\"w\":\"nonbank\",\"d\":\"Not a bank; describing a financial institution or company that offers money-related services but does not hold a formal banking charter or license.\",\"s\":\"PayPal is a nonbank financial company because it handles money but is not an official bank.\",\"p\":\"NAH-NBA-ngk\",\"o\":\"Latin\",\"y\":6,\"bp\":19,\"sy\":\"naa.nbae.ngk\",\"ps\":\"adjective\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nonbankable\",\"d\":\"Not acceptable to a bank as a financial asset or creditworthy project; describing a loan, project, or person that a bank would refuse to finance.\",\"s\":\"The strange art film was considered nonbankable because investors doubted it would ever make a profit.\",\"p\":\"non-BANK-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.bank.able\",\"ps\":\"adjective\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nonbanker\",\"d\":\"A person who does not work in or belong to the banking industry; someone outside the professional world of banking and finance.\",\"s\":\"As a nonbanker, she found all the financial jargon at the investment meeting confusing.\",\"p\":\"non-BANK-ur\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.banker\",\"ps\":\"noun\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nonbankruptcy\",\"d\":\"Not involving or related to bankruptcy; describing a legal or financial process that resolves debt or financial difficulty without a formal bankruptcy filing.\",\"s\":\"The lawyer specialized in nonbankruptcy debt solutions like negotiation and payment plans.\",\"p\":\"non-BANK-rupt-see\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.bankrupt.cy\",\"ps\":\"adjective\",\"t\":[\"law\",\"economy\",\"olatin\"]},{\"w\":\"nonbaptismal\",\"d\":\"Not relating to or involving the religious ceremony of baptism; describing a rite, name, or event that has no connection to baptism.\",\"s\":\"The church service was a nonbaptismal ceremony celebrating the couple's anniversary.\",\"p\":\"non-bap-TIZ-mul\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"non.bap.tismal\",\"ps\":\"adjective\",\"t\":[\"religion\",\"olatin\"]},{\"w\":\"nonbaptized\",\"d\":\"Not having undergone the religious ceremony of baptism; describing a person who has never been baptized.\",\"s\":\"The historical record showed that many nonbaptized children were still welcomed into the village community.\",\"p\":\"non-BAP-tyzd\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.bap.tized\",\"ps\":\"adjective\",\"t\":[\"religion\",\"olatin\"]},{\"w\":\"nonbarbaric\",\"d\":\"Not barbaric or cruel; describing behavior, a practice, or a society that is civilized and does not involve savage or brutal actions.\",\"s\":\"The referee insisted the competition remain nonbarbaric, with strict rules against any violent behavior.\",\"p\":\"non-bar-BAIR-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.bar.bar.ic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonbarbiturate\",\"d\":\"Not belonging to the class of drugs known as barbiturates; describing a sedative or medication that produces calming effects through a different chemical mechanism.\",\"s\":\"The doctor prescribed a nonbarbiturate sleep aid that was considered safer for long-term use.\",\"p\":\"non-bar-BIH-chur-it\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.bar.bi.tu.rate\",\"ps\":\"adjective\",\"t\":[\"body\",\"pharmacy\",\"chemistry\",\"tools\",\"olatin\"]},{\"w\":\"nonbarcoded\",\"d\":\"Not marked with a barcode; describing a product or item that lacks the printed series of parallel lines used for electronic scanning and identification.\",\"s\":\"The handmade crafts were sold as nonbarcoded items at the farmers' market, each priced by a paper tag.\",\"p\":\"non-BAR-kohd-id\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.bar.cod.ed\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonbarking\",\"d\":\"Not producing a barking sound; describing a dog breed or animal that rarely or never makes the sharp, loud sound typical of most dogs.\",\"s\":\"The basenji is known as a nonbarking dog, communicating with yodels and howls instead.\",\"p\":\"non-BAR-king\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.bark.ing\",\"ps\":\"adjective\",\"t\":[\"animals\",\"olatin\"]},{\"w\":\"nonbarley\",\"d\":\"Not containing or derived from barley; describing a food, beverage, or grain product made without the use of barley.\",\"s\":\"The brewer experimented with nonbarley grains like sorghum to create a gluten-free beer.\",\"p\":\"non-BAR-lee\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.bar.ley\",\"ps\":\"adjective\",\"t\":[\"farming\",\"dishes\",\"olatin\"]},{\"w\":\"nonbarometric\",\"d\":\"Not relating to or measured by atmospheric pressure using a barometer; describing a system or method that does not rely on barometric readings.\",\"s\":\"The scientist used a nonbarometric pressure sensor that measured force through electrical resistance instead of air.\",\"p\":\"non-bair-uh-MET-rik\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.baro.met.ric\",\"ps\":\"adjective\",\"t\":[\"weather\",\"numbers\",\"olatin\"]},{\"w\":\"nonbarred\",\"d\":\"Not having bars or stripes; also, not blocked or restricted by barriers, rules, or legal prohibitions.\",\"s\":\"The nonbarred windows let sunlight flood every corner of the old library.\",\"p\":\"non-BARD\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.barred\",\"ps\":\"adjective\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"nonbarren\",\"d\":\"Not barren; describing land, a person, or an organism that is fertile and capable of producing growth, crops, or offspring.\",\"s\":\"The scientists were excited to discover a nonbarren region on the distant planet that could support plant life.\",\"p\":\"non-BAIR-un\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.bar.ren\",\"ps\":\"adjective\",\"t\":[\"farming\",\"olatin\"]},{\"w\":\"nonbarricaded\",\"d\":\"Not blocked or closed off by a barricade; describing a road, passage, or area that remains open and unobstructed by barriers.\",\"s\":\"The nonbarricaded street allowed emergency vehicles to pass through quickly during the storm.\",\"p\":\"non-BAIR-ih-kay-did\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.bar.ri.cad.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonbaryonic\",\"d\":\"Not composed of baryons, which are particles such as protons and neutrons that make up ordinary matter; often used to describe dark matter that cannot be detected through normal means.\",\"s\":\"Physicists believe that most of the universe's dark matter is nonbaryonic, meaning it isn't made of ordinary particles.\",\"p\":\"non-bair-ee-ON-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.bary.on.ic\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonbasal\",\"d\":\"Not located at or relating to the base; describing a structure, cell layer, or process that does not originate from or connect to the base level.\",\"s\":\"The doctor noted that the tumor cells showed a nonbasal pattern under the microscope.\",\"p\":\"non-BAY-sul\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.basal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonbasalt\",\"d\":\"Not composed of or relating to basalt, the dark volcanic rock formed from cooled lava; describing a geological formation made of different rock types.\",\"s\":\"The geologist confirmed that the unusual rock sample was nonbasalt, making it rare for that volcanic region.\",\"p\":\"non-buh-SAWLT\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.basalt\",\"ps\":\"adjective\",\"t\":[\"minerals\",\"olatin\"]},{\"w\":\"nonbasaltic\",\"d\":\"Not having the composition or characteristics of basalt; describing rock, lava, or geological material that differs from the typical dark, fine-grained volcanic rock.\",\"s\":\"The island's nonbasaltic soil surprised researchers who expected volcanic rock beneath the surface.\",\"p\":\"non-buh-SAWL-tik\",\"o\":\"Latin\",\"y\":8,\"bp\":34,\"sy\":\"non.basaltic\",\"ps\":\"adjective\",\"t\":[\"minerals\",\"olatin\"]},{\"w\":\"nonbaseball\",\"d\":\"Not related to or involving the sport of baseball; describing an activity, venue, or context that has nothing to do with the game.\",\"s\":\"The community center offered many nonbaseball summer sports programs for kids who preferred soccer or swimming.\",\"p\":\"non-BAYS-bawl\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.base.ball\",\"ps\":\"adjective\",\"t\":[\"sports\",\"olatin\"]},{\"w\":\"nonbaseline\",\"d\":\"Not conforming to or measured against a standard baseline; describing data, behavior, or performance that falls outside the normal reference point.\",\"s\":\"The researchers collected nonbaseline data to compare changes over time in the patients' conditions.\",\"p\":\"non-BAYS-lyn\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.base.line\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonbasement\",\"d\":\"Not located in or relating to a basement; describing a room, floor, or area of a building that is at or above ground level.\",\"s\":\"They chose a nonbasement apartment so they could enjoy natural light through large windows.\",\"p\":\"non-BAYS-munt\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.base.ment\",\"ps\":\"adjective\",\"t\":[\"buildings\",\"olatin\"]},{\"w\":\"nonbasic\",\"d\":\"Not fundamental or elementary; also, in chemistry, not having the properties of a base, such as a high pH or the ability to neutralize acids.\",\"s\":\"The advanced chemistry course covered nonbasic compounds that behaved differently from standard alkaline substances.\",\"p\":\"non-BAY-sik\",\"o\":\"Latin\",\"y\":7,\"bp\":27,\"sy\":\"non.ba.sic\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonbasilectal\",\"d\":\"Not relating to the basilect, which is the most informal or low-prestige variety of a language in a speech community; describing a dialect or speech form closer to the standard or high-prestige end of the spectrum.\",\"s\":\"Linguists noted that the speaker's dialect was nonbasilectal, meaning it wasn't the lowest-prestige variety in the region.\",\"p\":\"non-baz-ih-LEK-tul\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.basilec.tal\",\"ps\":\"adjective\",\"t\":[\"spices\",\"wordwords\",\"olatin\"]},{\"w\":\"nonbasketball\",\"d\":\"Not related to or involving the sport of basketball; describing an event, skill, or context that has no connection to the game.\",\"s\":\"The gym teacher created a nonbasketball unit so students could try volleyball and badminton instead.\",\"p\":\"non-BAS-kit-bawl\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.bas.ket.ball\",\"ps\":\"adjective\",\"t\":[\"household\",\"sports\",\"olatin\"]},{\"w\":\"nonbattered\",\"d\":\"Not coated or covered in a flour-and-liquid mixture; describing food or an object that has not been dipped in batter before cooking or processing.\",\"s\":\"The chef preferred nonbattered fish cooked simply with lemon and herbs for a lighter meal.\",\"p\":\"non-BAT-erd\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.bat.tered\",\"ps\":\"adjective\",\"t\":[\"culinary\",\"olatin\"]},{\"w\":\"nonbattle\",\"d\":\"Not involving or relating to actual armed combat or fighting; describing a situation, zone, or activity that is free from military conflict.\",\"s\":\"The general credited a nonbattle strategy of diplomacy for ending the conflict without casualties.\",\"p\":\"non-BAT-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.bat.tle\",\"ps\":\"adjective\",\"t\":[\"war\",\"olatin\"]},{\"w\":\"nonbauxite\",\"d\":\"Not composed of or relating to bauxite, the ore that is the primary source of aluminum; describing minerals or rocks that lack bauxite content.\",\"s\":\"Mining engineers drilled through nonbauxite layers before finally reaching the aluminum-rich ore they sought.\",\"p\":\"non-BAWK-syt\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.baux.ite\",\"ps\":\"adjective\",\"t\":[\"minerals\",\"olatin\"]},{\"w\":\"nonbeach\",\"d\":\"Not characteristic of or located on a beach; describing an area, environment, or activity that does not involve sandy shorelines or coastal waters.\",\"s\":\"The travel agent suggested several nonbeach destinations for tourists who preferred mountain hiking.\",\"p\":\"non-BEECH\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.beach\",\"ps\":\"adjective\",\"t\":[\"ecology\",\"waterways\",\"olatin\"]},{\"w\":\"nonbearing\",\"d\":\"(of a structural member) supporting no vertical weight other than its own\",\"s\":\"They took out a nonbearing wall.\",\"p\":\"non-BAIR-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.bear.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonbeautiful\",\"d\":\"Lacking beauty or aesthetic appeal; not considered attractive or pleasing to the senses by conventional standards.\",\"s\":\"The artist argued that nonbeautiful subjects like rusted pipes and cracked sidewalks deserved to be painted too.\",\"p\":\"non-BYOO-tih-ful\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.beau.ti.ful\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonbeauty\",\"d\":\"The absence or lack of beauty; a quality or characteristic that does not conform to standards of attractiveness or aesthetic appeal.\",\"s\":\"The photographer's exhibit celebrated nonbeauty, showing the charm and depth found in ordinary, imperfect things.\",\"p\":\"non-BYOO-tee\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.beau.ty\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonbedside\",\"d\":\"Not situated next to a patient's bed; describing a medical approach, manner, or setting that does not involve direct at-the-bedside interaction with a patient.\",\"s\":\"The hospital's nonbedside nurses worked in the lab and administrative offices rather than directly with patients.\",\"p\":\"non-BED-syd\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nonbed.side\",\"ps\":\"adjective\",\"t\":[\"body\",\"household\",\"olatin\"]},{\"w\":\"nonbeer\",\"d\":\"A beverage that resembles beer in appearance or flavor but contains little or no alcohol and is not technically classified as beer.\",\"s\":\"The restaurant's menu featured nonbeer beverages like sparkling water, lemonade, and herbal teas.\",\"p\":\"non-BEER\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.beer\",\"ps\":\"noun\",\"t\":[\"dishes\",\"olatin\"]},{\"w\":\"nonbehavioral\",\"d\":\"Not related to or focused on observable actions, conduct, or patterns of behavior; describing an approach or factor that lies outside the study of behavior.\",\"s\":\"The therapist used nonbehavioral techniques, focusing on emotions and thought patterns rather than actions alone.\",\"p\":\"non-bih-HAYV-yer-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.be.hav.ioral\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonbelief\",\"d\":\"The absence of belief or faith, especially in a religious or ideological doctrine; a state of not accepting something as true.\",\"s\":\"Her nonbelief in superstitions made her the calmest person in the group when they walked under a ladder.\",\"p\":\"non-bih-LEEF\",\"o\":\"Latin\",\"y\":7,\"bp\":28,\"sy\":\"non.be.lief\",\"ps\":\"noun\",\"t\":[\"religion\",\"logic\",\"olatin\"]},{\"w\":\"nonbelieving\",\"d\":\"Not holding or expressing belief, particularly in a religious faith or accepted doctrine; characterized by skepticism or lack of conviction.\",\"s\":\"The nonbelieving student asked for scientific evidence before accepting the theory presented in class.\",\"p\":\"non-bih-LEEV-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.be.liev.ing\",\"ps\":\"adjective\",\"t\":[\"religion\",\"character\",\"logic\",\"olatin\"]},{\"w\":\"nonbelligerency\",\"d\":\"The state or policy of not engaging in warfare or aggressive military action, even when surrounding parties are in conflict; a formal or informal stance of neutrality.\",\"s\":\"The small nation declared nonbelligerency during the war, choosing to stay neutral rather than join either side.\",\"p\":\"non-beh-LIJ-er-en-see\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.bel.ligeren.cy\",\"ps\":\"noun\",\"t\":[\"politics\",\"war\",\"olatin\"]},{\"w\":\"nonbeneficial\",\"d\":\"Not producing a positive outcome or advantage; failing to provide help, improvement, or benefit to a person, group, or situation.\",\"s\":\"Eating junk food every day is clearly nonbeneficial to your health and energy levels.\",\"p\":\"non-ben-uh-FISH-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.ben.e.fi.cial\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonbeneficially\",\"d\":\"In a manner that does not produce benefit or advantage; without being helpful or producing a positive effect.\",\"s\":\"The new policy nonbeneficially affected small businesses, causing several to close within the first year.\",\"p\":\"non-ben-uh-FISH-ul-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":31,\"sy\":\"non.ben.e.fi.cial.ly\",\"ps\":\"adverb\",\"t\":[\"olatin\"]},{\"w\":\"nonbeneficiary\",\"d\":\"A person or entity that does not receive benefits, funds, or advantages from a will, insurance policy, trust, or other arrangement.\",\"s\":\"As a nonbeneficiary of the will, the cousin received nothing from the estate after the trial.\",\"p\":\"non-ben-uh-FISH-ee-air-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.ben.e.fi.cia.ry\",\"ps\":\"noun\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"nonbenevolent\",\"d\":\"Not showing kindness, goodwill, or charitable intentions toward others; lacking a generous or well-meaning disposition.\",\"s\":\"The villain in the story was clearly nonbenevolent, caring only about his own power and wealth.\",\"p\":\"non-beh-NEV-uh-lent\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.benev.o.lent\",\"ps\":\"adjective\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nonbenign\",\"d\":\"Not gentle, mild, or harmless; potentially harmful or threatening, especially used to describe conditions or growths that may be dangerous.\",\"s\":\"The doctor reassured the patient that the test results would confirm whether the growth was benign or nonbenign.\",\"p\":\"non-beh-NYN\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.be.nign\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonbenthic\",\"d\":\"Not living on or associated with the bottom of a body of water; describing organisms or processes that occur in open water rather than on the seafloor or lake bed.\",\"s\":\"The marine biologist studied nonbenthic species that lived near the ocean's surface rather than on the seafloor.\",\"p\":\"non-BEN-thik\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.ben.th.ic\",\"ps\":\"adjective\",\"t\":[\"household\",\"olatin\"]},{\"w\":\"nonbenzodiazepine\",\"d\":\"A sedative or sleep-aid drug that produces effects similar to benzodiazepines but has a different chemical structure and does not belong to that drug class.\",\"s\":\"The physician prescribed a nonbenzodiazepine sleep aid that carried fewer risks of dependence than older medications.\",\"p\":\"non-ben-zoh-dy-AZ-uh-peen\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.ben.zo.di.azepine\",\"ps\":\"noun\",\"t\":[\"pharmacy\",\"chemistry\",\"olatin\"]},{\"w\":\"nonbereaved\",\"d\":\"Not experiencing grief or sorrow due to the loss of a loved one; describing a person who has not suffered bereavement.\",\"s\":\"The counselor helped nonbereaved family members understand how to support their grieving relatives during the difficult time.\",\"p\":\"non-bih-REEVD\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.be.reaved\",\"ps\":\"adjective\",\"t\":[\"emotions\",\"olatin\"]},{\"w\":\"nonbetting\",\"d\":\"Not involving or participating in wagering or gambling; describing a person or activity that abstains from placing bets.\",\"s\":\"The nonbetting section of the horse racing event was popular with families who came just to enjoy the atmosphere.\",\"p\":\"non-BET-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.bet.ting\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonbeveled\",\"d\":\"Not having an angled or slanted edge; describing a surface or edge that remains flat and square rather than cut at an angle.\",\"s\":\"The carpenter chose nonbeveled edges for the tabletop, keeping the corners sharp and perfectly square.\",\"p\":\"non-BEV-uld\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.beveled\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonbidder\",\"d\":\"A person or entity that does not submit an offer or bid in an auction, contract process, or competitive sale.\",\"s\":\"As a nonbidder at the auction, Marcus watched the rare painting sell for a surprisingly high price.\",\"p\":\"non-BID-er\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.bid.der\",\"ps\":\"noun\",\"t\":[\"law\",\"economy\",\"olatin\"]},{\"w\":\"nonbidding\",\"d\":\"Not making or involving the submission of a bid or offer; describing participation in a process without placing a competitive offer.\",\"s\":\"The nonbidding observers at the auction took notes on which items attracted the most competitive offers.\",\"p\":\"non-BID-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.bid.ding\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonbijective\",\"d\":\"In mathematics, describing a function that is not bijective, meaning it fails to be both one-to-one and onto, so it does not create a perfect pairing between two sets.\",\"s\":\"The math teacher explained that a nonbijective function either skips some outputs or hits the same output twice.\",\"p\":\"non-by-JEK-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.bi.jec.tive\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonbiker\",\"d\":\"A person who does not ride a bicycle or motorcycle; someone who does not identify with or participate in biking culture.\",\"s\":\"As a nonbiker, she felt slightly out of place at the motorcycle rally but enjoyed the excitement anyway.\",\"p\":\"non-BY-ker\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.bik.er\",\"ps\":\"noun\",\"t\":[\"vehicles\",\"olatin\"]},{\"w\":\"nonbilabial\",\"d\":\"In linguistics, describing a sound or consonant that is not produced by bringing both lips together; any speech sound that does not require both lips to make contact.\",\"s\":\"The linguist noted that the 'k' sound is nonbilabial because it requires no lip contact.\",\"p\":\"non-by-LAY-bee-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.bi.l.abi.al\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonbilateral\",\"d\":\"Not involving two sides, parties, or nations equally; describing an arrangement, decision, or structure that is not shared or agreed upon by two parties.\",\"s\":\"The trade agreement was criticized for being nonbilateral, favoring only one country.\",\"p\":\"non-by-LAT-er-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":39,\"sy\":\"non.bi.lat.er.al\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonbiliary\",\"d\":\"Not relating to or involving bile or the bile ducts; describing a medical condition, process, or substance that has no connection to the biliary system.\",\"s\":\"The doctor confirmed the digestive issue was nonbiliary, meaning the bile ducts were not involved.\",\"p\":\"non-BIL-ee-air-ee\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.bil.iary\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonbilingual\",\"d\":\"Not able to speak or use two languages fluently; describing a person, community, or document that operates in only one language.\",\"s\":\"The nonbilingual student struggled to follow the Spanish-English classroom discussions.\",\"p\":\"non-by-LING-gwul\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.bilin.gual\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonbillable\",\"d\":\"Not able to be charged to a client or customer; describing time, services, or expenses that cannot be included in an invoice or billing statement.\",\"s\":\"The lawyer's lunch break was considered nonbillable time that clients would not be charged for.\",\"p\":\"non-BIL-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"non.bil.l.able\",\"ps\":\"adjective\",\"t\":[\"economy\",\"time\",\"olatin\"]},{\"w\":\"nonbillionaire\",\"d\":\"A person whose total wealth does not reach one billion dollars or more; someone who is not among the ultra-wealthy billionaire class.\",\"s\":\"As a nonbillionaire, she still managed to live comfortably on her teacher's salary.\",\"p\":\"non-bil-yun-AIR\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.bil.lion.aire\",\"ps\":\"noun\",\"t\":[\"economy\",\"character\",\"olatin\"]},{\"w\":\"nonbinomial\",\"d\":\"Not expressed as or relating to a binomial, meaning it does not consist of exactly two terms or names; used in mathematics or taxonomy to describe expressions or classifications that differ from the two-part form.\",\"s\":\"The math expression was nonbinomial because it contained three terms instead of two.\",\"p\":\"non-by-NOH-mee-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.bi.no.mi.al\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonbioabsorbable\",\"d\":\"Not capable of being broken down and absorbed by the body's biological tissues; describing materials such as certain surgical sutures or implants that the body cannot naturally dissolve.\",\"s\":\"Surgeons used nonbioabsorbable sutures that had to be manually removed after healing.\",\"p\":\"non-by-oh-ab-SOR-buh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.bioab.sorbable\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonbioaccumulative\",\"d\":\"Not tending to build up or concentrate in the tissues of living organisms over time; describing substances that do not increase in concentration as they move up the food chain.\",\"s\":\"Scientists preferred the nonbioaccumulative pesticide because it wouldn't build up in animals' tissues.\",\"p\":\"non-by-oh-uh-KYOO-myuh-lay-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.bioac.cu.mu.la.tive\",\"ps\":\"adjective\",\"t\":[\"body\",\"ecology\",\"character\",\"time\",\"olatin\"]},{\"w\":\"nonbioavailable\",\"d\":\"Not able to be absorbed or used by a living organism; describing a substance that exists in the body or environment but cannot be taken up and utilized by biological systems.\",\"s\":\"The mineral in that supplement was nonbioavailable, so the body could not actually absorb it.\",\"p\":\"non-by-oh-uh-VAY-luh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.bioavail.able\",\"ps\":\"adjective\",\"t\":[\"ecology\",\"olatin\"]},{\"w\":\"nonbiochemical\",\"d\":\"Not involving or relating to the chemical processes that occur within living organisms; describing a reaction, compound, or process that has no biological chemical basis.\",\"s\":\"The reaction was classified as nonbiochemical because it occurred entirely outside living cells.\",\"p\":\"non-by-oh-KEM-ih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.bio.chem.i.cal\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonbiochemist\",\"d\":\"A scientist or researcher who does not specialize in biochemistry; a person whose field of study does not focus on the chemical processes of living organisms.\",\"s\":\"As a nonbiochemist, the engineer needed a colleague's help to interpret the lab results.\",\"p\":\"non-by-oh-KEM-ist\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.bio.chemist\",\"ps\":\"noun\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonbiocidal\",\"d\":\"Not having the property of killing or destroying living organisms; describing a substance or treatment that does not act as a pesticide, disinfectant, or other life-destroying agent.\",\"s\":\"The cleaning solution was advertised as nonbiocidal, meaning it would not kill any living organisms.\",\"p\":\"non-by-oh-SY-dul\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.bio.ci.dal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonbiogenic\",\"d\":\"Not produced by or originating from living organisms or biological processes; describing a substance or material formed through chemical or physical means rather than by life forms.\",\"s\":\"The geologist confirmed the rock formation was nonbiogenic, created by pressure rather than living organisms.\",\"p\":\"non-beye-oh-JEN-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.bio.genic\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonbiographical\",\"d\":\"Not relating to or based on the story of a real person's life; describing content that is fictional or otherwise not rooted in true biographical accounts.\",\"s\":\"The film was entirely nonbiographical, featuring a fictional character loosely inspired by real events.\",\"p\":\"non-beye-oh-GRAF-ih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":31,\"sy\":\"non.bi.o.graph.i.cal\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"nonbiohazardous\",\"d\":\"Not posing any danger or risk to living organisms from biological sources; describing materials that are free from harmful biological agents or pathogens.\",\"s\":\"The waste was labeled nonbiohazardous and could be disposed of in regular trash bins.\",\"p\":\"non-beye-oh-HAZ-er-dus\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.bio.haz.ardous\",\"ps\":\"adjective\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"nonbiologist\",\"d\":\"A person who is not trained or professionally specialized in the study of biology; someone whose expertise lies outside the field of life sciences.\",\"s\":\"Even as a nonbiologist, she found the documentary about cells absolutely fascinating.\",\"p\":\"non-beye-OL-oh-jist\",\"o\":\"Latin\",\"y\":8,\"bp\":39,\"sy\":\"non.bi.ol.o.gist\",\"ps\":\"noun\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nonbiology\",\"d\":\"Any academic discipline, field of study, or subject matter that falls outside the science of biology and the study of living organisms.\",\"s\":\"Her passion lay in nonbiology subjects like math and history rather than science.\",\"p\":\"non-beye-OL-oh-jee\",\"o\":\"Latin\",\"y\":8,\"bp\":32,\"sy\":\"non.bi.ol.o.gy\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonbioluminescent\",\"d\":\"Not capable of producing or emitting light through biological or biochemical reactions; describing organisms or substances that do not glow by living processes.\",\"s\":\"Unlike fireflies, most garden insects are nonbioluminescent and produce no natural light.\",\"p\":\"non-beye-oh-loo-mih-NES-ent\",\"o\":\"Latin\",\"y\":9,\"bp\":33,\"sy\":\"non.bi.o.lu.mi.nes.cent\",\"ps\":\"adjective\",\"t\":[\"colors\",\"olatin\"]},{\"w\":\"nonbiomass\",\"d\":\"Material or matter that does not consist of or derive from living or once-living organic material; any substance not classified as biological mass.\",\"s\":\"Coal is considered a nonbiomass energy source because it is not recently living organic material.\",\"p\":\"non-BEYE-oh-mas\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.biomass\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonbiomechanical\",\"d\":\"Not relating to or governed by the mechanical principles that describe movement and forces in living organisms; describing systems that operate outside biological movement frameworks.\",\"s\":\"The robot's movement was purely nonbiomechanical, designed with gears rather than mimicking muscle action.\",\"p\":\"non-beye-oh-meh-KAN-ih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.biome.chan.i.cal\",\"ps\":\"adjective\",\"t\":[\"physics\",\"logic\",\"olatin\"]},{\"w\":\"nonbiomedical\",\"d\":\"Not pertaining to the application of biological and life sciences to medicine or healthcare; describing fields, research, or technologies that do not involve living-body medical science.\",\"s\":\"His research was nonbiomedical, focusing on the history of hospitals rather than medical treatments.\",\"p\":\"non-beye-oh-MED-ih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.biomed.i.cal\",\"ps\":\"adjective\",\"t\":[\"body\",\"pharmacy\",\"olatin\"]},{\"w\":\"nonbiometric\",\"d\":\"Not involving the measurement or statistical analysis of biological characteristics such as fingerprints, retinal patterns, or facial features for identification purposes.\",\"s\":\"The old security system was nonbiometric, relying on a simple PIN rather than fingerprints.\",\"p\":\"non-beye-oh-MET-rik\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.bio.met.ric\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonbiomimetic\",\"d\":\"Not designed to imitate or replicate the structures, functions, or processes found in living organisms; describing materials or technologies that draw no inspiration from nature.\",\"s\":\"The engineer's design was nonbiomimetic, invented without copying any patterns from nature.\",\"p\":\"non-beye-oh-mih-MET-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.biomimet.ic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonbiosynthetic\",\"d\":\"Not produced through the biochemical processes of a living organism; describing compounds or molecules that are manufactured by chemical rather than biological synthesis.\",\"s\":\"The compound was nonbiosynthetic, manufactured entirely in a lab rather than produced by living cells.\",\"p\":\"non-beye-oh-sin-THET-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.biosyn.thet.ic\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonbioturbated\",\"d\":\"Not disturbed, mixed, or reworked by the burrowing or movement of living organisms; describing sediment or geological layers that remain undisturbed by biological activity.\",\"s\":\"The sediment layer was nonbioturbated, perfectly undisturbed by any burrowing organisms over centuries.\",\"p\":\"non-beye-oh-TER-bay-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.bio.tur.bat.ed\",\"ps\":\"adjective\",\"t\":[\"minerals\",\"olatin\"]},{\"w\":\"nonbipedal\",\"d\":\"Not walking or moving upright on two feet; describing an animal or movement style that uses four or more limbs rather than just two for locomotion.\",\"s\":\"Snakes are nonbipedal creatures that move entirely without the use of legs.\",\"p\":\"non-beye-PEE-dul\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.bipedal\",\"ps\":\"adjective\",\"t\":[\"body\",\"animals\",\"olatin\"]},{\"w\":\"nonbipolar\",\"d\":\"Not characterized by two opposite extremes or poles; in psychology, describing a condition, personality, or mood pattern that does not involve the dramatic shifts seen in bipolar disorder.\",\"s\":\"The therapist noted the patient's mood disorder was nonbipolar, fitting a different diagnosis entirely.\",\"p\":\"non-beye-POH-ler\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.bipo.lar\",\"ps\":\"adjective\",\"t\":[\"disease\",\"stage\",\"character\",\"emotions\",\"olatin\"]},{\"w\":\"nonbirational\",\"d\":\"In mathematics, describing a relationship between algebraic varieties or geometric objects that cannot be connected by a rational map going in both directions.\",\"s\":\"The mathematician explained that the two curves had a nonbirational relationship in algebraic geometry.\",\"p\":\"non-beye-RASH-uh-nul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.bi.ra.tional\",\"ps\":\"adjective\",\"t\":[\"maps\",\"logic\",\"numbers\",\"olatin\"]},{\"w\":\"nonbirder\",\"d\":\"A person who does not engage in birdwatching as a hobby or interest; someone who has no particular focus on observing or identifying birds in the wild.\",\"s\":\"As a nonbirder, she visited the nature trail for the wildflowers rather than to spot birds.\",\"p\":\"non-BER-der\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.bird.er\",\"ps\":\"noun\",\"t\":[\"birds\",\"olatin\"]},{\"w\":\"nonbirding\",\"d\":\"Not relating to or involving the hobby of birdwatching; describing outdoor activities or excursions undertaken without the goal of observing or identifying birds.\",\"s\":\"The nonbirding hikers on the trail were surprised to learn how many rare species lived nearby.\",\"p\":\"non-BER-ding\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.bird.ing\",\"ps\":\"adjective\",\"t\":[\"birds\",\"sports\",\"olatin\"]},{\"w\":\"nonbirefringent\",\"d\":\"Not exhibiting birefringence, meaning light passing through the material is not split into two separate beams with different speeds; describing optically uniform substances.\",\"s\":\"The glass lens was nonbirefringent, bending light uniformly in all directions without splitting it.\",\"p\":\"non-beye-rih-FRIN-jent\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.bire.frin.gent\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonbirth\",\"d\":\"The absence or non-occurrence of a birth event; a state or condition in which a birth does not take place, sometimes used in demographic or philosophical contexts.\",\"s\":\"The philosopher discussed the concept of nonbirth as the state of not yet existing.\",\"p\":\"non-BERTH\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.birth\",\"ps\":\"noun\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonbiting\",\"d\":\"Not using or capable of using the mouth or mandibles to bite; describing insects, animals, or other creatures that do not bite humans or other organisms.\",\"s\":\"The zookeeper assured visitors that the large but nonbiting snake posed absolutely no danger.\",\"p\":\"nah-NBEYE-tih-ng\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"naa.nbay.tih.ng\",\"ps\":\"adjective\",\"t\":[\"animals\",\"insects\",\"olatin\"]},{\"w\":\"nonbituminous\",\"d\":\"Not containing or relating to bitumen, the thick, tar-like hydrocarbon substance found in some coals and asphalts; describing coal or rock free of that sticky material.\",\"s\":\"The nonbituminous coal burns differently and is used for specific industrial purposes.\",\"p\":\"non-bih-TOO-mih-nus\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.bi.tu.mi.nous\",\"ps\":\"adjective\",\"t\":[\"minerals\",\"olatin\"]},{\"w\":\"nonblack\",\"d\":\"Not of the color black; also used to describe a person who does not identify as Black in terms of racial or ethnic identity, often used in demographic contexts.\",\"s\":\"The artist used only nonblack inks, creating a vivid painting with blues, reds, and greens.\",\"p\":\"non-BLAK\",\"o\":\"Latin\",\"y\":6,\"bp\":25,\"sy\":\"non.black\",\"ps\":\"adjective\",\"t\":[\"colors\",\"olatin\"]},{\"w\":\"nonblacklisted\",\"d\":\"Not placed on a blacklist or list of banned, prohibited, or disfavored persons, organizations, or items; describing someone or something that has not been officially restricted.\",\"s\":\"The nonblacklisted contractor was free to bid on any government project without restriction.\",\"p\":\"non-BLAK-list-ed\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.black.list.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonbladder\",\"d\":\"Not relating to or functioning as the urinary bladder; describing tissue, cells, or anatomical structures that are distinct from and unrelated to the bladder organ.\",\"s\":\"The surgeon noted the tumor was in nonbladder tissue and had not affected the urinary organ.\",\"p\":\"non-BLAD-er\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.blad.der\",\"ps\":\"adjective\",\"t\":[\"body\",\"music\",\"olatin\"]},{\"w\":\"nonblameworthy\",\"d\":\"Not deserving of blame or moral criticism for an action or outcome; describing a person or behavior that cannot justifiably be held responsible for a negative result.\",\"s\":\"The judge declared the child's actions nonblameworthy given her young age and lack of understanding.\",\"p\":\"non-BLAYM-wer-thee\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.blame.wor.thy\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonblasphemous\",\"d\":\"Not containing, expressing, or constituting blasphemy; describing speech, writing, or actions that show no irreverence or disrespect toward sacred or religious things.\",\"s\":\"The comedian kept his jokes nonblasphemous so the whole family could enjoy the show.\",\"p\":\"non-BLAS-feh-mus\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.blas.phe.mous\",\"ps\":\"adjective\",\"t\":[\"religion\",\"olatin\"]},{\"w\":\"nonbleach\",\"d\":\"Not containing bleach or bleaching agents; describing a cleaning product, process, or fabric treatment that uses no chlorine or other whitening chemicals.\",\"s\":\"The label said to use only nonbleach detergent to protect the fabric's bright colors.\",\"p\":\"non-BLEECH\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.bleach\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"fabrics\",\"olatin\"]},{\"w\":\"nonbleached\",\"d\":\"Not treated with bleach or whitening agents; describing materials such as flour, paper, or fabric that retain their natural color without chemical whitening.\",\"s\":\"The baker preferred nonbleached flour because it retained more natural nutrients.\",\"p\":\"non-BLEECHT\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"sy\":\"non.bleached\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"fabrics\",\"colors\",\"olatin\"]},{\"w\":\"nonbleaching\",\"d\":\"Not causing or involving the removal of color through bleaching agents; describing a cleaning or treatment method that preserves the original color of a material.\",\"s\":\"The nonbleaching cleaner safely removed the stain without fading the carpet's pattern.\",\"p\":\"non-BLEE-ching\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.bleach.ing\",\"ps\":\"adjective\",\"t\":[\"colors\",\"olatin\"]},{\"w\":\"nonblended\",\"d\":\"Not mixed or combined from multiple sources or ingredients; describing a product, substance, or material that remains in its pure, unmixed original form.\",\"s\":\"The chef served nonblended spices separately so diners could appreciate each individual flavor.\",\"p\":\"non-BLEN-ded\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.blend.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonblinking\",\"d\":\"Not blinking or causing a blinking motion; describing lights that shine steadily without flashing, or eyes that remain fixed open without closing.\",\"s\":\"The owl's nonblinking stare made the hikers feel like they were being watched very carefully.\",\"p\":\"non-BLINK-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.blink.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonblockbuster\",\"d\":\"Not achieving the massive commercial success or widespread popularity associated with a blockbuster film, book, or product; describing modestly performing creative works.\",\"s\":\"The director was proud of his nonblockbuster film, which won awards despite small audiences.\",\"p\":\"non-BLOK-bus-ter\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.block.buster\",\"ps\":\"adjective\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nonblocked\",\"d\":\"Not obstructed, hindered, or prevented from proceeding; describing a pathway, signal, process, or system that remains open and free from any blockage.\",\"s\":\"The nonblocked drain allowed water to flow freely through the pipes after cleaning.\",\"p\":\"non-BLOKT\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.blocked\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonblocking\",\"d\":\"Not causing or resulting in an obstruction or delay; in computing, describing operations or systems that allow other processes to continue without waiting for a task to complete.\",\"s\":\"The nonblocking code allowed the program to run other tasks while waiting for a response.\",\"p\":\"non-BLOK-ing\",\"o\":\"Latin\",\"y\":7,\"bp\":35,\"sy\":\"non.block.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonblog\",\"d\":\"Online content, a website, or a form of digital media that does not follow the format or style of a blog, lacking regular dated entries written by an individual author.\",\"s\":\"Her weekly newsletter was a nonblog format, delivered straight to subscribers' inboxes.\",\"p\":\"non-BLOG\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.blog\",\"ps\":\"noun\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"nonblogging\",\"d\":\"Not engaging in the practice of writing or maintaining a blog; describing a person, platform, or activity that does not involve regular online journal-style entries.\",\"s\":\"The author's nonblogging approach meant all her writing appeared only in print magazines.\",\"p\":\"non-BLOG-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.blog.ging\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonblonde\",\"d\":\"Not having blonde or light golden-yellow hair color; describing a person whose hair is of a darker or otherwise distinct shade, such as brown, black, or red.\",\"s\":\"The casting director noticed that all the previous leads were blonde, so she chose a nonblonde actress this time.\",\"p\":\"non-BLOND\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.blonde\",\"ps\":\"adjective\",\"t\":[\"colors\",\"olatin\"]},{\"w\":\"nonblue\",\"d\":\"Not of the color blue; describing any hue, object, or surface whose color falls outside the range of blue on the visible color spectrum.\",\"s\":\"The artist challenged herself to create a painting using only nonblue colors for the ocean scene.\",\"p\":\"non-BLOO\",\"o\":\"Latin\",\"y\":9,\"bp\":19,\"sy\":\"non.blue\",\"ps\":\"adjective\",\"t\":[\"colors\",\"olatin\"]},{\"w\":\"nonblurred\",\"d\":\"Not blurred; remaining clear, sharp, and in focus without any smearing or loss of detail.\",\"s\":\"The nonblurred photograph captured every tiny detail of the butterfly's wings perfectly.\",\"p\":\"non-BLURD\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.blurred\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonblurring\",\"d\":\"Not causing or producing blurring; keeping images or outlines sharp and clearly defined.\",\"s\":\"The camera's nonblurring lens technology made sports photography much easier.\",\"p\":\"non-BLUR-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.blur.ring\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonblurry\",\"d\":\"Not blurry; having clear, distinct edges and details that are easy to see and distinguish.\",\"s\":\"She was thrilled that for once every photo from the birthday party was nonblurry and clear.\",\"p\":\"non-BLUR-ee\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.blur.ry\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonboard\",\"d\":\"Not related to or serving on a board of directors or governing body; outside the scope of a board's authority.\",\"s\":\"The nonboard members attended the meeting as observers but could not vote on decisions.\",\"p\":\"non-BORD\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.board\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"nonboarding\",\"d\":\"Not involving or related to boarding; describing students or residents who do not live at their school or institution.\",\"s\":\"Nonboarding students went home each afternoon while others stayed in the school dormitory.\",\"p\":\"non-BOR-ding\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.board.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonboating\",\"d\":\"Not involving or related to boating; describing activities, areas, or people that have nothing to do with operating a boat.\",\"s\":\"The lake offered nonboating recreational activities like swimming and fishing from the shore.\",\"p\":\"non-BOH-ting\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.boat.ing\",\"ps\":\"adjective\",\"t\":[\"seafaring\",\"olatin\"]},{\"w\":\"nonbody\",\"d\":\"Not having or constituting a physical body; referring to an entity or concept that lacks material or corporeal form.\",\"s\":\"In philosophy class, we discussed whether the mind is a nonbody element separate from the physical self.\",\"p\":\"non-BOD-ee\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.body\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonboilable\",\"d\":\"Not capable of being boiled; describing a material or substance that cannot safely withstand or be processed through boiling.\",\"s\":\"The nonboilable plastic container melted when the student accidentally put it in boiling water.\",\"p\":\"non-BOY-luh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.boil.able\",\"ps\":\"adjective\",\"t\":[\"culinary\",\"olatin\"]},{\"w\":\"nonboiled\",\"d\":\"Not having been subjected to boiling; remaining in a raw or unheated state rather than being cooked or sterilized by boiling.\",\"s\":\"The recipe called for nonboiled eggs to be mixed directly into the cold salad dressing.\",\"p\":\"non-BOYLD\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.boiled\",\"ps\":\"adjective\",\"t\":[\"culinary\",\"olatin\"]},{\"w\":\"nonboiling\",\"d\":\"Not boiling; describing a liquid or process that does not reach or involve the boiling point.\",\"s\":\"The scientist studied how substances behave in nonboiling water at various temperatures.\",\"p\":\"non-BOY-ling\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.boil.ing\",\"ps\":\"adjective\",\"t\":[\"culinary\",\"olatin\"]},{\"w\":\"nonbold\",\"d\":\"Not bold; describing text or a person that lacks heavy emphasis, strong weight, or daring confidence.\",\"s\":\"The editor asked the writer to use nonbold text for the body paragraphs to improve readability.\",\"p\":\"non-BOLD\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.bold\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonbolded\",\"d\":\"Not formatted in bold type; describing text that has not been made heavier or darker for emphasis.\",\"s\":\"The nonbolded headings blended too much with the body text, making the document hard to skim.\",\"p\":\"non-BOLD-ed\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.bold.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonbombastic\",\"d\":\"Not bombastic; characterized by straightforward, modest language that avoids inflated or overly dramatic expression.\",\"s\":\"The mayor's nonbombastic speech was refreshingly simple and direct, impressing the whole crowd.\",\"p\":\"non-bom-BAS-tik\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.bom.bas.tic\",\"ps\":\"adjective\",\"t\":[\"stage\",\"character\",\"wordwords\",\"olatin\"]},{\"w\":\"nonbondable\",\"d\":\"Not capable of forming a chemical or adhesive bond; describing substances or surfaces that cannot be joined together through bonding.\",\"s\":\"The chemist discovered that the new element was nonbondable with most common compounds.\",\"p\":\"non-BON-duh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.bond.able\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonbony\",\"d\":\"Not composed of or resembling bone; lacking the hard, calcified structure typical of skeletal material.\",\"s\":\"The jellyfish is a nonbony creature that moves gracefully through the water without a skeleton.\",\"p\":\"non-BOH-nee\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.bony\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonbook\",\"d\":\"Not a traditional book; referring to media or materials such as videos, audio recordings, or digital files that convey information without being a printed book.\",\"s\":\"The library created a new section for nonbook materials like DVDs, audiobooks, and maps.\",\"p\":\"non-BOOK\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.book\",\"ps\":\"noun\",\"t\":[\"festivals\",\"olatin\"]},{\"w\":\"nonbookkeeping\",\"d\":\"Not involving or related to bookkeeping; describing tasks or roles that do not include maintaining financial records or accounts.\",\"s\":\"The job posting described nonbookkeeping duties like scheduling, filing, and customer service.\",\"p\":\"non-BOOK-kee-ping\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.book.keep.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonboosted\",\"d\":\"Not having received a boost or increase; describing a signal, vaccine dose, or performance that has not been enhanced or amplified.\",\"s\":\"The nonboosted signal struggled to reach the back of the building where students sat.\",\"p\":\"non-BOOST-ed\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.boost.ed\",\"ps\":\"adjective\",\"t\":[\"pharmacy\",\"olatin\"]},{\"w\":\"nonbooting\",\"d\":\"Not capable of or not currently going through the startup process; describing a computer or device that fails to or does not initiate its operating system.\",\"s\":\"The technician identified the problem as a nonbooting hard drive that refused to start the computer.\",\"p\":\"non-BOOT-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.boot.ing\",\"ps\":\"adjective\",\"t\":[\"tools\",\"olatin\"]},{\"w\":\"nonborderline\",\"d\":\"Not borderline or marginal; clearly falling on one side of a boundary or classification rather than being at the edge between two categories.\",\"s\":\"The doctor confirmed that the patient's test results were nonborderline, clearly showing no disease.\",\"p\":\"non-BOR-dur-lyne\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.bor.der.line\",\"ps\":\"adjective\",\"t\":[\"maps\",\"olatin\"]},{\"w\":\"nonboreal\",\"d\":\"Not of or relating to the boreal zone; describing climates, organisms, or regions that are not characteristic of the cold northern forests.\",\"s\":\"The tropical rainforest is a nonboreal ecosystem, completely different from the cold northern forests.\",\"p\":\"non-BOR-ee-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.bo.re.al\",\"ps\":\"adjective\",\"t\":[\"weather\",\"olatin\"]},{\"w\":\"nonboring\",\"d\":\"Not boring or dull; describing something that is interesting, engaging, and holds one's attention well.\",\"s\":\"The teacher made every history lesson nonboring by using costumes, games, and dramatic storytelling.\",\"p\":\"non-BOR-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.bor.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonboron\",\"d\":\"Not containing or composed of boron; describing a chemical compound or material that lacks the element boron.\",\"s\":\"Scientists created a nonboron compound to replace boron in the new lightweight material.\",\"p\":\"non-BOR-on\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.boron\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonboronic\",\"d\":\"Not containing or derived from boronic acid; describing a chemical compound that lacks the characteristic boron-based functional group.\",\"s\":\"The chemist tested the nonboronic acid solution to see if it reacted differently with the compound.\",\"p\":\"non-buh-RON-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.boron.ic\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonborrowed\",\"d\":\"Not borrowed; describing money, words, or items that were obtained through one's own means rather than taken temporarily from another source.\",\"s\":\"The student was proud that all the money she used for college was nonborrowed savings from her own work.\",\"p\":\"non-BOR-od\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.bor.rowed\",\"ps\":\"adjective\",\"t\":[\"music\",\"economy\",\"wordwords\",\"olatin\"]},{\"w\":\"nonborrower\",\"d\":\"A person or entity that does not borrow money or goods; someone who finances needs through savings or income rather than loans.\",\"s\":\"As a nonborrower, she paid cash for everything and never owed money to any bank.\",\"p\":\"non-BOR-oh-ur\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"non.bor.row.er\",\"ps\":\"noun\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nonborrowing\",\"d\":\"Not involving the act of borrowing; describing financial behavior or policies that rely on existing resources rather than taking on debt.\",\"s\":\"The family's nonborrowing policy meant they saved up for everything before buying it.\",\"p\":\"non-BOR-oh-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.bor.row.ing\",\"ps\":\"adjective\",\"t\":[\"politics\",\"economy\",\"olatin\"]},{\"w\":\"nonbosonic\",\"d\":\"Not relating to or characteristic of bosons; describing particles or systems that do not follow the statistical behavior and properties of boson particles in quantum physics.\",\"s\":\"The physics professor explained that nonbosonic particles, unlike bosons, obey the Pauli exclusion principle and cannot occupy the same quantum state simultaneously.\",\"p\":\"non-boh-ZON-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonbotanical\",\"d\":\"Not related to or involving botany or plants; describing a subject, study, or object that has nothing to do with the scientific study of plant life.\",\"s\":\"The museum's nonbotanical exhibits focused on geology and fossils, while the plant collections were housed in an entirely separate wing of the building.\",\"p\":\"non-buh-TAN-ih-kul\",\"o\":\"Latin\",\"y\":8,\"bp\":33,\"ps\":\"adjective\",\"t\":[\"botany\",\"olatin\"]},{\"w\":\"nonbotanist\",\"d\":\"A person who is not a botanist; someone who does not study or specialize in the scientific examination of plants.\",\"s\":\"As a nonbotanist, Marco could appreciate the beauty of the wildflowers on the trail, but he had absolutely no idea what species they were or how they grew.\",\"p\":\"non-BOT-uh-nist\",\"o\":\"Latin\",\"y\":8,\"bp\":32,\"ps\":\"noun\",\"t\":[\"botany\",\"character\",\"olatin\"]},{\"w\":\"nonbottled\",\"d\":\"Not contained or sold in a bottle; describing beverages or liquids that are served or distributed through other means such as taps, cartons, or fountains.\",\"s\":\"The eco-conscious restaurant proudly served nonbottled water from a filtration system, reducing plastic waste and encouraging customers to use reusable containers.\",\"p\":\"non-BOT-uld\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"ps\":\"adjective\",\"t\":[\"dishes\",\"olatin\"]},{\"w\":\"nonbotulinum\",\"d\":\"Not produced by or related to the Clostridium botulinum bacterium; describing toxins, bacteria, or food conditions that do not involve the organism responsible for botulism.\",\"s\":\"Scientists confirmed that the bacterial strain found in the sample was nonbotulinum, meaning the contamination could not cause the dangerous paralytic illness known as botulism.\",\"p\":\"non-boch-uh-LY-num\",\"o\":\"Latin\",\"y\":8,\"bp\":33,\"ps\":\"adjective\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"nonbound\",\"d\":\"Not bound, tied, or restricted; describing something that is free from physical, legal, or conventional constraints.\",\"s\":\"The nonbound pages scattered across the desk reminded the editor that the manuscript still needed to be assembled and secured before it could be sent to the printer.\",\"p\":\"non-BOWND\",\"o\":\"Latin\",\"y\":9,\"bp\":24,\"ps\":\"adjective\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"nonbounded\",\"d\":\"Not having defined limits or boundaries; extending without restriction or a clear endpoint in space, quantity, or scope.\",\"s\":\"In mathematics class, the teacher explained that a nonbounded set continues infinitely in one direction and therefore has no finite upper or lower limit.\",\"p\":\"non-BOWN-ded\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonbourgeois\",\"d\":\"Not belonging to or characteristic of the middle class; describing attitudes, lifestyles, or people that fall outside conventional middle-class values and expectations.\",\"s\":\"The artist proudly lived a nonbourgeois lifestyle, rejecting suburban comfort and steady employment in favor of creative freedom and communal living.\",\"p\":\"non-boor-ZHWAH\",\"o\":\"Latin\",\"y\":9,\"bp\":33,\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonbovine\",\"d\":\"Not related to or derived from cattle; describing animals, products, or biological materials that do not come from cows or other bovine species.\",\"s\":\"The researchers searched specifically for nonbovine sources of collagen, hoping to find alternatives for patients who had religious or dietary restrictions against using cattle-derived products.\",\"p\":\"non-BOH-vyne\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"ps\":\"adjective\",\"t\":[\"animals\",\"olatin\"]},{\"w\":\"nonboxing\",\"d\":\"Not involving or related to the sport of boxing; describing athletic events, training programs, or activities that do not include competitive punching or fighting with gloves.\",\"s\":\"The gym offered a variety of nonboxing fitness classes including yoga, cycling, and swimming for members who preferred exercise without any combat sports elements.\",\"p\":\"non-BOK-sing\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"ps\":\"adjective\",\"t\":[\"fabrics\",\"sports\",\"olatin\"]},{\"w\":\"nonboycotted\",\"d\":\"Not subjected to a boycott; describing a product, business, or organization that has not been collectively refused patronage as a form of protest.\",\"s\":\"While several competing brands faced consumer protests, that company remained nonboycotted and even saw its sales increase as shoppers shifted their loyalty during the controversy.\",\"p\":\"non-BOY-kot-ed\",\"o\":\"Latin\",\"y\":9,\"bp\":33,\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonbracketed\",\"d\":\"Not enclosed within brackets; describing text, data, or items that appear without the grouping or clarifying symbols known as brackets.\",\"s\":\"The editor noted that all nonbracketed text in the document represented the author's original words, while anything inside brackets had been added for clarification by the editorial team.\",\"p\":\"non-BRAK-et-ed\",\"o\":\"Latin\",\"y\":8,\"bp\":33,\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonbraille\",\"d\":\"Not written or printed in braille; describing text or materials presented in standard print or other formats that are not the raised-dot system used by people with visual impairments.\",\"s\":\"The school worked hard to convert all nonbraille textbooks into accessible formats so that every visually impaired student could fully participate in classroom learning.\",\"p\":\"non-BRAYL\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonbranching\",\"d\":\"Going in one straight line without splitting into separate forks.\",\"p\":\"nan\",\"o\":\"Latin\",\"y\":9,\"bp\":33,\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonbrand\",\"d\":\"Describing a product not sold under a recognized commercial name.\",\"p\":\"nan\",\"o\":\"Latin\",\"y\":8,\"bp\":24,\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nonbranded\",\"d\":\"Describing a product or service that carries no specific commercial name or logo.\",\"p\":\"nan\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nonbrass\",\"d\":\"Describing a material or object not made of the yellow copper-and-zinc metal.\",\"p\":\"nan\",\"o\":\"Latin\",\"y\":8,\"bp\":24,\"t\":[\"music\",\"wordwords\",\"chemistry\",\"olatin\"]},{\"w\":\"nonbread\",\"d\":\"Describing a food that is not a baked flour loaf or roll.\",\"p\":\"nan\",\"o\":\"Latin\",\"y\":8,\"bp\":24,\"t\":[\"dishes\",\"culinary\",\"olatin\"]},{\"w\":\"nonbreaded\",\"d\":\"Describing food not coated with crumbs before cooking.\",\"p\":\"nan\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"t\":[\"culinary\",\"dishes\",\"olatin\"]},{\"w\":\"nonbreast\",\"d\":\"Describing something not relating to or coming from the chest gland of a person or animal.\",\"p\":\"nan\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"t\":[\"animals\",\"wordwords\",\"body\",\"olatin\"]},{\"w\":\"nonbreastfed\",\"d\":\"Describing a baby raised on formula or bottles rather than a mother's own milk.\",\"p\":\"nan\",\"o\":\"Latin\",\"y\":8,\"bp\":33,\"t\":[\"kinship\",\"olatin\"]},{\"w\":\"nonbreastfeeding\",\"d\":\"Describing a situation not involving nursing an infant with a mother's own milk.\",\"p\":\"nan\",\"o\":\"Latin\",\"y\":9,\"bp\":24,\"t\":[\"kinship\",\"olatin\"]},{\"w\":\"nonbreathing\",\"d\":\"Describing something that does not take in air or exchange gases.\",\"p\":\"nan\",\"o\":\"Latin\",\"y\":8,\"bp\":33,\"t\":[\"olatin\"]},{\"w\":\"nonbrecciated\",\"d\":\"In geology, describing rock not broken into angular fragments and cemented back together.\",\"p\":\"nan\",\"o\":\"Latin\",\"y\":9,\"bp\":22,\"t\":[\"minerals\",\"olatin\"]},{\"w\":\"nonbred\",\"d\":\"Describing an animal not produced through deliberate, selective mating.\",\"p\":\"nan\",\"o\":\"Latin\",\"y\":8,\"bp\":17,\"t\":[\"animals\",\"wordwords\",\"olatin\"]},{\"w\":\"nonbreeder\",\"d\":\"An animal that does not reproduce during a given season or period.\",\"p\":\"nan\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"t\":[\"animals\",\"time\",\"olatin\"]},{\"w\":\"nonbreeding\",\"d\":\"Describing a time or individual not involved in reproducing or raising young.\",\"p\":\"nan\",\"o\":\"Latin\",\"y\":7,\"bp\":32,\"t\":[\"time\",\"olatin\"]},{\"w\":\"nonbrewing\",\"d\":\"Describing a place or process not involving fermenting or making beer.\",\"p\":\"nan\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"t\":[\"chemistry\",\"dishes\",\"olatin\"]},{\"w\":\"nonbridal\",\"d\":\"Describing something not related to a wedding or a woman about to marry.\",\"p\":\"nan\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"t\":[\"religion\",\"kinship\",\"wordwords\",\"olatin\"]},{\"w\":\"nonbridged\",\"d\":\"In chemistry, describing a structure lacking a linking element connecting two parts.\",\"p\":\"nan\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"t\":[\"chemistry\",\"tools\",\"wordwords\",\"olatin\"]},{\"w\":\"nonbridging\",\"d\":\"Describing an atom or bond that does not connect two larger units in a structure.\",\"p\":\"nan\",\"o\":\"Latin\",\"y\":8,\"bp\":32,\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonbriefed\",\"d\":\"Describing a person not yet informed or given instructions about a topic or mission.\",\"p\":\"nan\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonbroadband\",\"d\":\"Describing a slow internet connection lacking today's high-speed data service.\",\"p\":\"nan\",\"o\":\"Latin\",\"y\":8,\"bp\":33,\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonbroadcast\",\"d\":\"Describing media not sent out to the public over TV or radio channels.\",\"p\":\"nan\",\"o\":\"Latin\",\"y\":8,\"bp\":33,\"t\":[\"olatin\"]},{\"w\":\"nonbroadcasting\",\"d\":\"Describing an organization that does not transmit programs to the general public.\",\"p\":\"nan\",\"o\":\"Latin\",\"y\":9,\"bp\":24,\"t\":[\"olatin\"]},{\"w\":\"nonbroiler\",\"d\":\"A chicken or other poultry that is not raised or intended for broiling as a method of cooking.\",\"p\":\"nan\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"t\":[\"culinary\",\"olatin\"]},{\"w\":\"nonbroken\",\"d\":\"Describing something that has not been broken, cracked, or damaged in any way.\",\"p\":\"nan\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"t\":[\"olatin\"]},{\"w\":\"nonbrominated\",\"d\":\"Describing a chemical compound or substance that has not been treated with or combined with bromine.\",\"p\":\"nan\",\"o\":\"Latin\",\"y\":9,\"bp\":22,\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonbronchitic\",\"d\":\"Describing a condition, substance, or person that is not associated with or affected by bronchitis.\",\"p\":\"nan\",\"o\":\"Latin\",\"y\":9,\"bp\":22,\"t\":[\"olatin\"]},{\"w\":\"nonbronze\",\"d\":\"Describing a material, color, or object that is not made of or resembling bronze.\",\"p\":\"nan\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"t\":[\"colors\",\"olatin\"]},{\"w\":\"nonbrown\",\"d\":\"Describing something that is not brown in color or does not have brown as its primary hue.\",\"s\":\"She chose a nonbrown color for her bedroom walls, painting them a bright sky blue.\",\"p\":\"nan\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.brown\",\"t\":[\"colors\",\"olatin\"]},{\"w\":\"nonbrutal\",\"d\":\"Describing behavior or treatment that is not brutal, harsh, or excessively cruel.\",\"s\":\"The coach believed in a nonbrutal training style that still pushed athletes to their limits.\",\"p\":\"nan\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.bru.tal\",\"t\":[\"olatin\"]},{\"w\":\"nonbubbly\",\"d\":\"Describing a liquid or personality that does not produce bubbles or exhibit a lively, effervescent quality.\",\"s\":\"The scientist preferred a nonbubbly solution so she could measure it more accurately.\",\"p\":\"nan\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.bub.bly\",\"t\":[\"olatin\"]},{\"w\":\"nonbudding\",\"d\":\"Describing an organism or cell that does not reproduce or grow through the process of budding.\",\"s\":\"The nonbudding plant reproduced through spores rather than growing new shoots.\",\"p\":\"nan\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.bud.ding\",\"t\":[\"olatin\"]},{\"w\":\"nonbudget\",\"d\":\"Describing something that is not related to or constrained by a specific financial budget.\",\"s\":\"The principal said the school trip was a nonbudget item and needed special approval.\",\"p\":\"nan\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.bud.get\",\"t\":[\"olatin\"]},{\"w\":\"nonbudgetary\",\"d\":\"Relating to matters or items that fall outside the scope of a formal financial budget.\",\"s\":\"The committee discussed nonbudgetary concerns like student morale and community involvement.\",\"p\":\"nan\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"non.bud.getary\",\"t\":[\"olatin\"]},{\"w\":\"nonbudgeted\",\"d\":\"Describing an expense or item that was not planned for or included in an official budget.\",\"s\":\"The sudden roof repair was a nonbudgeted expense that surprised the school board.\",\"p\":\"nan\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.bud.get.ed\",\"t\":[\"olatin\"]},{\"w\":\"nonbuilder\",\"d\":\"A person or company that does not construct or develop buildings or physical structures.\",\"s\":\"As a nonbuilder, the company focused on designing plans rather than constructing anything.\",\"p\":\"nan\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.builder\",\"t\":[\"buildings\",\"olatin\"]},{\"w\":\"nonbuilding\",\"d\":\"Describing a structure or activity that does not qualify as or involve the construction of a traditional building.\",\"s\":\"The park was classified as nonbuilding land, so no structures could ever be placed there.\",\"p\":\"NAH-NBIH-ldih-ng\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"naa.nbih.ldih.ng\",\"t\":[\"buildings\",\"festivals\",\"olatin\"]},{\"w\":\"nonbulbar\",\"d\":\"Describing something that does not originate from or relate to the bulbar region of the brain or spinal cord.\",\"s\":\"The doctor noted that the patient's condition was nonbulbar, meaning it did not affect the brain stem.\",\"p\":\"nan\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.bul.bar\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonbulbous\",\"d\":\"Describing a plant or structure that does not grow from or form a bulb-shaped base.\",\"s\":\"The plant's nonbulbous roots spread sideways rather than forming a round underground bulb.\",\"p\":\"nan\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.bul.bous\",\"t\":[\"botany\",\"olatin\"]},{\"w\":\"nonbulimic\",\"d\":\"Describing a person or behavior pattern that is not associated with or characterized by bulimia.\",\"s\":\"The nutritionist designed a meal plan to support both bulimic and nonbulimic patients.\",\"p\":\"nan\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.bu.lim.ic\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nonbullied\",\"d\":\"Describing a person who has not been subjected to bullying or intimidating behavior by others.\",\"s\":\"The survey showed that nonbullied students reported feeling happier and more confident at school.\",\"p\":\"nan\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.bul.lied\",\"t\":[\"olatin\"]},{\"w\":\"nonbully\",\"d\":\"A person who does not engage in bullying behavior; someone who treats others with respect and kindness rather than using intimidation or cruelty.\",\"s\":\"Teachers praised Marcus for being a nonbully who always stood up for his classmates.\",\"p\":\"nahn-BUL-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.bul.ly\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonbullying\",\"d\":\"Not involving or characterized by bullying; describing behavior, programs, or environments that are free from intimidation, harassment, or cruelty.\",\"s\":\"The school promoted a nonbullying culture by rewarding students who showed kindness.\",\"p\":\"nahn-BUL-ee-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"non.bul.ly.ing\",\"ps\":\"adjective\",\"t\":[\"ecology\",\"character\",\"olatin\"]},{\"w\":\"nonbundled\",\"d\":\"Not grouped or packaged together as a single unit; describing products or services sold separately rather than as a combined package.\",\"s\":\"The software was sold as nonbundled, meaning each program had to be purchased separately.\",\"p\":\"nahn-BUN-dld\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.bun.dled\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonbuoyant\",\"d\":\"Not capable of floating or staying afloat in water or another fluid; lacking the ability to rise or remain at the surface.\",\"s\":\"The heavy metal anchor was nonbuoyant and sank straight to the ocean floor.\",\"p\":\"nahn-BOY-unt\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.buoy.ant\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonbureaucratic\",\"d\":\"Not characterized by excessive rules, paperwork, or rigid administrative procedures; describing a system or organization that operates with flexibility and minimal red tape.\",\"s\":\"The startup prided itself on a nonbureaucratic style where decisions were made quickly.\",\"p\":\"nahn-byoo-roh-KRAT-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.bu.reau.crat.ic\",\"ps\":\"adjective\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nonburger\",\"d\":\"A food item made to resemble a burger but containing no traditional beef or meat patty, such as a veggie or plant-based alternative.\",\"s\":\"The restaurant offered a nonburger menu full of tacos, wraps, and grain bowls.\",\"p\":\"nahn-BUR-gur\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.burg.er\",\"ps\":\"noun\",\"t\":[\"botany\",\"festivals\",\"olatin\"]},{\"w\":\"nonburn\",\"d\":\"Not resulting in or causing burning; describing a substance, material, or process that does not produce a burning sensation or combustion.\",\"s\":\"Engineers tested the nonburn material to ensure it wouldn't catch fire in an emergency.\",\"p\":\"nahn-BURN\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.burn\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonburning\",\"d\":\"Not burning or capable of catching fire; describing a material or substance that resists combustion or does not produce flames.\",\"s\":\"The firefighters used a nonburning gel to coat the wooden beams before the controlled test.\",\"p\":\"nahn-BUR-ning\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.burn.ing\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonburrowing\",\"d\":\"Not digging or tunneling into the ground; describing an animal or organism that does not create burrows or underground passages for shelter.\",\"s\":\"Unlike moles, the nonburrowing lizard lived on rocky surfaces above the ground.\",\"p\":\"nahn-BUR-oh-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.bur.row.ing\",\"ps\":\"adjective\",\"t\":[\"animals\",\"olatin\"]},{\"w\":\"nonbursate\",\"d\":\"Lacking a bursa or pouch-like structure; used in biology to describe organisms or anatomical features that do not have a sac-shaped cavity.\",\"s\":\"The biology textbook described the organism's nonbursate structure as lacking a pouch-like cavity.\",\"p\":\"nahn-BUR-sayt\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.bur.sate\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonbusiness\",\"d\":\"Not related to or involving commercial trade or professional enterprise; describing activities, organizations, or purposes that are personal, recreational, or nonprofit in nature.\",\"s\":\"She checked her personal email on her nonbusiness hours so it wouldn't interfere with work.\",\"p\":\"NAH-NBIH-znuh-s\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"naa.nbih.znah.s\",\"ps\":\"adjective\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nonbusy\",\"d\":\"Not occupied with a great deal of activity or work; describing a person, place, or time period that is relatively calm, idle, or free from demands.\",\"s\":\"The librarian enjoyed the nonbusy afternoons when she could reorganize the shelves quietly.\",\"p\":\"nahn-BIZ-ee\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.busy\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nonbutter\",\"d\":\"A spread or substitute that resembles butter but does not contain actual dairy butter, such as a margarine or plant-based alternative.\",\"s\":\"The bakery offered nonbutter substitutes for customers who were avoiding dairy products.\",\"p\":\"nahn-BUT-ur\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.but.ter\",\"ps\":\"noun\",\"t\":[\"botany\",\"farming\",\"olatin\"]},{\"w\":\"nonbuttered\",\"d\":\"Not coated or prepared with butter; describing food that has been made or served without the addition of butter.\",\"s\":\"She ordered nonbuttered toast to keep her breakfast as light as possible.\",\"p\":\"nahn-BUT-urd\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.but.tered\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonbutterfat\",\"d\":\"Not containing or derived from the natural fat found in dairy butter; describing food products formulated without the fat component of milk or cream.\",\"s\":\"The label on the milk carton listed the nonbutterfat solids as a separate ingredient.\",\"p\":\"nahn-BUT-ur-fat\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.but.ter.fat\",\"ps\":\"adjective\",\"t\":[\"farming\",\"olatin\"]},{\"w\":\"nonbuyer\",\"d\":\"A person who does not purchase a particular product or service; someone who visits a store or considers an item but ultimately chooses not to buy.\",\"s\":\"The salesperson tried to understand why every nonbuyer left the store without making a purchase.\",\"p\":\"nahn-BY-ur\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.buy.er\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonbuying\",\"d\":\"Not engaged in the act of purchasing; describing behavior or a group of people who are not actively acquiring goods or services.\",\"s\":\"Researchers studied nonbuying behavior to figure out what stopped shoppers from checking out.\",\"p\":\"nahn-BY-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.buy.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonbyte\",\"d\":\"Not consisting of or measured in bytes; describing data units or computer memory structures that do not conform to the standard eight-bit byte format.\",\"s\":\"The programmer noted that the data format used a nonbyte unit that wasn't standard in most systems.\",\"p\":\"nahn-BYT\",\"o\":\"Latin\",\"y\":9,\"bp\":19,\"sy\":\"non.byte\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"noncabinet\",\"d\":\"Not belonging to or associated with a governmental cabinet; describing a position, official, or role that falls outside the main group of senior government ministers.\",\"s\":\"The president appointed several noncabinet advisors to help with the new policy changes.\",\"p\":\"nahn-KAB-ih-nit\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.cab.i.net\",\"ps\":\"adjective\",\"t\":[\"household\",\"politics\",\"olatin\"]},{\"w\":\"noncable\",\"d\":\"Not transmitted through or requiring a cable system; describing television, internet, or communications services delivered without physical cable connections.\",\"s\":\"The noncable television service used an antenna to pick up local broadcast channels.\",\"p\":\"nahn-KAY-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.ca.ble\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncacheable\",\"d\":\"Not able to be stored in a cache for quick retrieval; describing data or web content that must be freshly loaded each time rather than saved in temporary memory.\",\"s\":\"The web developer flagged certain pages as noncacheable so users always saw the latest content.\",\"p\":\"nahn-KASH-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.cacheable\",\"ps\":\"adjective\",\"t\":[\"music\",\"time\",\"olatin\"]},{\"w\":\"noncached\",\"d\":\"Not stored in a cache or temporary memory; describing data or digital content that is retrieved directly from its original source each time it is needed.\",\"s\":\"The noncached data had to be fetched from the server every single time, slowing the website down.\",\"p\":\"nahn-KASHT\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.cached\",\"ps\":\"adjective\",\"t\":[\"music\",\"time\",\"olatin\"]},{\"w\":\"noncaching\",\"d\":\"Not using or performing the process of storing data in a temporary memory location; describing a system or method that always retrieves information from its primary source.\",\"s\":\"The noncaching browser setting meant every page loaded fresh but used more data.\",\"p\":\"nahn-KASH-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.caching\",\"ps\":\"adjective\",\"t\":[\"music\",\"time\",\"olatin\"]},{\"w\":\"noncaffeinated\",\"d\":\"Not containing caffeine; describing a beverage or food product, such as herbal tea or decaf coffee, from which the stimulant caffeine has been removed or was never present.\",\"s\":\"She switched to noncaffeinated tea in the evenings so she could fall asleep more easily.\",\"p\":\"nahn-KAF-ih-nayt-id\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.caf.feinat.ed\",\"ps\":\"adjective\",\"t\":[\"dishes\",\"olatin\"]},{\"w\":\"noncaking\",\"d\":\"Not forming lumps or a hardened mass; describing a powdery or granular substance that remains loose and free-flowing without clumping together.\",\"s\":\"The company used noncaking salt in its product to prevent it from clumping in humid weather.\",\"p\":\"nahn-KAY-king\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.cak.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncalcareous\",\"d\":\"Not containing or composed of calcium carbonate or limestone; describing rock, soil, or biological material that lacks the chalky or limy properties of calcareous substances.\",\"s\":\"The geologist identified the rock sample as noncalcareous because it contained no calcium carbonate.\",\"p\":\"nahn-kal-KAIR-ee-us\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.cal.care.ous\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"minerals\",\"olatin\"]},{\"w\":\"noncalcic\",\"d\":\"Not containing or relating to calcium; used in science and geology to describe soils, minerals, or compounds that are free of significant calcium content.\",\"s\":\"The soil scientist labeled the plot as noncalcic since it showed no signs of calcium buildup.\",\"p\":\"nahn-KAL-sik\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.cal.cic\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"minerals\",\"olatin\"]},{\"w\":\"noncalciferous\",\"d\":\"Not bearing or yielding calcium; describing a substance, rock, or biological tissue that does not contain or produce calcium compounds.\",\"s\":\"The scientist noted that the noncalciferous rock layers contained no calcium carbonate minerals.\",\"p\":\"nahn-kal-SIF-ur-us\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.cal.cif.er.ous\",\"ps\":\"adjective\",\"t\":[\"body\",\"chemistry\",\"minerals\",\"maps\",\"olatin\"]},{\"w\":\"noncalcified\",\"d\":\"Not having undergone calcification; describing tissue or material that has not hardened through the deposit of calcium salts, remaining soft and flexible.\",\"s\":\"The noncalcified cartilage in the young athlete's knee was still soft and flexible.\",\"p\":\"nahn-KAL-sih-fyd\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.cal.ci.fied\",\"ps\":\"adjective\",\"t\":[\"body\",\"chemistry\",\"olatin\"]},{\"w\":\"noncalcifying\",\"d\":\"Not undergoing or causing the process of calcification; describing cells, tissues, or substances that do not deposit calcium salts to become hardened.\",\"s\":\"Researchers discovered a noncalcifying strain of bacteria that could not form mineral deposits.\",\"p\":\"nahn-KAL-sih-fy-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.cal.ci.fy.ing\",\"ps\":\"adjective\",\"t\":[\"body\",\"chemistry\",\"olatin\"]},{\"w\":\"noncalcium\",\"d\":\"Not relating to or containing calcium; describing a dietary supplement, compound, or mineral source that provides nutrients other than calcium.\",\"s\":\"The dietitian recommended a noncalcium supplement for patients who already had high calcium levels.\",\"p\":\"nahn-KAL-see-um\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.cal.ci.um\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"minerals\",\"olatin\"]},{\"w\":\"noncalculable\",\"d\":\"Not able to be calculated or precisely determined; describing a quantity, risk, or outcome that cannot be measured or computed with accuracy.\",\"s\":\"The emotional damage from the accident was noncalculable and could not be expressed in dollars.\",\"p\":\"nahn-KAL-kyoo-luh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.cal.cu.la.ble\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"noncalculus\",\"d\":\"Not involving or requiring the branch of mathematics known as calculus; describing a course, problem, or mathematical approach that uses only more basic mathematical methods.\",\"s\":\"The noncalculus math course covered statistics and logic without any derivatives or integrals.\",\"p\":\"nahn-KAL-kyoo-lus\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.cal.cu.lus\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"noncalendrical\",\"d\":\"Not based on or organized according to a standard calendar system; describing a time-keeping method, event, or cycle that does not follow conventional calendar divisions.\",\"s\":\"The tribe used a noncalendrical system to track time based on seasonal animal migrations.\",\"p\":\"nahn-kuh-LEN-drih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.cal.en.dri.cal\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"time\",\"olatin\"]},{\"w\":\"noncalibrated\",\"d\":\"Not adjusted or measured against a standard scale; describing an instrument, device, or process that has not been set to ensure accurate and consistent readings.\",\"s\":\"Using a noncalibrated thermometer gave inaccurate readings during the chemistry experiment.\",\"p\":\"nahn-KAL-ih-bray-tid\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.cal.i.brat.ed\",\"ps\":\"adjective\",\"t\":[\"music\",\"tools\",\"numbers\",\"olatin\"]},{\"w\":\"noncall\",\"d\":\"A situation in sports or officiating where a referee or judge does not make a ruling or penalty call on a play that might otherwise have been flagged.\",\"s\":\"The referee made a controversial noncall when he ignored the obvious foul at the end of the game.\",\"p\":\"nahn-KAWL\",\"o\":\"Latin\",\"y\":9,\"bp\":19,\"sy\":\"non.call\",\"ps\":\"noun\",\"t\":[\"stage\",\"law\",\"sports\",\"olatin\"]},{\"w\":\"noncallable\",\"d\":\"Not able to be redeemed or repaid by the issuer before the stated maturity date; describing a bond or financial instrument that the issuer cannot buy back early.\",\"s\":\"The investor preferred noncallable bonds because the bank could not redeem them early.\",\"p\":\"nah-NKAW-luh-buh-l\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"naa.nkao.lah.bah.l\",\"ps\":\"adjective\",\"t\":[\"music\",\"olatin\"]},{\"w\":\"noncalligraphic\",\"d\":\"Not characterized by the artistic, decorative style of calligraphy; describing handwriting or text that is plain and functional rather than ornate or beautifully stylized.\",\"s\":\"The artist's noncalligraphic style used bold printed letters rather than elegant flowing script.\",\"p\":\"nahn-kal-ih-GRAF-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.cal.li.graph.ic\",\"ps\":\"adjective\",\"t\":[\"landforms\",\"painting\",\"character\",\"olatin\"]},{\"w\":\"noncalorific\",\"d\":\"Not producing or containing significant calories; describing a food, beverage, or substance that provides little to no energy value when consumed.\",\"s\":\"The company advertised its noncalorific sweetener as a way to enjoy sweetness without gaining weight.\",\"p\":\"nahn-kal-uh-RIF-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"noncalorif.ic\",\"ps\":\"adjective\",\"t\":[\"physics\",\"dishes\",\"olatin\"]},{\"w\":\"noncalorimetric\",\"d\":\"Not involving or measured by calorimetry; describing a scientific method or process that determines heat or energy without using a calorimeter or heat-measurement device.\",\"s\":\"The noncalorimetric method measured reaction rates without tracking heat changes.\",\"p\":\"nahn-kal-uh-rih-MET-rik\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"noncalori.met.ric\",\"ps\":\"adjective\",\"t\":[\"physics\",\"tools\",\"numbers\",\"olatin\"]},{\"w\":\"noncamouflaged\",\"d\":\"Not disguised or hidden by camouflage; visible and easy to detect because no attempt has been made to blend into the surroundings.\",\"s\":\"The bright red noncamouflaged uniforms made the soldiers easy to spot in the forest.\",\"p\":\"non-KAM-uh-flahzd\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.cam.ou.flaged\",\"ps\":\"adjective\",\"t\":[\"ecology\",\"olatin\"]},{\"w\":\"noncampaigning\",\"d\":\"Not engaged in or related to a political campaign; describing a person or activity that does not involve running for office or promoting a candidate.\",\"s\":\"The noncampaigning senator focused entirely on passing new legislation rather than seeking votes.\",\"p\":\"non-kam-PAYN-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.cam.paign.ing\",\"ps\":\"adjective\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"noncamping\",\"d\":\"Not involving or related to camping; describing an activity, facility, or area where overnight outdoor camping is not permitted or practiced.\",\"s\":\"My family always books hotels because we are strictly noncamping vacationers.\",\"p\":\"non-KAMP-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.camp.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncampus\",\"d\":\"Not located on or associated with a school or university campus; referring to facilities, events, or activities that take place off campus.\",\"s\":\"Many noncampus students take their college courses entirely online from home.\",\"p\":\"non-KAM-pus\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.cam.pus\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonCanadian\",\"d\":\"Not Canadian; referring to a person, organization, or thing that is not from or associated with Canada.\",\"s\":\"The nonCanadian players on the hockey team had to obtain special work visas.\",\"p\":\"non-kuh-NAY-dee-un\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.cana.di.an\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncanal\",\"d\":\"Not consisting of or relating to a canal; describing a waterway or passage that does not have the structure or function of a canal.\",\"s\":\"The engineer proposed a noncanal irrigation system using underground pipes instead of open channels.\",\"p\":\"non-kuh-NAL\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.canal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncanalized\",\"d\":\"Not directed or confined through a canal or narrow channel; describing something that flows or moves freely without being forced into a fixed route.\",\"s\":\"The noncanalized river spread freely across the floodplain during heavy rains.\",\"p\":\"non-KAN-uh-lyzd\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"non.canal.ized\",\"ps\":\"adjective\",\"t\":[\"maps\",\"olatin\"]},{\"w\":\"noncancelable\",\"d\":\"Not able to be canceled or terminated; describing a contract, policy, or agreement that must remain in force and cannot be ended by either party.\",\"s\":\"Once you sign the noncancelable lease, you are committed to paying rent for the full year.\",\"p\":\"non-KAN-suh-luh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.cance.lable\",\"ps\":\"adjective\",\"t\":[\"physics\",\"law\",\"politics\",\"olatin\"]},{\"w\":\"noncanceled\",\"d\":\"Not having been canceled; describing an event, order, or arrangement that has been kept in place and has not been called off.\",\"s\":\"The noncanceled flight departed on time despite the stormy weather threatening nearby airports.\",\"p\":\"non-KAN-suld\",\"o\":\"Latin\",\"y\":8,\"bp\":34,\"sy\":\"non.canceled\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncancellation\",\"d\":\"The absence or avoidance of cancellation; the state in which something such as a contract, reservation, or event has not been canceled.\",\"s\":\"The hotel's noncancellation policy meant guests lost their deposit if they changed their minds.\",\"p\":\"non-kan-suh-LAY-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.can.cel.la.tion\",\"ps\":\"noun\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"noncancelled\",\"d\":\"Not having been cancelled; the British-spelling variant describing an event, booking, or agreement that remains active and has not been called off.\",\"s\":\"The noncancelled reservation held our table even when we arrived thirty minutes late.\",\"p\":\"non-KAN-suld\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.can.celled\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"noncancer\",\"d\":\"Not related to or caused by cancer; describing a medical condition, cell, or growth that is benign and does not involve cancerous activity.\",\"s\":\"The biopsy revealed the growth was noncancer and completely harmless.\",\"p\":\"non-KAN-ser\",\"o\":\"Latin\",\"y\":7,\"bp\":26,\"sy\":\"non.cancer\",\"ps\":\"adjective\",\"t\":[\"body\",\"disease\",\"olatin\"]},{\"w\":\"noncandidacy\",\"d\":\"The state or condition of not being a candidate; the status of a person who has not announced or declared their intention to run for a particular office or position.\",\"s\":\"His noncandidacy announcement surprised supporters who had expected him to run for governor.\",\"p\":\"non-KAN-dih-duh-see\",\"o\":\"Latin\",\"y\":8,\"bp\":39,\"sy\":\"non.can.di.da.cy\",\"ps\":\"noun\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"noncandidate\",\"d\":\"someone who has announced they are not a candidate; especially a politician who has announced that he or she is not a candidate for some political office\",\"s\":\"The senator remained a noncandidate despite thousands of fans urging her to enter the presidential race.\",\"p\":\"non-KAN-dih-dayt\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.can.di.date\",\"ps\":\"noun\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"noncanine\",\"d\":\"Not of or relating to dogs; describing an animal, behavior, or characteristic that does not belong to the dog family or is not dog-like.\",\"s\":\"The veterinary clinic expanded to treat noncanine pets such as rabbits, birds, and lizards.\",\"p\":\"non-KAY-nyn\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.ca.nine\",\"ps\":\"adjective\",\"t\":[\"animals\",\"kinship\",\"olatin\"]},{\"w\":\"noncanned\",\"d\":\"Not preserved or stored in a can; describing food or other products that are fresh, frozen, or packaged by methods other than canning.\",\"s\":\"The chef insisted on using only noncanned tomatoes freshly picked from the garden.\",\"p\":\"non-KAND\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.canned\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncannibalistic\",\"d\":\"Not involving or practicing cannibalism; describing a species, group, or behavior in which individuals do not consume members of their own kind.\",\"s\":\"Scientists were relieved to find that the newly discovered insect species was noncannibalistic.\",\"p\":\"non-kan-uh-buh-LIS-tik\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.can.ni.bal.is.tic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncanonical\",\"d\":\"Not belonging to or recognized by an established canon or authoritative set of rules, texts, or standards; outside the accepted or official body of work.\",\"s\":\"The teacher assigned a noncanonical novel that most students had never heard of before.\",\"p\":\"non-kuh-NON-ih-kul\",\"o\":\"Latin\",\"y\":7,\"bp\":38,\"sy\":\"non.canon.i.cal\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"noncanonicality\",\"d\":\"The quality or state of being outside an established canon; the condition of a text, idea, or practice that is not recognized as authoritative or standard.\",\"s\":\"The professor wrote a paper on the noncanonicality of several ancient texts excluded from the Bible.\",\"p\":\"non-kuh-non-ih-KAL-ih-tee\",\"o\":\"Latin\",\"y\":9,\"bp\":31,\"sy\":\"non.canon.i.cal.i.ty\",\"ps\":\"noun\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"noncanonically\",\"d\":\"In a manner that is not canonical; in a way that does not conform to an established or officially recognized set of rules, texts, or standards.\",\"s\":\"The story was written noncanonically, meaning it did not follow the official rules of the book series.\",\"p\":\"non-kuh-NON-ih-kuh-lee\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.canon.i.cal.ly\",\"ps\":\"adverb\",\"t\":[\"olatin\"]},{\"w\":\"noncanonized\",\"d\":\"Not having been officially declared a saint or elevated to canonical status; describing a person, text, or work that has not been formally recognized by a religious or authoritative body.\",\"s\":\"The noncanonized saint was beloved locally even though the church never officially recognized her.\",\"p\":\"non-KAN-uh-nyzd\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.can.on.ized\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"religion\",\"olatin\"]},{\"w\":\"noncanvas\",\"d\":\"Not made of or relating to canvas; describing a material, surface, or artwork that uses a medium other than traditional woven canvas fabric.\",\"s\":\"The artist experimented with noncanvas surfaces like wood and metal for her new paintings.\",\"p\":\"non-KAN-vus\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.can.vas\",\"ps\":\"adjective\",\"t\":[\"fabrics\",\"painting\",\"festivals\",\"olatin\"]},{\"w\":\"noncapable\",\"d\":\"Not having the ability, skill, or power to do something; lacking the necessary capacity or qualification to perform a task.\",\"s\":\"The outdated software was noncapable of running the new high-definition graphics program.\",\"p\":\"non-KAY-puh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.ca.pable\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncapillary\",\"d\":\"Not of or relating to capillaries; describing a vessel, tube, or flow that is too large or structured differently to exhibit the narrow-tube fluid action seen in capillaries.\",\"s\":\"The noncapillary tube was too wide to draw liquid upward through surface tension.\",\"p\":\"non-KAP-ih-lair-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.cap.il.lary\",\"ps\":\"adjective\",\"t\":[\"seafaring\",\"olatin\"]},{\"w\":\"noncapital\",\"d\":\"Not involving capital punishment or not relating to a capital city; describing a crime that does not carry the death penalty or a city that is not a seat of government.\",\"s\":\"Shoplifting is a noncapital offense, meaning it cannot result in the death penalty.\",\"p\":\"non-KAP-ih-tul\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.cap.i.tal\",\"ps\":\"adjective\",\"t\":[\"nations\",\"law\",\"politics\",\"olatin\"]},{\"w\":\"noncapitalist\",\"d\":\"A person who does not believe in or practice capitalism; one who supports an economic system that is not based on private ownership and the pursuit of profit.\",\"s\":\"The noncapitalist community shared resources equally among all its members.\",\"p\":\"non-KAP-ih-tul-ist\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.cap.i.tal.ist\",\"ps\":\"noun\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"noncapitalistic\",\"d\":\"Not based on or characterized by capitalism; describing an economic system, society, or approach that does not rely on private ownership, free markets, or profit-driven enterprise.\",\"s\":\"The noncapitalistic economy relied on bartering and cooperative farming rather than profit-driven business.\",\"p\":\"non-kap-ih-tul-IS-tik\",\"o\":\"Latin\",\"y\":9,\"bp\":31,\"sy\":\"non.cap.i.tal.is.tic\",\"ps\":\"adjective\",\"t\":[\"economy\",\"character\",\"olatin\"]},{\"w\":\"noncapitalized\",\"d\":\"Not written or printed with a capital letter; also, not funded or financed through the investment of capital in a business or economic venture.\",\"s\":\"The noncapitalized words in the title made the editor cringe.\",\"p\":\"non-KAP-ih-tul-yzd\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.cap.i.tal.ized\",\"ps\":\"adjective\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"noncapped\",\"d\":\"Not having a cap, limit, or maximum restriction placed on it; describing a fee, salary, benefit, or container that has no upper boundary or covering.\",\"s\":\"The noncapped spending on the project worried the school board.\",\"p\":\"non-KAPT\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.capped\",\"ps\":\"adjective\",\"t\":[\"maps\",\"economy\",\"olatin\"]},{\"w\":\"noncapsizable\",\"d\":\"Not able to be capsized or overturned; describing a boat or vessel that is designed or built in such a way that it will not tip over or flip in the water.\",\"s\":\"The heavy-bottomed sailboat was designed to be noncapsizable even in rough seas.\",\"p\":\"non-KAP-sy-zuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.cap.siz.able\",\"ps\":\"adjective\",\"t\":[\"seafaring\",\"olatin\"]},{\"w\":\"noncaptive\",\"d\":\"Not held in captivity; describing an animal, person, or population that lives freely in its natural environment rather than being confined or controlled.\",\"s\":\"The noncaptive wolves roamed freely across the national park.\",\"p\":\"non-KAP-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.cap.tive\",\"ps\":\"adjective\",\"t\":[\"animals\",\"ecology\",\"olatin\"]},{\"w\":\"noncarb\",\"d\":\"Not containing carbohydrates; describing a food, diet, or substance that has little or no carbohydrate content.\",\"s\":\"She ordered a noncarb meal to stick to her low-carbohydrate diet.\",\"p\":\"non-KARB\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.carb\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncarbohydrate\",\"d\":\"Not consisting of or relating to carbohydrates; describing a nutrient, molecule, or food source that does not contain sugars, starches, or other carbohydrate compounds.\",\"s\":\"The scientist studied noncarbohydrate energy sources in muscle cells.\",\"p\":\"non-kar-boh-HY-drayt\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.car.bo.hy.drate\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"noncarbon\",\"d\":\"Not made of or containing carbon; describing an element, material, or compound that does not include carbon atoms in its composition.\",\"s\":\"Researchers explored noncarbon materials for building lighter spacecraft.\",\"p\":\"non-KAR-bun\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.car.bon\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"noncarbonaceous\",\"d\":\"Not composed of or containing carbon or carbon-based compounds; describing a material or substance that lacks the organic carbon content typical of coal, graphite, or living matter.\",\"s\":\"The noncarbonaceous mineral deposit contained no traces of organic matter.\",\"p\":\"non-kar-buh-NAY-shus\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.car.bona.ceous\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"noncarbonated\",\"d\":\"not having carbonation\",\"s\":\"She preferred noncarbonated water because the bubbles bothered her stomach.\",\"p\":\"non-KAR-buh-nay-tid\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.car.bon.at.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncarboniferous\",\"d\":\"Not belonging to or characteristic of the Carboniferous geological period; also describing a substance or deposit that does not contain or produce significant amounts of carbon or coal.\",\"s\":\"The geologist identified the rock layer as noncarboniferous because it lacked coal seams.\",\"p\":\"non-kar-buh-NIF-er-us\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.car.bonif.er.ous\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"minerals\",\"olatin\"]},{\"w\":\"noncarbonized\",\"d\":\"Not having been converted into carbon or charcoal through burning or chemical treatment; describing a material that retains its original composition without being charred or turned to carbon.\",\"s\":\"The noncarbonized wood sample was used as a control in the archaeology experiment.\",\"p\":\"non-KAR-buh-nyzd\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.car.bonized\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"noncarboxylic\",\"d\":\"Not containing or relating to a carboxyl group; describing a chemical compound or acid that lacks the characteristic -COOH functional group found in carboxylic acids.\",\"s\":\"The chemist noted the compound was noncarboxylic, lacking the typical acid group.\",\"p\":\"non-kar-bok-SIL-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.car.boxylic\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"noncarburized\",\"d\":\"Not having undergone carburization; describing a metal, especially steel, that has not been treated by introducing extra carbon into its surface to harden it.\",\"s\":\"The noncarburized steel part was softer and more flexible than the hardened version.\",\"p\":\"non-KAR-byuh-ryzd\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.car.bur.ized\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"noncarcinogen\",\"d\":\"A substance or agent that does not cause cancer or promote the development of cancerous cells in living tissue.\",\"s\":\"Scientists confirmed the new food dye was a noncarcinogen after years of testing.\",\"p\":\"non-KAR-sih-noh-jen\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.car.cino.gen\",\"ps\":\"noun\",\"t\":[\"body\",\"disease\",\"olatin\"]},{\"w\":\"noncarcinomatous\",\"d\":\"Not relating to or characteristic of carcinoma; describing tissue or a condition that does not involve cancerous tumor growth.\",\"s\":\"The biopsy results were a relief because the growth was noncarcinomatous.\",\"p\":\"non-kar-sih-NOH-muh-tus\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.car.ci.no.ma.tous\",\"ps\":\"adjective\",\"t\":[\"body\",\"disease\",\"olatin\"]},{\"w\":\"noncardiopulmonary\",\"d\":\"Not involving or relating to the heart and lungs together; describing a condition, procedure, or system that does not concern the cardiopulmonary system.\",\"s\":\"The doctor ruled out noncardiopulmonary causes before checking the patient's lungs and heart.\",\"p\":\"non-kar-dee-oh-PUL-muh-nair-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.car.diopul.monary\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"noncardiovascular\",\"d\":\"Not related to or involving the heart and blood vessels; describing causes, conditions, or treatments that do not affect the cardiovascular system.\",\"s\":\"The pain turned out to be noncardiovascular, stemming from a muscle strain instead.\",\"p\":\"non-kar-dee-oh-VAS-kyoo-ler\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.car.dio.vas.cu.lar\",\"ps\":\"adjective\",\"t\":[\"body\",\"seafaring\",\"olatin\"]},{\"w\":\"noncareer\",\"d\":\"Not related to or intended as part of a professional career; describing activities, roles, or pursuits done outside one's chosen occupation.\",\"s\":\"She took on noncareer volunteer work simply because she loved helping others.\",\"p\":\"non-kuh-REER\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.ca.r.eer\",\"ps\":\"adjective\",\"t\":[\"jobs\",\"olatin\"]},{\"w\":\"noncareerist\",\"d\":\"A person who does not prioritize career advancement or professional ambition as the central focus of their life.\",\"s\":\"The noncareerist teacher stayed in the classroom for love of kids, not promotions.\",\"p\":\"non-kuh-REER-ist\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.ca.r.eerist\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"noncareful\",\"d\":\"Lacking care or attention; not cautious or thorough in handling tasks or situations.\",\"s\":\"His noncareful handling of the glass vase made everyone in the room nervous.\",\"p\":\"non-KAIR-ful\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.car.e.ful\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncarer\",\"d\":\"A person who does not serve in a caregiving role and is not responsible for looking after another individual's wellbeing.\",\"s\":\"The agency struggled to identify which residents were noncarer households needing extra support.\",\"p\":\"non-KAIR-er\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.car.er\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"noncaring\",\"d\":\"Showing a lack of concern, compassion, or interest in the wellbeing of others or in one's responsibilities.\",\"s\":\"The noncaring attitude of the indifferent clerk frustrated every customer in line.\",\"p\":\"non-KAIR-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.car.ing\",\"ps\":\"adjective\",\"t\":[\"maps\",\"olatin\"]},{\"w\":\"noncariogenic\",\"d\":\"Not capable of causing or promoting tooth decay or dental cavities; describing foods, substances, or materials that do not contribute to caries.\",\"s\":\"The dentist recommended noncariogenic snacks like cheese and nuts instead of sugary candy.\",\"p\":\"non-kair-ee-oh-JEN-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.car.i.o.genic\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"noncarious\",\"d\":\"Not affected by or exhibiting dental caries; describing teeth or dental tissue that show no signs of decay.\",\"s\":\"The X-ray showed that most of the patient's teeth were noncarious and healthy.\",\"p\":\"non-KAIR-ee-us\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.car.i.ous\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"noncarnal\",\"d\":\"Not relating to physical or bodily desires; spiritual, intellectual, or emotional rather than fleshly in nature.\",\"s\":\"Their friendship was purely noncarnal, built on shared interests and deep conversation.\",\"p\":\"non-KAR-nul\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.car.nal\",\"ps\":\"adjective\",\"t\":[\"religion\",\"emotions\",\"olatin\"]},{\"w\":\"noncarnivore\",\"d\":\"An organism that does not eat meat as part of its diet, such as an herbivore or omnivore that avoids animal flesh.\",\"s\":\"A panda is technically a noncarnivore despite being classified as a bear.\",\"p\":\"non-KAR-nih-vor\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.car.ni.vore\",\"ps\":\"noun\",\"t\":[\"animals\",\"olatin\"]},{\"w\":\"noncarnivorous\",\"d\":\"Not feeding on meat or animal flesh; describing animals, plants, or diets that exclude the consumption of other animals.\",\"s\":\"The noncarnivorous dinosaur species fed exclusively on plants and fruits.\",\"p\":\"non-kar-NIV-er-us\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.car.niv.o.rous\",\"ps\":\"adjective\",\"t\":[\"animals\",\"botany\",\"olatin\"]},{\"w\":\"noncarotid\",\"d\":\"Not relating to or involving the carotid artery; describing blood vessels, structures, or procedures that do not concern the carotid artery in the neck.\",\"s\":\"The surgeon identified a noncarotid artery as the source of the unusual blood flow.\",\"p\":\"non-kuh-ROT-id\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.car.otid\",\"ps\":\"adjective\",\"t\":[\"body\",\"seafaring\",\"olatin\"]},{\"w\":\"noncartilaginous\",\"d\":\"Not composed of or relating to cartilage; describing tissue, skeletal structures, or organisms that lack or do not involve cartilage.\",\"s\":\"The fossil came from a noncartilaginous fish species with a fully bony skeleton.\",\"p\":\"non-kar-tih-LAJ-ih-nus\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.car.ti.lagi.nous\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"noncartographic\",\"d\":\"Not relating to or involving the creation or use of maps; describing data, representations, or methods that do not use cartography.\",\"s\":\"The noncartographic images in the atlas included photographs and historical drawings.\",\"p\":\"non-kar-toh-GRAF-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.car.to.graph.ic\",\"ps\":\"adjective\",\"t\":[\"maps\",\"olatin\"]},{\"w\":\"noncasein\",\"d\":\"Not consisting of or derived from casein; describing the proteins or components of milk that are not the casein fraction.\",\"s\":\"The noncasein proteins in milk are less commonly studied than the dominant caseins.\",\"p\":\"non-KAY-seen\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.ca.sein\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"noncaste\",\"d\":\"Not belonging to or determined by a caste system; describing a society, relationship, or individual not defined by hereditary social rank.\",\"s\":\"The reformers pushed for a noncaste society where birth rank held no legal power.\",\"p\":\"non-KAST\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.caste\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncastrated\",\"d\":\"describing a male farm animal that has not had an operation to stop it from fathering young\",\"s\":\"The farmer separated the noncastrated males from the rest of the herd.\",\"p\":\"non-KAS-tray-tid\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.cas.trat.ed\",\"ps\":\"adjective\",\"t\":[\"animals\",\"olatin\"]},{\"w\":\"noncasual\",\"d\":\"Not informal or relaxed in manner, dress, or approach; describing something that is formal, deliberate, or serious in nature.\",\"s\":\"The noncasual tone of the letter made it clear the matter was serious.\",\"p\":\"non-KAZH-oo-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.ca.su.al\",\"ps\":\"adjective\",\"t\":[\"fabrics\",\"olatin\"]},{\"w\":\"noncat\",\"d\":\"Any animal or creature that is not a cat; used to distinguish feline animals from all other species in a given context.\",\"s\":\"The shelter labeled the friendly hamster section the 'noncat small pets' area.\",\"p\":\"non-KAT\",\"o\":\"Latin\",\"y\":8,\"bp\":18,\"sy\":\"non.cat\",\"ps\":\"noun\",\"t\":[\"animals\",\"olatin\"]},{\"w\":\"noncatalog\",\"d\":\"Not included in or related to a catalog; describing items, courses, or products that are not listed in an official or published catalog.\",\"s\":\"The store offered noncatalog items that could only be found in the physical showroom.\",\"p\":\"non-KAT-uh-lawg\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.cat.a.log\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncatalogued\",\"d\":\"Not entered into or organized within a catalog or official listing; describing items or records that have not been formally indexed or classified.\",\"s\":\"Thousands of noncatalogued specimens sat forgotten in dusty museum storage boxes.\",\"p\":\"non-KAT-uh-logd\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.cat.a.logued\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncatalytic\",\"d\":\"Not functioning as or involving a catalyst; describing a reaction, substance, or process that proceeds without the aid of a catalytic agent.\",\"s\":\"The reaction occurred slowly because it used a noncatalytic pathway without any enzyme.\",\"p\":\"non-kat-uh-LIT-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.cat.alyt.ic\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"noncatalyzed\",\"d\":\"Not accelerated or facilitated by a catalyst; describing a chemical reaction that takes place without the presence of a catalytic substance.\",\"s\":\"The noncatalyzed chemical reaction took hours longer than the version with a catalyst.\",\"p\":\"non-KAT-uh-lyzd\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.cat.alyzed\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"physics\",\"olatin\"]},{\"w\":\"noncatchment\",\"d\":\"Not within or relating to a designated catchment area; describing a region, population, or drainage zone that falls outside an officially defined catchment boundary.\",\"s\":\"Water flowing through the noncatchment zone was not collected for the reservoir.\",\"p\":\"non-KACH-ment\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.catch.ment\",\"ps\":\"adjective\",\"t\":[\"maps\",\"olatin\"]},{\"w\":\"noncategorical\",\"d\":\"Not absolute, definitive, or organized into distinct categories; describing a statement, approach, or classification that is conditional or not strictly divided.\",\"s\":\"The teacher gave a noncategorical answer that left students wondering which group the organism belonged to.\",\"p\":\"non-kat-ih-GOR-ih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.cat.e.gor.i.cal\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"noncategorizable\",\"d\":\"Impossible or impractical to place into a specific category or group; describing something so unique or ambiguous that standard classification systems cannot contain it.\",\"s\":\"The strange new creature was noncategorizable because it had features of both reptiles and mammals.\",\"p\":\"non-kat-ih-GOR-ih-zy-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.cat.e.go.riz.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncategorized\",\"d\":\"Not arranged or assigned into categories; describing data, items, or information that has not been sorted or grouped by type.\",\"s\":\"The noncategorized files sat in a messy pile on the librarian's desk.\",\"p\":\"non-KAT-ih-guh-ryzd\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.cat.e.go.rized\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncatenative\",\"d\":\"Not involving the linking or chaining of units in sequence; in linguistics, describing a morphological process that does not join morphemes end to end.\",\"s\":\"The linguist explained that the language used a noncatenative system, building words by changing internal vowels rather than adding endings.\",\"p\":\"non-KAT-ih-nay-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.cate.na.tive\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"noncationic\",\"d\":\"Not carrying a positive electrical charge; describing ions, surfactants, or molecules that are neutral or negatively charged rather than cationic.\",\"s\":\"The chemist chose a noncationic detergent because it would not interfere with the negatively charged surfaces in the experiment.\",\"p\":\"non-kat-eye-ON-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.ca.tion.ic\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"physics\",\"olatin\"]},{\"w\":\"noncattle\",\"d\":\"Not belonging to the category of cattle; describing livestock, animals, or agricultural subjects that are not bovine in nature.\",\"s\":\"The farm was licensed for noncattle livestock, including sheep, goats, and pigs.\",\"p\":\"non-KAT-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.cat.tle\",\"ps\":\"adjective\",\"t\":[\"animals\",\"farming\",\"olatin\"]},{\"w\":\"noncausally\",\"d\":\"In a manner that does not involve or imply a cause-and-effect relationship; describing how events or variables are related without one directly producing the other.\",\"s\":\"The two events were noncausally related — they happened at the same time but one did not cause the other.\",\"p\":\"non-KAW-zuh-lee\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.causal.ly\",\"ps\":\"adverb\",\"t\":[\"olatin\"]},{\"w\":\"noncausative\",\"d\":\"Not expressing or involving causation; in grammar, describing a verb or construction that does not indicate one thing causing another to happen.\",\"s\":\"The verb 'sleep' is noncausative because you cannot use it to say you made someone else sleep in the same simple form.\",\"p\":\"non-KAW-zuh-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.causative\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"noncausatively\",\"d\":\"In a way that does not express or imply causation; describing an action or linguistic construction where no causal relationship between events is indicated.\",\"s\":\"The sentence was structured noncausatively, describing the result without indicating who or what brought it about.\",\"p\":\"non-KAW-zuh-tiv-lee\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.causative.ly\",\"ps\":\"adverb\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"noncaustic\",\"d\":\"Not capable of burning, corroding, or chemically destroying tissue or materials; describing a substance that is safe to handle and does not cause chemical burns.\",\"s\":\"The art teacher assured students that the noncaustic paint was safe to use without gloves.\",\"p\":\"non-KAW-stik\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.caus.tic\",\"ps\":\"adjective\",\"t\":[\"body\",\"chemistry\",\"olatin\"]},{\"w\":\"noncavitary\",\"d\":\"Not involving or forming a cavity; in medicine, describing a lesion, tumor, or infection that does not create a hollow space within an organ or tissue.\",\"s\":\"The doctor was relieved to report that the lesion was noncavitary and had not formed a hollow core.\",\"p\":\"non-KAV-ih-tair-ee\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.cav.i.tary\",\"ps\":\"adjective\",\"t\":[\"body\",\"disease\",\"pharmacy\",\"music\",\"olatin\"]},{\"w\":\"noncelebration\",\"d\":\"The absence of a celebration or festivity; a situation in which an event or occasion passes without any commemorative acknowledgment or rejoicing.\",\"s\":\"The family chose a quiet noncelebration on the anniversary, preferring reflection over a party.\",\"p\":\"non-sel-ih-BRAY-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.cel.e.bra.tion\",\"ps\":\"noun\",\"t\":[\"festivals\",\"olatin\"]},{\"w\":\"noncelebratory\",\"d\":\"Not marked by or intended for celebration; describing an event, tone, or occasion that lacks festivity, joy, or commemorative spirit.\",\"s\":\"The graduation ceremony had a noncelebratory tone because many students were still worried about the future.\",\"p\":\"non-sel-ih-BRAY-tor-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.cel.e.bra.to.ry\",\"ps\":\"adjective\",\"t\":[\"festivals\",\"emotions\",\"olatin\"]},{\"w\":\"noncelebrity\",\"d\":\"A person who is not famous or well-known to the general public; an ordinary individual without celebrity status.\",\"s\":\"The talk show decided to feature noncelebrity guests to show real people's everyday struggles.\",\"p\":\"non-suh-LEB-rih-tee\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"non.celebri.ty\",\"ps\":\"noun\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"noncelestial\",\"d\":\"Not relating to the sky, heavens, or outer space; belonging to or existing on Earth rather than in the celestial realm.\",\"s\":\"The planetarium exhibit separated noncelestial phenomena, like weather, from stars and planets.\",\"p\":\"non-suh-LES-chul\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.ce.les.tial\",\"ps\":\"adjective\",\"t\":[\"astronomy\",\"olatin\"]},{\"w\":\"noncellular\",\"d\":\"not made up of or divided into cells\",\"s\":\"Viruses are considered noncellular because they lack the cell structure found in living organisms.\",\"p\":\"non-SEL-yuh-ler\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"non.cel.lu.lar\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"noncellulose\",\"d\":\"Not composed of or derived from cellulose; describing materials that lack the fibrous plant-based polymer found in cell walls.\",\"s\":\"Scientists tested whether the fiber in the drink was noncellulose, meaning it came from a synthetic source.\",\"p\":\"non-SEL-yuh-lohs\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.cel.lu.lose\",\"ps\":\"adjective\",\"t\":[\"botany\",\"olatin\"]},{\"w\":\"noncellulosic\",\"d\":\"Not made from or relating to cellulose; describing fibers, materials, or substances that are not derived from plant cell-wall matter.\",\"s\":\"The synthetic fabric was made from noncellulosic fibers that did not break down as easily as cotton.\",\"p\":\"non-sel-yuh-LOH-sik\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.cel.lu.losic\",\"ps\":\"adjective\",\"t\":[\"botany\",\"olatin\"]},{\"w\":\"noncement\",\"d\":\"Not consisting of or using cement as a binding agent; describing a material or substance that relies on a different adhesive or bonding method.\",\"s\":\"The builder used a noncement adhesive that set just as firmly but required no mixing.\",\"p\":\"non-sih-MENT\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.ce.ment\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncensored\",\"d\":\"Not subjected to censorship; describing content or information that has been allowed to pass through without removal, alteration, or suppression.\",\"s\":\"The documentary was a noncensored version that included footage cut from the original broadcast.\",\"p\":\"non-SEN-serd\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.cen.sored\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncensoring\",\"d\":\"Not engaging in the act of censoring; describing a policy, person, or system that allows content to be shared freely without blocking or editing it.\",\"s\":\"The noncensoring platform allowed users to post a wide range of opinions without content being removed.\",\"p\":\"non-SEN-ser-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.cen.sor.ing\",\"ps\":\"adjective\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"noncensorship\",\"d\":\"The absence or rejection of censorship; a condition or policy in which information and expression are not suppressed or controlled by authorities.\",\"s\":\"The journalist argued that noncensorship was essential to a free and informed society.\",\"p\":\"non-SEN-ser-ship\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.cen.sor.ship\",\"ps\":\"noun\",\"t\":[\"poetry\",\"politics\",\"olatin\"]},{\"w\":\"noncensus\",\"d\":\"Not based on or related to an official census count; describing data, populations, or methods that fall outside the scope of a formal government enumeration.\",\"s\":\"The study relied on noncensus data collected through surveys rather than official government counts.\",\"p\":\"non-SEN-sus\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.cen.sus\",\"ps\":\"adjective\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"noncentered\",\"d\":\"Not positioned at or focused on the center; describing something whose emphasis, alignment, or arrangement is placed off to one side rather than in the middle.\",\"s\":\"The abstract painting had a noncentered composition, with the main image shifted to the upper left corner.\",\"p\":\"non-SEN-terd\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.cen.tered\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncentral\",\"d\":\"Not located at or forming the center; situated away from the main or most important point, region, or hub of something.\",\"s\":\"The meeting was held at a noncentral location, which made it harder for some team members to attend.\",\"p\":\"non-SEN-trul\",\"o\":\"Latin\",\"y\":7,\"bp\":29,\"sy\":\"non.cen.tral\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncentralized\",\"d\":\"Not organized or controlled from a single central authority; describing a system in which power, decision-making, or resources are distributed among multiple locations or groups.\",\"s\":\"The noncentralized school system let each district make its own rules about curriculum.\",\"p\":\"non-SEN-truh-lyzd\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.cen.tral.ized\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"noncerebellar\",\"d\":\"Not relating to or involving the cerebellum, the part of the brain that coordinates movement and balance; describing neurological conditions or regions outside the cerebellum.\",\"s\":\"The neurologist noted that the patient's symptoms appeared to be noncerebellar in origin, pointing instead to the brain's frontal lobe.\",\"p\":\"non-sehr-uh-BEL-er\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.cere.bel.lar\",\"ps\":\"adjective\",\"t\":[\"body\",\"maps\",\"olatin\"]},{\"w\":\"noncerebrovascular\",\"d\":\"Not relating to the blood vessels of the brain; describing medical conditions, events, or structures that do not involve the cerebral vascular system.\",\"s\":\"The headache had a noncerebrovascular cause, meaning the blood vessels in the brain were not involved.\",\"p\":\"non-suh-ree-broh-VAS-kyuh-ler\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.cere.brovas.cu.lar\",\"ps\":\"adjective\",\"t\":[\"body\",\"seafaring\",\"olatin\"]},{\"w\":\"nonceremonial\",\"d\":\"Not involving or requiring formal ceremony or ritual; relaxed and informal rather than following prescribed traditional procedures.\",\"s\":\"The nonceremonial gathering was just friends sharing a meal, with no formal rituals or speeches.\",\"p\":\"non-sehr-uh-MOH-nee-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.cer.e.mo.ni.al\",\"ps\":\"adjective\",\"t\":[\"religion\",\"festivals\",\"olatin\"]},{\"w\":\"noncerium\",\"d\":\"Not containing or composed of cerium, the rare-earth metallic element; describing a substance or material from which cerium is absent.\",\"s\":\"The alloy was classified as noncerium because it contained none of the rare-earth element cerium.\",\"p\":\"non-SEER-ee-um\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.ceri.um\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"noncertifiable\",\"d\":\"Not able to be officially certified or verified; describing something that does not meet the standards or requirements necessary to receive formal certification.\",\"s\":\"The course was noncertifiable, so students received no official credential upon completion.\",\"p\":\"non-ser-TIF-ih-fy-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.cer.ti.fi.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncertificate\",\"d\":\"Not associated with or requiring the awarding of a formal certificate; describing a course, program, or activity that provides learning or experience without issuing official credentials.\",\"s\":\"She enrolled in a noncertificate workshop just to gain skills without worrying about earning credentials.\",\"p\":\"non-ser-TIF-ih-kut\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.cer.tifi.cate\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncertified\",\"d\":\"Not having received official certification or formal approval; describing a person, product, or process that has not been verified by a recognized authority.\",\"s\":\"The noncertified mechanic was talented, but the shop required official credentials before hiring.\",\"p\":\"non-SER-tih-fyd\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.cer.ti.fied\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"noncervical\",\"d\":\"Not relating to the cervix or the cervical region of the neck; describing medical conditions, procedures, or anatomical structures that do not involve these areas.\",\"s\":\"The doctor confirmed the pain was noncervical, originating in the lower back rather than the neck.\",\"p\":\"non-SER-vih-kul\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.cer.vi.cal\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"noncesium\",\"d\":\"Not containing or composed of cesium, the soft silvery-white alkali metal element; describing a material or compound from which cesium is entirely absent.\",\"s\":\"The scientist confirmed the compound was noncesium, ruling out that radioactive element from the sample.\",\"p\":\"non-SEE-zee-um\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.ce.sium\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"colors\",\"olatin\"]},{\"w\":\"nonchain\",\"d\":\"Not part of a chain of businesses or establishments; describing a store, restaurant, or organization that operates independently rather than as one of many linked locations.\",\"s\":\"The food critic preferred nonchain restaurants where recipes were original and locally inspired.\",\"p\":\"non-CHAYN\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.chain\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonchalky\",\"d\":\"Not having the dry, powdery, or gritty texture or appearance associated with chalk; describing a surface or substance that is smooth and free from chalky residue.\",\"s\":\"The art supply store advertised nonchalky pastels that left a smooth, vibrant color without a dusty residue.\",\"p\":\"non-CHAW-kee\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.chalky\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonchallenged\",\"d\":\"Not having been presented with a difficult task, obstacle, or opposition; describing a person or situation that has not faced any significant challenge or test.\",\"s\":\"The student felt bored and nonchallenged by the easy assignments, so she asked for extra work.\",\"p\":\"non-CHAL-enjd\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.chal.lenged\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonchallenging\",\"d\":\"Not presenting difficulty, complexity, or significant effort; describing a task, activity, or situation that is easy and requires little mental or physical exertion.\",\"s\":\"The nonchallenging puzzle was finished in minutes, leaving the child eager for something harder.\",\"p\":\"non-CHAL-en-jing\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.chal.leng.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonchanged\",\"d\":\"Not having undergone any alteration or modification; remaining in the same state or condition as before without any change having occurred.\",\"s\":\"The nonchanged settings on the computer remained exactly as the teacher had left them.\",\"p\":\"non-CHAYJND\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.changed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonchanging\",\"d\":\"Not undergoing or producing change; remaining constant and stable over time without variation or alteration.\",\"s\":\"The nonchanging rules of the game made it easy for new players to learn quickly.\",\"p\":\"non-CHAYN-jing\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.chang.ing\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nonchaos\",\"d\":\"The absence of chaos; a state of order, calm, and predictability in which confusion and disorder are not present.\",\"s\":\"The scientist described the perfectly ordered lab environment as a state of nonchaos.\",\"p\":\"non-KAY-os\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.chaos\",\"ps\":\"noun\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"nonchaotic\",\"d\":\"Not marked by chaos, disorder, or randomness; describing a system, environment, or situation that is orderly, organized, and predictable.\",\"s\":\"The librarian appreciated the nonchaotic atmosphere of the reading room on quiet afternoons.\",\"p\":\"non-kay-OT-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.chaot.ic\",\"ps\":\"adjective\",\"t\":[\"disease\",\"ecology\",\"olatin\"]},{\"w\":\"noncharacter\",\"d\":\"A person or figure in a story, film, or real life who lacks distinct personality traits, moral depth, or memorable qualities; also, something that does not qualify as a true character.\",\"s\":\"The bland background figure in the story was considered a noncharacter by most readers.\",\"p\":\"non-KEHR-ik-ter\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.char.ac.ter\",\"ps\":\"noun\",\"t\":[\"poetry\",\"logic\",\"olatin\"]},{\"w\":\"nonchargeable\",\"d\":\"Not able to be charged a fee or cost; describing a service, item, or expense for which no payment is required or permitted.\",\"s\":\"The minor repairs were nonchargeable, so the customer paid nothing extra.\",\"p\":\"non-CHAR-juh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.charge.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncharged\",\"d\":\"Not carrying an electrical charge; describing a particle, atom, or object that is electrically neutral and has no positive or negative charge.\",\"s\":\"The noncharged particles passed through the magnetic field without being deflected.\",\"p\":\"non-CHARJD\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.charged\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"physics\",\"olatin\"]},{\"w\":\"noncharging\",\"d\":\"Not in the act of charging or demanding payment; also describing a device, animal, or entity that is not moving forward aggressively or building up an electrical charge.\",\"s\":\"The noncharging policy at the community clinic helped many low-income families get care.\",\"p\":\"non-CHAR-jing\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.charg.ing\",\"ps\":\"adjective\",\"t\":[\"animals\",\"physics\",\"buildings\",\"tools\",\"olatin\"]},{\"w\":\"noncharismatic\",\"d\":\"Not possessing or displaying charisma; describing a person who lacks the natural charm, magnetism, or inspirational quality that attracts and influences others.\",\"s\":\"Despite being noncharismatic, the soft-spoken scientist earned respect through brilliant discoveries.\",\"p\":\"non-kehr-iz-MAT-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.charis.mat.ic\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"noncharitable\",\"d\":\"Not charitable in nature; describing an organization, act, or attitude that is not motivated by generosity, benevolence, or the desire to help others.\",\"s\":\"The noncharitable organization focused on profits rather than helping the community.\",\"p\":\"non-CHEHR-ih-tuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.char.i.ta.ble\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonchauvinist\",\"d\":\"A person who does not hold chauvinistic beliefs; someone who does not display excessive or prejudiced loyalty to their own group, gender, or nationality at the expense of others.\",\"s\":\"He was proud to be a nonchauvinist who treated everyone as an equal.\",\"p\":\"non-SHOH-vih-nist\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.chau.vin.ist\",\"ps\":\"noun\",\"t\":[\"nations\",\"logic\",\"olatin\"]},{\"w\":\"nonchauvinistic\",\"d\":\"Not characterized by chauvinism; describing an attitude, person, or viewpoint that is free from excessive bias, prejudice, or superiority toward one's own group or gender.\",\"s\":\"The nonchauvinistic coach encouraged players of all backgrounds to join the team.\",\"p\":\"non-shoh-vih-NIS-tik\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.chau.vin.is.tic\",\"ps\":\"adjective\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"noncheater\",\"d\":\"A person who does not cheat; someone who consistently plays by the rules and acts with honesty and integrity in games, tests, or relationships.\",\"s\":\"Being a noncheater, she always covered her answers during tests even when tempted.\",\"p\":\"non-CHEE-ter\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"ps\":\"noun\",\"t\":[\"sports\",\"olatin\"]},{\"w\":\"noncheating\",\"d\":\"Not engaging in dishonest or deceptive behavior; acting with complete fairness and integrity according to the established rules.\",\"s\":\"The honor code was designed to encourage noncheating behavior in all students.\",\"p\":\"non-CHEE-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"sy\":\"noncheat.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonchecking\",\"d\":\"Not involving or related to the act of checking, verifying, or using a checking account.\",\"s\":\"The nonchecking account did not allow customers to write paper checks.\",\"p\":\"non-CHEK-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"sy\":\"noncheck.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncheerleader\",\"d\":\"A person who is not a cheerleader and does not participate in organized cheering or spirit activities.\",\"s\":\"As a noncheerleader, she supported the team from the bleachers rather than the sidelines.\",\"p\":\"non-CHEER-lee-der\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"noncheer.lead.er\",\"ps\":\"noun\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"noncheese\",\"d\":\"A food product made to resemble cheese but containing no actual dairy cheese ingredients.\",\"s\":\"The vegan pizza was topped with a noncheese spread made from cashews.\",\"p\":\"non-CHEEZ\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"ps\":\"noun\",\"t\":[\"farming\",\"dishes\",\"olatin\"]},{\"w\":\"nonchef\",\"d\":\"A person who is not a professionally trained or employed chef and does not work in culinary food preparation.\",\"s\":\"As a nonchef, Marcus followed the recipe very carefully to avoid burning dinner.\",\"p\":\"non-SHEF\",\"o\":\"Latin\",\"y\":9,\"bp\":17,\"ps\":\"noun\",\"t\":[\"culinary\",\"character\",\"olatin\"]},{\"w\":\"nonchelated\",\"d\":\"Describing a substance that has not been chemically bound through chelation, meaning metal ions are not trapped within a ring-like molecular structure.\",\"s\":\"The nonchelated iron supplement was less easily absorbed by the body.\",\"p\":\"non-KEE-lay-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"sy\":\"nonchelat.ed\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonchelating\",\"d\":\"Not capable of or involved in chelation, the process by which a molecule forms multiple bonds to a single metal ion.\",\"s\":\"Scientists searched for a nonchelating compound that would not bind to metal ions.\",\"p\":\"non-KEE-lay-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"nonchelat.ing\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonchemical\",\"d\":\"Not involving or derived from chemicals; relating to processes or substances that are natural or free from synthetic chemical compounds.\",\"s\":\"The farmer used nonchemical pest control methods, such as introducing ladybugs to eat aphids.\",\"p\":\"non-KEM-ih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"non.chem.i.cal\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonchemically\",\"d\":\"In a manner that does not involve or rely on chemical processes or synthetic chemical substances.\",\"s\":\"The stain was nonchemically removed using plain hot water and scrubbing.\",\"p\":\"non-KEM-ih-kul-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.chem.i.cal.ly\",\"ps\":\"adverb\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonchemist\",\"d\":\"A person who is not trained or professionally employed as a chemist and lacks specialized knowledge in chemistry.\",\"s\":\"As a nonchemist, she found the lab instructions confusing and asked for help.\",\"p\":\"non-KEM-ist\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.chemist\",\"ps\":\"noun\",\"t\":[\"chemistry\",\"character\",\"logic\",\"olatin\"]},{\"w\":\"nonchemotactic\",\"d\":\"Not exhibiting or relating to chemotaxis, the movement of an organism toward or away from a chemical stimulus.\",\"s\":\"The researchers were surprised to find that the bacteria were nonchemotactic and moved randomly.\",\"p\":\"non-kee-moh-TAK-tik\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"nonchemo.tac.tic\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonchemotherapeutic\",\"d\":\"Not relating to or involving the use of chemical drugs to treat disease, especially cancer.\",\"s\":\"Doctors explored nonchemotherapeutic options like immunotherapy to treat the patient's cancer.\",\"p\":\"non-kee-moh-thair-uh-PYOO-tik\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"nonchemother.a.peu.tic\",\"ps\":\"adjective\",\"t\":[\"disease\",\"pharmacy\",\"chemistry\",\"olatin\"]},{\"w\":\"nonchemotherapy\",\"d\":\"A treatment approach for disease, especially cancer, that does not use chemical drug therapy.\",\"s\":\"The doctor recommended a nonchemotherapy treatment plan to avoid the harsh side effects.\",\"p\":\"non-kee-moh-THAIR-uh-pee\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nonchemother.a.py\",\"ps\":\"noun\",\"t\":[\"body\",\"disease\",\"pharmacy\",\"chemistry\",\"olatin\"]},{\"w\":\"nonchicken\",\"d\":\"Not consisting of or derived from chicken; describing a food or product that contains no chicken ingredients.\",\"s\":\"The restaurant offered a nonchicken protein option for those who preferred beef or tofu.\",\"p\":\"non-CHIK-en\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nonchick.en\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonchild\",\"d\":\"A person who is not a child; an adult or someone who does not fit the classification of a child.\",\"s\":\"The event was designed for adults only, so every nonchild attendee needed an ID.\",\"p\":\"non-CHYLD\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.child\",\"ps\":\"noun\",\"t\":[\"character\",\"kinship\",\"olatin\"]},{\"w\":\"nonchildbearing\",\"d\":\"Not capable of or involved in bearing children; describing a person or period of life not associated with pregnancy or childbirth.\",\"s\":\"The study focused on the health patterns of nonchildbearing women in their thirties.\",\"p\":\"non-CHYLD-bair-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.child.bear.ing\",\"ps\":\"adjective\",\"t\":[\"maps\",\"kinship\",\"olatin\"]},{\"w\":\"nonchildlike\",\"d\":\"Not resembling or characteristic of a child; lacking the innocence, simplicity, or behavior typical of children.\",\"s\":\"Her calm, logical response to the crisis was completely nonchildlike for her age.\",\"p\":\"non-CHYLD-lyk\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.child.like\",\"ps\":\"adjective\",\"t\":[\"law\",\"kinship\",\"olatin\"]},{\"w\":\"nonchilled\",\"d\":\"Not cooled or refrigerated; describing food, drink, or another substance that has not been subjected to chilling.\",\"s\":\"The nonchilled beverages sat at room temperature, which some guests found unrefreshing.\",\"p\":\"non-CHILD\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.chilled\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonchimeric\",\"d\":\"Not chimeric; describing an organism, cell, or molecule that does not contain genetically distinct cells or mixed genetic material from different sources.\",\"s\":\"The gene was confirmed to be nonchimeric, meaning it came from a single source.\",\"p\":\"non-ky-MAIR-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonChinese\",\"d\":\"Not of or relating to China, its people, language, or culture.\",\"s\":\"The festival welcomed nonChinese visitors who were curious about Lunar New Year traditions.\",\"p\":\"non-chy-NEEZ\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nonchi.nese\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonchipping\",\"d\":\"Not prone to chipping or breaking off in small pieces; describing a surface or material that resists chipping.\",\"s\":\"The nonchipping paint on the walls held up beautifully for over a decade.\",\"p\":\"non-CHIP-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"sy\":\"nonchip.ping\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonchlorinated\",\"d\":\"Not treated with or containing chlorine; describing water or chemical compounds that have not been exposed to chlorination.\",\"s\":\"The pool used nonchlorinated water treated with a saltwater system instead.\",\"p\":\"non-KLOR-ih-nay-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nonchlo.ri.nat.ed\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonchlorofluorocarbon\",\"d\":\"A chemical compound that does not contain chlorine, fluorine, and carbon in the combination characteristic of CFCs, which are known to damage the ozone layer.\",\"s\":\"Scientists developed a nonchlorofluorocarbon coolant to protect the ozone layer.\",\"p\":\"non-klor-oh-FLOOR-oh-kar-bon\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"nonchlo.roflu.o.ro.car.bon\",\"ps\":\"noun\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonchloroplast\",\"d\":\"Not relating to or involving the chloroplast, the organelle in plant cells responsible for photosynthesis.\",\"s\":\"The nonchloroplast structures in the cell performed functions unrelated to photosynthesis.\",\"p\":\"non-KLOR-oh-plast\",\"o\":\"Latin\",\"y\":9,\"bp\":24,\"sy\":\"nonchloro.plast\",\"ps\":\"adjective\",\"t\":[\"botany\",\"olatin\"]},{\"w\":\"nonchoked\",\"d\":\"Not obstructed or constricted; describing a passage, flow, or opening that is free and unblocked.\",\"s\":\"The engine ran smoothly because the nonchoked fuel line allowed proper airflow.\",\"p\":\"non-CHOKT\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.choked\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncholera\",\"d\":\"Not caused by or related to cholera; describing a disease or condition that is not associated with the cholera bacterium.\",\"s\":\"The health report confirmed the illness was a noncholera gastrointestinal infection.\",\"p\":\"non-KOL-er-uh\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.c.holera\",\"ps\":\"adjective\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"noncholesterol\",\"d\":\"Not containing or relating to cholesterol; describing foods or substances free from cholesterol.\",\"s\":\"The doctor suggested replacing butter with a noncholesterol spread to improve heart health.\",\"p\":\"non-kuh-LES-ter-ol\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.c.holes.terol\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncholinergic\",\"d\":\"Not involving or activated by acetylcholine; describing nerve fibers or receptors that do not use the neurotransmitter choline to send signals.\",\"s\":\"The researchers discovered that the noncholinergic pathway played a surprising role in the patient's muscle response.\",\"p\":\"non-koh-lin-ER-jik\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.cholin.er.gic\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonchondrodysplastic\",\"d\":\"Not affected by or relating to chondrodysplasia, a group of disorders involving abnormal bone and cartilage development.\",\"s\":\"The doctor confirmed the child's bone growth was nonchondrodysplastic, meaning no cartilage disorder was present.\",\"p\":\"non-kon-droh-dis-PLAS-tik\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.chon.drodys.plas.tic\",\"ps\":\"adjective\",\"t\":[\"body\",\"disease\",\"olatin\"]},{\"w\":\"nonchoral\",\"d\":\"Not relating to or performed by a choir or chorus; describing music or singing that is not choral in nature.\",\"s\":\"The music director arranged a nonchoral performance, featuring only instrumental soloists for the evening.\",\"p\":\"non-KOR-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.choral\",\"ps\":\"adjective\",\"t\":[\"music\",\"olatin\"]},{\"w\":\"nonchord\",\"d\":\"A musical tone or combination of tones that does not belong to the prevailing harmonic chord structure.\",\"s\":\"The composer deliberately used a nonchord tone to create tension before resolving back to the harmony.\",\"p\":\"non-KORD\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.chord\",\"ps\":\"noun\",\"t\":[\"music\",\"olatin\"]},{\"w\":\"nonchordal\",\"d\":\"Not belonging to or derived from a chord; describing musical notes or tones that exist outside the harmonic chord framework.\",\"s\":\"The jazz musician favored nonchordal notes that bent around the melody in unexpected ways.\",\"p\":\"non-KOR-dul\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.chordal\",\"ps\":\"adjective\",\"t\":[\"music\",\"olatin\"]},{\"w\":\"nonchoroidal\",\"d\":\"Not relating to or involving the choroid, the vascular layer of the eye between the retina and the sclera.\",\"s\":\"The eye specialist noted the growth was nonchoroidal, originating outside the choroid layer entirely.\",\"p\":\"non-kuh-ROY-dul\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.choroidal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonchromium\",\"d\":\"Not containing or relating to the metallic element chromium; describing an alloy or material that is free of chromium.\",\"s\":\"The engineer selected a nonchromium alloy to reduce costs without sacrificing too much corrosion resistance.\",\"p\":\"non-KROH-mee-um\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"sy\":\"nonchromi.um\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonchromosomal\",\"d\":\"Not located on or associated with a chromosome; describing genetic material or traits that exist outside of the chromosomal DNA.\",\"s\":\"Scientists found that this particular trait was nonchromosomal, passed on through a different genetic mechanism.\",\"p\":\"non-kroh-muh-SOH-mul\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nonchro.mo.so.mal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonchronic\",\"d\":\"Not chronic; describing a condition or situation that is temporary or short-term rather than persistent and long-lasting.\",\"s\":\"The doctor reassured her that the rash was nonchronic and would clear up within a few weeks.\",\"p\":\"non-KRON-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nonchron.ic\",\"ps\":\"adjective\",\"t\":[\"disease\",\"music\",\"time\",\"olatin\"]},{\"w\":\"nonchronically\",\"d\":\"In a manner that is not chronic; temporarily or for a limited time rather than on a long-term, persistent basis.\",\"s\":\"The patient suffered nonchronically from headaches, meaning they occurred only occasionally and briefly.\",\"p\":\"non-KRON-ik-lee\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nonchron.i.cal.ly\",\"ps\":\"adverb\",\"t\":[\"disease\",\"music\",\"time\",\"olatin\"]},{\"w\":\"nonchronological\",\"d\":\"Not arranged or presented in the order in which events occurred in time; out of sequence.\",\"s\":\"The novel was told in a nonchronological order, jumping between the character's past and present.\",\"p\":\"non-kron-uh-LOJ-ih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"nonchrono.log.i.cal\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nonchronologically\",\"d\":\"In a manner that is not arranged according to the order of time; without following a chronological sequence.\",\"s\":\"The documentary was edited nonchronologically, weaving interviews with flashbacks in a surprising pattern.\",\"p\":\"non-kron-uh-LOJ-ih-kul-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"nonchrono.log.i.cal.ly\",\"ps\":\"adverb\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nonchurch\",\"d\":\"Not affiliated with, belonging to, or associated with a church or organized religious institution.\",\"s\":\"The wedding took place in a nonchurch setting, held outdoors in a flower-filled meadow.\",\"p\":\"non-CHURCH\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"ps\":\"adjective\",\"t\":[\"religion\",\"olatin\"]},{\"w\":\"nonchurchgoer\",\"d\":\"A person who does not attend church services or belong to a religious congregation.\",\"s\":\"As a nonchurchgoer, she still celebrated holidays with deep personal traditions of her own.\",\"p\":\"non-CHURCH-goh-er\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nonchurch.go.er\",\"ps\":\"noun\",\"t\":[\"religion\",\"olatin\"]},{\"w\":\"nonchurchly\",\"d\":\"Not related to or characteristic of a church or religious institution; lacking a church-like quality.\",\"s\":\"The ceremony had a nonchurchly feel, with folk music and nature-inspired decorations throughout.\",\"p\":\"non-CHURCH-lee\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"sy\":\"nonchurch.ly\",\"ps\":\"adjective\",\"t\":[\"religion\",\"olatin\"]},{\"w\":\"nonciliate\",\"d\":\"Not having cilia; describing an organism or cell that lacks the tiny hair-like structures used for movement.\",\"s\":\"The biology student learned that nonciliate cells lack the tiny hair-like structures used for movement.\",\"p\":\"non-SIL-ee-it\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.cil.i.ate\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonciliated\",\"d\":\"Lacking cilia; describing cells or organisms that do not possess tiny hair-like projections on their surface.\",\"s\":\"The tissue sample showed nonciliated cells lining a portion of the airway where cilia would normally be.\",\"p\":\"non-SIL-ee-ay-tid\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.cil.i.at.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncinematic\",\"d\":\"Not related to or characteristic of cinema or film; lacking the qualities associated with movies.\",\"s\":\"Critics described the live theater production as a deliberately noncinematic experience meant to feel raw and immediate.\",\"p\":\"non-sin-uh-MAT-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"noncin.e.mat.ic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncinematographic\",\"d\":\"Not relating to the art or technique of cinematography; lacking the visual or technical qualities of filmmaking.\",\"s\":\"The art installation used a noncinematographic visual style, relying on still images rather than moving footage.\",\"p\":\"non-sin-uh-mat-uh-GRAF-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"noncin.e.mato.graph.ic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncircadian\",\"d\":\"Not following or related to the natural 24-hour biological cycle of living organisms; not governed by a daily rhythm.\",\"s\":\"The scientist studied noncircadian sleep patterns in people who live in constant artificial light.\",\"p\":\"non-sur-KAY-dee-un\",\"o\":\"Latin\",\"y\":8,\"bp\":39,\"sy\":\"non.cir.ca.di.an\",\"ps\":\"adjective\",\"t\":[\"music\",\"time\",\"olatin\"]},{\"w\":\"noncircular\",\"d\":\"Not having the shape of a circle; not round or curved in a perfectly circular way.\",\"s\":\"The architect designed a noncircular dome that resembled an elongated egg from the outside.\",\"p\":\"non-SUR-kyuh-ler\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.cir.cu.lar\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"noncirculating\",\"d\":\"Not moving or flowing through a system; describing something, such as library materials, that is not available for distribution or loan.\",\"s\":\"The library kept its noncirculating reference books behind the desk so they could never be checked out.\",\"p\":\"non-SUR-kyuh-lay-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.cir.cu.lat.ing\",\"ps\":\"adjective\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"noncirculative\",\"d\":\"Not having the property of circulating or moving through a system; lacking the tendency to flow or spread.\",\"s\":\"The plant virus spread through a noncirculative mechanism, staying only in the insect's mouthparts.\",\"p\":\"non-SUR-kyuh-lay-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.cir.cu.la.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncircumferential\",\"d\":\"Not relating to or measured along the circumference; not following or encircling the outer boundary of a round shape.\",\"s\":\"The crack in the pipe was noncircumferential, running lengthwise rather than wrapping around the pipe.\",\"p\":\"non-sur-kum-fuh-REN-shul\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.cir.cum.fer.en.tial\",\"ps\":\"adjective\",\"t\":[\"maps\",\"numbers\",\"olatin\"]},{\"w\":\"noncircumstantial\",\"d\":\"Not based on or consisting of circumstantial evidence; not dependent on indirect or incidental details to establish a conclusion.\",\"s\":\"The lawyer argued that the evidence was noncircumstantial—a direct eyewitness account rather than inference.\",\"p\":\"non-sur-kum-STAN-shul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.cir.cum.stan.tial\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"noncircumventable\",\"d\":\"Impossible to get around or bypass; describing a rule, obstacle, or system that cannot be avoided or outwitted.\",\"s\":\"The new security system was marketed as noncircumventable, with no known way to bypass it.\",\"p\":\"non-sur-kum-VEN-tuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.cir.cum.ventable\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncircus\",\"d\":\"Not related to or characteristic of a circus; lacking the entertainment, spectacle, or performers typically found in a circus.\",\"s\":\"The performer's noncircus background made her acrobatic street show feel fresh and unconventional.\",\"p\":\"non-SUR-kus\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.cir.cus\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncitizen\",\"d\":\"a person who is not a legal member of the country where they live\",\"s\":\"As a noncitizen, he needed a special work permit before he could legally accept the job offer.\",\"p\":\"non-SIT-ih-zen\",\"o\":\"Latin\",\"y\":7,\"bp\":30,\"sy\":\"nonci.t.i.zen\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"noncitizenship\",\"d\":\"The state or condition of not being a citizen of a particular country; the status of a person who lacks the rights and responsibilities of citizenship.\",\"s\":\"Her noncitizenship status meant she could not vote in the national election, though she paid taxes.\",\"p\":\"non-SIT-ih-zen-ship\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"nonci.t.i.zen.ship\",\"ps\":\"noun\",\"t\":[\"nations\",\"politics\",\"olatin\"]},{\"w\":\"noncitric\",\"d\":\"Not containing or derived from citric acid; not related to the acidic compound found in citrus fruits.\",\"s\":\"The food scientist developed a noncitric preservative that kept fruit fresh without any lemon or lime acids.\",\"p\":\"non-SIT-rik\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"ps\":\"adjective\",\"t\":[\"chemistry\",\"spices\",\"olatin\"]},{\"w\":\"noncitrus\",\"d\":\"Not belonging to or derived from the citrus family of fruits; describing fruits or flavors that lack the tartness of oranges, lemons, or limes.\",\"s\":\"She preferred noncitrus fruits like apples and peaches because oranges irritated her stomach.\",\"p\":\"non-SIT-rus\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"ps\":\"adjective\",\"t\":[\"spices\",\"kinship\",\"olatin\"]},{\"w\":\"noncity\",\"d\":\"Not relating to or characteristic of a city; describing an area or lifestyle that is rural or suburban rather than urban.\",\"s\":\"They moved to a noncity area, trading skyscrapers and traffic for open fields and quiet roads.\",\"p\":\"non-SIT-ee\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"nonci.ty\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncivil\",\"d\":\"Not relating to civil matters or ordinary citizens; outside the realm of civilian life or civil law.\",\"s\":\"The dispute fell under noncivil jurisdiction, meaning a military court would handle the case instead.\",\"p\":\"non-SIV-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.civ.il\",\"ps\":\"adjective\",\"t\":[\"law\",\"politics\",\"olatin\"]},{\"w\":\"noncivilized\",\"d\":\"not having a high state of culture and social development\",\"s\":\"Early explorers mistakenly labeled Indigenous societies as noncivilized, failing to recognize their rich cultures.\",\"p\":\"non-SIV-uh-lyzd\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.civ.i.lized\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonclaim\",\"d\":\"The absence of a claim; a situation in which no formal demand, assertion of right, or request for compensation is made.\",\"s\":\"The insurance company recorded a nonclaim year for the policyholder, which earned her a discount.\",\"p\":\"non-KLAYM\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.claim\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonclaimed\",\"d\":\"Not having been claimed; describing property, a prize, or a right that no one has formally requested or asserted ownership over.\",\"s\":\"The nonclaimed luggage sat on the airport carousel for hours before staff removed it to storage.\",\"p\":\"non-KLAYMD\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.claimed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonclarified\",\"d\":\"Not made clear or pure; describing a substance, such as butter or a liquid, that has not been processed to remove impurities.\",\"s\":\"The nonclarified butter still contained milk solids, giving it a richer, creamier taste than ghee.\",\"p\":\"non-KLAIR-uh-fyd\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"nonclar.i.fied\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonclassical\",\"d\":\"not classical\",\"s\":\"The music teacher introduced her students to nonclassical genres like jazz and blues to broaden their horizons.\",\"p\":\"non-KLAS-ih-kul\",\"o\":\"Latin\",\"y\":7,\"bp\":38,\"sy\":\"non.clas.si.cal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonclassified\",\"d\":\"Not designated as secret or restricted; describing information or documents that are available to the general public without special clearance.\",\"s\":\"The government released the nonclassified portions of the report so the public could read them freely.\",\"p\":\"non-KLAS-uh-fyd\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.clas.si.fied\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonclassifying\",\"d\":\"Not sorting, categorizing, or arranging things into specific groups or classes.\",\"s\":\"The nonclassifying system treated all students equally without sorting them into ability groups.\",\"p\":\"non-KLAS-uh-fy-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.clas.si.fy.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonclassroom\",\"d\":\"Not taking place in or associated with a traditional classroom setting; describing education or activities that occur outside formal school rooms.\",\"s\":\"The students enjoyed nonclassroom learning by studying plants in the garden outside.\",\"p\":\"non-KLAS-room\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.class.room\",\"ps\":\"adjective\",\"t\":[\"festivals\",\"olatin\"]},{\"w\":\"nonclausal\",\"d\":\"Not relating to or consisting of a clause; describing a grammatical structure or legal element that does not take the form of a clause.\",\"s\":\"The lawyer noted the nonclausal nature of the simple agreement, which had no conditional phrases.\",\"p\":\"non-KLAW-zul\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.clausal\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"law\",\"wordwords\",\"olatin\"]},{\"w\":\"nonclay\",\"d\":\"Not consisting of or relating to clay; describing soil or material that does not contain the fine-grained mineral particles typical of clay.\",\"s\":\"The scientist tested the nonclay soil sample to see how well it would drain after heavy rain.\",\"p\":\"non-KLAY\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.clay\",\"ps\":\"adjective\",\"t\":[\"minerals\",\"physics\",\"olatin\"]},{\"w\":\"nonclayey\",\"d\":\"Not having the sticky, dense, or fine-grained properties of clay; describing soil or material that lacks clay-like characteristics.\",\"s\":\"The gardener preferred the nonclayey soil because it was loose and easy to dig through.\",\"p\":\"non-KLAY-ee\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.clayey\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonclean\",\"d\":\"Not clean; in a state of dirtiness, impurity, or contamination.\",\"s\":\"The mechanic's nonclean hands left grease marks on everything he touched in the kitchen.\",\"p\":\"non-KLEEN\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.clean\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncleanable\",\"d\":\"Not able to be cleaned or made free of dirt and impurities; describing a surface or material that resists cleaning efforts.\",\"s\":\"The permanent marker stain on the whiteboard was noncleanable, no matter how hard they scrubbed.\",\"p\":\"non-KLEE-nuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.clean.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonclear\",\"d\":\"Not clear or transparent; describing something that is murky, vague, or difficult to see through or understand.\",\"s\":\"The instructions were nonclear, leaving every student confused about what to do next.\",\"p\":\"non-KLEER\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.clear\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncleared\",\"d\":\"Not having been cleared, approved, or made free of obstruction; describing a path, person, or item that has not received official clearance.\",\"s\":\"The noncleared debris on the road made it impossible for cars to pass safely after the storm.\",\"p\":\"non-KLEERD\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.cleared\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncleaved\",\"d\":\"Not split, divided, or cut apart; describing a substance or structure that has not been cleaved into separate parts.\",\"s\":\"The noncleaved protein molecule remained whole throughout the entire experiment.\",\"p\":\"non-KLEEVD\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.cleaved\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"noncleaving\",\"d\":\"Not splitting or dividing; describing a process or substance that does not break apart into separate pieces.\",\"s\":\"The noncleaving enzyme left the DNA strand completely intact during the lab procedure.\",\"p\":\"non-KLEE-ving\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.cleav.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncleft\",\"d\":\"Not divided or split; describing a structure, such as a palate or chin, that does not have a cleft or gap.\",\"s\":\"The geologist noted the noncleft rock face was perfectly smooth without any cracks or splits.\",\"p\":\"non-KLEFT\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.cleft\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonclergy\",\"d\":\"People who are not members of the clergy; those who do not hold an ordained religious office or title within a church.\",\"s\":\"The wedding was officiated by a nonclergy community leader chosen by the couple.\",\"p\":\"non-KLUR-jee\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.cler.gy\",\"ps\":\"noun\",\"t\":[\"religion\",\"olatin\"]},{\"w\":\"nonclergyman\",\"d\":\"A person who is not a member of the clergy; someone who does not hold an ordained religious office or position.\",\"s\":\"The ceremony was led by a nonclergyman who had studied philosophy rather than theology.\",\"p\":\"non-KLER-jee-man\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.cler.gy.man\",\"ps\":\"noun\",\"t\":[\"religion\",\"character\",\"olatin\"]},{\"w\":\"nonclient\",\"d\":\"A person who is not a client; someone who has not entered into a professional or business relationship with a service provider.\",\"s\":\"As a nonclient visitor, she could browse the salon but not receive any services.\",\"p\":\"non-KLY-ent\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.client\",\"ps\":\"noun\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nonclimatological\",\"d\":\"Not related to or concerned with climatology; describing something that does not involve the scientific study of climate patterns.\",\"s\":\"The researchers sought nonclimatological explanations for why the plants were dying so quickly.\",\"p\":\"non-kly-muh-tuh-LAH-jih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":33,\"sy\":\"non.cli.ma.to.log.i.cal\",\"ps\":\"adjective\",\"t\":[\"weather\",\"olatin\"]},{\"w\":\"noncling\",\"d\":\"Describing a material or fabric that does not stick to or adhere to surfaces, including skin or other fabrics.\",\"s\":\"She bought a noncling fabric for her curtains so they wouldn't stick to the window in humid weather.\",\"p\":\"non-KLING\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.cling\",\"ps\":\"adjective\",\"t\":[\"body\",\"fabrics\",\"olatin\"]},{\"w\":\"nonclipped\",\"d\":\"Not having been cut, trimmed, or clipped; remaining in its original, uncut state.\",\"s\":\"The dog's nonclipped fur was long and shaggy by the end of the winter months.\",\"p\":\"non-KLIPT\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.clipped\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonclogging\",\"d\":\"Designed or able to resist blocking or clogging; describing a system or material that allows free flow without obstruction.\",\"s\":\"The plumber recommended a nonclogging drain filter that would keep pipes clear all year.\",\"p\":\"non-KLOG-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.clog.ging\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonclonal\",\"d\":\"Not derived from a single common ancestor cell or organism; describing cells or organisms that are genetically diverse rather than identical copies.\",\"s\":\"The nonclonal cell population showed surprising genetic diversity under the microscope.\",\"p\":\"non-KLOH-nul\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.clon.al\",\"ps\":\"adjective\",\"t\":[\"kinship\",\"olatin\"]},{\"w\":\"nonclonally\",\"d\":\"In a manner that is not clonal; describing a process or characteristic that does not involve reproduction from a single genetic source.\",\"s\":\"The bacteria reproduced nonclonally, producing offspring with varied genetic traits.\",\"p\":\"non-KLOH-nul-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"non.clon.al.ly\",\"ps\":\"adverb\",\"t\":[\"olatin\"]},{\"w\":\"noncloned\",\"d\":\"Not produced by cloning; describing an organism or cell that was not created as a genetic duplicate of another.\",\"s\":\"The scientist was excited to study the noncloned organism because it had a completely unique genome.\",\"p\":\"non-KLOHND\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.cloned\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonclonogenic\",\"d\":\"Not capable of forming a clone or colony of genetically identical cells; describing cells that cannot reproduce in that way.\",\"s\":\"The treatment targeted nonclonogenic cancer cells that were unable to form new tumor colonies.\",\"p\":\"non-kloh-nuh-JEN-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.clono.genic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonclonotypic\",\"d\":\"Not characteristic of or specific to a single clone type; describing something that involves multiple distinct clonal varieties.\",\"s\":\"The nonclonotypic immune cells responded to a broad range of threats rather than one specific target.\",\"p\":\"non-kloh-nuh-TIP-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.clono.typ.ic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonclosed\",\"d\":\"Not closed or sealed; describing a set, system, or structure that does not form a complete, self-contained loop or boundary.\",\"s\":\"The nonclosed circuit allowed electricity to escape before reaching the light bulb.\",\"p\":\"non-KLOHZD\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.closed\",\"ps\":\"adjective\",\"t\":[\"maps\",\"olatin\"]},{\"w\":\"nonclosing\",\"d\":\"Not closing or coming to an end; describing something that remains open or ongoing without a conclusion.\",\"s\":\"The nonclosing store stayed open around the clock to serve customers at any hour.\",\"p\":\"non-KLOH-zing\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.clos.ing\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonclothing\",\"d\":\"Items or products that are not clothing; referring to goods that do not include garments or wearable textiles.\",\"s\":\"The charity accepted nonclothing donations such as books, toys, and household items.\",\"p\":\"non-KLOH-thing\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.cloth.ing\",\"ps\":\"noun\",\"t\":[\"fabrics\",\"olatin\"]},{\"w\":\"nonclotting\",\"d\":\"Not capable of forming a clot; describing blood or a substance that does not coagulate or thicken into a solid mass.\",\"s\":\"The scientist studied nonclotting blood samples to understand rare bleeding disorders.\",\"p\":\"non-KLOT-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.clot.ting\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"noncloudy\",\"d\":\"Not cloudy; describing a sky, liquid, or substance that is clear and free of cloudiness or turbidity.\",\"s\":\"The noncloudy sky made it perfect for stargazing from the backyard that night.\",\"p\":\"non-KLOW-dee\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.cloudy\",\"ps\":\"adjective\",\"t\":[\"weather\",\"olatin\"]},{\"w\":\"noncloying\",\"d\":\"Not overly sweet or sentimental; describing a taste, smell, or experience that does not become unpleasant through excess.\",\"s\":\"The chef created a noncloying dessert that was sweet enough to enjoy without feeling sick afterward.\",\"p\":\"non-KLOY-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.cloy.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonclub\",\"d\":\"Not affiliated with or belonging to a club or organized membership group; describing a person or thing outside such an association.\",\"s\":\"As a nonclub member, he had to pay a higher entry fee to use the gym facilities.\",\"p\":\"non-KLUB\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.club\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonclusterable\",\"d\":\"Not able to be grouped into clusters; describing data points or elements that resist being organized into distinct groups or categories.\",\"s\":\"The scattered data points were nonclusterable, making it impossible to find any meaningful patterns.\",\"p\":\"non-KLUS-ter-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.clus.ter.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncoached\",\"d\":\"Not having received coaching or formal instruction; describing an athlete, performer, or student who has not been guided by a coach.\",\"s\":\"The noncoached athlete improved her technique entirely through self-study and online videos.\",\"p\":\"non-KOHCHT\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.coached\",\"ps\":\"adjective\",\"t\":[\"sports\",\"vehicles\",\"olatin\"]},{\"w\":\"noncoaching\",\"d\":\"Not involving or related to coaching; describing a role, activity, or position that does not include instructing or training others.\",\"s\":\"The mentor took on a noncoaching role at the school, focusing only on student counseling.\",\"p\":\"non-KOH-ching\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.coach.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncoal\",\"d\":\"Not derived from or related to coal; describing energy sources, industries, or materials that do not involve coal.\",\"s\":\"The power plant switched to noncoal energy sources like wind and solar to reduce pollution.\",\"p\":\"non-KOHL\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.coal\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"noncoalitional\",\"d\":\"Not based on or involving a coalition; describing a political or social arrangement that does not rely on the merging of separate groups.\",\"s\":\"The party ran a noncoalitional campaign, refusing to partner with any other political group.\",\"p\":\"non-koh-uh-LISH-uh-nul\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.coali.tion.al\",\"ps\":\"adjective\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"noncoastal\",\"d\":\"Not located on or near a coast; describing areas, communities, or features that are inland and far from the sea or ocean.\",\"s\":\"Children growing up in noncoastal regions often see the ocean for the first time on a school trip.\",\"p\":\"non-KOH-stul\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.coastal\",\"ps\":\"adjective\",\"t\":[\"waterways\",\"olatin\"]},{\"w\":\"noncoated\",\"d\":\"Not covered with a coating, layer, or finish; describing a surface or material that has been left bare without any protective or decorative covering.\",\"s\":\"The noncoated wood absorbed the rain immediately because it had no protective sealant on it.\",\"p\":\"non-KOH-tid\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.coat.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncoaxial\",\"d\":\"Not sharing the same axis or central line; describing components or structures whose axes do not align or coincide.\",\"s\":\"The engineer had to fix the noncoaxial cables because they weren't properly aligned along the same axis.\",\"p\":\"non-koh-AK-see-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.coax.i.al\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncochlear\",\"d\":\"Not relating to or involving the cochlea, the spiral-shaped organ in the inner ear responsible for converting sound into nerve signals.\",\"s\":\"The audiologist explained that the patient's hearing loss was noncochlear, meaning the inner ear was fine.\",\"p\":\"non-KOK-lee-er\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"sy\":\"non.cochlear\",\"ps\":\"adjective\",\"t\":[\"body\",\"music\",\"olatin\"]},{\"w\":\"noncocoa\",\"d\":\"Not containing or derived from cocoa; describing foods, beverages, or products that do not include cocoa as an ingredient.\",\"s\":\"The barista labeled the drink 'noncocoa' to warn customers it contained no chocolate whatsoever.\",\"p\":\"non-KOH-koh\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.co.coa\",\"ps\":\"adjective\",\"t\":[\"dishes\",\"olatin\"]},{\"w\":\"noncoded\",\"d\":\"Not encoded or organized according to a code; describing information, sequences, or instructions that lack a specific coded structure.\",\"s\":\"The researcher found noncoded regions of DNA that were once dismissed as junk but turned out to be important.\",\"p\":\"non-KOH-did\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.cod.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncoder\",\"d\":\"A person who does not write computer code; also used in genetics to describe a DNA sequence that does not encode a protein.\",\"s\":\"As a noncoder, she relied on drag-and-drop tools to build her website without writing a single line of script.\",\"p\":\"non-KOH-der\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.coder\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"noncodified\",\"d\":\"Not arranged or written into a formal code or systematic set of rules; describing laws, customs, or practices that remain unwritten or informal.\",\"s\":\"Many social rules remain noncodified, meaning they exist as unwritten customs rather than official laws.\",\"p\":\"non-KOD-ih-fyd\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.cod.i.fied\",\"ps\":\"adjective\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"noncoerced\",\"d\":\"Not forced or pressured into doing something; describing an action or decision made freely without threats or compulsion.\",\"s\":\"The judge confirmed that the suspect's confession was noncoerced and given entirely of his own free will.\",\"p\":\"non-koh-ERST\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.co.erced\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncoercion\",\"d\":\"The absence of force, pressure, or threats used to make someone act against their will; a principle of allowing free and voluntary action.\",\"s\":\"The treaty was built on a principle of noncoercion, ensuring no nation could be forced to sign against its will.\",\"p\":\"non-koh-ER-zhun\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.co.er.cion\",\"ps\":\"noun\",\"t\":[\"physics\",\"logic\",\"olatin\"]},{\"w\":\"noncoercive\",\"d\":\"Not using or involving force, intimidation, or pressure; describing an approach or method that relies on voluntary cooperation rather than compulsion.\",\"s\":\"The therapist used a noncoercive approach, gently encouraging patients rather than pressuring them to change.\",\"p\":\"non-koh-ER-siv\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"non.co.er.cive\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"noncognate\",\"d\":\"Not related in origin or meaning; describing words, languages, or concepts that do not share a common linguistic or ancestral root.\",\"s\":\"Linguists noted that the similar-sounding words in the two languages were actually noncognate and unrelated in origin.\",\"p\":\"non-KOG-nayt\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"noncog.nate\",\"ps\":\"adjective\",\"t\":[\"botany\",\"wordwords\",\"olatin\"]},{\"w\":\"noncognition\",\"d\":\"The absence of conscious thought, perception, or mental processing; a state or process that does not involve cognitive activity.\",\"s\":\"Philosophers debated whether emotion operates in a state of noncognition, completely separate from rational thought.\",\"p\":\"non-kog-NISH-un\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"noncog.ni.tion\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"noncognitive\",\"d\":\"Not related to conscious thinking or intellectual processes; describing skills, traits, or behaviors such as emotional regulation or social skills that go beyond pure reasoning.\",\"s\":\"Grit and perseverance are noncognitive skills that can be just as important as raw intelligence in school.\",\"p\":\"non-KOG-nih-tiv\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"noncog.ni.tive\",\"ps\":\"adjective\",\"t\":[\"emotions\",\"logic\",\"olatin\"]},{\"w\":\"noncognitivism\",\"d\":\"A philosophical theory holding that moral statements do not express factual claims and cannot be judged as true or false, but instead express emotions or attitudes.\",\"s\":\"Under noncognitivism, statements like 'stealing is wrong' express feelings rather than facts that can be true or false.\",\"p\":\"non-KOG-nih-tiv-iz-um\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"noncog.ni.tivism\",\"ps\":\"noun\",\"t\":[\"law\",\"emotions\",\"logic\",\"olatin\"]},{\"w\":\"noncognitivist\",\"d\":\"A person who holds the philosophical view of noncognitivism, believing that moral statements express feelings or commands rather than objective truths.\",\"s\":\"The noncognitivist philosopher argued that moral language is more like cheering than making factual claims.\",\"p\":\"non-KOG-nih-tiv-ist\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"noncog.ni.tivist\",\"ps\":\"noun\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"noncognizant\",\"d\":\"Not aware of or informed about something; lacking knowledge or consciousness of a particular fact, situation, or circumstance.\",\"s\":\"She was noncognizant of the new school rule and accidentally broke it on her first day back.\",\"p\":\"non-KOG-nih-zunt\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"nonc.og.nizant\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"noncognoscenti\",\"d\":\"People who are not experts or connoisseurs in a particular field; those who lack specialized knowledge or refined taste in a subject.\",\"s\":\"The art show was designed for the noncognoscenti, welcoming visitors who knew nothing about modern sculpture.\",\"p\":\"non-kog-nuh-SHEN-tee\",\"o\":\"Latin\",\"y\":9,\"bp\":24,\"sy\":\"noncognoscen.ti\",\"ps\":\"noun\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"noncohesive\",\"d\":\"Not holding together as a unified whole; lacking the tendency to stick or bond together in a consistent or organized way.\",\"s\":\"The essay felt noncohesive because each paragraph introduced a completely different idea without any connection.\",\"p\":\"non-koh-HEE-siv\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"non.co.he.sive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncoincidence\",\"d\":\"The state of two or more things not occurring at the same time or place, or not matching up in a meaningful way.\",\"s\":\"Scientists pointed to the noncoincidence of the two events as proof that one must have caused the other.\",\"p\":\"non-koh-IN-sih-dens\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.co.in.ci.dence\",\"ps\":\"noun\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"noncoincident\",\"d\":\"Not occupying the same position, time, or space simultaneously; describing events or things that do not coincide with one another.\",\"s\":\"The two timelines were noncoincident, meaning the historical events happened at completely different moments.\",\"p\":\"non-koh-IN-sih-dent\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.co.in.ci.dent\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"noncoincidental\",\"d\":\"Not happening by chance or accident; describing a relationship or event that is deliberately planned or structurally determined rather than random.\",\"s\":\"The matching fingerprints were noncoincidental — the detective knew the same person had touched both objects.\",\"p\":\"non-koh-in-sih-DEN-tul\",\"o\":\"Latin\",\"y\":9,\"bp\":31,\"sy\":\"non.co.in.ci.den.tal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncoincidently\",\"d\":\"In a manner that is not by chance; deliberately or by design rather than by accident or random occurrence.\",\"s\":\"Noncoincidently, the two rivals both signed up for the same competition on the very same day.\",\"p\":\"non-koh-IN-sih-dent-lee\",\"o\":\"Latin\",\"y\":9,\"bp\":31,\"sy\":\"non.co.in.ci.dent.ly\",\"ps\":\"adverb\",\"t\":[\"olatin\"]},{\"w\":\"noncoinciding\",\"d\":\"Not occurring at the same time or place; referring to events, objects, or points that fail to overlap or correspond with each other.\",\"s\":\"The teacher used two noncoinciding circles on the board to show students the concept of separate sets.\",\"p\":\"non-koh-in-SY-ding\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.co.in.cid.ing\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"noncoking\",\"d\":\"Describing a type of coal or fuel that does not form coke when heated; unable to undergo the coking process that produces hard carbon residue.\",\"s\":\"Engineers selected a noncoking fuel for the furnace so it would burn cleanly without leaving carbon deposits.\",\"p\":\"non-KOH-king\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.cok.ing\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"noncola\",\"d\":\"A soft drink or beverage that does not contain cola flavoring or cola nut extract; any carbonated drink outside the cola category.\",\"s\":\"She ordered a noncola soda because she didn't want caffeine but still craved a fizzy drink.\",\"p\":\"non-KOH-luh\",\"o\":\"Latin\",\"y\":9,\"bp\":20,\"sy\":\"non.co.la\",\"ps\":\"noun\",\"t\":[\"dishes\",\"olatin\"]},{\"w\":\"noncold\",\"d\":\"Not cold in temperature; describing a substance, environment, or condition that does not have a low or chilly temperature.\",\"s\":\"The patient's noncold symptoms pointed to allergies rather than a viral infection.\",\"p\":\"non-KOHLD\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.cold\",\"ps\":\"adjective\",\"t\":[\"ecology\",\"olatin\"]},{\"w\":\"noncollagenous\",\"d\":\"Not composed of or relating to collagen; describing proteins, tissues, or substances that do not contain collagen as a structural component.\",\"s\":\"Researchers studied the noncollagenous proteins in bone to understand how minerals bind to tissue.\",\"p\":\"non-kuh-LAJ-uh-nus\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.col.lage.nous\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"noncollapsible\",\"d\":\"not capable of collapsing\",\"s\":\"The emergency shelter was built from noncollapsible panels so it could withstand strong winds and heavy snow.\",\"p\":\"non-kuh-LAP-sih-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.col.lapsi.ble\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncollateralized\",\"d\":\"Describing a loan or financial agreement that is not secured by collateral; issued without any asset pledged as a guarantee of repayment.\",\"s\":\"The small business owner obtained a noncollateralized loan, meaning she didn't have to risk her home as security.\",\"p\":\"non-kuh-LAT-er-ul-yzd\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.col.lat.er.al.ized\",\"ps\":\"adjective\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"noncollecting\",\"d\":\"Not engaged in the act of gathering or accumulating items; describing a person or organization that does not collect objects, data, or funds.\",\"s\":\"The noncollecting museum visitor simply enjoyed the art rather than snapping photos of every piece.\",\"p\":\"non-kuh-LEK-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.col.lect.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncollectivist\",\"d\":\"A person who does not support or adhere to collectivism; one who opposes the idea of group ownership or communal control over resources and decisions.\",\"s\":\"The noncollectivist economist believed that individuals, not groups, should control their own resources.\",\"p\":\"non-kuh-LEK-tih-vist\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.col.lec.tivist\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"noncollectivized\",\"d\":\"Not organized under a system of collective ownership or control; describing an economy, farm, or enterprise that remains privately owned rather than state-managed.\",\"s\":\"In noncollectivized farming communities, families owned and managed their own land independently.\",\"p\":\"non-kuh-LEK-tih-vyzd\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.col.lec.tivized\",\"ps\":\"adjective\",\"t\":[\"farming\",\"economy\",\"olatin\"]},{\"w\":\"noncollector\",\"d\":\"A person who does not collect or accumulate objects, data, or items of any particular kind; someone with no collecting hobby or practice.\",\"s\":\"As a noncollector, he threw away his old baseball cards without realizing they were worth hundreds of dollars.\",\"p\":\"non-kuh-LEK-ter\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.col.lec.tor\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"noncollegial\",\"d\":\"Not characterized by cooperation, mutual respect, or shared responsibility among colleagues; lacking the cooperative spirit typical of a collegial environment.\",\"s\":\"Her noncollegial attitude in meetings made it hard for the team to collaborate or share ideas freely.\",\"p\":\"non-kuh-LEE-jee-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.col.le.gial\",\"ps\":\"adjective\",\"t\":[\"ecology\",\"character\",\"olatin\"]},{\"w\":\"noncollegiate\",\"d\":\"Not associated with, belonging to, or characteristic of a college or university; describing a person, program, or activity outside the college setting.\",\"s\":\"The noncollegiate athlete trained just as hard as varsity players, even though he wasn't on a university team.\",\"p\":\"non-kuh-LEE-jee-it\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.col.le.giate\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncolliding\",\"d\":\"Not crashing into or striking one another; describing objects or particles that travel paths that do not intersect or impact each other.\",\"s\":\"Scientists designed noncolliding particle beams to study each stream separately without interference.\",\"p\":\"non-kuh-LY-ding\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.col.lid.ing\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"noncollimated\",\"d\":\"Describing light, radiation, or a beam that has not been aligned into parallel rays; scattered or divergent rather than focused into a precise column.\",\"s\":\"The noncollimated laser beam spread out in all directions instead of forming a tight, focused ray.\",\"p\":\"non-KOL-ih-may-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.col.li.mat.ed\",\"ps\":\"adjective\",\"t\":[\"physics\",\"buildings\",\"olatin\"]},{\"w\":\"noncollinear\",\"d\":\"Not lying on the same straight line; describing three or more points that cannot all be connected by a single straight line.\",\"s\":\"The three noncollinear points on the graph could be connected to form a triangle rather than a straight line.\",\"p\":\"non-kuh-LIN-ee-er\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.collinear\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncollision\",\"d\":\"The absence of a collision or crash; a situation in which two or more objects pass near each other without making contact or impact.\",\"s\":\"The traffic engineers celebrated a noncollision record after the new roundabout was installed at the busy intersection.\",\"p\":\"non-kuh-LIH-zhun\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.col.li.sion\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"noncolloidal\",\"d\":\"Not having the properties of a colloid; describing a substance or mixture in which particles do not remain evenly dispersed throughout another medium.\",\"s\":\"The chemist separated the noncolloidal particles from the mixture because they were too large to remain suspended.\",\"p\":\"non-kuh-LOY-dul\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.col.loidal\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"noncolonial\",\"d\":\"Not related to, characteristic of, or resulting from colonialism; describing a nation, culture, or policy that is free from colonial influence or domination.\",\"s\":\"Historians praised the noncolonial approach of the treaty, which respected each nation's full independence.\",\"p\":\"non-kuh-LOH-nee-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.colo.nial\",\"ps\":\"adjective\",\"t\":[\"nations\",\"politics\",\"olatin\"]},{\"w\":\"noncolonic\",\"d\":\"Not relating to or involving the colon; describing a medical condition, procedure, or substance that does not affect or originate in the large intestine.\",\"s\":\"The gastroenterologist determined the patient's pain was noncolonic, originating outside the large intestine.\",\"p\":\"non-kuh-LON-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.colonic\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"noncolor\",\"d\":\"A neutral tone such as black, white, or gray that is not considered a true color in the traditional color spectrum; an achromatic shade.\",\"s\":\"The designer chose a noncolor like white for the walls to keep the room looking clean and simple.\",\"p\":\"nah-NKUH-ler\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"naa.nkah.ler\",\"ps\":\"noun\",\"t\":[\"festivals\",\"colors\",\"olatin\"]},{\"w\":\"noncolored\",\"d\":\"Having no added color or dye; remaining in a natural, uncolored state without any pigmentation or tinting applied.\",\"s\":\"The artist used noncolored pencils to sketch the outline before adding any paint.\",\"p\":\"non-KUL-erd\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.col.ored\",\"ps\":\"adjective\",\"t\":[\"painting\",\"colors\",\"olatin\"]},{\"w\":\"noncolorfast\",\"d\":\"Describing a dye or fabric whose color is not resistant to fading or washing; prone to losing or bleeding its color when exposed to water or light.\",\"s\":\"The cheap shirt was noncolorfast and turned the whole wash pink after one cycle.\",\"p\":\"non-KUL-er-fast\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.col.or.fast\",\"ps\":\"adjective\",\"t\":[\"fabrics\",\"colors\",\"olatin\"]},{\"w\":\"noncolorful\",\"d\":\"Lacking bright, vivid, or varied colors; dull, drab, or visually uninteresting in terms of color or visual excitement.\",\"s\":\"The winter landscape was noncolorful, covered only in shades of gray and white.\",\"p\":\"non-KUL-er-ful\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.col.or.ful\",\"ps\":\"adjective\",\"t\":[\"colors\",\"olatin\"]},{\"w\":\"noncolumnar\",\"d\":\"Not shaped like or arranged in columns; describing a structure, cell arrangement, or form that does not have a tall, pillar-like shape or organization.\",\"s\":\"The modern building had a noncolumnar design, with smooth walls replacing the traditional pillars.\",\"p\":\"non-kuh-LUM-ner\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.colum.nar\",\"ps\":\"adjective\",\"t\":[\"buildings\",\"olatin\"]},{\"w\":\"noncombative\",\"d\":\"Not aggressive or inclined to fight; describing a person, animal, or approach that avoids conflict and does not engage in combative behavior.\",\"s\":\"The noncombative dog wagged its tail at every stranger instead of barking.\",\"p\":\"non-kum-BAT-iv\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.com.bat.ive\",\"ps\":\"adjective\",\"t\":[\"animals\",\"character\",\"war\",\"olatin\"]},{\"w\":\"noncombatively\",\"d\":\"In a manner that avoids aggression or fighting; acting peacefully and without any desire to engage in conflict or confrontation.\",\"s\":\"She responded noncombatively to the criticism, calmly explaining her point of view.\",\"p\":\"non-kum-BAT-iv-lee\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.com.bat.ive.ly\",\"ps\":\"adverb\",\"t\":[\"olatin\"]},{\"w\":\"noncombination\",\"d\":\"The state or condition of elements or substances not being mixed or joined together; a failure or refusal to combine into a unified whole.\",\"s\":\"The chemist noted a noncombination of the two substances, meaning they refused to mix together.\",\"p\":\"non-kom-bih-NAY-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.com.bi.na.tion\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"noncombined\",\"d\":\"Not joined, merged, or mixed together; describing substances, elements, or groups that remain separate and distinct rather than unified.\",\"s\":\"The noncombined ingredients sat in separate bowls, waiting to be mixed.\",\"p\":\"non-kum-BYND\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.com.bined\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncomedic\",\"d\":\"Not humorous or comic in nature; describing a work, performance, or situation that is serious, dramatic, or solemn rather than funny.\",\"s\":\"The play had a noncomedic tone, leaving the audience feeling somber by the final act.\",\"p\":\"non-kuh-MEE-dik\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.comedic\",\"ps\":\"adjective\",\"t\":[\"stage\",\"olatin\"]},{\"w\":\"noncomedogenic\",\"d\":\"Describing a skincare or cosmetic product that is formulated not to clog pores or cause comedones, helping to keep skin clear of blackheads and acne.\",\"s\":\"The dermatologist recommended a noncomedogenic moisturizer so it wouldn't clog her pores.\",\"p\":\"non-kom-ih-doh-JEN-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.come.do.genic\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"noncomedy\",\"d\":\"A genre, work, or performance that is not comedic; a serious or dramatic form of storytelling that contains no humor or comic elements.\",\"s\":\"The film festival featured only noncomedy entries, focusing on thrillers and dramas.\",\"p\":\"non-KOM-ih-dee\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.com.e.dy\",\"ps\":\"noun\",\"t\":[\"stage\",\"poetry\",\"olatin\"]},{\"w\":\"noncomic\",\"d\":\"Not related to or characteristic of comedy; describing something serious, dramatic, or straightforward in tone with no humorous intent.\",\"s\":\"The speech had a noncomic delivery that reminded students how serious the issue was.\",\"p\":\"non-KOM-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.com.ic\",\"ps\":\"adjective\",\"t\":[\"stage\",\"olatin\"]},{\"w\":\"noncommercialized\",\"d\":\"Not developed or transformed for the purpose of making profit; describing something that has not been taken over by commercial interests or business activity.\",\"s\":\"The remote mountain village remained noncommercialized, preserving its traditional way of life far from the noise and pressure of modern tourism and business.\",\"p\":\"nahn-kuh-MUR-shuh-lyzd\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.com.mer.cial.ized\",\"ps\":\"adjective\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"noncommercially\",\"d\":\"In a manner that does not involve making money or conducting business; without commercial purpose or profit-seeking intent.\",\"s\":\"The young artist shared her paintings noncommercially on a free website, simply wanting to inspire others without earning any money from her work.\",\"p\":\"nahn-kuh-MUR-shuh-lee\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.com.mer.cial.ly\",\"ps\":\"adverb\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"noncomminuted\",\"d\":\"Not broken or ground into tiny pieces or fragments; remaining whole and intact rather than being crushed or pulverized.\",\"s\":\"The geologist noted that the noncomminuted rock samples were far more useful for analysis because they still showed their original internal layers and crystal structures.\",\"p\":\"nahn-KOM-ih-nyoo-tid\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.com.min.ut.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncommitment\",\"d\":\"The state of not making a firm decision, promise, or pledge; a refusal or failure to commit to a particular course of action or position.\",\"s\":\"His constant noncommitment to weekend plans frustrated his friends, who could never be sure whether he would actually show up to their gatherings or events.\",\"p\":\"nahn-kuh-MIT-ment\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.com.mit.ment\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"noncommitted\",\"d\":\"Not having made a definite choice, promise, or pledge; unwilling or unable to firmly support one side, idea, or plan over another.\",\"s\":\"She remained noncommitted about which college to attend, telling her parents she needed more time to visit campuses and review financial aid packages carefully.\",\"p\":\"nahn-kuh-MIT-id\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.com.mit.ted\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncommodifiable\",\"d\":\"Not able to be turned into a product that can be bought and sold on a market; describing something whose value cannot be reduced to a price or commercial exchange.\",\"s\":\"Many philosophers argue that true friendship is noncommodifiable because its worth comes from genuine care, not from any transaction or financial exchange between people.\",\"p\":\"nahn-kuh-MOD-ih-fy-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.com.mod.i.fi.able\",\"ps\":\"adjective\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"noncommodified\",\"d\":\"Not converted into a product meant for sale or commercial trade; describing something that has not been assigned a market value or treated as a tradable good.\",\"s\":\"In many Indigenous cultures, sacred land is considered noncommodified and cannot be bought or sold, regardless of what outside developers or governments might offer.\",\"p\":\"nahn-kuh-MOD-ih-fyd\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.com.mod.i.fied\",\"ps\":\"adjective\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"noncommon\",\"d\":\"Not ordinary, shared, or widespread; describing something that is uncommon, rare, or not held in common by a general group of people.\",\"s\":\"The museum proudly displayed the noncommon gemstones, explaining to visitors that these rare minerals could be found in only a handful of locations around the entire world.\",\"p\":\"nahn-KOM-un\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.com.mon\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncommunal\",\"d\":\"Not shared among or belonging to a community or group; describing something that is private, individual, or not organized around communal living or ownership.\",\"s\":\"Unlike the collective farms of the region, this noncommunal property was owned and managed entirely by one family who made all the decisions independently.\",\"p\":\"nahn-kuh-MYOO-nul\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"non.com.mu.nal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncommunicational\",\"d\":\"Not involving, relating to, or designed for the exchange of information or messages; describing a system or process in which communication does not occur.\",\"s\":\"The researchers were surprised to find that the signals were noncommunicational, carrying no meaningful information between the two organisms despite appearing at regular intervals.\",\"p\":\"nahn-kuh-myoo-nih-KAY-shun-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":33,\"sy\":\"non.com.mu.ni.ca.tion.al\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncommunicative\",\"d\":\"Not inclined or able to share information, thoughts, or feelings; tending to keep silent rather than expressing ideas or engaging in conversation with others.\",\"s\":\"The detective found the witness frustratingly noncommunicative, answering every question with a shrug or a one-word reply that revealed almost nothing useful about the incident.\",\"p\":\"nahn-kuh-MYOO-nih-kay-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.com.mu.nica.tive\",\"ps\":\"adjective\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"noncommunion\",\"d\":\"The absence of fellowship, shared bond, or spiritual union between individuals or groups; a state of being separate or disconnected rather than joined together in common purpose.\",\"s\":\"The theologian described the noncommunion between the two factions as deeply troubling, warning that their refusal to share worship would permanently divide the congregation.\",\"p\":\"nahn-kuh-MYOON-yun\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.com.mu.nion\",\"ps\":\"noun\",\"t\":[\"religion\",\"olatin\"]},{\"w\":\"noncommunism\",\"d\":\"A political or social philosophy or system that is not based on communist principles; the rejection or absence of communist ideology in a society or organization.\",\"s\":\"The newly formed government emphasized its commitment to noncommunism, promising free elections and private ownership of businesses as core principles of its new constitution.\",\"p\":\"nahn-KOM-yuh-nih-zum\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.com.mu.nism\",\"ps\":\"noun\",\"t\":[\"politics\",\"logic\",\"olatin\"]},{\"w\":\"noncommunist\",\"d\":\"Not adhering to or supporting the principles of communism; describing a person, government, or system that does not follow communist ideology or political doctrine.\",\"s\":\"The noncommunist nations formed a strong alliance during the Cold War, pledging to support each other economically and militarily against the spread of Soviet influence.\",\"p\":\"NAH-NKAH-myoo-nih-st\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"naa.nkaa.myuw.nih.st\",\"ps\":\"adjective\",\"t\":[\"politics\",\"logic\",\"olatin\"]},{\"w\":\"noncommunistic\",\"d\":\"Not reflecting or based on the beliefs and practices of communism; describing an idea, system, or policy that does not follow communist principles or collective ownership.\",\"s\":\"The economist argued that noncommunistic market systems generally produced greater individual wealth, though critics pointed out they also created wider gaps between rich and poor citizens.\",\"p\":\"nahn-kuh-myoo-NIS-tik\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.com.mu.nis.tic\",\"ps\":\"adjective\",\"t\":[\"politics\",\"logic\",\"olatin\"]},{\"w\":\"noncommuter\",\"d\":\"A person who does not travel regularly between home and a workplace, especially one who works from home or lives near their place of employment.\",\"s\":\"As a noncommuter who worked entirely from her home office, she saved nearly two hours every day that other employees spent stuck in heavy traffic.\",\"p\":\"nahn-kuh-MYOO-ter\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.com.muter\",\"ps\":\"noun\",\"t\":[\"jobs\",\"olatin\"]},{\"w\":\"noncommuting\",\"d\":\"In mathematics, describing operations or elements where changing the order of the operation produces a different result; not satisfying the commutative property.\",\"s\":\"The professor explained that matrix multiplication is noncommuting, meaning that multiplying matrix A by matrix B gives a completely different result than multiplying B by A.\",\"p\":\"nahn-kuh-MYOO-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.com.mut.ing\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"noncompacted\",\"d\":\"Not pressed, packed, or compressed tightly together; describing a material or substance that retains a loose, airy structure rather than being densely compacted.\",\"s\":\"The gardener recommended using noncompacted soil in the raised beds because plant roots grow much more easily through loose earth than through tightly packed ground.\",\"p\":\"nahn-kum-PAK-tid\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.com.pact.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncomparable\",\"d\":\"Not able to be meaningfully compared with something else because the two things are too different in nature, kind, or quality to be measured against each other.\",\"s\":\"The judge ruled that the two works of art were noncomparable, since one was a bronze sculpture and the other a digital animation created in an entirely different medium.\",\"p\":\"nahn-KOM-pair-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.com.pa.ra.ble\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"noncomparative\",\"d\":\"Not involving comparison between two or more things; describing an approach or judgment that evaluates each item on its own merits rather than in relation to others.\",\"s\":\"The teacher used a noncomparative grading system in which each student's portfolio was assessed against a fixed set of standards, not ranked against classmates' work.\",\"p\":\"nahn-kum-PAIR-uh-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.com.par.a.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncompassionate\",\"d\":\"Lacking sympathy, kindness, or concern for the suffering of others; showing no empathy or emotional care toward people who are struggling or in pain.\",\"s\":\"The reviewer criticized the villain's noncompassionate attitude toward the villagers, arguing that it made the character feel unrealistic because even flawed people usually show some human warmth.\",\"p\":\"nahn-kum-PASH-un-it\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.com.pas.sion.ate\",\"ps\":\"adjective\",\"t\":[\"emotions\",\"olatin\"]},{\"w\":\"noncompete\",\"d\":\"Describing a legal agreement in which a person promises not to work for a competitor or start a competing business for a set period of time after leaving a job.\",\"s\":\"Before signing the noncompete agreement, the software engineer asked a lawyer to review each clause carefully to make sure the restrictions were reasonable and legally enforceable in her state.\",\"p\":\"nah-nkuh-MPEE-t\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"naa.nkah.mpiy.t\",\"ps\":\"adjective\",\"t\":[\"law\",\"time\",\"olatin\"]},{\"w\":\"noncompetence\",\"d\":\"The lack of legal authority, skill, or qualification needed to handle a particular matter; a state of being unqualified or without the proper jurisdiction to act.\",\"s\":\"The attorney argued noncompetence of the lower court, insisting that such an important constitutional question could only be decided at the federal appellate level.\",\"p\":\"nahn-KOM-pih-tuns\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.com.pe.tence\",\"ps\":\"noun\",\"t\":[\"poetry\",\"law\",\"olatin\"]},{\"w\":\"noncompetency\",\"d\":\"The condition of lacking the necessary skills, qualifications, or legal authority required for a specific task or role; an absence of recognized ability or jurisdiction.\",\"s\":\"The board cited the candidate's noncompetency in financial management as the primary reason for rejecting her application to lead the nonprofit organization's budget committee.\",\"p\":\"nahn-KOM-pih-ten-see\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.com.pe.ten.cy\",\"ps\":\"noun\",\"t\":[\"poetry\",\"law\",\"olatin\"]},{\"w\":\"noncompetent\",\"d\":\"Not having the required skills, qualifications, or legal authority to perform a task or make a decision; lacking the ability or jurisdiction deemed necessary for a role.\",\"s\":\"The court declared itself noncompetent to rule on the international trade dispute, redirecting the case to a specialized tribunal that had the proper legal authority.\",\"p\":\"nahn-KOM-pih-tent\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.com.pe.tent\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"law\",\"olatin\"]},{\"w\":\"noncompetition\",\"d\":\"The state or condition of not competing; often refers to a legal agreement in which a person or company agrees not to engage in business activities that rival a former employer.\",\"s\":\"The terms of the noncompetition clause prevented the former executive from joining any competing technology firm for a full two years after leaving her previous company.\",\"p\":\"nahn-kom-pih-TIH-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.com.pe.ti.tion\",\"ps\":\"noun\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"noncompetitional\",\"d\":\"Not relating to or involving competition; describing an activity, environment, or arrangement in which participants are not competing against one another for prizes, rankings, or recognition.\",\"s\":\"The summer art camp was intentionally noncompetitional, encouraging every student to experiment freely with paint and clay without worrying about being judged or ranked against peers.\",\"p\":\"nahn-kom-pih-TIH-shun-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.com.pe.ti.tion.al\",\"ps\":\"adjective\",\"t\":[\"ecology\",\"sports\",\"olatin\"]},{\"w\":\"noncompetitor\",\"d\":\"A person, organization, or entity that is not competing in a particular contest, market, or field; someone who does not rival others for the same goal or resource.\",\"s\":\"As a noncompetitor who simply loved running, Marcus joined the local 5K race for the joy of it, cheering on the serious athletes rather than racing against them.\",\"p\":\"nahn-kum-PET-ih-ter\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.com.peti.tor\",\"ps\":\"noun\",\"t\":[\"economy\",\"sports\",\"olatin\"]},{\"w\":\"noncompilable\",\"d\":\"In computing, describing code or a program that cannot be processed and converted into a working executable by a compiler because of errors or incompatible syntax.\",\"s\":\"The programming instructor warned students that even a single misplaced semicolon could render their entire project noncompilable, producing error messages that would prevent the program from running at all.\",\"p\":\"nahn-kum-PY-luh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.com.pi.l.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncompiled\",\"d\":\"Not gathered, assembled, or collected into an organized whole; in computing, describing code that has not been processed through a compiler to create an executable program.\",\"s\":\"The programmer shared the noncompiled source code with her team so they could all review and modify the logic before converting it into a finished, runnable application.\",\"p\":\"nahn-kum-PYLD\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.com.piled\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncomplementary\",\"d\":\"Not completing, balancing, or working well together with something else; describing elements that fail to enhance or perfectly match each other in function, color, or purpose.\",\"s\":\"The interior designer pointed out that the bright orange walls and the red furniture were noncomplementary, creating a visual clash that made the small living room feel chaotic and uncomfortable.\",\"p\":\"nahn-kom-pluh-MEN-tuh-ree\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.com.ple.men.tary\",\"ps\":\"adjective\",\"t\":[\"sports\",\"colors\",\"olatin\"]},{\"w\":\"noncomplementing\",\"d\":\"Failing to complete, enhance, or work in harmony with another element; not supplying what is needed to form a satisfying or functional whole when combined with something else.\",\"s\":\"In genetics class, we learned that noncomplementing mutations in the same gene produce a defective trait even when both copies are present in the organism's cells.\",\"p\":\"nahn-KOM-pluh-men-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.com.ple.ment.ing\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"music\",\"olatin\"]},{\"w\":\"noncomplete\",\"d\":\"Not whole, finished, or fully developed; lacking some necessary part or element that would make something entire or fully realized.\",\"s\":\"The architect submitted a noncomplete set of blueprints to the city, missing several required pages that showed the building's electrical wiring and emergency exit plans.\",\"p\":\"nahn-kum-PLEET\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.com.plete\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"noncompleted\",\"d\":\"Not finished or brought to a successful end; describing a task, project, or process that was started but never fully accomplished or concluded.\",\"s\":\"The list of noncompleted homework assignments piled up on Maya's desk throughout the busy week, reminding her of all the work she still had to finish before the weekend.\",\"p\":\"nahn-kum-PLEE-tid\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.com.plet.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncompleteness\",\"d\":\"The quality or state of being unfinished, lacking necessary parts, or failing to meet the requirements of being whole or fully developed.\",\"s\":\"The professor criticized the essay's noncompleteness, explaining that the student had raised a strong argument but failed to include any supporting evidence or a proper conclusion.\",\"p\":\"nahn-kum-PLEET-nes\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.com.plete.ness\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"noncompletion\",\"d\":\"The failure to finish or bring something to its intended end; the state of a task, project, or goal that has been left unfinished or abandoned before being fully accomplished.\",\"s\":\"Noncompletion of the required community service hours meant that the students would not receive credit for the volunteer program, no matter how many hours they had already finished.\",\"p\":\"nahn-kum-PLEE-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.com.ple.tion\",\"ps\":\"noun\",\"t\":[\"sports\",\"olatin\"]},{\"w\":\"noncompliant\",\"d\":\"not following a rule, order, or required standard\",\"s\":\"The health inspector found the kitchen noncompliant with the food safety rules.\",\"p\":\"nahn-kum-PLY-unt\",\"o\":\"Latin\",\"y\":7,\"bp\":38,\"sy\":\"non.com.pli.ant\",\"ps\":\"noun\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"noncomplicated\",\"d\":\"Not difficult, complex, or hard to understand; describing something that is straightforward and free from unnecessary complications or confusing elements.\",\"s\":\"The teacher appreciated the noncomplicated instructions that came with the science kit, since clear and simple directions made it much easier for younger students to complete the experiment successfully.\",\"p\":\"nahn-KOM-plih-kay-tid\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.com.pli.cat.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncomplimentary\",\"d\":\"Not expressing praise, flattery, or admiration; describing a remark, review, or attitude that is critical, unfavorable, or lacking in any positive feedback.\",\"s\":\"The food critic's noncomplimentary review of the new restaurant shocked the chef, who had expected at least some praise for the months of careful menu planning and preparation.\",\"p\":\"nahn-kom-plih-MEN-tuh-ree\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.com.pli.men.ta.ry\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncomposed\",\"d\":\"Not put together in an orderly, artistic, or structured way; describing something that lacks deliberate arrangement, organization, or the calm self-control associated with being composed.\",\"s\":\"The symphony's final movement felt rushed and noncomposed, as though the musician had improvised randomly rather than following the carefully written score the composer had created.\",\"p\":\"nahn-kum-POZD\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.com.posed\",\"ps\":\"adjective\",\"t\":[\"painting\",\"olatin\"]},{\"w\":\"noncomposer\",\"d\":\"A person who does not compose music or other creative works; someone who performs, studies, or listens to compositions but does not create original pieces.\",\"s\":\"As a noncomposer, he enjoyed playing other people's music but never wrote his own.\",\"p\":\"non-kum-POH-zer\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.com.pos.er\",\"ps\":\"noun\",\"t\":[\"music\",\"olatin\"]},{\"w\":\"noncomposited\",\"d\":\"Not combined or merged from multiple layers or elements; describing an image, material, or structure that has not been composited together.\",\"s\":\"The raw footage was noncomposited and still needed visual effects added before the scene was finished.\",\"p\":\"non-kum-POZ-it-ed\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.com.pos.it.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncompositional\",\"d\":\"Not relating to or based on compositional structure; lacking deliberate arrangement of elements into a unified whole.\",\"s\":\"Her abstract painting was praised for its noncompositional style, which ignored all traditional arrangement rules.\",\"p\":\"non-kom-puh-ZI-shun-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.com.po.si.tion.al\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncompostable\",\"d\":\"Unable to be broken down through composting into organic matter; describing materials that do not decompose naturally in a compost environment.\",\"s\":\"The school reminded students that plastic bags are noncompostable and should never go in the garden bin.\",\"p\":\"non-kum-POHST-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.com.postable\",\"ps\":\"adjective\",\"t\":[\"ecology\",\"olatin\"]},{\"w\":\"noncomposted\",\"d\":\"Not yet broken down through the composting process; describing organic or other material that has not been converted into compost.\",\"s\":\"The noncomposted kitchen scraps still needed several weeks before they would break down into rich soil.\",\"p\":\"non-kum-POHST-ed\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.com.post.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncompound\",\"d\":\"Not made up of two or more combined elements or parts; consisting of a single, simple component rather than a mixture or combination.\",\"s\":\"Water is a compound, but pure gold is a noncompound element found in its simplest form.\",\"p\":\"non-KOM-pownd\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.com.pound\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncomprehending\",\"d\":\"Not understanding or grasping the meaning of something; failing to comprehend information, language, or ideas presented.\",\"s\":\"The student stared at the equation with a noncomprehending look, completely lost.\",\"p\":\"non-kom-prih-HEN-ding\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.com.pre.hend.ing\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"noncompressed\",\"d\":\"Not squeezed, compacted, or reduced in size or volume; remaining in its original, uncompressed state.\",\"s\":\"The noncompressed audio file was huge and took forever to upload to the website.\",\"p\":\"non-kum-PREST\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.com.pressed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncompressible\",\"d\":\"Unable to be compressed or reduced in volume by applying pressure; resisting compaction regardless of the force applied.\",\"s\":\"Unlike air, water is essentially noncompressible and cannot be squeezed into a smaller space.\",\"p\":\"non-kum-PRES-ih-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.com.press.ible\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"noncompulsive\",\"d\":\"Not driven by an irresistible urge or compulsion; describing behavior or thinking that is free from obsessive or forceful impulses.\",\"s\":\"Her noncompulsive approach to cleaning meant she tidied up only when she actually felt like it.\",\"p\":\"non-kum-PUL-siv\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.com.pul.sive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncompulsory\",\"d\":\"Not required or mandatory; describing something that is entirely optional and left to individual choice.\",\"s\":\"Attendance at the Saturday workshop was noncompulsory, so many students chose to sleep in.\",\"p\":\"non-kum-PUL-suh-ree\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.com.pul.so.ry\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncomputational\",\"d\":\"Not involving or related to mathematical calculation or computer processing; describing methods or approaches that do not rely on computation.\",\"s\":\"The art class offered a refreshingly noncomputational way to solve problems through drawing and building.\",\"p\":\"non-kom-pyoo-TAY-shun-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.com.pu.ta.tion.al\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"noncomputed\",\"d\":\"Not calculated or processed by a computer or mathematical method; arrived at without the use of computation.\",\"s\":\"The noncomputed estimate was based on the shopkeeper's experience rather than any digital tools.\",\"p\":\"non-kum-PYOO-ted\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.com.put.ed\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"noncomputer\",\"d\":\"Not involving or related to a computer; describing a device, method, or system that operates without computer technology.\",\"s\":\"She kept a noncomputer filing system using color-coded folders and handwritten labels.\",\"p\":\"non-kum-PYOO-ter\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.com.put.er\",\"ps\":\"adjective\",\"t\":[\"tools\",\"olatin\"]},{\"w\":\"noncomputerized\",\"d\":\"Not converted to or operated by computer systems; describing records, processes, or equipment that remain manual or analog.\",\"s\":\"The small village library was noncomputerized and relied on a card catalog to track its books.\",\"p\":\"non-kum-PYOO-tuh-ryzd\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.com.put.er.ized\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonconative\",\"d\":\"Not relating to the mental faculty of will, desire, or striving; describing thought or behavior that lacks purposeful motivation or drive.\",\"s\":\"The professor explained that a nonconative mental state involves no desire or urge to act.\",\"p\":\"non-KOH-nuh-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.cona.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonconcatenative\",\"d\":\"Not involving the chaining or linking of elements in sequence; in linguistics, describing morphology that does not add prefixes or suffixes but changes the internal structure of a word.\",\"s\":\"The linguist studied nonconcatenative morphology, where word parts don't simply attach end to end.\",\"p\":\"non-kon-KAT-uh-nay-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.con.cate.na.tive\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonconcave\",\"d\":\"Not curved inward like the inside of a bowl or cave; describing a surface or shape that does not dip or hollow inward.\",\"s\":\"The lens was nonconcave, meaning it bulged outward rather than curving inward.\",\"p\":\"non-kon-KAYV\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.con.cave\",\"ps\":\"adjective\",\"t\":[\"landforms\",\"olatin\"]},{\"w\":\"nonconceptual\",\"d\":\"Not based on or related to abstract concepts or ideas; existing or experienced before or apart from the formation of mental concepts.\",\"s\":\"Babies experience the world in a nonconceptual way, feeling emotions before forming any ideas about them.\",\"p\":\"non-kon-SEP-choo-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.con.cep.tu.al\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonconceptualized\",\"d\":\"Not yet formed into a clear concept or abstract idea; remaining vague, unorganized, or undefined in the mind.\",\"s\":\"The artist's raw emotion remained nonconceptualized until she finally painted it onto the canvas.\",\"p\":\"non-kon-SEP-choo-uh-lyzd\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.con.cep.tu.al.ized\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonconceptually\",\"d\":\"In a manner that does not involve abstract concepts or ideas; without drawing on conceptual thought or theoretical frameworks.\",\"s\":\"Young children often experience fear nonconceptually, without being able to explain why they feel scared.\",\"p\":\"non-kon-SEP-choo-uh-lee\",\"o\":\"Latin\",\"y\":9,\"bp\":31,\"sy\":\"non.con.cep.tu.al.ly\",\"ps\":\"adverb\",\"t\":[\"painting\",\"olatin\"]},{\"w\":\"nonconcern\",\"d\":\"A complete lack of worry, interest, or care about a particular matter; an attitude of total indifference toward something.\",\"s\":\"His nonconcern about the upcoming test surprised his parents, who expected him to be nervous.\",\"p\":\"non-kun-SURN\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.con.cern\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonconcerned\",\"d\":\"Not worried, interested, or troubled by a particular matter; displaying or feeling complete indifference.\",\"s\":\"She seemed completely nonconcerned about the storm warning, humming quietly as she read her book.\",\"p\":\"non-kun-SURND\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"non.con.cerned\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonconcerted\",\"d\":\"Not planned or carried out together in a coordinated way; describing actions or efforts that are uncoordinated or not jointly organized.\",\"s\":\"The nonconcerted efforts of the volunteers led to confusion and duplicate work throughout the day.\",\"p\":\"non-kun-SUR-ted\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.con.cert.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonconcession\",\"d\":\"The refusal to yield, give up, or make a compromise; an absence of any giving of ground in a negotiation or dispute.\",\"s\":\"The negotiator's nonconcession on the key issues caused the peace talks to break down completely.\",\"p\":\"non-kun-SESH-un\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.con.ces.sion\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonconcessionary\",\"d\":\"Not involving or granting concessions or compromises; describing a stance, policy, or person that refuses to yield any ground.\",\"s\":\"The landlord took a nonconcessionary stance and refused to lower the rent despite the tenant's pleas.\",\"p\":\"non-kun-SESH-uh-nair-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.con.ces.sion.ary\",\"ps\":\"adjective\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"nonconciliatory\",\"d\":\"Not intended to make peace or reduce hostility; describing an attitude or action that does nothing to soothe conflict or bring about reconciliation.\",\"s\":\"His nonconciliatory tone during the argument made it impossible to reach any kind of agreement.\",\"p\":\"non-kun-SIL-ee-uh-tor-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":33,\"sy\":\"non.c.on.cil.ia.to.ry\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonconclusion\",\"d\":\"The absence of a final decision, resolution, or concluding outcome; a state in which no definitive end or judgment has been reached.\",\"s\":\"The debate ended in a nonconclusion, with neither side convincing the other.\",\"p\":\"non-kun-KLOO-zhun\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.con.clu.sion\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonconcur\",\"d\":\"To fail to agree or share the same opinion; to withhold agreement or approval from a decision or viewpoint.\",\"s\":\"The two scientists nonconcur on the results, so a third expert was called in.\",\"p\":\"non-kun-KUR\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.con.cur\",\"ps\":\"verb\",\"t\":[\"olatin\"]},{\"w\":\"nonconcurrence\",\"d\":\"A failure or refusal to agree with a position, decision, or opinion; the state of not being in agreement with others.\",\"s\":\"The judge noted a clear nonconcurrence between the two witnesses' stories.\",\"p\":\"non-kun-KUR-unts\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.con.cur.rence\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonconcurrent\",\"d\":\"Not occurring at the same time or running in agreement; describing events, processes, or opinions that do not coincide or align.\",\"s\":\"The two construction projects were nonconcurrent, so workers finished one before starting the other.\",\"p\":\"non-kun-KUR-unt\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.con.cur.rent\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nonconcurring\",\"d\":\"Not agreeing or happening simultaneously; describing a person or process that does not align with others in opinion or timing.\",\"s\":\"The nonconcurring board members signed a separate statement explaining their objections.\",\"p\":\"non-kun-KUR-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.con.cur.ring\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonconcussed\",\"d\":\"Not having suffered a concussion or traumatic brain injury from an impact; describing a person whose brain has not been shaken or injured.\",\"s\":\"The doctor confirmed the player was nonconcussed and cleared to return to the game.\",\"p\":\"non-kun-KUST\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.con.cussed\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"noncondemning\",\"d\":\"Not judging, blaming, or declaring someone or something to be wrong or guilty; taking an accepting and non-judgmental stance toward others.\",\"s\":\"The counselor took a noncondemning approach, listening without judging the student's mistakes.\",\"p\":\"non-kun-DEM-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.con.demn.ing\",\"ps\":\"adjective\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"noncondensable\",\"d\":\"Describing a gas that cannot be turned into a liquid by cooling or compressing under normal conditions; resistant to condensation.\",\"s\":\"Engineers had to remove the noncondensable gases from the system to keep it running efficiently.\",\"p\":\"non-kun-DEN-suh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.con.dens.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncondensed\",\"d\":\"Not reduced from a gas to a liquid state; remaining in a gaseous or expanded form without having undergone condensation.\",\"s\":\"The noncondensed steam escaped into the air instead of turning back into water.\",\"p\":\"non-kun-DENST\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"non.con.densed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncondensible\",\"d\":\"Unable to be condensed or converted into liquid form; an alternative spelling of noncondensable, referring to gases that resist condensation.\",\"s\":\"The noncondensible vapor in the pipe caused pressure to build up unexpectedly.\",\"p\":\"non-kun-DEN-sih-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.con.den.si.ble\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"noncondensing\",\"d\":\"Not causing or undergoing condensation; describing a heating or cooling system in which steam or vapor does not convert back into liquid form.\",\"s\":\"A noncondensing boiler releases steam rather than recapturing it as water.\",\"p\":\"non-kun-DEN-sing\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.con.dens.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonconditional\",\"d\":\"Not dependent on conditions or requirements; describing a statement, agreement, or relationship that has no attached stipulations or qualifications.\",\"s\":\"The teacher gave nonconditional praise, encouraging students regardless of their test scores.\",\"p\":\"non-kun-DISH-un-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.con.di.tion.al\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonconditionally\",\"d\":\"In a manner that is free from conditions, requirements, or limitations; without any attached stipulations or qualifying terms.\",\"s\":\"She supported her friend nonconditionally, standing by her no matter what happened.\",\"p\":\"non-kun-DISH-un-uh-lee\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.con.di.tion.al.ly\",\"ps\":\"adverb\",\"t\":[\"olatin\"]},{\"w\":\"nonconditioned\",\"d\":\"Not shaped or altered by training, experience, or external stimuli; describing a response or state that has not been taught or modified through conditioning.\",\"s\":\"The nonconditioned response was natural, not learned through any training or reward.\",\"p\":\"non-kun-DIH-shund\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.con.di.tioned\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncondominium\",\"d\":\"A property or housing arrangement that is not organized as a condominium, meaning individual units are not separately owned within a shared building.\",\"s\":\"Because the building was classified as a noncondominium, residents rented rather than owned their units.\",\"p\":\"non-kon-duh-MIN-ee-um\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.con.do.mini.um\",\"ps\":\"noun\",\"t\":[\"buildings\",\"olatin\"]},{\"w\":\"nonconducting\",\"d\":\"not able to conduct heat or electricity or sound\",\"s\":\"Rubber is nonconducting, which is why electricians wear rubber gloves for safety.\",\"p\":\"non-kun-DUK-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.con.duct.ing\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonconduction\",\"d\":\"The absence or failure of transmission of heat, electricity, or sound through a material; the property of not conducting energy.\",\"s\":\"The plastic coating ensured nonconduction, keeping the electrical current safely inside the wire.\",\"p\":\"non-kun-DUK-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.con.duc.tion\",\"ps\":\"noun\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonconductivity\",\"d\":\"The quality or state of being unable to transmit heat, electricity, or sound; the characteristic of a material that does not allow energy to pass through it.\",\"s\":\"Scientists measured the nonconductivity of the new ceramic material to use it in insulators.\",\"p\":\"non-kun-duk-TIV-ih-tee\",\"o\":\"Latin\",\"y\":9,\"bp\":31,\"sy\":\"non.con.duc.tiv.i.ty\",\"ps\":\"noun\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonconference\",\"d\":\"Relating to or describing athletic games, competitions, or events played against teams that are not members of the same official league or conference.\",\"s\":\"Our basketball team played several nonconference games against schools from different districts.\",\"p\":\"non-KON-fer-ents\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.con.fer.ence\",\"ps\":\"adjective\",\"t\":[\"sports\",\"olatin\"]},{\"w\":\"nonconfessing\",\"d\":\"Not admitting to or acknowledging a fault, crime, belief, or wrongdoing; describing someone who refuses or fails to make a confession.\",\"s\":\"The nonconfessing suspect stayed silent throughout the entire police interview.\",\"p\":\"non-kun-FES-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.con.fess.ing\",\"ps\":\"adjective\",\"t\":[\"law\",\"logic\",\"olatin\"]},{\"w\":\"nonconfession\",\"d\":\"The absence of an admission of guilt, wrongdoing, or religious belief; a failure or refusal to confess something.\",\"s\":\"The lawyer described her client's nonconfession as a sign of innocence, not guilt.\",\"p\":\"non-kun-FEH-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.con.fes.sion\",\"ps\":\"noun\",\"t\":[\"religion\",\"law\",\"logic\",\"olatin\"]},{\"w\":\"nonconfessional\",\"d\":\"Not affiliated with or requiring allegiance to any particular religious faith or denomination; open to people of all beliefs or no belief.\",\"s\":\"The nonconfessional school welcomed students of all religious backgrounds equally.\",\"p\":\"non-kun-FEH-shuh-nul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.con.fes.sion.al\",\"ps\":\"adjective\",\"t\":[\"nations\",\"religion\",\"logic\",\"olatin\"]},{\"w\":\"nonconfidence\",\"d\":\"A lack of trust, assurance, or faith in someone or something; the state of not having confidence in a person, system, or outcome.\",\"s\":\"His nonconfidence showed in the way he hesitated before every answer.\",\"p\":\"non-KON-fih-dens\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.con.fi.dence\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonconfident\",\"d\":\"Lacking self-assurance or trust in oneself or others; not displaying or feeling confidence in one's abilities or judgments.\",\"s\":\"The nonconfident speaker kept looking at the floor instead of making eye contact.\",\"p\":\"non-KON-fih-dent\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.con.fi.dent\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonconfidential\",\"d\":\"Not meant to be kept secret or private; available to the public or to anyone who wishes to access the information.\",\"s\":\"The principal explained that the meeting notes were nonconfidential and could be shared with parents.\",\"p\":\"non-kon-fih-DEN-shul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.con.fi.den.tial\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonconfigurable\",\"d\":\"Not able to be set up, arranged, or adjusted to different specifications; describing software, hardware, or systems whose settings cannot be changed by the user.\",\"s\":\"The nonconfigurable software ran the same way on every computer without any user adjustments.\",\"p\":\"non-kun-FIG-yur-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.con.fig.urable\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonconfined\",\"d\":\"Not restricted, imprisoned, or limited to a particular space or boundary; free from physical or figurative limitations.\",\"s\":\"The nonconfined animals roamed freely across the wide open nature reserve.\",\"p\":\"non-kun-FYND\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.con.fined\",\"ps\":\"adjective\",\"t\":[\"maps\",\"olatin\"]},{\"w\":\"nonconfinement\",\"d\":\"The state or condition of not being restricted, imprisoned, or held within a limited space; freedom from confinement.\",\"s\":\"The judge ordered nonconfinement for the first-time offender, allowing community service instead.\",\"p\":\"non-kun-FYN-ment\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.con.fine.ment\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonconfining\",\"d\":\"Not restricting movement, growth, or freedom; describing conditions, spaces, or rules that do not limit or enclose.\",\"s\":\"The loose, nonconfining uniform allowed students to move freely during gym class.\",\"p\":\"non-kun-FY-ning\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.con.fin.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonconfirmatory\",\"d\":\"Not serving to confirm, verify, or establish the truth of something; describing evidence or results that fail to support or prove a claim.\",\"s\":\"The test results were nonconfirmatory, so doctors ordered additional exams to find answers.\",\"p\":\"non-kun-FUR-muh-tor-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":31,\"sy\":\"non.con.fir.ma.to.ry\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonconfirmed\",\"d\":\"Not yet verified, approved, or established as true or official; remaining uncertain or unvalidated.\",\"s\":\"The nonconfirmed reservation meant the hotel might give the room to someone else.\",\"p\":\"non-kun-FURMD\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"non.con.firmed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonconflicted\",\"d\":\"Not experiencing internal struggle, divided loyalties, or opposing emotions about a decision or situation; feeling clear and undivided.\",\"s\":\"She felt nonconflicted about her decision to join the team once she heard their goals.\",\"p\":\"non-kun-FLIK-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.con.flict.ed\",\"ps\":\"adjective\",\"t\":[\"emotions\",\"numbers\",\"olatin\"]},{\"w\":\"nonconflicting\",\"d\":\"Not clashing, contradicting, or interfering with one another; describing ideas, schedules, or interests that exist together without opposition.\",\"s\":\"The two schedules were nonconflicting, so everyone could attend both events.\",\"p\":\"non-kun-FLIK-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.con.flict.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonconfluence\",\"d\":\"The absence of a flowing together or merging of streams, ideas, or groups; the state in which separate elements do not combine at a common point.\",\"s\":\"The nonconfluence of the two streams was surprising because scientists expected them to merge.\",\"p\":\"non-KON-floo-ents\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.con.flu.ence\",\"ps\":\"noun\",\"t\":[\"waterways\",\"olatin\"]},{\"w\":\"nonconfluent\",\"d\":\"Not flowing together or merging at a common point; describing rivers, lesions, or ideas that remain separate and distinct from one another.\",\"s\":\"The two neighborhoods remained nonconfluent despite the city's plan to connect them.\",\"p\":\"non-KON-floo-ent\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.con.flu.ent\",\"ps\":\"adjective\",\"t\":[\"disease\",\"waterways\",\"olatin\"]},{\"w\":\"nonconform\",\"d\":\"To fail or refuse to follow established rules, customs, or expected standards of behavior; to act in a way that differs from the norm.\",\"s\":\"Artists often nonconform to society's expectations in order to express their unique vision.\",\"p\":\"non-kun-FORM\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.con.form\",\"ps\":\"verb\",\"t\":[\"olatin\"]},{\"w\":\"nonconformal\",\"d\":\"Not matching or conforming to a standard shape, pattern, or set of rules; describing a design or approach that does not follow conventional form.\",\"s\":\"The nonconformal design of the building stood out boldly against the rows of identical houses.\",\"p\":\"non-kun-FOR-mul\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.con.for.mal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonconformance\",\"d\":\"a failure to meet a required rule, standard, or specification\",\"s\":\"The factory was fined for nonconformance with the fire safety rules.\",\"p\":\"non-kun-FOR-mants\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.con.for.mance\",\"ps\":\"noun\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonconformer\",\"d\":\"A person or thing that does not follow established customs, rules, or expectations; someone who chooses to live or behave differently from the accepted norm.\",\"s\":\"The young artist was known as a nonconformer who painted in styles no one had seen before.\",\"p\":\"non-kun-FOR-mer\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"non.con.former\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonconfrontation\",\"d\":\"The avoidance of direct conflict, argument, or face-to-face opposition; a tendency or policy of keeping peace by not challenging others directly.\",\"s\":\"Her strategy of nonconfrontation helped keep the peace during the tense meeting.\",\"p\":\"non-kon-frun-TAY-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.con.fronta.tion\",\"ps\":\"noun\",\"t\":[\"politics\",\"logic\",\"olatin\"]},{\"w\":\"nonconfrontational\",\"d\":\"Not inclined to argue, challenge, or engage in direct conflict; describing a calm, peaceful approach that avoids disagreement or opposition.\",\"s\":\"The counselor used a nonconfrontational tone to help both students talk through their argument calmly.\",\"p\":\"non-kon-frun-TAY-shuh-nul\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.con.fronta.tion.al\",\"ps\":\"adjective\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nonconfrontationally\",\"d\":\"In a manner that avoids direct conflict, argument, or opposition; acting peacefully and diplomatically without challenging or provoking others.\",\"s\":\"She nonconfrontationally suggested a compromise so that neither side felt attacked.\",\"p\":\"non-kon-frun-TAY-shuh-nul-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.con.fronta.tion.al.ly\",\"ps\":\"adverb\",\"t\":[\"politics\",\"logic\",\"olatin\"]},{\"w\":\"nonconfused\",\"d\":\"Not in a state of bewilderment, disorder, or misunderstanding; clear-headed and able to think or perceive things accurately and without confusion.\",\"s\":\"After the clear explanation, the students were nonconfused and ready to solve the math problems.\",\"p\":\"non-kun-FYOOZD\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.con.fused\",\"ps\":\"adjective\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"noncongealing\",\"d\":\"Not thickening, solidifying, or turning into a gel-like substance; describing a liquid or material that remains fluid and does not congeal under normal conditions.\",\"s\":\"The scientists used a special additive to keep the mixture noncongealing even at low temperatures.\",\"p\":\"non-kun-GEE-ling\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.con.geal.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncongenital\",\"d\":\"Not present at birth; describing a condition, trait, or characteristic that develops after birth rather than being inherited or formed during fetal development.\",\"s\":\"The doctor explained that the patient's skin condition was noncongenital, meaning it developed after birth.\",\"p\":\"non-kun-JEN-ih-tul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.con.gen.i.tal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncongenitally\",\"d\":\"In a manner that is not related to birth or inherited conditions; describing how a trait or condition came about after birth rather than being present from the start.\",\"s\":\"The disorder was acquired noncongenitally, developing only after the child turned five.\",\"p\":\"non-kun-JEN-ih-tul-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":31,\"sy\":\"non.con.gen.i.tal.ly\",\"ps\":\"adverb\",\"t\":[\"olatin\"]},{\"w\":\"noncongested\",\"d\":\"Not blocked, overcrowded, or filled to excess; describing a road, passage, or area that flows freely without obstruction or overload.\",\"s\":\"Thanks to the new bypass road, the downtown area remained noncongested even during rush hour.\",\"p\":\"non-kun-JES-ted\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.con.gest.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncongestion\",\"d\":\"The absence of blockage, overcrowding, or excess buildup in a passage, road, or system; the state of flowing freely and without obstruction.\",\"s\":\"The urban planners celebrated the noncongestion of the new transit corridor on its opening week.\",\"p\":\"non-kun-JES-chun\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.con.ges.tion\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"noncongestive\",\"d\":\"Not causing or characterized by a dangerous buildup of fluid, traffic, or material; describing a condition or situation that does not result in congestion.\",\"s\":\"The cardiologist noted the patient's heart failure was noncongestive, which required a different treatment plan.\",\"p\":\"non-kun-JES-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.con.ges.tive\",\"ps\":\"adjective\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"noncongregational\",\"d\":\"Not associated with or organized around a congregation or gathered religious community; describing a church structure or group that does not operate under congregational governance.\",\"s\":\"The meditation retreat was noncongregational, allowing people to practice quietly on their own.\",\"p\":\"non-kon-greh-GAY-shuh-nul\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.con.gre.ga.tion.al\",\"ps\":\"adjective\",\"t\":[\"religion\",\"olatin\"]},{\"w\":\"noncongruence\",\"d\":\"The state of not matching, corresponding, or being identical in shape, size, or proportion; the lack of agreement or compatibility between two or more things.\",\"s\":\"The teacher pointed out the noncongruence of the two triangles since their sides had different lengths.\",\"p\":\"non-KON-groo-ents\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.con.gru.ence\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"noncongruent\",\"d\":\"Not identical in shape and size; describing geometric figures or other elements that cannot be made to overlap perfectly no matter how they are positioned.\",\"s\":\"The two rectangles were noncongruent because one was twice as wide as the other.\",\"p\":\"non-KON-groo-ent\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.con.gru.ent\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncongruently\",\"d\":\"In a manner that is not matching or identical in shape, size, or form; describing how two figures or elements relate when they do not perfectly correspond to each other.\",\"s\":\"The puzzle pieces fit noncongruently, leaving gaps that made the picture impossible to complete.\",\"p\":\"non-KON-groo-ent-lee\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.con.gru.ent.ly\",\"ps\":\"adverb\",\"t\":[\"olatin\"]},{\"w\":\"noncongruous\",\"d\":\"Not fitting together harmoniously or appropriately; lacking agreement or compatibility between parts or elements.\",\"s\":\"The bright pink chair looked noncongruous in the otherwise all-white office.\",\"p\":\"non-KON-groo-us\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.con.gru.ous\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonconical\",\"d\":\"Not having the shape or form of a cone; lacking the tapered, pointed structure characteristic of a cone.\",\"s\":\"The architect designed a nonconical roof that was flat and modern rather than pointed.\",\"p\":\"non-KON-ih-kul\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.con.i.cal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonconiferous\",\"d\":\"Not belonging to or characteristic of the group of cone-bearing trees, such as oaks or maples, which do not produce pinecones.\",\"s\":\"Oak and maple trees are nonconiferous because they have broad leaves instead of needles.\",\"p\":\"non-koh-NIF-er-us\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.conif.er.ous\",\"ps\":\"adjective\",\"t\":[\"flowers\",\"maps\",\"olatin\"]},{\"w\":\"nonconjectural\",\"d\":\"Not based on guesswork or speculation; grounded in verified facts or solid evidence rather than assumptions.\",\"s\":\"The scientist insisted that her findings were nonconjectural, backed by solid experimental data.\",\"p\":\"non-kun-JEK-chur-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.con.jec.tural\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonconjoined\",\"d\":\"Not joined or linked together; existing as separate, independent units that have not been combined or merged.\",\"s\":\"The two reports were nonconjoined, each standing as a completely separate document.\",\"p\":\"non-kun-JOIND\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.con.joined\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonconjoint\",\"d\":\"Not united or connected as a single combined unit; operating or existing independently rather than together.\",\"s\":\"The twins had nonconjoint schedules, each attending a different school across town.\",\"p\":\"non-kun-JOINT\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.con.joint\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonconjugative\",\"d\":\"Not capable of or relating to conjugation, particularly in biology referring to bacteria or other organisms that cannot transfer genetic material through direct cell-to-cell contact.\",\"s\":\"The bacteria carried a nonconjugative plasmid, so it could not transfer genetic material to neighboring cells.\",\"p\":\"non-KON-joo-gay-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.con.juga.tive\",\"ps\":\"adjective\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"nonconnotative\",\"d\":\"Not carrying any implied or associated meanings beyond a word's literal definition; having no emotional or cultural overtones.\",\"s\":\"The word 'table' is largely nonconnotative, carrying almost no emotional baggage for most readers.\",\"p\":\"non-KON-oh-tay-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.con.no.ta.tive\",\"ps\":\"adjective\",\"t\":[\"emotions\",\"wordwords\",\"olatin\"]},{\"w\":\"nonconscientious\",\"d\":\"Not showing careful attention, diligence, or a strong sense of right and wrong; lacking thoroughness or moral awareness in one's actions.\",\"s\":\"The nonconscientious student rushed through the assignment without checking a single answer.\",\"p\":\"non-kon-shee-EN-shus\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.con.sci.en.tious\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonconsecutive\",\"d\":\"Not following one after another in an unbroken sequence; having gaps or interruptions between items or events.\",\"s\":\"The teacher assigned nonconsecutive chapters, skipping from chapter two straight to chapter seven.\",\"p\":\"non-kun-SEK-yoo-tiv\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.con.sec.u.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonconsecutively\",\"d\":\"In a manner that is not sequential or continuous; with breaks or skips between items rather than in an uninterrupted order.\",\"s\":\"The events were listed nonconsecutively, jumping back and forth across different years.\",\"p\":\"non-kun-SEK-yoo-tiv-lee\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.con.sec.u.tive.ly\",\"ps\":\"adverb\",\"t\":[\"olatin\"]},{\"w\":\"nonconsensual\",\"d\":\"Done without the agreement or permission of all parties involved; occurring without mutual consent.\",\"s\":\"The students learned that any nonconsensual sharing of someone's personal photos is both wrong and illegal.\",\"p\":\"non-kun-SEN-shoo-ul\",\"o\":\"Latin\",\"y\":7,\"bp\":28,\"sy\":\"non.con.sen.su.al\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonconsensus\",\"d\":\"A state in which there is no general agreement or shared opinion among a group of people on a particular issue.\",\"s\":\"There was a clear nonconsensus among the panel members, with each expert holding a different opinion.\",\"p\":\"non-kun-SEN-sus\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.con.sen.sus\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonconsequent\",\"d\":\"Not following logically from what came before; lacking a proper cause-and-effect relationship with preceding statements or events.\",\"s\":\"The judge ruled that the minor infraction was nonconsequent to the larger crime being investigated.\",\"p\":\"non-KON-sih-kwent\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.con.se.quent\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonconsequential\",\"d\":\"Having no significant results or importance; not producing meaningful effects or outcomes worth considering.\",\"s\":\"The small typo in the report was nonconsequential and did not affect the overall results.\",\"p\":\"non-kon-sih-KWEN-shul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.con.se.quen.tial\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonconservation\",\"d\":\"The failure to preserve or maintain a quantity, resource, or property at a constant level, especially in physics where a quantity such as energy is not kept constant in a system.\",\"s\":\"The physics experiment demonstrated the nonconservation of energy in a system with significant heat loss.\",\"p\":\"non-kon-sur-VAY-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.con.ser.va.tion\",\"ps\":\"noun\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonconserved\",\"d\":\"Not maintained at a constant or unchanged level; in science, referring to a quantity or biological sequence that changes or varies rather than remaining stable.\",\"s\":\"The gene sequence was nonconserved across species, changing significantly as animals evolved.\",\"p\":\"non-kun-SURVD\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"non.con.served\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonconserving\",\"d\":\"Not acting to preserve or maintain something at a constant level; allowing a resource, quantity, or property to change or diminish.\",\"s\":\"A nonconserving system loses energy to the environment rather than keeping it locked inside.\",\"p\":\"non-kun-SUR-ving\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.con.serv.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonconsideration\",\"d\":\"The state of not being taken into account or given thought; a failure to weigh or evaluate something when making a decision.\",\"s\":\"The proposal's rejection was due to the committee's nonconsideration of the environmental impact.\",\"p\":\"non-kun-sid-ur-AY-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.con.sid.er.a.tion\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonconsolute\",\"d\":\"Describing two liquids or substances that do not dissolve into each other or form a homogeneous mixture when combined.\",\"s\":\"The two liquids were nonconsolute and separated into distinct layers when mixed together.\",\"p\":\"non-KON-suh-loot\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.con.so.lute\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonconsonantal\",\"d\":\"Not having the properties or qualities of a consonant; relating to sounds or letters that function as vowels or lack consonant characteristics.\",\"s\":\"Vowel sounds are nonconsonantal because they flow freely without the mouth blocking the airflow.\",\"p\":\"non-kon-suh-NAN-tul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.con.so.nan.tal\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonconspecific\",\"d\":\"Belonging to a different species; not of the same species as the organism being compared or studied.\",\"s\":\"The bird refused to mate with a nonconspecific partner from a closely related but different species.\",\"p\":\"non-kon-spuh-SIF-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.con.spe.cif.ic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonconstant\",\"d\":\"Not remaining the same or fixed; subject to change or variation over time or across different conditions.\",\"s\":\"The temperature in the lab was nonconstant, rising and falling unpredictably throughout the day.\",\"p\":\"non-KON-stunt\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.con.stant\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nonconstituency\",\"d\":\"The condition of not having or representing an organized group of voters or supporters; lacking a defined base of constituents.\",\"s\":\"The representative addressed the nonconstituency crowd even though they could not vote in her district.\",\"p\":\"non-kun-STICH-oo-en-see\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.con.stituen.cy\",\"ps\":\"noun\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"nonconstricted\",\"d\":\"Not squeezed, narrowed, or tightened; remaining open, wide, or unrestricted in flow or passage.\",\"s\":\"The wide hallway was nonconstricted, allowing students to move freely between classes.\",\"p\":\"non-kun-STRIK-tid\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.con.strict.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonconstricting\",\"d\":\"Not squeezing, narrowing, or tightening around something; allowing free movement or flow without applying pressure.\",\"s\":\"The doctor recommended nonconstricting clothing to help improve circulation in the patient's legs.\",\"p\":\"non-kun-STRIK-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.con.strict.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonconstructed\",\"d\":\"Not built, assembled, or created by human effort; arising naturally or occurring without deliberate fabrication.\",\"s\":\"The researchers studied the natural, nonconstructed wetland to see how it filtered water on its own.\",\"p\":\"non-kun-STRUK-tid\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.con.struct.ed\",\"ps\":\"adjective\",\"t\":[\"fabrics\",\"olatin\"]},{\"w\":\"nonconstruction\",\"d\":\"The absence of building or assembling; the state of not erecting structures or developing physical or conceptual frameworks.\",\"s\":\"The city's nonconstruction policy in the wetlands helped protect the local wildlife habitat.\",\"p\":\"non-kun-STRUK-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.con.struc.tion\",\"ps\":\"noun\",\"t\":[\"buildings\",\"olatin\"]},{\"w\":\"nonconstructive\",\"d\":\"Not helpful in building, improving, or advancing something; failing to contribute useful ideas, solutions, or progress.\",\"s\":\"The teacher reminded students that nonconstructive criticism only discourages others without offering any help.\",\"p\":\"non-kun-STRUK-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.con.struc.tive\",\"ps\":\"adjective\",\"t\":[\"buildings\",\"olatin\"]},{\"w\":\"nonconsular\",\"d\":\"Not related to or holding the office of a consul; describing a person or function that does not involve official diplomatic representation at a consulate.\",\"s\":\"The diplomat held a nonconsular position at the embassy, focusing on trade rather than visa services.\",\"p\":\"non-KON-suh-lur\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.con.sular\",\"ps\":\"adjective\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"nonconsulted\",\"d\":\"Not asked for input, advice, or an opinion; describing a person or group that was excluded from a decision-making process.\",\"s\":\"The nonconsulted team members felt left out when the final decision was announced without their input.\",\"p\":\"non-kun-SUL-tid\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.con.sult.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonconsulting\",\"d\":\"Not engaged in providing professional advice or guidance; describing a role or capacity that does not involve offering expert recommendations.\",\"s\":\"She took a nonconsulting role at the firm, preferring to focus on research rather than advising clients.\",\"p\":\"non-kun-SUL-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.con.sult.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonconsumer\",\"d\":\"A person or entity that does not purchase or use goods and services; someone who does not participate in the buying and consuming of products.\",\"s\":\"As a nonconsumer of processed foods, he grew most of his own vegetables in the backyard garden.\",\"p\":\"non-kun-SOO-mur\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.con.sumer\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonconsumerist\",\"d\":\"Not promoting or characterized by the belief that buying and owning goods is the most important goal; rejecting the values of a consumer-driven culture.\",\"s\":\"Her nonconsumerist lifestyle meant she rarely bought new things, preferring to repair or borrow instead.\",\"p\":\"non-kun-SOO-mur-ist\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.con.sumerist\",\"ps\":\"adjective\",\"t\":[\"character\",\"sports\",\"logic\",\"olatin\"]},{\"w\":\"nonconsuming\",\"d\":\"Not using up, burning through, or depleting a resource or material; existing or operating without causing destruction or exhaustion of something.\",\"s\":\"The nonconsuming nature of the experiment meant that the sample could be used again for further testing.\",\"p\":\"non-kun-SOO-ming\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.con.sum.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonconsumption\",\"d\":\"The deliberate or circumstantial act of not using, eating, or depleting goods or resources.\",\"s\":\"The study measured nonconsumption of sugary drinks among teenagers who switched to drinking water.\",\"p\":\"non-kun-SUMP-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.con.sump.tion\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"noncontact\",\"d\":\"Not involving physical touching between people or objects; describing activities or interactions that occur without direct physical contact.\",\"s\":\"The gym class played a noncontact version of football so nobody would get hurt.\",\"p\":\"non-KON-takt\",\"o\":\"Latin\",\"y\":7,\"bp\":29,\"sy\":\"non.con.tact\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncontacted\",\"d\":\"Not reached out to or communicated with; describing a person or group that has not been approached or given information.\",\"s\":\"The noncontacted families in the remote village had never interacted with the outside world.\",\"p\":\"non-KON-tak-tid\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.con.tact.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncontainerizable\",\"d\":\"Not capable of being packed or shipped in standard freight containers; too large, oddly shaped, or otherwise unsuitable for containerization.\",\"s\":\"The oversized machinery was noncontainerizable and had to be shipped on a special flatbed vessel.\",\"p\":\"non-kun-TAY-nur-eye-zuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.con.tainer.iz.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncontainerized\",\"d\":\"Not packed, stored, or transported in sealed freight containers; describing cargo or goods moved in bulk or loose form rather than in standardized boxes.\",\"s\":\"Noncontainerized cargo such as lumber is loaded loosely onto the ship's deck.\",\"p\":\"non-kun-TAY-nur-eyezd\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.con.tainer.ized\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncontaminant\",\"d\":\"A substance or agent that does not introduce harmful or impure elements into an environment, food, or material.\",\"s\":\"Scientists confirmed that the new chemical was a noncontaminant, safe to use near drinking water sources.\",\"p\":\"non-kun-TAM-ih-nunt\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.con.tam.i.nant\",\"ps\":\"noun\",\"t\":[\"ecology\",\"olatin\"]},{\"w\":\"noncontaminated\",\"d\":\"Not polluted, infected, or made impure by the introduction of harmful substances or organisms.\",\"s\":\"The hikers drank from the noncontaminated spring water after testing it with purification strips.\",\"p\":\"non-kun-TAM-ih-nay-tid\",\"o\":\"Latin\",\"y\":9,\"bp\":31,\"sy\":\"non.con.tam.i.nat.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncontaminative\",\"d\":\"Describing something that does not have the ability or tendency to introduce pollutants or harmful substances into another material or environment.\",\"s\":\"The hospital chose a noncontaminative cleaning solution that would not leave harmful residue on surfaces.\",\"p\":\"non-kun-TAM-ih-nay-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.con.tam.i.na.tive\",\"ps\":\"adjective\",\"t\":[\"ecology\",\"olatin\"]},{\"w\":\"noncontemporary\",\"d\":\"Not belonging to the same time period; referring to something or someone from a different era rather than the present day.\",\"s\":\"The museum displayed noncontemporary artwork from centuries past alongside modern pieces.\",\"p\":\"non-kun-TEM-puh-reh-ree\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.con.tem.po.rary\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"noncontender\",\"d\":\"A person, team, or thing that is not competing seriously for a prize, title, or position of importance.\",\"s\":\"The small team was considered a noncontender for the championship but surprised everyone by making it to the finals.\",\"p\":\"non-kun-TEN-der\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"non.con.tender\",\"ps\":\"noun\",\"t\":[\"sports\",\"olatin\"]},{\"w\":\"noncontending\",\"d\":\"Not actively competing, struggling, or striving for a win, title, or goal.\",\"s\":\"The noncontending players sat on the bench, cheering for their teammates without competing themselves.\",\"p\":\"non-kun-TEN-ding\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.con.tend.ing\",\"ps\":\"adjective\",\"t\":[\"sports\",\"olatin\"]},{\"w\":\"noncontested\",\"d\":\"Not challenged, disputed, or opposed by any party; accepted without argument or competition.\",\"s\":\"The election was noncontested since only one candidate had signed up to run for class president.\",\"p\":\"non-kun-TES-tid\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.con.test.ed\",\"ps\":\"adjective\",\"t\":[\"sports\",\"logic\",\"olatin\"]},{\"w\":\"noncontextual\",\"d\":\"Not related to or dependent on the surrounding circumstances, background, or setting in which something occurs or is understood.\",\"s\":\"The teacher warned that noncontextual reading of the poem would cause students to miss its deeper meaning.\",\"p\":\"non-kun-TEX-choo-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.con.tex.tu.al\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncontextually\",\"d\":\"In a manner that disregards or ignores the surrounding circumstances or setting that would normally help explain the meaning of something.\",\"s\":\"He quoted the author noncontextually, making it seem like she supported ideas she actually opposed.\",\"p\":\"non-kun-TEX-choo-ul-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":31,\"sy\":\"non.con.tex.tu.al.ly\",\"ps\":\"adverb\",\"t\":[\"olatin\"]},{\"w\":\"noncontiguous\",\"d\":\"Not touching, adjoining, or sharing a common border; describing areas or objects that are separated and do not connect directly.\",\"s\":\"Alaska and Hawaii are noncontiguous states, separated from the rest of the United States by other land or ocean.\",\"p\":\"non-kun-TIG-yoo-us\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.con.tigu.ous\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncontingent\",\"d\":\"Not dependent on or conditioned by any uncertain future event or circumstance; unconditional and absolute.\",\"s\":\"The reward was noncontingent, meaning students received it regardless of whether they had finished their work.\",\"p\":\"non-kun-TIN-junt\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.con.tin.gent\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncontinuable\",\"d\":\"Not capable of being extended, resumed, or carried forward beyond a certain point.\",\"s\":\"The expired contract was noncontinuable without a full renegotiation between both parties.\",\"p\":\"non-kun-TIN-yoo-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.con.tinu.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncontinuing\",\"d\":\"Not ongoing or persisting; describing something that stops or does not extend beyond a fixed point in time.\",\"s\":\"The noncontinuing nature of the grant meant the school had to find new funding after one year.\",\"p\":\"non-kun-TIN-yoo-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.con.tin.u.ing\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"noncontinuity\",\"d\":\"The state or quality of lacking an unbroken, connected sequence; the presence of gaps or interruptions in flow or progression.\",\"s\":\"The noncontinuity of the TV series frustrated fans who wanted to know how the story ended.\",\"p\":\"non-kon-tih-NYOO-ih-tee\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.con.ti.nu.ity\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"noncontoured\",\"d\":\"Lacking a defined or shaped outline; flat and without curves, ridges, or a sculpted profile.\",\"s\":\"The noncontoured seat was flat and hard, offering no support for long car rides.\",\"p\":\"non-KON-terd\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.con.toured\",\"ps\":\"adjective\",\"t\":[\"painting\",\"olatin\"]},{\"w\":\"noncontraband\",\"d\":\"Goods or items that are legal, permitted, and not prohibited from being transported, owned, or traded.\",\"s\":\"The customs officer confirmed that all items in the luggage were noncontraband and perfectly legal to bring in.\",\"p\":\"non-KON-truh-band\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.con.tra.band\",\"ps\":\"noun\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"noncontract\",\"d\":\"Not governed by, established through, or related to a formal legally binding agreement between parties.\",\"s\":\"The noncontract workers were paid by the hour without any long-term agreement in place.\",\"p\":\"nah-NKAH-ntra-kt\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"naa.nkaa.ntrae.kt\",\"ps\":\"adjective\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"noncontracted\",\"d\":\"Not bound by or established through a formal written agreement; operating or existing outside the terms of a contract.\",\"s\":\"The noncontracted employees had more flexibility but fewer guaranteed hours each week.\",\"p\":\"non-kun-TRAKT-id\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.con.tract.ed\",\"ps\":\"adjective\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"noncontractile\",\"d\":\"Unable to contract, shorten, or tighten; describing tissue, especially muscle, that lacks the ability to pull together.\",\"s\":\"Unlike muscle tissue, noncontractile tissue in the body does not squeeze or tighten on its own.\",\"p\":\"non-kun-TRAK-tul\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.con.trac.tile\",\"ps\":\"adjective\",\"t\":[\"body\",\"law\",\"olatin\"]},{\"w\":\"noncontracting\",\"d\":\"Not entering into or forming a binding agreement; also describing tissue or material that is not shrinking or tightening.\",\"s\":\"The noncontracting parties were still invited to observe the signing ceremony as witnesses.\",\"p\":\"non-kun-TRAKT-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.con.tract.ing\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"noncontractor\",\"d\":\"A person or organization that performs work or services without being officially licensed, hired, or bound under a formal contractor agreement.\",\"s\":\"As a noncontractor, she handled repairs herself rather than hiring an outside company.\",\"p\":\"non-kun-TRAK-ter\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.con.trac.tor\",\"ps\":\"noun\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"noncontractual\",\"d\":\"Not involving, required by, or based on the terms of a formal contract or legally binding agreement.\",\"s\":\"Their noncontractual agreement relied entirely on trust, with no written document to back it up.\",\"p\":\"non-kun-TRAK-choo-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.con.trac.tu.al\",\"ps\":\"adjective\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"noncontractually\",\"d\":\"In a manner that is not governed by or connected to the terms of a formal contract or binding legal agreement.\",\"s\":\"They agreed noncontractually to share resources, though either side could back out at any time.\",\"p\":\"non-kun-TRAK-choo-ul-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.con.trac.tu.al.ly\",\"ps\":\"adverb\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"noncontradictory\",\"d\":\"Not containing or involving contradictions; describing statements, ideas, or propositions that are consistent and do not conflict with each other.\",\"s\":\"The scientist's findings were noncontradictory, all pointing consistently toward the same conclusion.\",\"p\":\"non-kon-truh-DIK-tuh-ree\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.con.tra.dic.to.ry\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncontrastive\",\"d\":\"Not serving to highlight differences or create contrast; describing elements that blend together rather than standing out against one another.\",\"s\":\"The two shades of gray in the painting were so noncontrastive that they blended into each other.\",\"p\":\"non-kun-TRAS-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.con.trastive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncontributor\",\"d\":\"A person or entity that does not provide input, effort, money, or support toward a shared goal, project, or fund.\",\"s\":\"Every team member contributed to the project except one noncontributor who missed every meeting.\",\"p\":\"non-kun-TRIB-yoo-ter\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.con.trib.u.tor\",\"ps\":\"noun\",\"t\":[\"economy\",\"sports\",\"olatin\"]},{\"w\":\"noncontributory\",\"d\":\"Not requiring or involving contributions, especially describing a pension or benefit plan funded entirely by an employer without employee payments.\",\"s\":\"The employees appreciated the noncontributory pension plan because the company paid all the costs.\",\"p\":\"non-kun-TRIB-yoo-tor-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":31,\"sy\":\"non.con.trib.u.to.ry\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncontrollable\",\"d\":\"Not able to be managed, directed, or kept within limits; impossible to regulate or restrain.\",\"s\":\"The wildfire spread in a noncontrollable manner, forcing thousands to evacuate.\",\"p\":\"non-kun-TROH-luh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.con.trol.lable\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncontrolled\",\"d\":\"Not subject to regulation, supervision, or restraint; operating or existing without oversight or imposed limits.\",\"s\":\"The noncontrolled experiment produced unreliable results because too many variables were left unchecked.\",\"p\":\"non-kun-TROHLD\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.con.trolled\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncontrolling\",\"d\":\"Not having or exercising authority or dominance over others; describing a minority ownership stake that does not direct major decisions.\",\"s\":\"The noncontrolling shareholders had little say in the company's major decisions.\",\"p\":\"non-kun-TROH-ling\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.con.trol.ling\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"nonconvergent\",\"d\":\"(of lines, planes, or surfaces) never meeting or crossing; tending to move apart or remain at a constant distance rather than coming together.\",\"s\":\"The two theories were nonconvergent, heading in completely opposite directions with no common ground.\",\"p\":\"non-kun-VER-junt\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.con.ver.gent\",\"ps\":\"adjective\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nonconverging\",\"d\":\"Not coming together toward a common point; describing paths, lines, or trends that continue to move apart or remain parallel rather than meeting.\",\"s\":\"The nonconverging paths in the maze led explorers away from the center rather than toward it.\",\"p\":\"non-kun-VER-jing\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.con.verg.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonconversant\",\"d\":\"Not familiar with or knowledgeable about a particular subject, skill, or area; lacking experience or fluency in something.\",\"s\":\"She was nonconversant with the new software, so her colleague patiently walked her through each step.\",\"p\":\"non-KON-ver-sunt\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.con.ver.sant\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonconversational\",\"d\":\"Not having the relaxed, informal, and interactive qualities of natural conversation; stiff, scripted, or impersonal in tone or style.\",\"s\":\"His nonconversational tone during the lecture made it hard for students to feel engaged.\",\"p\":\"non-kon-ver-SAY-shun-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.con.ver.sa.tion.al\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonconvincing\",\"d\":\"Failing to persuade or win over an audience; not effective at making others believe or accept an argument or claim.\",\"s\":\"The student's nonconvincing excuse for missing homework made the teacher raise an eyebrow.\",\"p\":\"non-kun-VIN-sing\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.con.vinc.ing\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonconvulsive\",\"d\":\"Not involving or characterized by sudden, uncontrolled muscle contractions or seizures; describing a calm or stable physical state.\",\"s\":\"The doctor noted that the patient's seizure was nonconvulsive, meaning there were no visible shaking movements.\",\"p\":\"non-kun-VUL-siv\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.con.vul.sive\",\"ps\":\"adjective\",\"t\":[\"body\",\"law\",\"character\",\"olatin\"]},{\"w\":\"noncook\",\"d\":\"A person who does not cook or has little to no skill or interest in preparing food.\",\"s\":\"As a self-described noncook, Marcus relied on microwave meals and takeout every night.\",\"p\":\"NON-kook\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.cook\",\"ps\":\"noun\",\"t\":[\"culinary\",\"olatin\"]},{\"w\":\"noncooked\",\"d\":\"Not prepared by heating; describing food that is raw or unprocessed by any cooking method.\",\"s\":\"The recipe called for noncooked oats to be stirred directly into the overnight mixture.\",\"p\":\"NON-kookt\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.cooked\",\"ps\":\"adjective\",\"t\":[\"culinary\",\"olatin\"]},{\"w\":\"noncooking\",\"d\":\"Not involving the preparation or heating of food; describing activities, appliances, or spaces that have no role in food preparation.\",\"s\":\"She preferred noncooking recipes like salads and smoothies on busy weeknights.\",\"p\":\"NON-koo-king\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.cook.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncooled\",\"d\":\"Not reduced in temperature by a cooling system or mechanism; describing equipment, spaces, or substances that have not been chilled or refrigerated.\",\"s\":\"The noncooled server room quickly overheated during the summer power outage.\",\"p\":\"NON-koold\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.cooled\",\"ps\":\"adjective\",\"t\":[\"tools\",\"olatin\"]},{\"w\":\"noncooperating\",\"d\":\"Refusing or failing to work together with others toward a common goal; not participating in joint efforts or collaborative activities.\",\"s\":\"The noncooperating witness refused to answer any of the detective's questions.\",\"p\":\"non-koh-AH-puh-ray-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.co.op.er.at.ing\",\"ps\":\"adjective\",\"t\":[\"sports\",\"olatin\"]},{\"w\":\"noncooperator\",\"d\":\"A person who refuses to cooperate or work jointly with others, especially in an organized effort or group endeavor.\",\"s\":\"The noncooperator in the group project left his teammates scrambling to finish the work alone.\",\"p\":\"non-koh-AH-puh-ray-tor\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.co.op.er.a.tor\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"noncoordinated\",\"d\":\"Not organized or arranged in a smooth, unified way; lacking the careful planning that brings different parts into harmony.\",\"s\":\"The noncoordinated rescue effort caused confusion, with multiple teams arriving at the wrong locations.\",\"p\":\"non-koh-AWR-dih-nay-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.co.or.di.nat.ed\",\"ps\":\"adjective\",\"t\":[\"music\",\"olatin\"]},{\"w\":\"noncoordinating\",\"d\":\"Not acting to bring separate elements into a balanced or organized relationship; failing to synchronize or align efforts.\",\"s\":\"The noncoordinating departments each solved the same problem separately, wasting valuable resources.\",\"p\":\"non-koh-AWR-dih-nay-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":31,\"sy\":\"non.co.or.di.nat.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncoplanar\",\"d\":\"Describing points, lines, or figures that do not all lie within the same flat plane in geometry.\",\"s\":\"The three-dimensional sculpture was built with noncoplanar supports that jutted out in all directions.\",\"p\":\"non-koh-PLAY-ner\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.copla.nar\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"noncoplanarity\",\"d\":\"The condition or property of geometric elements that do not all exist within a single flat plane.\",\"s\":\"The engineer calculated the noncoplanarity of the antenna supports to ensure the structure would be stable.\",\"p\":\"non-koh-play-NAIR-ih-tee\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.copla.nari.ty\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"noncopper\",\"d\":\"Not consisting of or containing copper; made from or relating to materials other than the metal copper.\",\"s\":\"The electrician switched to noncopper wiring in sections of the building to reduce costs.\",\"p\":\"non-KAH-per\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.cop.per\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"noncopular\",\"d\":\"In grammar, describing a verb or construction that does not function as a linking verb connecting a subject to its complement.\",\"s\":\"In the sentence 'She runs fast,' the verb is noncopular because it expresses action, not a state of being.\",\"p\":\"non-KAH-pyoo-ler\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.cop.u.lar\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"noncopyrightable\",\"d\":\"Describing creative work or information that cannot be protected by copyright law and is therefore freely available for anyone to use.\",\"s\":\"Basic facts and ideas are noncopyrightable, meaning anyone can use them freely in their writing.\",\"p\":\"non-KAH-pee-ry-tuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.copy.rightable\",\"ps\":\"adjective\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"noncopyrighted\",\"d\":\"Not protected by copyright; describing material that has no legal copyright claim and may be used freely by the public.\",\"s\":\"The teacher used noncopyrighted illustrations so students could reproduce them in their projects.\",\"p\":\"non-KAH-pee-ry-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.copy.right.ed\",\"ps\":\"adjective\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"noncore\",\"d\":\"Not belonging to the essential, central, or most important part of something; describing secondary or peripheral elements of a system or organization.\",\"s\":\"The company sold its noncore divisions to focus on its main product line.\",\"p\":\"NAH-NKAW-r\",\"o\":\"Latin\",\"y\":7,\"bp\":19,\"sy\":\"naa.nkao.r\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncorneal\",\"d\":\"Not relating to or involving the cornea, the transparent front surface of the eye.\",\"s\":\"The eye doctor noted that the irritation was noncorneal, originating from the eyelid rather than the cornea.\",\"p\":\"non-KAWR-nee-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.corneal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncoronary\",\"d\":\"Not relating to the coronary arteries or to the heart's blood supply; describing conditions or structures unrelated to cardiac circulation.\",\"s\":\"The cardiologist determined that the chest pain was noncoronary and likely caused by muscle strain.\",\"p\":\"non-KAWR-uh-nair-ee\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.coro.nary\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"noncorotational\",\"d\":\"Not rotating together in the same direction or at the same rate; describing objects or systems that do not share a common rotation.\",\"s\":\"Scientists studied the noncorotational motion of the planet's magnetic field relative to its surface.\",\"p\":\"non-koh-roh-TAY-shun-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.coro.ta.tion.al\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncorporate\",\"d\":\"Not organized as or belonging to a corporation; relating to individuals, partnerships, or entities that lack corporate legal structure.\",\"s\":\"The noncorporate bakery was a small family business with no shareholders or board of directors.\",\"p\":\"nah-NKAW-rpruh-t\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"naa.nkao.rprah.t\",\"ps\":\"adjective\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"noncorporation\",\"d\":\"An organization or group that has not been legally established as a corporation and therefore lacks the formal structure and rights of one.\",\"s\":\"As a noncorporation, the community garden group operated under simple volunteer agreements rather than legal bylaws.\",\"p\":\"non-kawr-puh-RAY-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.cor.po.ra.tion\",\"ps\":\"noun\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"noncorporeal\",\"d\":\"Not having a physical body or material form; existing only as spirit, thought, or abstract concept rather than as tangible matter.\",\"s\":\"Ghosts are often described as noncorporeal beings that exist without a physical body.\",\"p\":\"non-kawr-PAW-ree-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":39,\"sy\":\"non.cor.po.re.al\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncorrect\",\"d\":\"Not accurate or right; failing to meet the standard of being correct or error-free.\",\"s\":\"The teacher marked the noncorrect answers in red so students could review their mistakes.\",\"p\":\"non-kuh-REKT\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.cor.rect\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncorrected\",\"d\":\"Not having been reviewed and fixed; remaining in an unchanged state with errors or inaccuracies still present.\",\"s\":\"The noncorrected draft was full of spelling errors that the editor still needed to fix.\",\"p\":\"non-kuh-REK-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.cor.rect.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncorrecting\",\"d\":\"Not making adjustments to fix errors or inaccuracies; failing to identify and remedy mistakes as they occur.\",\"s\":\"The noncorrecting auto-fill feature on the old keyboard frustrated the novelist trying to type quickly.\",\"p\":\"non-kuh-REK-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.cor.rect.ing\",\"ps\":\"adjective\",\"t\":[\"pharmacy\",\"olatin\"]},{\"w\":\"noncorrective\",\"d\":\"Not designed or intended to fix, improve, or compensate for a deficiency; describing something that makes no corrective adjustment.\",\"s\":\"The noncorrective lenses in the frames were purely decorative and had no vision-fixing power.\",\"p\":\"non-kuh-REK-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.cor.rec.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncorrelatable\",\"d\":\"Impossible to connect or establish a meaningful relationship between; describing data or variables that cannot be shown to correspond with each other.\",\"s\":\"The two sets of data were noncorrelatable because they measured completely unrelated phenomena.\",\"p\":\"non-kawr-uh-LAY-tuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.cor.re.lat.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncorrelated\",\"d\":\"Having no demonstrated statistical or logical relationship; describing two or more variables that do not move or change in relation to each other.\",\"s\":\"Researchers found that ice cream sales and crime rates, though they rise together in summer, are actually noncorrelated in any meaningful way.\",\"p\":\"non-KAWR-uh-lay-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.cor.re.lat.ed\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"noncorrelating\",\"d\":\"Failing to show a consistent relationship or pattern between two or more sets of data, events, or variables.\",\"s\":\"The noncorrelating variables in the study made it impossible to draw any cause-and-effect conclusions.\",\"p\":\"non-KAWR-uh-lay-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.cor.re.lat.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncorrelation\",\"d\":\"The absence of any measurable or meaningful relationship between two variables, events, or sets of data.\",\"s\":\"The scientist reported a noncorrelation between the students' shoe sizes and their math scores.\",\"p\":\"non-kawr-uh-LAY-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.cor.re.la.tion\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"noncorrelative\",\"d\":\"Not having a reciprocal or corresponding relationship; describing terms, ideas, or elements that do not mutually depend on or relate to each other.\",\"s\":\"The two symptoms were noncorrelative, appearing in patients for completely different reasons.\",\"p\":\"non-kuh-REL-uh-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.cor.rel.a.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncorrespondence\",\"d\":\"The state of not matching, agreeing, or communicating; a lack of agreement or connection between two things that should align.\",\"s\":\"The noncorrespondence between the map and the actual terrain confused the hikers on the trail.\",\"p\":\"non-kawr-uh-SPAHN-dents\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.cor.re.spon.dence\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"noncorridor\",\"d\":\"An area or region that does not serve as a passage or connecting route between two places, especially in geography or ecology.\",\"s\":\"The architect designed a noncorridor layout where rooms opened directly into a central space.\",\"p\":\"non-KAWR-ih-dor\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"non.cor.ri.dor\",\"ps\":\"adjective\",\"t\":[\"ecology\",\"maps\",\"olatin\"]},{\"w\":\"noncorrodible\",\"d\":\"Resistant to or incapable of being worn away by chemical reactions such as rust or oxidation; describing materials that do not corrode.\",\"s\":\"The bridge was built with noncorrodible alloys so it would last centuries without rusting.\",\"p\":\"non-kuh-ROH-duh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.cor.rodi.ble\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"noncorrugated\",\"d\":\"Having a smooth, flat surface without ridges, grooves, or wrinkled folds; not shaped into a corrugated pattern.\",\"s\":\"The package was shipped in a noncorrugated box, which unfortunately offered less cushioning.\",\"p\":\"non-KAWR-uh-gay-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.cor.ru.gat.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncorrupt\",\"d\":\"Free from dishonesty, bribery, or moral wrongdoing; describing a person or system that operates with complete integrity.\",\"s\":\"The voters hoped to elect a noncorrupt official who would spend their tax money honestly.\",\"p\":\"non-kuh-RUPT\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.cor.rupt\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"noncorrupted\",\"d\":\"Not damaged, altered, or made impure by outside interference; remaining in its original, uncorrupted, and honest state.\",\"s\":\"The noncorrupted data files were recovered safely after the computer crash.\",\"p\":\"non-kuh-RUP-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.cor.rupt.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncorrupting\",\"d\":\"Not causing moral, ethical, or physical degradation; describing an influence or substance that does not lead to corruption or decay.\",\"s\":\"Scientists searched for a noncorrupting storage medium that would preserve records forever.\",\"p\":\"non-kuh-RUP-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.cor.rupt.ing\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"logic\",\"olatin\"]},{\"w\":\"noncortical\",\"d\":\"Not relating to or located in the cortex, especially the outer layer of the brain; describing neural or biological processes that originate elsewhere.\",\"s\":\"The neurologist explained that the seizure originated in a noncortical region of the brain.\",\"p\":\"non-KAWR-tih-kul\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.cor.ti.cal\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"noncorticosteroid\",\"d\":\"A drug or substance that reduces inflammation or treats medical conditions without belonging to the corticosteroid class of hormones.\",\"s\":\"The doctor prescribed a noncorticosteroid medication to avoid the side effects of steroids.\",\"p\":\"non-kawr-tih-koh-STAIR-oyd\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.cor.ti.cos.teroid\",\"ps\":\"noun\",\"t\":[\"body\",\"disease\",\"pharmacy\",\"olatin\"]},{\"w\":\"noncorticosteroidal\",\"d\":\"Describing a treatment, drug, or approach that does not involve or rely on corticosteroid hormones to achieve its effect.\",\"s\":\"The researcher studied noncorticosteroidal treatments for reducing inflammation in athletes.\",\"p\":\"non-kawr-tih-koh-stuh-ROY-dul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.cor.ti.cos.teroidal\",\"ps\":\"adjective\",\"t\":[\"pharmacy\",\"olatin\"]},{\"w\":\"noncosmetic\",\"d\":\"Not related to improving appearance; describing a medical procedure, product, or treatment intended for health or function rather than beauty.\",\"s\":\"The surgeon insisted the procedure was entirely noncosmetic and medically necessary.\",\"p\":\"non-kahz-MET-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.cos.met.ic\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"noncosmopolitan\",\"d\":\"Not characteristic of or open to the wider world; limited in cultural exposure or experience to a particular region or community.\",\"s\":\"The small village felt decidedly noncosmopolitan, with everyone knowing their neighbor's name.\",\"p\":\"non-kahz-muh-PAH-lih-tun\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.cos.mopoli.tan\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncototient\",\"d\":\"In number theory, a positive integer that cannot be expressed as the difference between a number and its count of relative primes up to that number.\",\"s\":\"In number theory class, we listed which integers were noncototient values.\",\"p\":\"non-koh-TOH-shunt\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.co.to.tient\",\"ps\":\"noun\",\"t\":[\"royalty\",\"logic\",\"numbers\",\"olatin\"]},{\"w\":\"noncotton\",\"d\":\"Not made from or containing cotton fibers; describing fabric, clothing, or material produced from synthetic or other natural sources.\",\"s\":\"She preferred noncotton fabrics in the summer because they dried faster after rain.\",\"p\":\"non-KAH-tun\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.cot.ton\",\"ps\":\"adjective\",\"t\":[\"fabrics\",\"olatin\"]},{\"w\":\"noncount\",\"d\":\"Referring to a noun that cannot be counted or used with a number, such as 'water' or 'air,' because it represents a mass or abstract concept rather than individual units.\",\"s\":\"In English class, we learned that 'water' is a noncount noun and cannot be pluralized easily.\",\"p\":\"NON-kownt\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.count\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"wordwords\",\"olatin\"]},{\"w\":\"noncountable\",\"d\":\"Describing something that cannot be counted or enumerated individually, especially a noun representing a substance or concept without distinct units.\",\"s\":\"Air is a noncountable substance because you cannot say 'one air, two airs.'.\",\"p\":\"non-KOWN-tuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.count.able\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"noncountry\",\"d\":\"A territory or region that does not hold the official status of a recognized sovereign country, often used in political or geographical contexts.\",\"s\":\"The territory existed in a strange legal gray area, considered a noncountry by international law.\",\"p\":\"non-KUN-tree\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.coun.try\",\"ps\":\"noun\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"noncounty\",\"d\":\"Relating to an area, organization, or jurisdiction that does not belong to or fall under the authority of a county.\",\"s\":\"The new city was incorporated as a noncounty municipality with its own governing charter.\",\"p\":\"non-KOWN-tee\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.coun.ty\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"noncoupled\",\"d\":\"Not joined, linked, or connected to another unit or system; describing two things that operate independently without being attached.\",\"s\":\"The noncoupled engine components vibrated independently, which reduced overall efficiency.\",\"p\":\"non-KUP-uld\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.cou.pled\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncovariant\",\"d\":\"In mathematics or physics, describing a quantity or equation that does not change in the same way, or together, under a given transformation or change of coordinates.\",\"s\":\"The physics equation was noncovariant, meaning it changed form depending on the reference frame.\",\"p\":\"non-koh-VAIR-ee-unt\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.co.vari.ant\",\"ps\":\"adjective\",\"t\":[\"physics\",\"maps\",\"numbers\",\"olatin\"]},{\"w\":\"noncoverage\",\"d\":\"The state of not being covered, included, or protected by an insurance plan, policy, or media report.\",\"s\":\"The insurance letter explained the noncoverage of dental procedures under her current plan.\",\"p\":\"non-KUV-er-ij\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"non.cov.er.age\",\"ps\":\"noun\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"noncovered\",\"d\":\"Not included under the protection or scope of an insurance plan, agreement, or policy; left without coverage.\",\"s\":\"The noncovered expenses added up quickly and surprised the family at billing time.\",\"p\":\"non-KUV-erd\",\"o\":\"Latin\",\"y\":7,\"bp\":29,\"sy\":\"non.cov.ered\",\"ps\":\"adjective\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"noncow\",\"d\":\"Any animal or organism that is not a cow; used in agricultural or biological contexts to distinguish cattle from other animals.\",\"s\":\"The farmer sorted the animals into cow and noncow categories for the veterinary survey.\",\"p\":\"non-KOW\",\"o\":\"Latin\",\"y\":8,\"bp\":18,\"sy\":\"non.cow\",\"ps\":\"noun\",\"t\":[\"animals\",\"farming\",\"olatin\"]},{\"w\":\"noncowboy\",\"d\":\"A person who is not a cowboy and does not engage in the lifestyle, work, or culture traditionally associated with cowboys.\",\"s\":\"As a noncowboy, Marcus struggled to stay on the horse for more than a few seconds.\",\"p\":\"non-KOW-boy\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.cow.boy\",\"ps\":\"noun\",\"t\":[\"festivals\",\"character\",\"olatin\"]},{\"w\":\"noncranial\",\"d\":\"Not relating to or located in the cranium, or skull; describing bones, nerves, or structures that are found outside the skull.\",\"s\":\"The injury was noncranial, so doctors were relieved there was no damage to the skull.\",\"p\":\"non-KRAY-nee-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.cra.nial\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"noncraniofacial\",\"d\":\"Not pertaining to the combined region of the skull and face; describing conditions, surgeries, or structures unrelated to the craniofacial area.\",\"s\":\"The birth defect was classified as noncraniofacial because it affected the limbs, not the head.\",\"p\":\"non-kray-nee-oh-FAY-shul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.cran.io.fa.cial\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"noncreaky\",\"d\":\"Not making a harsh squeaking or groaning sound when moved or used; describing a floor, door, or object that moves silently and smoothly.\",\"s\":\"The carpenter installed new floorboards that were completely noncreaky, even under heavy footsteps.\",\"p\":\"non-KREE-kee\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.creaky\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncreated\",\"d\":\"Not brought into existence by any act of creation; describing something that was never made or produced, often used in philosophical or theological discussions.\",\"s\":\"Some philosophers argue that the universe is noncreated, existing without a beginning cause.\",\"p\":\"non-kree-AY-ted\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.cre.at.ed\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"noncreational\",\"d\":\"Not related to or involving the act of creation; describing a process, theory, or concept that does not involve creating something new.\",\"s\":\"The museum exhibit took a noncreational perspective, focusing on natural forces rather than divine design.\",\"p\":\"non-kree-AY-shun-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.cre.ation.al\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"noncreationary\",\"d\":\"Not based on or supporting the idea of creation; describing a viewpoint or approach that does not rely on the concept of things being created.\",\"s\":\"Her noncreationary worldview led her to study evolutionary biology with great enthusiasm.\",\"p\":\"non-kree-AY-shun-air-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.cre.ation.ary\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncreationist\",\"d\":\"A person who does not believe in creationism, the idea that the universe and living things were created by a divine being, typically accepting scientific explanations instead.\",\"s\":\"As a noncreationist, he believed life arose through natural processes over billions of years.\",\"p\":\"non-kree-AY-shun-ist\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.cre.ation.ist\",\"ps\":\"noun\",\"t\":[\"astronomy\",\"olatin\"]},{\"w\":\"noncreative\",\"d\":\"Lacking imagination, originality, or the ability to produce new ideas; describing a task, person, or approach that does not involve creativity.\",\"s\":\"The noncreative assignment required students to copy facts rather than express original ideas.\",\"p\":\"non-kree-AY-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.cre.ative\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncreativity\",\"d\":\"The complete absence or lack of creative thought, originality, or imaginative ability in a person, work, or process.\",\"s\":\"Critics blamed the film's failure on the noncreativity of a script full of tired clichés.\",\"p\":\"non-kree-ay-TIV-ih-tee\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.cre.ativ.i.ty\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"noncreator\",\"d\":\"A person or entity that did not bring something into existence; one who does not create or originate anything.\",\"s\":\"As a noncreator of the artwork, she had no legal copyright over the painting.\",\"p\":\"non-kree-AY-tor\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.cre.ator\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"noncredentialled\",\"d\":\"Not holding official qualifications, certifications, or credentials required for a particular profession or position.\",\"s\":\"The noncredentialled volunteer was enthusiastic but lacked the official qualifications for the role.\",\"p\":\"non-krih-DEN-shald\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.cre.den.tialled\",\"ps\":\"adjective\",\"t\":[\"jobs\",\"olatin\"]},{\"w\":\"noncredible\",\"d\":\"Not believable, trustworthy, or capable of being accepted as true; lacking the qualities that would make something or someone convincing.\",\"s\":\"The witness's story seemed noncredible because it changed every time she told it.\",\"p\":\"non-KRED-ih-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"non.cred.i.ble\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncredited\",\"d\":\"Not given official credit, recognition, or acknowledgment for work, contributions, or academic courses completed.\",\"s\":\"The background actors were noncredited, their names never appearing in the film's ending scroll.\",\"p\":\"non-KRED-ih-ted\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.cred.it.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncreditor\",\"d\":\"A person or organization that is not owed money by another party and therefore does not hold the status of a creditor in a financial or legal arrangement.\",\"s\":\"As a noncreditor, she had no legal claim to the money owed by the bankrupt company.\",\"p\":\"non-KRED-ih-tor\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.cred.i.tor\",\"ps\":\"noun\",\"t\":[\"law\",\"economy\",\"olatin\"]},{\"w\":\"noncreditworthy\",\"d\":\"Not considered reliable or trustworthy enough to receive a loan or financial credit, usually due to a poor financial history or lack of assets.\",\"s\":\"The bank rejected the application because the business was deemed noncreditworthy after years of losses.\",\"p\":\"non-KRED-it-wur-thee\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.cred.it.wor.thy\",\"ps\":\"adjective\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"noncremated\",\"d\":\"Not having been cremated; describing human or animal remains that were not burned as part of a funeral or disposal process.\",\"s\":\"The family chose a traditional burial, leaving the body noncremated according to their beliefs.\",\"p\":\"non-KREE-may-ted\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.cre.mat.ed\",\"ps\":\"adjective\",\"t\":[\"animals\",\"olatin\"]},{\"w\":\"noncrime\",\"d\":\"An act or behavior that is not considered a crime under the law; something that may be controversial or unusual but does not violate any legal statute.\",\"s\":\"Jaywalking is sometimes called a noncrime because penalties are rarely enforced in many cities.\",\"p\":\"non-KRYM\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.crime\",\"ps\":\"noun\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"noncriminological\",\"d\":\"Not related to criminology, the scientific study of crime, criminals, and the criminal justice system.\",\"s\":\"The professor took a noncriminological approach to studying poverty, focusing on economic factors rather than criminal behavior.\",\"p\":\"non-krim-ih-nuh-LOJ-ih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":33,\"sy\":\"non.crim.i.no.log.i.cal\",\"ps\":\"adjective\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"noncritic\",\"d\":\"A person who does not analyze, judge, or offer criticism of others' work, ideas, or performances.\",\"s\":\"As a noncritic, she simply enjoyed the movie without analyzing every scene.\",\"p\":\"non-KRIT-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.crit.ic\",\"ps\":\"noun\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"noncritically\",\"d\":\"In a manner that does not involve critical judgment, analysis, or evaluation; accepting or approaching something without scrutiny.\",\"s\":\"He noncritically accepted all the information in the article without questioning its sources.\",\"p\":\"non-KRIT-ih-kul-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.crit.i.cal.ly\",\"ps\":\"adverb\",\"t\":[\"olatin\"]},{\"w\":\"noncrop\",\"d\":\"Referring to plants, land, or agricultural products that are not grown or used as commercial or food crops.\",\"s\":\"The farmer left noncrop plants growing along the fence to attract helpful insects.\",\"p\":\"non-KROP\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.crop\",\"ps\":\"adjective\",\"t\":[\"botany\",\"farming\",\"economy\",\"olatin\"]},{\"w\":\"noncrossover\",\"d\":\"In genetics, describing a chromosome or organism in which the genetic material did not exchange segments with its paired chromosome during cell division.\",\"s\":\"Scientists studied noncrossover events in genetics to understand when chromosomes fail to exchange segments.\",\"p\":\"non-KROS-oh-ver\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.crossover\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"noncruciferous\",\"d\":\"Not belonging to the cruciferous family of plants, which includes vegetables like broccoli, cabbage, and cauliflower, known for their cross-shaped flowers.\",\"s\":\"The dietitian noted that spinach is a noncruciferous vegetable, unlike broccoli or cabbage.\",\"p\":\"non-kroo-SIF-er-us\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.cru.cif.er.ous\",\"ps\":\"adjective\",\"t\":[\"botany\",\"flowers\",\"spices\",\"kinship\",\"olatin\"]},{\"w\":\"noncrumbly\",\"d\":\"Not prone to breaking apart into small pieces or crumbs; describing a food or material that holds together well without falling apart.\",\"s\":\"The baker perfected a noncrumbly cookie that held together perfectly for school lunches.\",\"p\":\"non-KRUM-blee\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.crumbly\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncrushable\",\"d\":\"Unable to be crushed, flattened, or destroyed by pressure; describing a material or object that maintains its shape and structure under force.\",\"s\":\"The engineer designed a noncrushable container to safely transport delicate scientific instruments.\",\"p\":\"non-KRUSH-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.crush.able\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"noncrustacean\",\"d\":\"Any aquatic or land animal that does not belong to the crustacean group, which includes shrimp, crabs, and lobsters.\",\"s\":\"The biologist clarified that insects are noncrustacean arthropods, despite sharing some similarities with crabs.\",\"p\":\"non-krus-TAY-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.crus.tacean\",\"ps\":\"noun\",\"t\":[\"animals\",\"marine\",\"olatin\"]},{\"w\":\"noncrustal\",\"d\":\"Not relating to or found within the Earth's crust; describing geological materials or processes that originate in the mantle or deeper layers of the Earth.\",\"s\":\"The geologist's research focused on noncrustal sources of heat deep within the Earth's mantle.\",\"p\":\"non-KRUS-tul\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.crustal\",\"ps\":\"adjective\",\"t\":[\"minerals\",\"olatin\"]},{\"w\":\"noncrustose\",\"d\":\"In botany, describing a lichen or similar organism that does not form a crust-like layer firmly attached to a surface such as rock or bark.\",\"s\":\"The noncrustose lichen grew in leafy layers rather than forming a flat crust on the rock.\",\"p\":\"non-KRUS-tohs\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.crus.tose\",\"ps\":\"adjective\",\"t\":[\"botany\",\"minerals\",\"olatin\"]},{\"w\":\"noncryogenic\",\"d\":\"Not involving or related to extremely low temperatures; describing a process, material, or technology that does not require or operate at cryogenic conditions.\",\"s\":\"The lab stored most chemicals in noncryogenic conditions at room temperature.\",\"p\":\"non-kry-oh-JEN-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"non.cryo.genic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncryptic\",\"d\":\"Not hidden, mysterious, or difficult to understand; open and straightforward in meaning.\",\"s\":\"The teacher's noncryptic instructions made it easy for every student in the class to understand exactly what the assignment required.\",\"p\":\"non-KRIP-tik\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.cryp.tic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncryptographic\",\"d\":\"Not relating to or involving the use of secret codes or encryption techniques used to protect information.\",\"s\":\"The scientist stored her basic lab notes in a noncryptographic file, since the data did not need to be kept secret from anyone.\",\"p\":\"non-krip-toh-GRAF-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.cryp.to.graph.ic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncrystal\",\"d\":\"A solid material that lacks the regular, repeating internal structure characteristic of a true crystal.\",\"s\":\"Glass is a common noncrystal because its atoms are arranged randomly rather than in the precise, orderly pattern found in quartz.\",\"p\":\"non-KRIS-tul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.crys.tal\",\"ps\":\"noun\",\"t\":[\"minerals\",\"olatin\"]},{\"w\":\"noncrystallizable\",\"d\":\"Describing a substance that cannot be made to form crystals under normal or standard conditions.\",\"s\":\"The chemist noted that the unusual compound was noncrystallizable, meaning no matter how slowly she cooled it, it never formed solid crystals.\",\"p\":\"non-KRIS-tuh-lie-zuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.crys.tal.liz.able\",\"ps\":\"adjective\",\"t\":[\"minerals\",\"olatin\"]},{\"w\":\"noncrystallographic\",\"d\":\"Not relating to the study or mapping of crystal structures; lacking the organized atomic arrangement studied in crystallography.\",\"s\":\"The newly discovered mineral had a noncrystallographic arrangement of atoms, which puzzled scientists who expected a typical crystal lattice.\",\"p\":\"non-kris-tuh-loh-GRAF-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.crys.tal.lo.graph.ic\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"minerals\",\"olatin\"]},{\"w\":\"noncubical\",\"d\":\"Not shaped like a cube; lacking the six equal square faces that define a cubic form.\",\"s\":\"The architect designed noncubical rooms with slanted walls and curved ceilings to give the building a more artistic and dynamic appearance.\",\"p\":\"non-KYOO-bi-kul\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.cu.bi.cal\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"noncuboidal\",\"d\":\"Not shaped like a cuboid; lacking the rectangular, box-like three-dimensional form of a cuboid.\",\"s\":\"The sculptor intentionally created noncuboidal forms that curved and twisted, making her abstract artwork stand out from typical boxy sculptures.\",\"p\":\"non-kyoo-BOY-dul\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"sy\":\"non.cuboidal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncued\",\"d\":\"Not prompted or signaled by a cue; occurring or performed without a triggering signal or hint.\",\"s\":\"The drama coach was impressed when her student delivered a noncued performance, remembering every line without needing a prompt from the wings.\",\"p\":\"non-KYOOD\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.cued\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonculinary\",\"d\":\"Not related to cooking, food preparation, or the kitchen arts.\",\"s\":\"The chef was surprised to receive a nonculinary award for his work teaching children to read, a cause entirely outside his kitchen career.\",\"p\":\"non-KYOO-luh-nair-ee\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.culi.nary\",\"ps\":\"adjective\",\"t\":[\"culinary\",\"olatin\"]},{\"w\":\"noncultivated\",\"d\":\"Not prepared, farmed, or developed by human effort; left in a natural or wild state.\",\"s\":\"The hikers crossed acres of noncultivated land where wild grasses and native plants grew freely without any human interference or farming.\",\"p\":\"non-KUL-tuh-vay-tid\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.cul.ti.vat.ed\",\"ps\":\"adjective\",\"t\":[\"farming\",\"olatin\"]},{\"w\":\"noncultivation\",\"d\":\"The state or practice of not farming, growing, or developing land or crops through human effort.\",\"s\":\"The government report cited noncultivation of the fertile valley as a major reason why food supplies in the region remained dangerously low.\",\"p\":\"non-kul-tuh-VAY-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.cul.ti.va.tion\",\"ps\":\"noun\",\"t\":[\"farming\",\"olatin\"]},{\"w\":\"nonculturable\",\"d\":\"Describing a microorganism that cannot be grown or maintained in a laboratory culture under standard scientific conditions.\",\"s\":\"Many bacteria found in deep ocean sediments are nonculturable, which makes studying their behavior extremely difficult for marine microbiologists.\",\"p\":\"non-KUL-chur-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.cul.tur.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncultural\",\"d\":\"Not relating to the culture, traditions, arts, or social practices of a group of people.\",\"s\":\"The researchers focused on noncultural factors such as climate and geography to explain differences in the populations they were studying.\",\"p\":\"non-KUL-chur-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.cul.tur.al\",\"ps\":\"adjective\",\"t\":[\"festivals\",\"olatin\"]},{\"w\":\"nonculturally\",\"d\":\"In a way that is not related to or influenced by the culture or traditions of a society.\",\"s\":\"The policy was nonculturally motivated, based purely on economic data rather than the traditions or values of any particular community.\",\"p\":\"non-KUL-chur-uh-lee\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.cul.tur.al.ly\",\"ps\":\"adverb\",\"t\":[\"festivals\",\"olatin\"]},{\"w\":\"noncultured\",\"d\":\"Not grown in a laboratory culture dish; not developed through the process of culturing cells or microorganisms.\",\"s\":\"The lab technician labeled the noncultured sample carefully, noting that it had been taken directly from the patient without any lab growth process.\",\"p\":\"non-KUL-churd\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.cul.tured\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncurable\",\"d\":\"Not able to be cured or remedied; describing a condition or disease for which no cure exists.\",\"s\":\"The doctor gently explained that while the noncurable condition could be managed with medication, it would never fully go away on its own.\",\"p\":\"non-KYOOR-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.cur.able\",\"ps\":\"adjective\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"noncurated\",\"d\":\"Not carefully selected, organized, or managed by a curator or editor; assembled without deliberate curation.\",\"s\":\"The noncurated photo collection on the shared drive contained thousands of random images with no logical order or theme connecting them.\",\"p\":\"non-KYOOR-ay-tid\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.cu.rat.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncurative\",\"d\":\"Not having the ability to cure or heal; describing a treatment that manages symptoms without eliminating the underlying cause.\",\"s\":\"The doctor prescribed a noncurative therapy to reduce the patient's pain and improve daily comfort, though the disease itself would remain.\",\"p\":\"non-KYOOR-uh-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"non.cu.ra.tive\",\"ps\":\"adjective\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"noncured\",\"d\":\"Not treated by curing processes such as salting, smoking, or drying; also, not healed or remedied.\",\"s\":\"The butcher offered noncured sausages made without any added salt or preservatives, appealing to customers seeking a more natural product.\",\"p\":\"non-KYOORD\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.cured\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncurfew\",\"d\":\"Describing a situation, area, or policy in which no curfew or time restriction on movement is imposed.\",\"s\":\"The students were relieved to learn that the overnight field trip destination was a noncurfew zone where they could explore the town freely.\",\"p\":\"non-KUR-fyoo\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.cur.few\",\"ps\":\"adjective\",\"t\":[\"politics\",\"time\",\"olatin\"]},{\"w\":\"noncurious\",\"d\":\"Lacking curiosity or interest; not eager to learn, explore, or ask questions about the world.\",\"s\":\"It was rare to meet such a noncurious student, as most children in the class eagerly raised their hands to ask about every new topic.\",\"p\":\"non-KYOOR-ee-us\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.cu.ri.ous\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncurly\",\"d\":\"Not curly; describing hair, fibers, or other materials that are straight and do not form curls or waves.\",\"s\":\"The stylist noted that the client's naturally noncurly hair would need special techniques to hold a curl.\",\"p\":\"non-KUR-lee\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.curly\",\"ps\":\"adjective\",\"t\":[\"waterways\",\"olatin\"]},{\"w\":\"noncurrency\",\"d\":\"The state of not being currency or legal tender; also, the quality of being out of date or no longer in current use.\",\"s\":\"The museum displayed old trading beads and shells to illustrate the noncurrency status of items once used as money in ancient civilizations.\",\"p\":\"non-KUR-un-see\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"non.cur.ren.cy\",\"ps\":\"noun\",\"t\":[\"law\",\"economy\",\"olatin\"]},{\"w\":\"noncurrent\",\"d\":\"not current or belonging to the present time\",\"s\":\"The accountant listed the building as a noncurrent asset because it would not be sold within the year.\",\"p\":\"non-KUR-unt\",\"o\":\"Latin\",\"y\":7,\"bp\":29,\"sy\":\"non.cur.rent\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"noncursive\",\"d\":\"Not written in cursive script; describing handwriting or print in which letters are separate and not joined together.\",\"s\":\"Many young students today are more comfortable with noncursive block printing because schools have reduced the amount of time spent teaching joined handwriting.\",\"p\":\"non-KUR-siv\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.cur.sive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncursorial\",\"d\":\"Not adapted or suited for running; describing animals whose body structure is not built primarily for fast or sustained running.\",\"s\":\"Turtles are noncursorial animals because their heavy shells and short legs make running impossible, unlike the swift cheetah built for speed.\",\"p\":\"non-kur-SOR-ee-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":39,\"sy\":\"non.cur.so.ri.al\",\"ps\":\"adjective\",\"t\":[\"animals\",\"olatin\"]},{\"w\":\"noncurved\",\"d\":\"Not curved or bent; perfectly straight without any arc, bend, or rounded shape.\",\"s\":\"The engineer insisted on noncurved pipes for this section of the water system because any bend would slow the flow and reduce pressure.\",\"p\":\"non-KURVD\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.curved\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncushioned\",\"d\":\"Not padded or softened with a cushion; lacking any material designed to absorb shock or provide comfort.\",\"s\":\"After sitting on a noncushioned wooden bench for three hours during the performance, the audience members were grateful when the intermission finally arrived.\",\"p\":\"non-KOOSH-und\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"non.cush.ioned\",\"ps\":\"adjective\",\"t\":[\"household\",\"olatin\"]},{\"w\":\"noncuspidal\",\"d\":\"Not relating to or having a cusp; lacking the pointed tip or peak characteristic of a cuspidal shape in mathematics or anatomy.\",\"s\":\"The dentist noted the noncuspidal shape of the worn molar, explaining that years of grinding had completely flattened what was once a sharp chewing point.\",\"p\":\"non-KUS-pi-dul\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.cus.p.i.dal\",\"ps\":\"adjective\",\"t\":[\"body\",\"numbers\",\"olatin\"]},{\"w\":\"noncustom\",\"d\":\"Not made to order or specially tailored for an individual; describing standard, off-the-shelf items produced without customization.\",\"s\":\"Because the school had a limited budget, all the furniture purchased was noncustom, meaning every classroom received the same standard desks and chairs.\",\"p\":\"non-KUS-tum\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.cus.tom\",\"ps\":\"adjective\",\"t\":[\"fabrics\",\"household\",\"olatin\"]},{\"w\":\"noncustomer\",\"d\":\"A person who does not currently purchase goods or services from a particular business or organization.\",\"s\":\"The marketing team sent special discount offers to noncustomers in the area, hoping to attract new buyers who had never tried the product.\",\"p\":\"non-KUS-tuh-mur\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.cus.tomer\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"noncustoms\",\"d\":\"Not relating to or processed through the official customs inspection system used at national borders.\",\"s\":\"The noncustoms shipment traveled through a special trade zone where it was exempt from the usual border inspections and import duties.\",\"p\":\"non-KUS-tumz\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.cus.toms\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncut\",\"d\":\"Not cut, trimmed, or edited; remaining in its original, unaltered, or unabridged state.\",\"s\":\"The director released a noncut version of the film that included every scene originally filmed, making it nearly four hours long.\",\"p\":\"non-KUT\",\"o\":\"Latin\",\"y\":8,\"bp\":18,\"sy\":\"non.cut\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncute\",\"d\":\"Not attractive, adorable, or charming in appearance or manner; lacking cuteness.\",\"s\":\"The cartoonist deliberately drew the villain as a noncute character with sharp angles and a scowl to make him clearly unlikable to young readers.\",\"p\":\"non-KYOOT\",\"o\":\"Latin\",\"y\":9,\"bp\":19,\"sy\":\"non.cute\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncuticular\",\"d\":\"Not relating to or involving the cuticle, the thin outer layer of skin or the protective coating found on plant leaves and insect bodies.\",\"s\":\"The biologist focused on noncuticular tissue deep beneath the leaf's surface to understand how nutrients traveled through the plant's internal structure.\",\"p\":\"non-kyoo-TIK-yuh-lur\",\"o\":\"Latin\",\"y\":8,\"bp\":39,\"sy\":\"non.cu.tic.u.lar\",\"ps\":\"adjective\",\"t\":[\"body\",\"insects\",\"botany\",\"olatin\"]},{\"w\":\"noncutting\",\"d\":\"Not designed or used for cutting; describing a tool, edge, or action that does not slice or sever material.\",\"s\":\"The safety scissors given to kindergartners are noncutting on the side that faces the child's skin, preventing accidental injuries during art projects.\",\"p\":\"non-KUT-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.cut.ting\",\"ps\":\"adjective\",\"t\":[\"tools\",\"olatin\"]},{\"w\":\"noncyber\",\"d\":\"Not relating to computers, the internet, or digital technology; existing or occurring in the physical rather than virtual world.\",\"s\":\"The elderly librarian preferred noncyber research methods, carefully flipping through printed index cards and dusty reference books to find the information she needed.\",\"p\":\"non-SY-bur\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.cy.ber\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncyclical\",\"d\":\"Not occurring in regular repeated cycles; not following a predictable pattern that repeats at regular intervals.\",\"s\":\"Unlike seasonal flu, the spread of this illness was noncyclical, appearing randomly throughout the year with no predictable pattern scientists could track.\",\"p\":\"non-SY-kli-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.cycli.cal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncyclically\",\"d\":\"In a manner that does not follow regular repeated cycles or predictable periodic patterns.\",\"s\":\"The data fluctuated noncyclically, rising and falling at completely unpredictable times rather than following the seasonal rhythm the researchers had expected.\",\"p\":\"non-SY-kli-kul-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.cycli.cal.ly\",\"ps\":\"adverb\",\"t\":[\"olatin\"]},{\"w\":\"noncycling\",\"d\":\"Not going through repeated cycles; remaining in a stable state without returning to an earlier phase or condition.\",\"s\":\"Scientists identified a noncycling group of cells in the tissue sample that had stopped dividing entirely, unlike the rapidly multiplying cells nearby.\",\"p\":\"non-SY-kling\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.cy.cling\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncyclist\",\"d\":\"A person who does not ride a bicycle or does not participate in cycling as a sport or activity.\",\"s\":\"As a noncyclist, she preferred to jog through the park rather than rent a bicycle.\",\"p\":\"non-SY-klist\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.cy.clist\",\"ps\":\"noun\",\"t\":[\"sports\",\"vehicles\",\"olatin\"]},{\"w\":\"noncyclonic\",\"d\":\"Not relating to or having the characteristics of a cyclone; describing weather patterns or systems that do not rotate in a cyclonic manner.\",\"s\":\"The weather system was noncyclonic, meaning it lacked the spinning, circular motion of a true storm.\",\"p\":\"non-sy-KLON-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.cy.clonic\",\"ps\":\"adjective\",\"t\":[\"weather\",\"olatin\"]},{\"w\":\"noncylinder\",\"d\":\"Something that is not cylindrical in shape; an object or form that lacks the round, tube-like structure of a cylinder.\",\"s\":\"The engineer designed a noncylinder container shaped like a rectangular box to fit the shelf perfectly.\",\"p\":\"non-SIL-in-der\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.cylin.der\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"noncylindrical\",\"d\":\"Not having the shape or properties of a cylinder; describing any three-dimensional form that is not a cylinder.\",\"s\":\"The sculpture was noncylindrical, featuring flat sides and sharp angles instead of a smooth rounded form.\",\"p\":\"non-sih-LIN-drih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.cylin.dri.cal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncynical\",\"d\":\"Not cynical; describing a person or attitude that is trusting, optimistic, or willing to believe in the good intentions of others.\",\"s\":\"Her noncynical attitude made her believe that most people genuinely wanted to help each other.\",\"p\":\"non-SIN-ih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.cyn.i.cal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncytochrome\",\"d\":\"A molecule or protein that is not a cytochrome; referring to cellular components that do not belong to the cytochrome family of proteins involved in electron transport.\",\"s\":\"The researcher identified a noncytochrome protein that still played a role in the cell's energy process.\",\"p\":\"non-SY-toh-krohm\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.cy.tochrome\",\"ps\":\"noun\",\"t\":[\"chemistry\",\"physics\",\"kinship\",\"olatin\"]},{\"w\":\"noncytokine\",\"d\":\"A signaling molecule or substance that is not classified as a cytokine; not belonging to the group of small proteins that regulate immune and inflammatory responses.\",\"s\":\"The immune signal was classified as a noncytokine molecule because it didn't fit the standard protein structure.\",\"p\":\"non-SY-toh-kyn\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.cy.tokine\",\"ps\":\"noun\",\"t\":[\"disease\",\"chemistry\",\"olatin\"]},{\"w\":\"noncytologic\",\"d\":\"Not relating to cytology; describing an approach, test, or method that does not involve the study or examination of individual cells.\",\"s\":\"The doctor ordered a noncytologic test since examining individual cells wasn't necessary for this diagnosis.\",\"p\":\"non-sy-toh-LOJ-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":39,\"sy\":\"non.cy.to.log.ic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncytological\",\"d\":\"Not pertaining to cytology or the microscopic study of cells; used to describe analyses or findings that do not rely on cellular examination.\",\"s\":\"The noncytological analysis focused on tissue structures rather than individual cell types.\",\"p\":\"non-sy-toh-LOJ-ih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.cy.to.log.i.cal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"noncytopathic\",\"d\":\"Not causing damage or disease to cells; describing a virus or agent that does not harm or destroy the cells it infects.\",\"s\":\"Scientists celebrated when they found a noncytopathic virus strain that infected cells without destroying them.\",\"p\":\"non-sy-toh-PATH-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.cy.to.path.ic\",\"ps\":\"adjective\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"noncytosol\",\"d\":\"A substance or compartment that is not part of the cytosol; referring to cellular material not found in the liquid interior of the cell.\",\"s\":\"The enzyme was found in a noncytosol compartment, specifically inside the cell's mitochondria.\",\"p\":\"non-SY-toh-sol\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.cy.tosol\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"noncytotoxic\",\"d\":\"Not toxic to cells; describing a substance or treatment that does not cause damage or death to living cells.\",\"s\":\"The new drug was noncytotoxic, meaning it attacked the infection without harming healthy cells.\",\"p\":\"non-sy-toh-TOK-sik\",\"o\":\"Latin\",\"y\":9,\"bp\":39,\"sy\":\"non.cy.to.tox.ic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondaily\",\"d\":\"Not occurring or published every day; describing something that does not happen or appear on a daily basis.\",\"s\":\"The nondaily newspaper was published only on Sundays and contained long feature stories.\",\"p\":\"non-DAY-lee\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nondai.ly\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nondairy\",\"d\":\"Containing no milk or milk-derived ingredients; describing foods or products made without any dairy components.\",\"s\":\"She ordered a nondairy latte made with oat milk because she was lactose intolerant.\",\"p\":\"non-DAIR-ee\",\"o\":\"Latin\",\"y\":7,\"bp\":24,\"ps\":\"adjective\",\"t\":[\"farming\",\"olatin\"]},{\"w\":\"nondamaged\",\"d\":\"Not harmed, broken, or impaired; describing something that remains in its original, undamaged condition.\",\"s\":\"The inspector carefully set aside all nondamaged boxes to be shipped out first.\",\"p\":\"non-DAM-ijd\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.dam.aged\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondamaging\",\"d\":\"Not causing harm, injury, or deterioration; describing an action or substance that leaves people or things unharmed.\",\"s\":\"The cleaning crew used a nondamaging solution that removed stains without scratching the floor.\",\"p\":\"non-DAM-ij-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.dam.ag.ing\",\"ps\":\"adjective\",\"t\":[\"botany\",\"olatin\"]},{\"w\":\"nondamped\",\"d\":\"Not reduced or suppressed in vibration or oscillation; describing a wave or signal whose energy is not diminished over time.\",\"s\":\"The nondamped vibration of the string caused the sound to ring out loudly and for a long time.\",\"p\":\"non-DAMPT\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.damped\",\"ps\":\"adjective\",\"t\":[\"physics\",\"time\",\"olatin\"]},{\"w\":\"nondamping\",\"d\":\"Not reducing or absorbing energy from a vibrating or oscillating system; describing a condition in which oscillations continue without being lessened.\",\"s\":\"The physicist described a nondamping oscillation that kept swinging at full strength without slowing down.\",\"p\":\"non-DAMP-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.damp.ing\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nondance\",\"d\":\"Movement, performance, or artistic expression that is not classified as dance; describing activity that deliberately avoids the conventions of traditional dance.\",\"s\":\"The performer's act was categorized as nondance movement art because it didn't follow any dance rhythms.\",\"p\":\"non-DANS\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.dance\",\"ps\":\"noun\",\"t\":[\"stage\",\"painting\",\"festivals\",\"olatin\"]},{\"w\":\"nondancer\",\"d\":\"A person who does not dance or who has no training or involvement in dance as an art form or activity.\",\"s\":\"As a self-described nondancer, he stood at the edge of the floor and clapped along to the music.\",\"p\":\"non-DAN-ser\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.dancer\",\"ps\":\"noun\",\"t\":[\"stage\",\"olatin\"]},{\"w\":\"nondancing\",\"d\":\"Not involving or related to dance; describing an activity, performance, or person that does not include dancing.\",\"s\":\"The nondancing guests mingled near the snack table while others filled the ballroom floor.\",\"p\":\"non-DAN-sing\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.danc.ing\",\"ps\":\"adjective\",\"t\":[\"stage\",\"olatin\"]},{\"w\":\"nondatabase\",\"d\":\"A system or collection of information that is not organized as a formal database; referring to data storage that lacks the structured format of a true database.\",\"s\":\"The researcher kept her notes in a nondatabase format, simply filing paper cards in a box.\",\"p\":\"non-DAY-tuh-bays\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"sy\":\"non.database\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nondated\",\"d\":\"Not marked with or assigned a specific date; describing a document, artifact, or item that has no date recorded on it.\",\"s\":\"The nondated letter found in the attic made it impossible to know exactly when it was written.\",\"p\":\"non-DAY-tid\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.dat.ed\",\"ps\":\"adjective\",\"t\":[\"ancient\",\"olatin\"]},{\"w\":\"nondating\",\"d\":\"Not engaged in romantic dating; describing a person or period during which no romantic relationships are being pursued.\",\"s\":\"She described herself as nondating for the year, choosing to focus on her career instead.\",\"p\":\"non-DAY-ting\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.dat.ing\",\"ps\":\"adjective\",\"t\":[\"ancient\",\"olatin\"]},{\"w\":\"nondead\",\"d\":\"Not dead; referring to something or someone that is still alive, active, or functioning rather than deceased or inactive.\",\"s\":\"The scientist confirmed that the cells were nondead after the experiment, still showing signs of activity.\",\"p\":\"non-DED\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.dead\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondeadly\",\"d\":\"Not capable of causing death; describing something that may be harmful or unpleasant but does not result in death.\",\"s\":\"The doctor reassured the patient that the spider's bite was nondeadly but would cause some swelling.\",\"p\":\"non-DED-lee\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.dead.ly\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondeaf\",\"d\":\"Not deaf; describing a person who has normal or functional hearing ability.\",\"s\":\"The drama club was open to both deaf and nondeaf students, and performances included sign language.\",\"p\":\"non-DEF\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.deaf\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondealer\",\"d\":\"A person or business that is not a dealer; someone who does not buy and sell goods, especially in a specific trade such as cars or cards.\",\"s\":\"The nondealer at the card table simply watched as the others played their hands.\",\"p\":\"non-DEE-ler\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.deal.er\",\"ps\":\"noun\",\"t\":[\"economy\",\"vehicles\",\"olatin\"]},{\"w\":\"nondealership\",\"d\":\"A business or outlet for selling goods that is not an authorized dealership; a seller not affiliated with a manufacturer's official distribution network.\",\"s\":\"The mechanic worked at a nondealership garage that fixed all makes and models.\",\"p\":\"non-DEE-ler-ship\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.deal.er.ship\",\"ps\":\"noun\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"nondeath\",\"d\":\"The state or condition of not dying; survival or continued existence, sometimes used to describe outcomes that fall short of death.\",\"s\":\"The philosopher argued that certain spiritual traditions focus on nondeath, or the continuance of the soul.\",\"p\":\"non-DETH\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.death\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nondebatable\",\"d\":\"Not open to debate or argument; describing something so clearly settled or agreed upon that discussion is unnecessary.\",\"s\":\"The safety rule about wearing helmets was nondebatable in our cycling club.\",\"p\":\"non-dih-BAY-tuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.de.bat.able\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nondebt\",\"d\":\"Not constituting or related to debt; describing financial arrangements, obligations, or instruments that do not involve borrowed money.\",\"s\":\"The company celebrated its nondebt status after paying off every loan it owed.\",\"p\":\"non-DET\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.debt\",\"ps\":\"adjective\",\"t\":[\"music\",\"economy\",\"olatin\"]},{\"w\":\"nondecayed\",\"d\":\"Not having undergone decay or decomposition; describing organic or other material that remains in its original, unrotted condition.\",\"s\":\"The ancient jar of honey was remarkably nondecayed after thousands of years in the tomb.\",\"p\":\"non-dih-KAYD\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.de.cayed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondecaying\",\"d\":\"Not undergoing decay, rot, or deterioration; describing a substance or material that remains stable and does not break down over time.\",\"s\":\"Scientists searched for a nondecaying material that could survive extreme heat and cold.\",\"p\":\"non-dih-KAY-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.de.cay.ing\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nondeceptive\",\"d\":\"Not intended to deceive or mislead; describing communication, behavior, or actions that are honest and straightforward.\",\"s\":\"The advertisement was praised for being nondeceptive and completely honest about the product's limits.\",\"p\":\"non-dih-SEP-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.de.cep.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondeciduate\",\"d\":\"Describing a type of placental arrangement in mammals in which the maternal tissue does not separate and shed with the placenta at birth.\",\"s\":\"The biology textbook explained that some mammals are nondeciduate, meaning their placentas attach differently.\",\"p\":\"non-dih-SIJ-oo-it\",\"o\":\"Latin\",\"y\":9,\"bp\":39,\"sy\":\"non.de.cid.u.ate\",\"ps\":\"adjective\",\"t\":[\"body\",\"animals\",\"olatin\"]},{\"w\":\"nondeciduous\",\"d\":\"Not shedding leaves seasonally; describing plants, especially trees, that retain their leaves throughout the year rather than dropping them in autumn.\",\"s\":\"The pine tree is nondeciduous, keeping its green needles through the entire winter.\",\"p\":\"non-dih-SIJ-oo-us\",\"o\":\"Latin\",\"y\":9,\"bp\":39,\"sy\":\"non.de.cid.u.ous\",\"ps\":\"adjective\",\"t\":[\"botany\",\"flowers\",\"time\",\"olatin\"]},{\"w\":\"nondecimal\",\"d\":\"Not based on the number ten; describing a numbering system or mathematical approach that does not use base ten as its foundation.\",\"s\":\"Binary code is a nondecimal system because it uses only two digits instead of ten.\",\"p\":\"non-DES-ih-mul\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.dec.i.mal\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nondecision\",\"d\":\"A failure to make a clear decision; a situation in which no definitive choice or ruling is reached despite the need for one.\",\"s\":\"The committee's nondecision left everyone frustrated because nothing was resolved at the meeting.\",\"p\":\"non-dih-SIH-zhun\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.de.ci.sion\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nondecisive\",\"d\":\"Not producing a clear or final result; describing an action, battle, or vote that fails to settle a question or determine a definite outcome.\",\"s\":\"The general's nondecisive battle strategy left his troops confused about their next move.\",\"p\":\"non-dih-SY-siv\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"non.de.ci.sive\",\"ps\":\"adjective\",\"t\":[\"politics\",\"war\",\"olatin\"]},{\"w\":\"nondeclarative\",\"d\":\"Not expressed or stated openly; in psychology, referring to a type of memory (such as skills or habits) that cannot be consciously recalled or verbally described.\",\"s\":\"Riding a bike relies on nondeclarative memory, the kind you can't easily explain in words.\",\"p\":\"non-dih-KLAIR-uh-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.declar.a.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondeclared\",\"d\":\"Not officially announced, reported, or made known to the proper authorities, such as goods not reported at customs or income not reported to tax officials.\",\"s\":\"The customs officer flagged the nondeclared items hidden in the traveler's luggage.\",\"p\":\"non-dih-KLAIRD\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.de.clared\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"economy\",\"olatin\"]},{\"w\":\"nondeclaring\",\"d\":\"Not announcing, stating, or formally reporting something that is expected or required to be disclosed.\",\"s\":\"The nondeclaring player in bridge simply passed instead of naming a trump suit.\",\"p\":\"non-dih-KLAIR-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"non.declar.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondecodable\",\"d\":\"Not able to be decoded, translated, or interpreted into understandable meaning, especially referring to encrypted messages or unrecognizable text.\",\"s\":\"The scrambled transmission was nondecodable without the correct encryption key.\",\"p\":\"non-dee-KOH-duh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.de.cod.able\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nondecoded\",\"d\":\"Not having been translated from a coded or encrypted format into plain, understandable language or data.\",\"s\":\"The spy's nondecoded message sat in the vault, its secrets still locked away.\",\"p\":\"non-dee-KOHD-ed\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.de.cod.ed\",\"ps\":\"adjective\",\"t\":[\"landforms\",\"wordwords\",\"olatin\"]},{\"w\":\"nondecomposable\",\"d\":\"Not capable of being broken down into simpler parts, elements, or components, whether through chemical, biological, or mathematical processes.\",\"s\":\"Certain plastics are nondecomposable and persist in landfills for hundreds of years.\",\"p\":\"non-dee-kum-POH-zuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.de.com.pos.able\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"numbers\",\"olatin\"]},{\"w\":\"nondecomposed\",\"d\":\"Not having broken down or decayed into simpler substances; remaining in an original, unbroken state without rotting or decomposing.\",\"s\":\"The scientist was amazed to find nondecomposed wood preserved in the icy permafrost.\",\"p\":\"non-dee-kum-POHZD\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.de.com.posed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondecorated\",\"d\":\"Not adorned, embellished, or ornamented in any way; plain and lacking any decorative elements.\",\"s\":\"The nondecorated walls of the minimalist apartment gave the room a calm, clean look.\",\"p\":\"non-DEK-uh-ray-ted\",\"o\":\"Latin\",\"y\":8,\"bp\":39,\"sy\":\"non.dec.o.rat.ed\",\"ps\":\"adjective\",\"t\":[\"landforms\",\"olatin\"]},{\"w\":\"nondecorative\",\"d\":\"Not intended or used for decoration or ornamentation; serving a purely functional or practical purpose rather than an aesthetic one.\",\"s\":\"The support beam was purely nondecorative, built only to hold up the ceiling.\",\"p\":\"non-DEK-uh-ray-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.dec.o.ra.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondecreasing\",\"d\":\"Not becoming smaller or lower in value; remaining the same or increasing, never going down, often used in mathematics to describe a sequence or function.\",\"s\":\"The math teacher explained that a nondecreasing function never goes lower as the input rises.\",\"p\":\"non-dih-KREE-sing\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.de.creas.ing\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nondedicated\",\"d\":\"Not committed exclusively to a single purpose, task, or function; able to be used for multiple purposes rather than reserved for just one.\",\"s\":\"The nondedicated server handled many different tasks rather than focusing on one program.\",\"p\":\"non-DED-ih-kay-ted\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"nonded.i.cat.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondeducibility\",\"d\":\"The quality or state of not being able to be logically concluded or derived from given premises or evidence; the inability to be deduced.\",\"s\":\"The logician wrote a paper on the nondeducibility of certain conclusions from the given set of facts.\",\"p\":\"non-dih-doo-sih-BIL-ih-tee\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"nond.e.ducibil.i.ty\",\"ps\":\"noun\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nondeducible\",\"d\":\"Not able to be logically inferred, concluded, or derived from available facts, evidence, or premises.\",\"s\":\"The conclusion was nondeducible from the two premises provided in the argument.\",\"p\":\"non-dih-DOO-sih-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"nond.e.ducible\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nondeductive\",\"d\":\"Not based on or using deductive reasoning, which moves from general principles to specific conclusions; using another form of reasoning such as inductive or abductive logic.\",\"s\":\"Inductive reasoning is nondeductive because it draws broad conclusions from specific observations.\",\"p\":\"non-dih-DUK-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"nond.e.duc.tive\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nondeep\",\"d\":\"Not deep; lacking significant depth, whether physically, intellectually, or emotionally; shallow or superficial in nature.\",\"s\":\"The nondeep end of the pool was perfect for the youngest swimmers learning their first strokes.\",\"p\":\"non-DEEP\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.deep\",\"ps\":\"adjective\",\"t\":[\"emotions\",\"olatin\"]},{\"w\":\"nondefamatory\",\"d\":\"Not damaging to a person's reputation; not containing false statements that would harm someone's good name or character.\",\"s\":\"The journalist made sure every statement in the article was nondefamatory and backed by solid evidence.\",\"p\":\"non-dih-FAM-uh-tor-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.defam.a.to.ry\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondefault\",\"d\":\"Not involving or constituting a failure to meet a financial obligation or legal requirement; referring to a situation where payments or duties are fulfilled as expected.\",\"s\":\"The bank rewarded its nondefault customers with lower interest rates on their next loans.\",\"p\":\"nan\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.de.fault\",\"ps\":\"adjective\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"nondefecting\",\"d\":\"Not abandoning one's allegiance, group, country, or cause to join an opposing side; remaining loyal and not switching sides.\",\"s\":\"The nondefecting agents remained loyal to their country even under tremendous pressure.\",\"p\":\"non-dih-FEK-ting\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.de.fect.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondefective\",\"d\":\"Not flawed, broken, or imperfect; functioning properly and meeting all required standards of quality or performance.\",\"s\":\"The factory inspector stamped each nondefective product with a green approval label.\",\"p\":\"non-dih-FEK-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.de.fec.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondefendant\",\"d\":\"A person in a legal proceeding who is not the party being sued or accused; someone present in a case who does not hold the position of defendant.\",\"s\":\"As a nondefendant witness, she was free to leave the courtroom after giving her testimony.\",\"p\":\"non-dih-FEN-dunt\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.de.fen.dant\",\"ps\":\"noun\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"nondefense\",\"d\":\"Not related to or intended for military defense; referring to government spending, programs, or activities that are civilian or non-military in nature.\",\"s\":\"The budget was spent on nondefense programs like education and road repair.\",\"p\":\"nah-ndih-FEH-ns\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"naa.ndih.feh.ns\",\"ps\":\"adjective\",\"t\":[\"politics\",\"war\",\"olatin\"]},{\"w\":\"nondefensive\",\"d\":\"Not acting in a guarded or self-protective manner; open, receptive to criticism, and willing to engage without feeling threatened or putting up emotional barriers.\",\"s\":\"Her nondefensive response to criticism helped the team work through the problem quickly.\",\"p\":\"non-dih-FEN-siv\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.de.fen.sive\",\"ps\":\"adjective\",\"t\":[\"emotions\",\"olatin\"]},{\"w\":\"nondeferrable\",\"d\":\"Not able to be postponed, delayed, or put off to a later time; requiring immediate attention or action.\",\"s\":\"The emergency surgery was nondeferrable and had to be performed immediately.\",\"p\":\"non-dih-FUR-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.de.ferrable\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nondeferred\",\"d\":\"Not postponed or delayed to a later time; handled, paid, or acted upon immediately rather than being put off.\",\"s\":\"The nondeferred payment was due the moment the contract was signed.\",\"p\":\"non-dih-FURD\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.de.ferred\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nondeficient\",\"d\":\"Not lacking in any necessary quality, nutrient, or quantity; having a sufficient or adequate amount of something required.\",\"s\":\"After months of a balanced diet, her blood test showed she was nondeficient in all key vitamins.\",\"p\":\"non-dih-FISH-unt\",\"o\":\"Latin\",\"y\":8,\"bp\":39,\"sy\":\"non.d.e.fi.cient\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondefinable\",\"d\":\"Not able to be clearly described, explained, or given a precise definition; too vague, complex, or abstract to pin down with words.\",\"s\":\"Some emotions feel nondefinable, impossible to capture fully in any single word.\",\"p\":\"non-dih-FY-nuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.de.fin.able\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nondefined\",\"d\":\"Not having been given a clear definition, boundary, or explanation; lacking precise meaning or specification.\",\"s\":\"The nondefined border between the two properties caused a long dispute between the neighbors.\",\"p\":\"non-dih-FYND\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.de.fined\",\"ps\":\"adjective\",\"t\":[\"maps\",\"olatin\"]},{\"w\":\"nondefining\",\"d\":\"Not serving to define, distinguish, or establish the essential nature or limits of something; not providing a clear characteristic or boundary.\",\"s\":\"The nondefining clause in the sentence added extra information without changing the core meaning.\",\"p\":\"non-dih-FY-ning\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.defin.ing\",\"ps\":\"adjective\",\"t\":[\"maps\",\"olatin\"]},{\"w\":\"nondefinite\",\"d\":\"Not fixed, certain, or clearly determined; lacking a precise or settled character, boundary, or outcome.\",\"s\":\"The scientist gave a nondefinite answer because the experiment results were still unclear.\",\"p\":\"non-DEF-ih-nit\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"non.def.i.nite\",\"ps\":\"adjective\",\"t\":[\"maps\",\"olatin\"]},{\"w\":\"nondefinitional\",\"d\":\"Not relating to, consisting of, or serving as a definition; not expressing or establishing the meaning of a term or concept.\",\"s\":\"The poet's use of the word was nondefinitional, more emotional than precise.\",\"p\":\"non-def-ih-NIH-shun-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":31,\"sy\":\"non.def.i.ni.tion.al\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondefinitive\",\"d\":\"Not final, conclusive, or authoritative; not providing a complete or settled answer, and open to further revision or interpretation.\",\"s\":\"The judge gave a nondefinitive ruling, leaving the case open to further review.\",\"p\":\"non-dih-FIN-ih-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.defini.tive\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"nondeflated\",\"d\":\"Not reduced in size, pressure, or value; remaining fully inflated or at its original level without having been deflated.\",\"s\":\"The nondeflated balloon stayed perfectly round throughout the entire party.\",\"p\":\"non-dih-FLAY-ted\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.de.flat.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondeflationary\",\"d\":\"Not causing or relating to deflation, which is a general decrease in prices or economic activity; not having a deflating effect on the economy or a system.\",\"s\":\"The economist praised the nondeflationary policy for keeping prices stable.\",\"p\":\"non-dih-FLAY-shun-air-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.de.fla.tion.ary\",\"ps\":\"adjective\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nondefoliated\",\"d\":\"Not having had its leaves stripped away by chemicals, disease, or other agents; retaining its natural foliage.\",\"s\":\"The nondefoliated forest zone was lush and green compared to the damaged areas nearby.\",\"p\":\"non-dih-FOH-lee-ay-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.de.fo.li.at.ed\",\"ps\":\"adjective\",\"t\":[\"disease\",\"botany\",\"chemistry\",\"olatin\"]},{\"w\":\"nondefoliating\",\"d\":\"Not causing the removal or loss of leaves from plants or trees; not acting as an agent that strips foliage.\",\"s\":\"The farmers chose a nondefoliating herbicide that wouldn't strip the leaves from crops.\",\"p\":\"non-dih-FOH-lee-ay-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.de.fo.li.at.ing\",\"ps\":\"adjective\",\"t\":[\"botany\",\"flowers\",\"olatin\"]},{\"w\":\"nondeformable\",\"d\":\"Not capable of being permanently changed in shape or structure when force is applied; resistant to deformation or distortion.\",\"s\":\"The engineer needed a nondeformable material that would keep its shape under extreme pressure.\",\"p\":\"non-dih-FOR-muh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.de.formable\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nondeformed\",\"d\":\"Not altered from its original or natural shape; free from distortion, disfigurement, or structural change caused by force or disease.\",\"s\":\"The nondeformed sample was used as a control in the materials science experiment.\",\"p\":\"non-dih-FORMD\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.de.formed\",\"ps\":\"adjective\",\"t\":[\"disease\",\"physics\",\"olatin\"]},{\"w\":\"nondeforming\",\"d\":\"Not causing a change in the shape, structure, or form of something; not producing distortion or physical alteration.\",\"s\":\"The nondeforming plastic casing protected the device even when dropped.\",\"p\":\"non-dih-FOR-ming\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.de.form.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondegeneracy\",\"d\":\"The state or quality of not degenerating or declining in quality, function, or structure; in physics or mathematics, the condition of having a unique, distinct solution or state rather than multiple overlapping ones.\",\"s\":\"The nondegeneracy of the crystal structure meant each energy level was unique.\",\"p\":\"non-dih-JEN-ur-uh-see\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.de.gen.er.a.cy\",\"ps\":\"noun\",\"t\":[\"physics\",\"numbers\",\"olatin\"]},{\"w\":\"nondegenerated\",\"d\":\"Not having declined in quality, function, or complexity; remaining in a healthy or fully functional state without deterioration or breakdown.\",\"s\":\"The nondegenerated nerve cells continued to function normally after the injury.\",\"p\":\"non-dih-JEN-ur-ay-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.de.gen.er.at.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondegenerative\",\"d\":\"Not causing or characterized by progressive deterioration or breakdown of cells, tissues, or functions; describing a condition or process that does not worsen over time.\",\"s\":\"The doctor was relieved to diagnose the condition as nondegenerative, meaning it wouldn't get worse.\",\"p\":\"non-deh-JEN-er-ah-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":31,\"sy\":\"non.de.gen.er.a.tive\",\"ps\":\"adjective\",\"t\":[\"body\",\"character\",\"time\",\"olatin\"]},{\"w\":\"nondegraded\",\"d\":\"Not broken down, decomposed, or reduced in quality; remaining in its original or intact condition without deterioration.\",\"s\":\"The nondegraded soil in the nature reserve remained rich and fertile.\",\"p\":\"non-deh-GRAYD-ed\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.de.grad.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondehydrated\",\"d\":\"Not having had water removed; retaining its natural moisture content and not in a dried-out state.\",\"s\":\"After drinking plenty of water, the hiker remained nondehydrated throughout the trail.\",\"p\":\"non-dee-HY-dray-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.de.hy.drat.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondehydrating\",\"d\":\"Not causing the removal of water or moisture; describing a process or substance that does not draw water out of something.\",\"s\":\"The sports drink was labeled nondehydrating because it replenished fluids rather than depleting them.\",\"p\":\"non-dee-HY-dray-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.de.hy.drat.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondeictic\",\"d\":\"Not serving as a pointing or referencing expression; describing language or words that do not indicate specific persons, places, or things in context.\",\"s\":\"The word 'justice' is nondeictic because it doesn't point to a specific person or place.\",\"p\":\"non-day-IK-tik\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.de.ic.tic\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nondeified\",\"d\":\"Not elevated to the status of a god or divine being; remaining in a non-divine, ordinary state without being worshipped as a deity.\",\"s\":\"The ancient hero remained nondeified in that culture, remembered as human rather than divine.\",\"p\":\"non-DEE-ih-fyd\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.de.i.fied\",\"ps\":\"adjective\",\"t\":[\"myth\",\"religion\",\"olatin\"]},{\"w\":\"nondelayed\",\"d\":\"Not held back, postponed, or slowed down; occurring or proceeding without any delay or interruption.\",\"s\":\"The nondelayed shipment arrived right on schedule, impressing the whole team.\",\"p\":\"non-deh-LAYD\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.de.layed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondelaying\",\"d\":\"Not causing or producing any delay; proceeding promptly without holding back progress or action.\",\"s\":\"The nondelaying response from the fire department saved the building from serious damage.\",\"p\":\"non-deh-LAY-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.de.lay.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondelegable\",\"d\":\"Not able to be assigned or transferred to another person; describing a duty or responsibility that must be carried out by the original party and cannot be passed on.\",\"s\":\"The principal explained that signing official documents was a nondelegable responsibility.\",\"p\":\"non-DEL-eh-gah-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.del.e.gable\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondelegate\",\"d\":\"A person who is not serving as a delegate or official representative at a meeting, convention, or assembly.\",\"s\":\"As a nondelegate, she could attend the convention but not cast an official vote.\",\"p\":\"non-DEL-eh-gayt\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"non.del.e.gate\",\"ps\":\"noun\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nondelegated\",\"d\":\"Not assigned or transferred to another person or group; describing authority or a task that has not been officially handed over to a representative.\",\"s\":\"The nondelegated authority stayed with the director and could not be passed to assistants.\",\"p\":\"non-DEL-eh-gay-ted\",\"o\":\"Latin\",\"y\":8,\"bp\":39,\"sy\":\"non.del.e.gat.ed\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"nondelegation\",\"d\":\"The absence or refusal of the transfer of authority or responsibility from one party to another; the principle that certain powers must not be handed off.\",\"s\":\"The court's nondelegation doctrine prevents lawmakers from handing too much power to other branches.\",\"p\":\"non-del-eh-GAY-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.del.e.ga.tion\",\"ps\":\"noun\",\"t\":[\"poetry\",\"logic\",\"olatin\"]},{\"w\":\"nondeletion\",\"d\":\"The absence of removal or erasure; describing a situation in which something, such as genetic material or data, has not been deleted or eliminated.\",\"s\":\"The nondeletion of the original file meant students could always return to the first draft.\",\"p\":\"non-deh-LEE-shun\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.dele.tion\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nondeliberate\",\"d\":\"Not done on purpose or with careful planning; accidental or unintentional in nature.\",\"s\":\"The teacher recognized the student's mistake as nondeliberate and didn't penalize him.\",\"p\":\"non-deh-LIB-er-it\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.de.lib.er.ate\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondeliberative\",\"d\":\"Not involving careful consideration, discussion, or debate; describing a process or body that does not engage in formal deliberation before making decisions.\",\"s\":\"The committee operated in a nondeliberative mode when time was short, skipping lengthy debate.\",\"p\":\"non-deh-LIB-er-ah-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":31,\"sy\":\"non.de.lib.er.a.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondelimited\",\"d\":\"Not having clearly defined boundaries or limits; lacking specific markers that separate or restrict an area, set, or concept.\",\"s\":\"The nondelimited text file had no clear boundaries between sections, making it hard to read.\",\"p\":\"non-deh-LIM-ih-ted\",\"o\":\"Latin\",\"y\":8,\"bp\":39,\"sy\":\"non.de.lim.it.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondelineated\",\"d\":\"Not clearly outlined, sketched, or described; lacking distinct boundaries or detailed definition in form or description.\",\"s\":\"The nondelineated map frustrated travelers because no roads or borders were clearly marked.\",\"p\":\"non-deh-LIN-ee-ay-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.de.lin.eat.ed\",\"ps\":\"adjective\",\"t\":[\"painting\",\"olatin\"]},{\"w\":\"nondelinquent\",\"d\":\"Not failing to meet obligations or breaking rules and laws; describing a person or account that is in good standing and not guilty of wrongdoing.\",\"s\":\"The nondelinquent students were praised for their responsible behavior throughout the year.\",\"p\":\"non-deh-LING-kwent\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.delin.quent\",\"ps\":\"adjective\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"nondelirious\",\"d\":\"Not experiencing delirium; mentally clear, calm, and coherent without confusion, hallucinations, or frenzied excitement.\",\"s\":\"The doctor confirmed the patient was nondelirious and thinking clearly after the medication.\",\"p\":\"non-deh-LEER-ee-us\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.deliri.ous\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondelocalized\",\"d\":\"Not spread or distributed across a wide area; in chemistry, describing electrons that remain concentrated in a specific bond or atom rather than spread across a molecule.\",\"s\":\"The nondelocalized electrons stayed fixed to one atom rather than spreading across the molecule.\",\"p\":\"non-deh-LOH-kuh-lyzd\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.de.lo.cal.ized\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"physics\",\"olatin\"]},{\"w\":\"nondeltaic\",\"d\":\"Not relating to or having the characteristics of a river delta; describing a landform or sediment deposit that was not formed at the mouth of a river.\",\"s\":\"The nondeltaic coastline had no river deposits, so the beach was made of fine white sand.\",\"p\":\"non-del-TAY-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.delta.ic\",\"ps\":\"adjective\",\"t\":[\"minerals\",\"landforms\",\"waterways\",\"olatin\"]},{\"w\":\"nondelusional\",\"d\":\"Not affected by false beliefs or delusions; mentally grounded in reality and not experiencing irrational or distorted perceptions.\",\"s\":\"The psychiatrist confirmed that the patient's beliefs were nondelusional and grounded in reality.\",\"p\":\"non-deh-LOO-zhun-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.delu.sion.al\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nondemanding\",\"d\":\"Not requiring great effort, skill, or attention; easy to fulfill or satisfy without placing heavy burdens or high expectations on someone.\",\"s\":\"The summer reading program was nondemanding, allowing students to relax while still enjoying books.\",\"p\":\"non-deh-MAN-ding\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.de.mand.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondemarcated\",\"d\":\"Not having clearly marked boundaries or divisions; lacking defined borders that separate one area or category from another.\",\"s\":\"The nondemarcated territory caused disputes because no one had agreed on where one land ended and another began.\",\"p\":\"non-deh-MAR-kay-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.de.mar.cat.ed\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nondematiaceous\",\"d\":\"Not belonging to the group of dark-pigmented fungi known as dematiaceous fungi; lacking the dark melanin pigmentation characteristic of that fungal group.\",\"s\":\"The lab identified the mold as nondematiaceous because it lacked the dark pigment seen in related species.\",\"p\":\"non-deh-may-tee-AY-shus\",\"o\":\"Latin\",\"y\":9,\"bp\":31,\"sy\":\"non.de.ma.ti.a.ceous\",\"ps\":\"adjective\",\"t\":[\"botany\",\"painting\",\"olatin\"]},{\"w\":\"nondemolition\",\"d\":\"The absence of tearing down or destroying a structure; describing a situation or policy in which buildings or structures are preserved rather than demolished.\",\"s\":\"The city council chose a nondemolition approach, repairing the old bridge rather than tearing it down.\",\"p\":\"non-dem-uh-LIH-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.de.mo.li.tion\",\"ps\":\"noun\",\"t\":[\"buildings\",\"politics\",\"olatin\"]},{\"w\":\"nondemonic\",\"d\":\"Not evil, devilish, or relating to demons; free from demonic qualities or supernatural malevolence.\",\"s\":\"The strange noise turned out to have a nondemonic explanation — it was just the pipes rattling.\",\"p\":\"non-deh-MON-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.de.mon.ic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondemonstrable\",\"d\":\"Not able to be proven, shown, or demonstrated through evidence or logical argument; incapable of being conclusively displayed or verified.\",\"s\":\"The philosopher argued that the existence of the soul is nondemonstrable through scientific experiments.\",\"p\":\"non-deh-MON-struh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.demon.stra.ble\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nondemonstrating\",\"d\":\"Not actively showing, proving, or displaying something; refraining from taking part in a public demonstration or protest.\",\"s\":\"The quiet students remained nondemonstrating during the school board meeting, choosing to write letters instead.\",\"p\":\"non-deh-MON-stray-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.demon.strat.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondenatured\",\"d\":\"Not having its natural structure altered or destroyed; describing a protein or other substance that retains its original molecular shape and biological activity.\",\"s\":\"The scientist used nondenatured proteins in the experiment to ensure they kept their natural shape.\",\"p\":\"non-deh-NAY-cherd\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.de.na.tured\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondendritic\",\"d\":\"Not having a branching, tree-like structure; describing a crystal, cell, or growth pattern that lacks the branching arms typical of dendritic forms.\",\"s\":\"The crystal formed a nondendritic pattern, growing in smooth layers rather than branching tree-like shapes.\",\"p\":\"non-den-DRIT-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.den.drit.ic\",\"ps\":\"adjective\",\"t\":[\"flowers\",\"minerals\",\"olatin\"]},{\"w\":\"nondeniable\",\"d\":\"Not able to be denied or disputed; so clearly true or evident that no one can reasonably argue against it.\",\"s\":\"The nondeniable truth of the matter was that the experiment had failed completely.\",\"p\":\"non-deh-NY-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"non.de.ni.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondenial\",\"d\":\"The absence of a denial or refusal; a failure to reject or contradict an accusation, claim, or statement.\",\"s\":\"The suspect's nondenial of the charges surprised everyone in the courtroom.\",\"p\":\"non-deh-NY-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.de.nial\",\"ps\":\"noun\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"nondenticulate\",\"d\":\"Not having small tooth-like projections or serrations along an edge; describing a surface or margin that is smooth rather than finely toothed.\",\"s\":\"The leaf's edge was nondenticulate, meaning it was smooth rather than having tiny tooth-like notches.\",\"p\":\"non-den-TIK-yoo-lit\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.den.tic.u.late\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nondeodorant\",\"d\":\"Not functioning as a deodorant; describing a product or substance that does not neutralize or mask unpleasant body odors.\",\"s\":\"The chemist tested the nondeodorant formula to see if it could still protect skin without masking odors.\",\"p\":\"non-dee-OH-dor-unt\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"non.deodor.ant\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondeodorized\",\"d\":\"Not having had odors removed or neutralized; retaining its natural smell without any deodorizing treatment applied.\",\"s\":\"The nondeodorized version of the product kept all its natural scents intact.\",\"p\":\"non-dee-OH-dor-yzd\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.deodor.ized\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondeparture\",\"d\":\"The absence of leaving or setting out; a situation in which someone or something does not depart from a location or deviate from an expected course.\",\"s\":\"The nondeparture of the rescue team meant that survivors had to wait another day.\",\"p\":\"non-deh-PAR-cher\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.de.par.ture\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nondependent\",\"d\":\"Not relying on or requiring the support of another person, substance, or factor; self-sufficient and free from dependency.\",\"s\":\"She was proud of being financially nondependent by the time she turned sixteen.\",\"p\":\"non-deh-PEN-dent\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.de.pen.dent\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondepletable\",\"d\":\"Not capable of being used up, exhausted, or permanently reduced; describing a resource that can renew itself or cannot be emptied by use.\",\"s\":\"Solar energy is considered a nondepletable resource because the sun keeps shining every day.\",\"p\":\"non-deh-PLEE-tuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.de.pletable\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondepleting\",\"d\":\"Not causing a reduction or exhaustion of a supply or resource; describing a process or activity that uses something without diminishing the total amount available.\",\"s\":\"Scientists search for nondepleting energy sources that won't run out as the world's population grows.\",\"p\":\"non-deh-PLEE-ting\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.de.plet.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondeployable\",\"d\":\"Not capable of being deployed or sent into active service; describing personnel or equipment that cannot be assigned to a mission or field operation.\",\"s\":\"The broken equipment was labeled nondeployable and sent back to the repair depot.\",\"p\":\"non-deh-PLOY-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.de.ploy.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondeployed\",\"d\":\"Not currently deployed or sent into active field service; describing troops or resources that remain at their home base rather than being assigned to an active mission.\",\"s\":\"The nondeployed soldiers stayed at the base while their unit went overseas.\",\"p\":\"non-deh-PLOYD\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.de.ployed\",\"ps\":\"adjective\",\"t\":[\"war\",\"olatin\"]},{\"w\":\"nondeployment\",\"d\":\"The state or condition of not being deployed; the absence of troops, equipment, or resources being sent into active service or a specific location.\",\"s\":\"The general's decision for nondeployment of the troops avoided an unnecessary conflict.\",\"p\":\"non-deh-PLOY-munt\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.de.ploy.ment\",\"ps\":\"noun\",\"t\":[\"war\",\"olatin\"]},{\"w\":\"nondepolarizing\",\"d\":\"Not causing a change in the electrical polarity of a nerve or muscle cell membrane; describing a substance that blocks nerve signals without triggering depolarization.\",\"s\":\"The doctor chose a nondepolarizing muscle relaxant so the patient's muscles wouldn't twitch during surgery.\",\"p\":\"non-dee-POH-luh-ry-zing\",\"o\":\"Latin\",\"y\":9,\"bp\":31,\"sy\":\"non.de.po.lar.iz.ing\",\"ps\":\"adjective\",\"t\":[\"body\",\"physics\",\"olatin\"]},{\"w\":\"nondeposition\",\"d\":\"The absence of deposition; a condition in which sediment, material, or testimony is not laid down or recorded in a given place or situation.\",\"s\":\"The geologist noted a period of nondeposition in the rock record, where no new sediment had been laid down.\",\"p\":\"non-dep-uh-ZIH-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.de.po.si.tion\",\"ps\":\"noun\",\"t\":[\"minerals\",\"law\",\"olatin\"]},{\"w\":\"nondepositional\",\"d\":\"Relating to or characterized by the absence of deposition; describing an environment or surface where no sediment or material is being accumulated or laid down.\",\"s\":\"The nondepositional surface in the cliff face puzzled the young geologist because there were no sediment layers.\",\"p\":\"non-dep-uh-ZIH-shun-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":31,\"sy\":\"non.de.po.si.tion.al\",\"ps\":\"adjective\",\"t\":[\"minerals\",\"ecology\",\"character\",\"olatin\"]},{\"w\":\"nondeprecated\",\"d\":\"Not having been deprecated or marked as outdated; describing software, terminology, or a practice that is still considered current and approved for use.\",\"s\":\"The software developer was relieved that the function was nondeprecated and could still be used safely.\",\"p\":\"non-DEP-rih-kay-tid\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.dep.re.cat.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondepreciated\",\"d\":\"Not having lost value over time; describing an asset or item whose monetary worth has not decreased through use, age, or accounting adjustments.\",\"s\":\"The antique chair was nondepreciated in value; in fact, it was worth more than ever.\",\"p\":\"non-deh-PREE-shee-ay-tid\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.de.pre.ci.at.ed\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nondepreciating\",\"d\":\"Not decreasing in value over time; describing an asset that maintains or increases its worth rather than losing value through wear or obsolescence.\",\"s\":\"Gold is often seen as a nondepreciating asset that holds its value over time.\",\"p\":\"non-deh-PREE-shee-ay-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":31,\"sy\":\"non.de.pre.ci.at.ing\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nondepressed\",\"d\":\"Not in a state of depression or low mood; describing a person, economy, or region that is not experiencing sadness, low activity, or reduced function.\",\"s\":\"The nondepressed group in the study reported higher energy levels and better sleep.\",\"p\":\"non-deh-PREST\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.de.pressed\",\"ps\":\"adjective\",\"t\":[\"economy\",\"emotions\",\"olatin\"]},{\"w\":\"nondepression\",\"d\":\"The absence of depression, whether referring to mental health, economics, or physical geography; a state in which no significant lowering or decline is present.\",\"s\":\"The psychologist studied periods of nondepression in patients to understand what kept their moods stable.\",\"p\":\"non-deh-PREH-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.de.pres.sion\",\"ps\":\"noun\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nondepressive\",\"d\":\"Not causing, relating to, or characterized by depression; describing a substance, situation, or personality that does not produce feelings of sadness or reduced activity.\",\"s\":\"The therapist focused on nondepressive coping strategies to help her client stay positive.\",\"p\":\"non-deh-PREH-siv\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.de.pres.sive\",\"ps\":\"adjective\",\"t\":[\"character\",\"emotions\",\"olatin\"]},{\"w\":\"nonderivational\",\"d\":\"Not formed by derivation from another word or source; describing a word, concept, or form that is original and not built by adding prefixes, suffixes, or other word-forming elements.\",\"s\":\"The linguist classified the word as nonderivational because it wasn't formed by adding prefixes or suffixes.\",\"p\":\"non-deh-riv-uh-NAY-shun-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.deriva.tion.al\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonderivative\",\"d\":\"Not derived from or based on something else; original and independent rather than copied or adapted from a pre-existing source.\",\"s\":\"The artist's style was considered nonderivative because it didn't copy or borrow from other artists.\",\"p\":\"non-deh-RIV-uh-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.deriva.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonderivatized\",\"d\":\"Not chemically converted into a derivative form; describing a compound or molecule that has been left in its original state without modification for analysis or reaction purposes.\",\"s\":\"The chemist tested the nonderivatized sample first before altering its molecular structure.\",\"p\":\"non-deh-RIV-uh-tyzd\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.deriva.tized\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonderived\",\"d\":\"Not taken or developed from another source; describing something that is original and stands independently without being copied or adapted from a prior form.\",\"s\":\"The linguist argued that some root words are nonderived and cannot be broken into smaller meaningful parts.\",\"p\":\"non-deh-RYVD\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.derived\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondermal\",\"d\":\"Not relating to or involving the skin; describing a process, route of administration, or condition that does not affect or pass through the skin.\",\"s\":\"The allergic reaction was nondermal, meaning it affected the lungs rather than the skin.\",\"p\":\"non-DUR-mul\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.der.mal\",\"ps\":\"adjective\",\"t\":[\"body\",\"maps\",\"olatin\"]},{\"w\":\"nondescendant\",\"d\":\"Not a descendant of a particular ancestor or source; describing an individual, group, or item that does not come from or trace its lineage to a specific origin.\",\"s\":\"Historians noted that the king's chosen heir was a nondescendant, unrelated by blood to the royal family.\",\"p\":\"non-deh-SEN-dunt\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.de.scen.dant\",\"ps\":\"noun\",\"t\":[\"kinship\",\"olatin\"]},{\"w\":\"nondescribable\",\"d\":\"Impossible or very difficult to describe in words; so unusual, complex, or overwhelming that language cannot adequately capture its qualities.\",\"s\":\"The beauty of the mountain sunrise was almost nondescribable, leaving the hikers completely speechless.\",\"p\":\"non-deh-SKRY-buh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.de.scrib.able\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nondescriptness\",\"d\":\"The quality of being unremarkable, plain, or lacking any distinctive features; the state of being so ordinary that one is hard to notice or describe.\",\"s\":\"The spy's nondescriptness made him perfect for the job — no one ever noticed him in a crowd.\",\"p\":\"non-deh-SKRIPT-nus\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.de.script.ness\",\"ps\":\"noun\",\"t\":[\"landforms\",\"olatin\"]},{\"w\":\"nondeserted\",\"d\":\"Not abandoned or empty; describing a place that still has inhabitants, activity, or signs of life and has not been left behind.\",\"s\":\"The nondeserted island was full of wildlife and lush plants, welcoming the explorers warmly.\",\"p\":\"non-deh-ZUR-tid\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.de.sert.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondesertion\",\"d\":\"The absence of desertion; the act or state of remaining loyal and not abandoning one's post, duties, or responsibilities.\",\"s\":\"The soldier received a commendation for nondesertion in the face of extreme danger.\",\"p\":\"non-deh-ZUR-shun\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.de.ser.tion\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nondeserving\",\"d\":\"Not worthy of receiving something; describing a person or group that has not earned or merited a particular reward, privilege, or recognition.\",\"s\":\"The committee debated whether the candidate was nondeserving of the award given the recent controversy.\",\"p\":\"non-deh-ZUR-ving\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.de.serv.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondesignated\",\"d\":\"Not officially assigned, labeled, or set apart for a specific purpose or role; lacking an official designation or classification.\",\"s\":\"The parking lot had several nondesignated spaces where anyone could park without a special permit.\",\"p\":\"non-DEZ-ig-nay-tid\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.des.ig.nat.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondesignating\",\"d\":\"Not assigning or marking something for a specific purpose, role, or identity; lacking the act of officially labeling or appointing.\",\"s\":\"The nondesignating committee refused to officially label any part of the park as restricted.\",\"p\":\"non-DEZ-ig-nay-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.des.ig.nat.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondesignative\",\"d\":\"Not serving to designate, identify, or point to a specific referent; describing language or symbols that do not assign or indicate a particular meaning or target.\",\"s\":\"The professor explained that some words are nondesignative and don't point to any specific object or idea.\",\"p\":\"non-DEZ-ig-nuh-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.des.ig.na.tive\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nondesigned\",\"d\":\"Not created according to a plan or intentional design; arising by chance or naturally without deliberate planning or artistic intention.\",\"s\":\"The artist claimed her sculpture was nondesigned, created through random movements and pure instinct.\",\"p\":\"non-deh-ZYND\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.de.signed\",\"ps\":\"adjective\",\"t\":[\"painting\",\"olatin\"]},{\"w\":\"nondesigner\",\"d\":\"A person who is not a professional designer; someone who creates or chooses items without formal training or expertise in design.\",\"s\":\"The nondesigner on the team still had great ideas for the school poster.\",\"p\":\"non-deh-ZY-nur\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.de.sign.er\",\"ps\":\"noun\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nondesirable\",\"d\":\"Not wanted or considered favorable; describing something that is unpleasant, unwanted, or not worth seeking out.\",\"s\":\"The coach removed all nondesirable habits from the team's training routine.\",\"p\":\"non-deh-ZY-ruh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.de.sir.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondesired\",\"d\":\"Not wanted or wished for; describing an outcome, effect, or object that was not sought or intended.\",\"s\":\"The experiment produced several nondesired side effects that confused the scientists.\",\"p\":\"non-deh-ZYRD\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.de.sired\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondesktop\",\"d\":\"Not designed for or relating to a traditional desktop computer; describing software, hardware, or devices intended for mobile, tablet, or other non-desk-based platforms.\",\"s\":\"The students used nondesktop devices like tablets and phones to complete their assignments.\",\"p\":\"non-DESK-top\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.desk.top\",\"ps\":\"adjective\",\"t\":[\"pharmacy\",\"household\",\"festivals\",\"tools\",\"olatin\"]},{\"w\":\"nondesperate\",\"d\":\"Not in a state of desperation or extreme urgency; describing a situation or person that is calm, stable, and not driven by dire need or crisis.\",\"s\":\"She remained nondesperate about the situation, calmly thinking through her options.\",\"p\":\"non-DES-pur-it\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.des.per.ate\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondestination\",\"d\":\"A place that is not considered a final target or goal for travel; describing a location that serves as a point along a journey rather than the intended endpoint.\",\"s\":\"The wandering traveler treated every stop as a nondestination, just passing through.\",\"p\":\"non-des-tih-NAY-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.des.ti.na.tion\",\"ps\":\"noun\",\"t\":[\"sports\",\"olatin\"]},{\"w\":\"nondestructive\",\"d\":\"Not causing damage or destruction; describing a method of testing or examining something that leaves the original object intact and undamaged.\",\"s\":\"The engineer used nondestructive testing to check the bridge without damaging it.\",\"p\":\"non-deh-STRUK-tiv\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.de.struc.tive\",\"ps\":\"adjective\",\"t\":[\"botany\",\"olatin\"]},{\"w\":\"nondestructively\",\"d\":\"In a manner that does not cause damage or destruction; performing an action, especially a test or evaluation, while leaving the subject completely unharmed.\",\"s\":\"Scientists scanned the ancient artifact nondestructively so it remained perfectly preserved.\",\"p\":\"non-deh-STRUK-tiv-lee\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.de.struc.tive.ly\",\"ps\":\"adverb\",\"t\":[\"olatin\"]},{\"w\":\"nondetachable\",\"d\":\"Not able to be separated or removed from the main object or structure; permanently fixed and unable to be taken apart or disconnected.\",\"s\":\"The battery was nondetachable, meaning it could not be removed from the device.\",\"p\":\"non-deh-TACH-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.de.tach.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondetached\",\"d\":\"Not separated or removed from something; remaining joined, connected, or emotionally involved rather than being kept apart or at a distance.\",\"s\":\"The nondetached garage was built directly against the side of the house.\",\"p\":\"non-deh-TACHT\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.de.tached\",\"ps\":\"adjective\",\"t\":[\"emotions\",\"olatin\"]},{\"w\":\"nondetailed\",\"d\":\"Lacking detail or specificity; describing an account, report, or description that is general and does not include precise or thorough information.\",\"s\":\"The teacher asked for a nondetailed summary, just the main points.\",\"p\":\"non-deh-TAYLD\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.de.tailed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondetectable\",\"d\":\"Impossible to detect or discover using available methods or instruments; so small, hidden, or subtle that it cannot be identified or measured.\",\"s\":\"The dye was nondetectable to the naked eye but glowed under ultraviolet light.\",\"p\":\"non-deh-TEK-tuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.de.tectable\",\"ps\":\"adjective\",\"t\":[\"music\",\"numbers\",\"olatin\"]},{\"w\":\"nondetection\",\"d\":\"The failure or inability to detect something; the state in which a substance, signal, or object is not identified or discovered by sensors, tests, or observation.\",\"s\":\"The spy relied on nondetection to move through the building unnoticed.\",\"p\":\"non-deh-TEK-shun\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.de.tec.tion\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nondetective\",\"d\":\"Not related to or characteristic of a detective or detective work; lacking the qualities of investigation or crime-solving.\",\"s\":\"The nondetective staff member solved the mystery by accident, not skill.\",\"p\":\"non-deh-TEK-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.de.tec.tive\",\"ps\":\"adjective\",\"t\":[\"law\",\"economy\",\"olatin\"]},{\"w\":\"nondetergent\",\"d\":\"Not containing or functioning as a detergent; lacking the cleaning or surfactant properties found in soaps and detergents.\",\"s\":\"The mechanic used a nondetergent oil because the old engine required it.\",\"p\":\"non-deh-TER-jent\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.de.ter.gent\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondeteriorative\",\"d\":\"Not causing or involving deterioration; describing something that does not break down, decay, or become worse over time.\",\"s\":\"Researchers sought a nondeteriorative coating to keep metal from rusting over time.\",\"p\":\"non-deh-TEER-ee-or-ah-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":33,\"sy\":\"non.de.te.ri.o.ra.tive\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nondeterminate\",\"d\":\"Not fixed, settled, or precisely defined; lacking a clear or definite conclusion or boundary.\",\"s\":\"The outcome of the experiment was nondeterminate, with many possible results.\",\"p\":\"non-deh-TER-mih-nit\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.de.ter.mi.nate\",\"ps\":\"adjective\",\"t\":[\"maps\",\"logic\",\"olatin\"]},{\"w\":\"nondetermined\",\"d\":\"Not decided or resolved; lacking a firm conclusion or a clearly established outcome.\",\"s\":\"The scientist called the cause nondetermined until more evidence was gathered.\",\"p\":\"non-deh-TER-mind\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.de.ter.mined\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nondeterrent\",\"d\":\"Not serving as a deterrent; incapable of discouraging or preventing an action or behavior.\",\"s\":\"Critics argued the mild punishment was nondeterrent and did nothing to stop crime.\",\"p\":\"non-deh-TER-ent\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.de.ter.rent\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondetrimental\",\"d\":\"Not causing harm, damage, or disadvantage; having no negative or injurious effect on someone or something.\",\"s\":\"Doctors confirmed the new diet was nondetrimental to the patient's health.\",\"p\":\"non-det-rih-MEN-tul\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.detri.men.tal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondetrital\",\"d\":\"Not composed of or relating to detritus or fragments of rock and organic material; describing sediment or matter that did not originate from the breakdown of pre-existing material.\",\"s\":\"The geologist identified nondetrital minerals that had formed in place rather than being transported.\",\"p\":\"non-deh-TRY-tul\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.de.tri.tal\",\"ps\":\"adjective\",\"t\":[\"minerals\",\"olatin\"]},{\"w\":\"nondevelopable\",\"d\":\"Not capable of being developed, expanded, or built upon; describing land or a concept that cannot be further advanced or improved.\",\"s\":\"The wetland was designated as nondevelopable land to protect local wildlife.\",\"p\":\"non-deh-VEL-up-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.de.vel.opable\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondevelopment\",\"d\":\"failure of normal development to occur\",\"s\":\"Scientists were alarmed by the nondevelopment of the tadpoles in the polluted pond.\",\"p\":\"non-deh-VEL-up-ment\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.de.vel.op.ment\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nondeviant\",\"d\":\"Conforming to accepted norms or standards; not departing from what is considered typical or expected behavior.\",\"s\":\"The student's nondeviant behavior made him a model example for the class.\",\"p\":\"non-DEE-vee-unt\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.de.viant\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondeviantly\",\"d\":\"In a manner that conforms to accepted norms; without departing from expected or standard behavior.\",\"s\":\"She acted nondeviantly throughout her time at school, always following the rules.\",\"p\":\"non-DEE-vee-unt-lee\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.de.viant.ly\",\"ps\":\"adverb\",\"t\":[\"olatin\"]},{\"w\":\"nondeviator\",\"d\":\"A person or thing that does not deviate from an established path, rule, or standard; one who consistently follows expected norms.\",\"s\":\"As a nondeviator, he always stuck to the original plan no matter what happened.\",\"p\":\"non-DEE-vee-ay-ter\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.de.vi.a.tor\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nondevotional\",\"d\":\"Not related to or intended for religious devotion or worship; lacking a spiritual or pious character.\",\"s\":\"The nondevotional assembly focused on school achievements rather than prayer.\",\"p\":\"non-deh-VOH-shun-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.de.vo.tion.al\",\"ps\":\"adjective\",\"t\":[\"religion\",\"olatin\"]},{\"w\":\"nondextrose\",\"d\":\"Not consisting of or derived from dextrose; describing a sugar or carbohydrate that is not the simple glucose sugar known as dextrose.\",\"s\":\"The lab tested nondextrose sugars to see how the body processed them differently.\",\"p\":\"non-DEK-strohz\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.dex.trose\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondiabetes\",\"d\":\"The absence of diabetes; a condition or state in which a person does not have diabetes mellitus.\",\"s\":\"The doctor confirmed that the patient's condition was nondiabetes, easing his worry.\",\"p\":\"non-dy-uh-BEE-teez\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.di.a.betes\",\"ps\":\"noun\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"nondiabetic\",\"d\":\"Not having, relating to, or characteristic of diabetes; describing a person who does not have diabetes or a substance not associated with the disease.\",\"s\":\"The nutritionist designed a meal plan suitable for both diabetic and nondiabetic patients.\",\"p\":\"non-dy-uh-BET-ik\",\"o\":\"Latin\",\"y\":7,\"bp\":38,\"sy\":\"non.di.a.bet.ic\",\"ps\":\"adjective\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"nondiagnosed\",\"d\":\"Not having received a formal medical diagnosis; describing a condition or person for whom no official diagnosis has been determined.\",\"s\":\"Many nondiagnosed conditions go untreated because patients never see a doctor.\",\"p\":\"non-dy-ag-NOZD\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.di.ag.nosed\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nondiagnostic\",\"d\":\"Not providing enough information to reach a diagnosis; failing to identify or distinguish a particular disease or condition.\",\"s\":\"The test results were nondiagnostic, giving the doctors no clear answer.\",\"p\":\"non-dy-ag-NOS-tik\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.di.ag.nos.tic\",\"ps\":\"adjective\",\"t\":[\"body\",\"disease\",\"olatin\"]},{\"w\":\"nondiagonal\",\"d\":\"Not diagonal; describing a line, direction, or arrangement that does not run at a slant between opposite corners but instead follows a straight horizontal or vertical path.\",\"s\":\"The architect insisted on nondiagonal lines to keep the design simple and clean.\",\"p\":\"non-dy-AG-uh-nul\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.di.ag.o.nal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondialectal\",\"d\":\"Not characteristic of or belonging to a particular regional dialect; using standard language rather than a local or regional variation.\",\"s\":\"The announcer used nondialectal speech so everyone across the country could understand.\",\"p\":\"non-dy-uh-LEK-tul\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.di.alec.tal\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nondialup\",\"d\":\"Not using or requiring a dial-up telephone connection to access the internet; describing broadband or other high-speed internet connections.\",\"s\":\"The school upgraded to nondialup internet so pages loaded instantly.\",\"p\":\"non-DY-ul-up\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.di.alup\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondialysis\",\"d\":\"Not involving or requiring the medical process of dialysis to filter waste from the blood; describing kidney function or treatment that does not depend on a dialysis machine.\",\"s\":\"The doctor was pleased that the patient's kidneys were healthy enough for nondialysis treatment.\",\"p\":\"non-dy-AL-ih-sis\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"non.dial.y.sis\",\"ps\":\"adjective\",\"t\":[\"body\",\"tools\",\"olatin\"]},{\"w\":\"nondialyzable\",\"d\":\"Unable to pass through a semipermeable membrane during dialysis; describing a substance whose molecules are too large to be separated by the dialysis process.\",\"s\":\"The large protein was nondialyzable, meaning it could not pass through the membrane.\",\"p\":\"non-DY-uh-ly-zuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.di.a.lyz.able\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nondiapausing\",\"d\":\"Not entering diapause, which is a period of suspended development in insects and other animals; continuing to develop or remain active without a dormant resting phase.\",\"s\":\"The nondiapausing insects kept developing through winter without entering a dormant state.\",\"p\":\"non-dy-uh-PAW-zing\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.di.a.paus.ing\",\"ps\":\"adjective\",\"t\":[\"animals\",\"insects\",\"olatin\"]},{\"w\":\"nondiaphragmatic\",\"d\":\"Not relating to, involving, or produced by the diaphragm muscle; describing breathing, sounds, or structures that do not involve the diaphragm.\",\"s\":\"The surgeon noted the nondiaphragmatic origin of the patient's breathing problem.\",\"p\":\"non-dy-uh-frag-MAT-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.di.aphrag.mat.ic\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nondiastatic\",\"d\":\"Not having or exhibiting diastatic activity; describing a substance, especially malt or flour, that lacks the enzymes needed to convert starch into sugar.\",\"s\":\"The baker chose nondiastatic malt to add flavor without affecting the dough's rise.\",\"p\":\"non-dy-uh-STAT-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.di.astat.ic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondictatorial\",\"d\":\"Not characteristic of or resembling a dictatorship; not imposing absolute authority or demanding total obedience from others.\",\"s\":\"The nondictatorial leader welcomed debate and allowed citizens to vote freely on important issues.\",\"p\":\"non-dik-tuh-TOR-ee-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.dic.ta.to.ri.al\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"nondictatorship\",\"d\":\"A system of government or organization that is not ruled by a single all-powerful leader; the absence of dictatorial rule.\",\"s\":\"The new constitution guaranteed a nondictatorship government where power was shared among elected officials.\",\"p\":\"non-dik-TAY-ter-ship\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.dic.ta.tor.ship\",\"ps\":\"noun\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"nondictionary\",\"d\":\"Not found in or recognized by a standard dictionary; describing a word, term, or expression that is not officially recorded as part of the standard language.\",\"s\":\"The slang terms used in the text messages were completely nondictionary words that confused the teacher.\",\"p\":\"non-DIK-shuh-nair-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.dic.tionary\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nondidactically\",\"d\":\"In a manner that is not intended to teach a moral lesson or instruct the audience; presenting ideas without a preachy or instructional tone.\",\"s\":\"The author wrote nondidactically, telling an entertaining story without trying to teach a moral lesson.\",\"p\":\"non-dy-DAK-tik-lee\",\"o\":\"Latin\",\"y\":9,\"bp\":31,\"sy\":\"non.di.dac.ti.cal.ly\",\"ps\":\"adverb\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nondiegetic\",\"d\":\"Not existing within the story world of a film, game, or narrative; describing sound, music, or narration that is heard by the audience but not by the characters within the story.\",\"s\":\"The nondiegetic music swelled dramatically during the movie scene, even though no one in the film could hear it.\",\"p\":\"non-dy-uh-JET-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":34,\"sy\":\"nondieget.ic\",\"ps\":\"adjective\",\"t\":[\"music\",\"poetry\",\"sports\",\"olatin\"]},{\"w\":\"nondietary\",\"d\":\"Not related to or determined by diet or eating habits; describing factors, treatments, or conditions that have nothing to do with food consumption.\",\"s\":\"The doctor said the patient's health problems were nondietary, meaning food choices were not the cause.\",\"p\":\"non-DY-uh-tair-ee\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"nondi.etary\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondieter\",\"d\":\"A person who does not follow a diet or restrict their food intake for the purpose of losing weight or improving health.\",\"s\":\"As a nondieter, Marcus ate whatever he wanted without counting calories or avoiding any foods.\",\"p\":\"non-DY-uh-ter\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"nondi.eter\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nondieting\",\"d\":\"Not engaging in or related to the practice of restricting food intake for weight loss or health purposes; describing an approach to eating that involves no formal dietary restrictions.\",\"s\":\"Her nondieting approach to health focused on joyful movement and listening to her body's hunger cues.\",\"p\":\"non-DY-uh-ting\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"nondi.et.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondifferent\",\"d\":\"Not different; being the same or identical in quality, nature, or character as something else.\",\"s\":\"The two water samples appeared nondifferent under basic testing, so scientists ran more advanced experiments.\",\"p\":\"non-DIF-er-ent\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.dif.fer.ent\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondifferentiable\",\"d\":\"In mathematics, describing a function that does not have a well-defined derivative at one or more points; not capable of being differentiated.\",\"s\":\"The sharp corner on the graph created a nondifferentiable point that the calculus student struggled to analyze.\",\"p\":\"non-dif-er-EN-shee-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.dif.fer.en.tiable\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nondifferential\",\"d\":\"Not involving or relating to a difference or distinction; in mathematics, not pertaining to differential calculus or rates of change.\",\"s\":\"The scientist used a nondifferential equation to model the system because the rates of change were constant.\",\"p\":\"non-dif-er-EN-shul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.dif.fer.en.tial\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nondifferentiated\",\"d\":\"Not having developed distinct or specialized characteristics; describing cells, organisms, or groups that have not become specialized for particular functions.\",\"s\":\"The stem cells remained nondifferentiated in the lab until scientists exposed them to specific chemicals.\",\"p\":\"non-dif-er-EN-shee-ay-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":33,\"sy\":\"non.dif.fer.en.ti.at.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondiffracting\",\"d\":\"Not bending or spreading out when passing through an opening or around an obstacle; describing a beam of light or waves that travels in a straight path without diffracting.\",\"s\":\"Scientists celebrated when they created a nondiffracting laser beam that traveled in a perfectly straight line.\",\"p\":\"non-dih-FRAK-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.diffract.ing\",\"ps\":\"adjective\",\"t\":[\"waterways\",\"olatin\"]},{\"w\":\"nondiffractive\",\"d\":\"Not involving or exhibiting diffraction; describing a wave, beam, or optical element that does not bend or spread around obstacles or through openings.\",\"s\":\"The nondiffractive lens allowed the microscope to produce sharper images than previous models.\",\"p\":\"non-dih-FRAK-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.diffrac.tive\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"physics\",\"olatin\"]},{\"w\":\"nondiffuse\",\"d\":\"Not diffuse; remaining concentrated or focused rather than spreading out in multiple directions.\",\"s\":\"The nondiffuse light from the lamp created a sharp, focused beam rather than a soft glow.\",\"p\":\"non-dih-FYOOS\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.dif.fuse\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondiffused\",\"d\":\"Not spread out or scattered; remaining concentrated in one area rather than dispersing throughout a medium.\",\"s\":\"The nondiffused dye stayed concentrated in one spot in the jar of water rather than spreading out.\",\"p\":\"non-dih-FYOOZD\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.dif.fused\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondiffusible\",\"d\":\"Not capable of diffusing or spreading through a membrane, barrier, or medium; unable to pass from one area to another by diffusion.\",\"s\":\"The large protein molecule was nondiffusible and could not pass through the tiny holes of the membrane.\",\"p\":\"non-dih-FYOO-zih-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.dif.fusible\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondiffusing\",\"d\":\"Not in the process of diffusing or spreading out; remaining in place without dispersing through a surrounding medium.\",\"s\":\"The nondiffusing gas remained trapped in the sealed container and did not blend with the surrounding air.\",\"p\":\"non-dih-FYOO-zing\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.dif.fus.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondiffusive\",\"d\":\"Not characterized by diffusion; describing a process or substance that does not tend to spread or disperse gradually through a medium.\",\"s\":\"The nondiffusive material acted as an excellent barrier, preventing gases from seeping through its layers.\",\"p\":\"non-dih-FYOO-siv\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.dif.fu.sive\",\"ps\":\"adjective\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nondigestible\",\"d\":\"not digestible\",\"s\":\"Cellulose is a nondigestible fiber that passes through the human body without being broken down.\",\"p\":\"non-dih-JES-tih-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":23,\"sy\":\"nondi.gestible\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondigital\",\"d\":\"Not involving digital technology, electronic devices, or computer-based systems; relating to physical, analog, or hand-produced methods.\",\"s\":\"The elderly man preferred nondigital tools like paper maps and printed books over smartphones and tablets.\",\"p\":\"non-DIJ-ih-tul\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"nondig.i.tal\",\"ps\":\"adjective\",\"t\":[\"physics\",\"tools\",\"olatin\"]},{\"w\":\"nondigitally\",\"d\":\"In a manner that does not use digital technology or electronic devices; by means of physical, analog, or traditional methods.\",\"s\":\"She chose to record her memories nondigitally, writing in a leather journal with a fountain pen.\",\"p\":\"non-DIJ-ih-tul-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"nondig.i.tal.ly\",\"ps\":\"adverb\",\"t\":[\"physics\",\"festivals\",\"tools\",\"olatin\"]},{\"w\":\"nondigitizable\",\"d\":\"Not capable of being converted into a digital format or represented as numerical data by electronic systems.\",\"s\":\"Some three-dimensional sculptures are considered nondigitizable because their texture and depth cannot be fully captured in a digital file.\",\"p\":\"non-DIJ-ih-ty-zy-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"nondig.i.ti.z.able\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nondigitized\",\"d\":\"Not converted into a digital format; existing only in physical or analog form without having been processed by a computer or scanner.\",\"s\":\"Many old hospital records remained nondigitized, stored in dusty paper folders in the basement.\",\"p\":\"non-DIJ-ih-tyzd\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"nondig.i.tized\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondilated\",\"d\":\"Not widened or expanded; describing a vessel, pupil, or opening that has not been stretched or enlarged from its normal size.\",\"s\":\"The doctor noted that the patient's pupils were nondilated, indicating no reaction to the medication.\",\"p\":\"non-DY-lay-tid\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"nondi.lat.ed\",\"ps\":\"adjective\",\"t\":[\"seafaring\",\"olatin\"]},{\"w\":\"nondilatonic\",\"d\":\"Not involving dilatonic effects or fields; used in physics to describe models or theories that do not include a dilaton scalar field.\",\"s\":\"The physicist described the nondilatonic string theory model as one that excluded certain expansion factors.\",\"p\":\"non-dy-luh-TON-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"nondila.ton.ic\",\"ps\":\"adjective\",\"t\":[\"physics\",\"logic\",\"olatin\"]},{\"w\":\"nondiligence\",\"d\":\"The absence of diligence or careful effort; a lack of steady, attentive, and hardworking behavior in completing tasks.\",\"s\":\"The teacher warned that nondiligence in studying would lead to poor results on the upcoming exam.\",\"p\":\"non-DIL-ih-junts\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"nondili.gence\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nondilutive\",\"d\":\"Not causing dilution or a reduction in concentration, value, or proportion; in finance, describing stock offerings that do not reduce existing shareholders' ownership percentage.\",\"s\":\"The company announced a nondilutive funding deal, meaning existing shareholders would not lose any ownership percentage.\",\"p\":\"non-dih-LOO-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"nondi.lu.tive\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nondimensional\",\"d\":\"Having no physical units or dimensions; describing a quantity or number that is expressed as a pure ratio without measurements such as meters or seconds.\",\"s\":\"Scientists use nondimensional numbers like pi to compare physical systems regardless of their units of measurement.\",\"p\":\"non-dih-MEN-shun-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nondi.men.sion.al\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nondimensionalized\",\"d\":\"Converted into a form that has no physical units by dividing by appropriate reference quantities, making equations easier to compare across different scales.\",\"s\":\"The engineer nondimensionalized the equation so it could be applied to any size of the physical model.\",\"p\":\"non-dih-MEN-shun-ul-yzd\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"nondi.men.sion.al.ized\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nondimensionally\",\"d\":\"In a manner that involves no physical units or dimensions; expressed as a pure number without reference to a measurement scale.\",\"s\":\"The aeronautical team expressed the results nondimensionally so engineers worldwide could use them easily.\",\"p\":\"non-dih-MEN-shun-ul-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"nondi.men.sion.al.ly\",\"ps\":\"adverb\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nondimorphic\",\"d\":\"Not exhibiting dimorphism; existing in only one form rather than two distinct forms based on sex, season, or other factors.\",\"s\":\"The nondimorphic species showed no visible differences between males and females, making identification tricky.\",\"p\":\"non-dy-MOR-fik\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"nondi.mor.phic\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nondinosaurian\",\"d\":\"Not belonging to or characteristic of the dinosaurs; describing any animal or organism that is not classified within the dinosaur group.\",\"s\":\"The fossil was confirmed to be nondinosaurian, belonging instead to an ancient crocodile-like reptile.\",\"p\":\"non-dy-nuh-SOR-ee-un\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"nondi.nosauri.an\",\"ps\":\"adjective\",\"t\":[\"animals\",\"olatin\"]},{\"w\":\"nondiphthongal\",\"d\":\"Not of or relating to a diphthong; describing a vowel sound that remains a single, pure sound rather than gliding between two vowel positions.\",\"s\":\"The linguist noted that the vowel sound was nondiphthongal, staying on one pure sound without gliding.\",\"p\":\"non-dif-THONG-gul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"nondiph.thon.gal\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nondiploid\",\"d\":\"Not having the normal double set of chromosomes found in most body cells; describing cells or organisms with a chromosome number other than the standard diploid count.\",\"s\":\"Cancer cells are often nondiploid, carrying abnormal numbers of chromosomes instead of the usual paired sets.\",\"p\":\"non-DIP-loyd\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nondiplomatic\",\"d\":\"Not diplomatic; lacking tact, skill in negotiation, or the careful sensitivity needed to handle delicate situations or relationships between people or nations.\",\"s\":\"His nondiplomatic response offended the foreign ambassador and nearly caused an international incident.\",\"p\":\"non-dip-luh-MAT-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nondiplo.mat.ic\",\"ps\":\"adjective\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"nondipolar\",\"d\":\"Not having two opposite electric or magnetic poles; describing a molecule or field that lacks a dipole moment or positive-negative charge separation.\",\"s\":\"The nondipolar molecule did not align itself in an electric field the way polar molecules normally do.\",\"p\":\"non-dy-POH-ler\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"nondipo.lar\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"physics\",\"time\",\"olatin\"]},{\"w\":\"nondipole\",\"d\":\"Not attributable to a dipole; referring to the portion of a magnetic or electric field that cannot be described by a simple two-pole model.\",\"s\":\"The geophysicist studied the nondipole components of Earth's magnetic field to understand its irregular variations.\",\"p\":\"non-DY-pohl\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nondirect\",\"d\":\"Not direct; not following a straight or immediate path or approach; involving intermediate steps, detours, or indirect means.\",\"s\":\"The therapist used a nondirect approach, asking open-ended questions rather than telling patients what to do.\",\"p\":\"NAH-nder-EH-kt\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"naa.nder.eh.kt\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondirected\",\"d\":\"Not guided toward a specific goal or destination; occurring without external instruction, assigned purpose, or a predetermined target.\",\"s\":\"The nondirected research program allowed scientists to explore any topic that sparked their curiosity.\",\"p\":\"non-dih-REK-tid\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"nondi.rect.ed\",\"ps\":\"adjective\",\"t\":[\"sports\",\"olatin\"]},{\"w\":\"nondirectional\",\"d\":\"Not favoring or restricted to any particular direction; able to receive or transmit equally in all directions without preference for one orientation.\",\"s\":\"The nondirectional antenna picked up signals from every point on the compass equally well.\",\"p\":\"non-dih-REK-shun-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nondi.rec.tion.al\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondirectionally\",\"d\":\"In a manner that does not favor or follow any single direction; operating or functioning equally regardless of orientation or angle.\",\"s\":\"The radar system scanned nondirectionally, sweeping the entire horizon without favoring any angle.\",\"p\":\"non-dih-REK-shun-ul-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"nondi.rec.tion.al.ly\",\"ps\":\"adverb\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nondirective\",\"d\":\"Not providing specific instructions or guidance; describing an approach, especially in counseling or teaching, that encourages individuals to find their own answers rather than being told what to do.\",\"s\":\"The counselor used a nondirective approach, letting students find their own solutions rather than giving direct advice.\",\"p\":\"non-dih-REK-tiv\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"nondi.rec.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondirector\",\"d\":\"A person who does not hold the position or role of director; someone who is not responsible for directing an organization, film, or group.\",\"s\":\"As a nondirector employee, she had no authority to make final decisions about the company's budget.\",\"p\":\"non-dih-REK-ter\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"nondi.rec.tor\",\"ps\":\"noun\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nondirty\",\"d\":\"Not dirty or unclean; free from dirt, pollution, or contamination.\",\"s\":\"The inspector confirmed that the kitchen surfaces were nondirty and passed the health code check.\",\"p\":\"non-DER-tee\",\"o\":\"Latin\",\"y\":8,\"bp\":24,\"ps\":\"adjective\",\"t\":[\"kinship\",\"olatin\"]},{\"w\":\"nondisabled\",\"d\":\"Not having a physical, mental, or developmental disability; describing a person who does not experience significant limitations in major life activities.\",\"s\":\"The survey collected responses from both disabled and nondisabled participants to compare their experiences.\",\"p\":\"non-dis-AY-buld\",\"o\":\"Latin\",\"y\":7,\"bp\":34,\"sy\":\"nondis.abled\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondisadvantaged\",\"d\":\"Not experiencing social, economic, or educational disadvantage; describing individuals or groups who have access to adequate resources and opportunities.\",\"s\":\"Researchers compared test scores between disadvantaged and nondisadvantaged students across the district.\",\"p\":\"non-dis-ad-VAN-tijd\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"nondis.ad.van.taged\",\"ps\":\"adjective\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nondiscardable\",\"d\":\"Not able to be thrown away, removed, or discarded; describing something that must be kept or cannot be eliminated.\",\"s\":\"The engineer labeled those memory segments as nondiscardable so the system would never delete them during cleanup.\",\"p\":\"non-dis-KAR-duh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"nondis.card.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondiscerning\",\"d\":\"Not showing keen judgment or the ability to distinguish differences; lacking the perceptiveness to recognize subtle distinctions in quality, character, or detail.\",\"s\":\"A nondiscerning reader might miss the subtle clues the author hid throughout the story.\",\"p\":\"non-dih-SER-ning\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nondis.cern.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondischargeable\",\"d\":\"Not able to be discharged, dismissed, or eliminated; in law, describing a debt or obligation that cannot be cleared away even through bankruptcy.\",\"s\":\"Student loans are often considered nondischargeable in bankruptcy, meaning they cannot simply be wiped away.\",\"p\":\"non-dis-CHAR-juh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nondis.charge.able\",\"ps\":\"adjective\",\"t\":[\"law\",\"economy\",\"olatin\"]},{\"w\":\"nondisciplinary\",\"d\":\"Not related to discipline or punishment; describing actions, measures, or proceedings that do not involve corrective or punitive consequences.\",\"s\":\"The principal called the meeting for nondisciplinary reasons, simply wanting to celebrate student achievements.\",\"p\":\"non-DIS-ih-plih-nair-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nondis.ci.plinary\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nondiscipline\",\"d\":\"The lack or absence of discipline; a state in which orderly conduct, self-control, or structured training is absent.\",\"s\":\"The teacher worried that nondiscipline in the classroom would make learning impossible for everyone.\",\"p\":\"non-DIS-ih-plin\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nondis.ci.pline\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nondisciplined\",\"d\":\"Not disciplined or trained in orderly, controlled behavior; lacking self-control, structure, or the habits developed through consistent practice and instruction.\",\"s\":\"The nondisciplined team wasted practice time and lost focus before the big tournament.\",\"p\":\"non-DIS-ih-plind\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"nondis.ci.plined\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondisclosure\",\"d\":\"The act or condition of not revealing or sharing confidential information, often required by a legal agreement between two parties.\",\"s\":\"Both parties signed a nondisclosure agreement promising to keep the project's details completely secret.\",\"p\":\"non-dih-SKLOH-zher\",\"o\":\"Latin\",\"y\":7,\"bp\":25,\"sy\":\"nondis.clo.sure\",\"ps\":\"noun\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"nondiscordant\",\"d\":\"Not conflicting or clashing; describing sounds, ideas, or elements that are in agreement or harmony with one another.\",\"s\":\"The choir's nondiscordant harmonies filled the auditorium with a beautifully smooth sound.\",\"p\":\"non-dih-SKOR-dnt\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nondis.cor.dant\",\"ps\":\"adjective\",\"t\":[\"music\",\"olatin\"]},{\"w\":\"nondiscount\",\"d\":\"Describing a price, rate, or item that is offered at full value without any reduction or markdown applied.\",\"s\":\"The luxury boutique set nondiscount prices, refusing to offer sales or markdowns on any item.\",\"p\":\"non-DIS-kownt\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"sy\":\"nondis.count\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondiscounted\",\"d\":\"Not reduced in price; sold or offered at the original full cost without any deduction or special deal.\",\"s\":\"The nondiscounted tickets cost twice as much as the early-bird special offered last month.\",\"p\":\"non-dih-SKOWN-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nondis.count.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondiscovered\",\"d\":\"Not yet found, uncovered, or revealed; remaining hidden or unknown despite the possibility of being found.\",\"s\":\"Many nondiscovered species likely still live in the deepest parts of the ocean.\",\"p\":\"non-dih-SKUV-erd\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nondis.cov.ered\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondiscovery\",\"d\":\"The state or condition of something remaining unfound or unrevealed; the failure or absence of any new discovery being made.\",\"s\":\"The expedition ended in nondiscovery when dense fog prevented the team from reaching the cave.\",\"p\":\"non-dih-SKUV-uh-ree\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"nondis.cov.ery\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nondiscretionary\",\"d\":\"Not subject to personal choice or judgment; referring to expenses or actions that are required and cannot be avoided or adjusted.\",\"s\":\"Rent and groceries are nondiscretionary expenses because you must pay for them whether you want to or not.\",\"p\":\"non-dih-SKRESH-uh-nair-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nondis.cre.tionary\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondiscriminant\",\"d\":\"Not serving as a factor that distinguishes or separates groups; failing or declining to act as a means of differentiation between categories.\",\"s\":\"A nondiscriminant hiring policy ensures every applicant is judged solely on their qualifications.\",\"p\":\"non-dih-SKRIM-ih-nnt\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"nondis.crim.i.nant\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondiscriminate\",\"d\":\"Not making distinctions or differences in treatment between people or groups; treating all individuals equally regardless of their background or characteristics.\",\"s\":\"The shelter's nondiscriminate admission policy welcomed people of every background and circumstance.\",\"p\":\"nah-ndih-SKRIH-muh-nuh-t\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"naa.ndih.skrih.mah.nah.t\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondiscriminating\",\"d\":\"Not making unfair or biased distinctions between people or groups; applying the same standards or treatment to everyone equally.\",\"s\":\"A nondiscriminating taste test treats every sample equally, with no preferences allowed.\",\"p\":\"non-dih-SKRIM-ih-nay-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"nondis.crim.i.nat.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondiscriminator\",\"d\":\"A person or system that does not make unfair distinctions between people based on race, gender, or other characteristics; one who treats all equally.\",\"s\":\"The company proudly called itself a nondiscriminator, hiring people based only on skill and effort.\",\"p\":\"non-dih-SKRIM-ih-nay-ter\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"nondis.crim.i.na.tor\",\"ps\":\"noun\",\"t\":[\"sports\",\"olatin\"]},{\"w\":\"nondiscursive\",\"d\":\"Not expressed through reasoning or lengthy verbal explanation; conveying meaning directly or intuitively rather than through logical argument or wandering discussion.\",\"s\":\"Poetry is often nondiscursive, conveying feelings through images rather than logical argument.\",\"p\":\"non-dih-SKER-siv\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nondis.cur.sive\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nondisfigured\",\"d\":\"Not marked, scarred, or altered in appearance in a way that damages or distorts the natural form; remaining intact and unharmed in looks.\",\"s\":\"After careful surgery, the patient's face remained nondisfigured and healed without visible scarring.\",\"p\":\"non-dis-FIG-yerd\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"nond.is.fig.ured\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondisjoint\",\"d\":\"Describing two or more sets or groups that share at least one common element and therefore are not completely separate from each other.\",\"s\":\"The two math sets were nondisjoint because they shared several common elements.\",\"p\":\"non-dis-JOYNT\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"sy\":\"nondis.joint\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nondisjointed\",\"d\":\"Not broken apart or lacking coherent connection; describing ideas, parts, or structures that remain logically linked and unified.\",\"s\":\"The speaker's nondisjointed presentation flowed smoothly from one point to the next.\",\"p\":\"non-dis-JOYN-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nondis.joint.ed\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nondisjunct\",\"d\":\"Not separated or divided; describing elements that remain joined or connected rather than existing as distinct, isolated parts.\",\"s\":\"The two overlapping categories were nondisjunct, so some items appeared in both groups simultaneously.\",\"p\":\"non-dis-JUNGKT\",\"o\":\"Latin\",\"y\":8,\"bp\":34,\"sy\":\"nondis.junct\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nondisjunction\",\"d\":\"meiosis in which there is a failure of paired homologous chromosomes to separate; results in an abnormal number of chromosomes in the daughter cells\",\"s\":\"During cell division, nondisjunction caused an extra chromosome to appear in the daughter cell.\",\"p\":\"non-dis-JUNGK-shun\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"nondis.junc.tion\",\"ps\":\"noun\",\"t\":[\"kinship\",\"numbers\",\"olatin\"]},{\"w\":\"nondisparagement\",\"d\":\"The condition or requirement of refraining from making critical or belittling remarks about another person, company, or product, often enforced by a legal clause.\",\"s\":\"The contract included a nondisparagement clause preventing either side from saying negative things about the other.\",\"p\":\"non-dih-SPAIR-ij-mnt\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"nondis.par.age.ment\",\"ps\":\"noun\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"nondispersive\",\"d\":\"Not causing or involving the spreading out or scattering of particles, waves, or light; maintaining concentration or unity without separating into components.\",\"s\":\"A nondispersive medium transmits all wavelengths of light at the same speed without splitting them.\",\"p\":\"non-dih-SPER-siv\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nondis.per.sive\",\"ps\":\"adjective\",\"t\":[\"physics\",\"waterways\",\"olatin\"]},{\"w\":\"nondisplaced\",\"d\":\"Not moved from its original or proper position; often used in medicine to describe a fracture in which the broken bone pieces remain correctly aligned.\",\"s\":\"The doctor was relieved to confirm that the fracture was nondisplaced, meaning the bone stayed in alignment.\",\"p\":\"non-dih-PLAYST\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"nondis.placed\",\"ps\":\"adjective\",\"t\":[\"body\",\"pharmacy\",\"olatin\"]},{\"w\":\"nondisplayable\",\"d\":\"Not capable of being shown or presented on a screen or other display; referring to data or content that cannot be rendered visibly.\",\"s\":\"Certain special characters are nondisplayable and appear as blank boxes on older computer screens.\",\"p\":\"non-dih-PLAY-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":24,\"sy\":\"nondis.playable\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondisplayed\",\"d\":\"Not shown, exhibited, or made visible to others; kept hidden or not presented for viewing on a screen or in a public setting.\",\"s\":\"The nondisplayed data was stored in a hidden file that only administrators could access.\",\"p\":\"non-dih-PLAYD\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"nondis.played\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondisposable\",\"d\":\"(of assets) unavailable for use\",\"s\":\"The museum's nondisposable artifacts were locked in a vault and could never be sold or given away.\",\"p\":\"non-dih-SPOH-zuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nondis.pos.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondisposal\",\"d\":\"The failure or refusal to get rid of, sell, or transfer something; the condition in which property or materials are retained rather than removed or discarded.\",\"s\":\"The court ordered nondisposal of all assets until the legal case was fully resolved.\",\"p\":\"non-dih-SPOH-zul\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"nondis.pos.al\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nondisputant\",\"d\":\"A person who is not involved in or party to a dispute or argument; someone who remains neutral and does not take sides in a disagreement.\",\"s\":\"As a nondisputant observer, she watched both sides of the argument without taking any position.\",\"p\":\"non-dih-SPYOO-tnt\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"nondis.putant\",\"ps\":\"noun\",\"t\":[\"character\",\"logic\",\"olatin\"]},{\"w\":\"nondisputed\",\"d\":\"Not challenged or argued against; accepted as true or valid by all parties without any objection or controversy.\",\"s\":\"The nondisputed facts of the case were accepted by both the defense and the prosecution.\",\"p\":\"non-dih-SPYOO-ted\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"nondis.put.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondisqualification\",\"d\":\"The state of not being disqualified; the condition in which a person or entry remains eligible and has not been removed from consideration or competition.\",\"s\":\"The committee issued a nondisqualification ruling, allowing all athletes to compete despite the earlier controversy.\",\"p\":\"non-dis-kwol-ih-fih-KAY-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"nondis.qual.i.fi.ca.tion\",\"ps\":\"noun\",\"t\":[\"sports\",\"olatin\"]},{\"w\":\"nondisqualified\",\"d\":\"Not removed from eligibility or competition; describing a person or entry that has been allowed to continue because no disqualifying rule was broken.\",\"s\":\"All nondisqualified applicants were invited to continue to the next round of the competition.\",\"p\":\"non-dis-KWOL-ih-fyd\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"nondis.qual.i.fied\",\"ps\":\"adjective\",\"t\":[\"sports\",\"olatin\"]},{\"w\":\"nondisqualifying\",\"d\":\"Not causing or resulting in disqualification; describing a condition, factor, or action that does not remove a person from eligibility or competition.\",\"s\":\"The minor paperwork error was considered nondisqualifying, so her application moved forward.\",\"p\":\"non-dis-KWOL-ih-fy-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"nondis.qual.i.fy.ing\",\"ps\":\"adjective\",\"t\":[\"nations\",\"sports\",\"olatin\"]},{\"w\":\"nondisrupted\",\"d\":\"Not thrown into disorder or chaos; remaining undisturbed and continuing to function in a normal, organized manner without interference.\",\"s\":\"The nondisrupted schedule allowed every class to finish on time.\",\"p\":\"non-dis-RUP-ted\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"nondis.rupt.ed\",\"ps\":\"adjective\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"nondisruptive\",\"d\":\"Not causing disturbance, interruption, or disorder; describing behavior, technology, or changes that allow normal activities to continue without interference.\",\"s\":\"The teacher praised the students for their nondisruptive behavior during the assembly.\",\"p\":\"non-dis-RUP-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nondis.rup.tive\",\"ps\":\"adjective\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"nondisruptively\",\"d\":\"In a manner that does not cause disturbance or interruption; carrying out actions quietly and smoothly so that normal routines are not disturbed.\",\"s\":\"The construction crew worked nondisruptively so that nearby students could keep studying.\",\"p\":\"non-dis-RUP-tiv-lee\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"nondis.rup.tive.ly\",\"ps\":\"adverb\",\"t\":[\"olatin\"]},{\"w\":\"nondisseminated\",\"d\":\"Not spread or distributed widely to many people or places; remaining contained and not broadcast or shared beyond a limited audience.\",\"s\":\"The nondisseminated report was kept within the committee and never shared with the public.\",\"p\":\"non-dih-SEM-ih-nay-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"nondis.sem.i.nat.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondissemination\",\"d\":\"The failure or deliberate refusal to spread or distribute information, materials, or ideas widely among a larger population.\",\"s\":\"The organization's policy of nondissemination kept sensitive data from spreading beyond approved staff.\",\"p\":\"non-dih-sem-ih-NAY-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"nondis.sem.i.na.tion\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nondissident\",\"d\":\"Not opposing or disagreeing with an established government, authority, or official position; describing a person who conforms to or accepts the ruling power.\",\"s\":\"As a nondissident citizen, he supported the government's policies without public opposition.\",\"p\":\"non-DIS-ih-dnt\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"nondis.si.dent\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"politics\",\"olatin\"]},{\"w\":\"nondissipated\",\"d\":\"Not wasted, scattered, or used up carelessly; describing energy, resources, or effort that has been conserved and retained rather than lost.\",\"s\":\"The nondissipated energy stored in the battery was still available hours later.\",\"p\":\"non-DIS-ih-pay-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"nondis.si.pat.ed\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nondissipative\",\"d\":\"Not causing or involving the loss or wasteful scattering of energy; describing a system or process that conserves energy without releasing it as heat or waste.\",\"s\":\"Engineers preferred a nondissipative circuit because it wasted very little energy as heat.\",\"p\":\"non-DIS-ih-pay-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nondis.si.pa.tive\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nondissociable\",\"d\":\"Not capable of being separated or broken apart into distinct components; describing elements that remain bonded or connected and cannot be easily divided.\",\"s\":\"The two chemical compounds were nondissociable under normal laboratory conditions.\",\"p\":\"non-dih-SOH-shuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nondis.so.cia.ble\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nondissociated\",\"d\":\"Not separated or broken apart from a compound or group; remaining bonded together rather than splitting into individual ions or components.\",\"s\":\"The nondissociated molecules stayed bonded together even at high temperatures.\",\"p\":\"non-dih-SOH-see-ay-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"nondis.so.ci.at.ed\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nondissolved\",\"d\":\"Not broken down or mixed into a liquid solution; remaining in solid or undissolved form rather than becoming absorbed into a surrounding substance.\",\"s\":\"The nondissolved particles settled at the bottom of the beaker after stirring.\",\"p\":\"non-dih-ZOLVD\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"nondis.solved\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondistal\",\"d\":\"Not distal; describing a position or structure that is not located far from the point of origin or attachment, typically used in anatomy or biology.\",\"s\":\"The nondistal part of the bone is closer to the center of the body.\",\"p\":\"non-DIS-tul\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"nondis.tal\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nondistant\",\"d\":\"Not distant; located close by or near in space, time, or relationship rather than far away.\",\"s\":\"The nondistant mountains were clearly visible without binoculars.\",\"p\":\"non-DIS-tunt\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"nondis.tant\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nondistillable\",\"d\":\"Not capable of being purified or separated through the process of distillation, in which a liquid is heated to vapor and then condensed.\",\"s\":\"The nondistillable mixture could not be separated by heating and collecting vapors.\",\"p\":\"non-dis-TIL-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nondis.til.l.able\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nondistinct\",\"d\":\"Not clearly separate or different from something else; lacking sharp boundaries or obvious differences that set it apart.\",\"s\":\"The two shades of gray were nondistinct and almost impossible to tell apart.\",\"p\":\"non-dis-TINKT\",\"o\":\"Latin\",\"y\":8,\"bp\":34,\"sy\":\"nondis.tinct\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondistinctive\",\"d\":\"Not serving to distinguish or differentiate; lacking qualities that make something stand out or identify it as unique.\",\"s\":\"The nondistinctive uniforms made it hard to identify which team each player was on.\",\"p\":\"non-dis-TINK-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"nondis.tinc.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondistinguishable\",\"d\":\"Impossible or very difficult to tell apart from something else; so similar that no meaningful differences can be detected.\",\"s\":\"The twin sisters wore matching outfits, making them practically nondistinguishable.\",\"p\":\"non-dis-TING-gwish-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"nondis.tin.guish.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondistinguishing\",\"d\":\"Not serving to mark a difference between things; failing to identify or set apart one thing from another by any notable characteristic.\",\"s\":\"The nondistinguishing features of the suspect's description made identification very difficult.\",\"p\":\"non-dis-TING-gwish-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"nondis.tin.guish.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondistorted\",\"d\":\"Not twisted, altered, or misrepresented from its original form; remaining accurate and true to its original shape or meaning.\",\"s\":\"The nondistorted image in the mirror showed her face exactly as it appeared.\",\"p\":\"non-dis-TORT-ed\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"nondis.tort.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondistorter\",\"d\":\"A device, lens, or medium that does not bend, warp, or alter the signal, image, or information passing through it.\",\"s\":\"The high-quality lens was praised as a nondistorter that kept images perfectly clear.\",\"p\":\"non-dis-TORT-er\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"nondis.torter\",\"ps\":\"noun\",\"t\":[\"physics\",\"tools\",\"olatin\"]},{\"w\":\"nondistorting\",\"d\":\"Not causing distortion; transmitting or representing something without bending, warping, or misrepresenting its original form.\",\"s\":\"The nondistorting glass in the museum cases let visitors see artifacts with perfect clarity.\",\"p\":\"non-dis-TORT-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nondis.tort.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondistracted\",\"d\":\"Not having one's attention pulled away from the task at hand; remaining focused and not diverted by outside influences.\",\"s\":\"She remained nondistracted during the exam even when her classmates whispered nearby.\",\"p\":\"non-dis-TRAKT-ed\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nondis.tract.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondistracting\",\"d\":\"Not causing a loss of focus or attention; describing an environment, object, or activity that does not pull the mind away from its main purpose.\",\"s\":\"The library's nondistracting atmosphere helped students focus on their homework.\",\"p\":\"non-dis-TRAKT-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"nondis.tract.ing\",\"ps\":\"adjective\",\"t\":[\"ecology\",\"olatin\"]},{\"w\":\"nondistressed\",\"d\":\"Not in a state of anxiety, pain, or hardship; calm and free from suffering or emotional turmoil.\",\"s\":\"The nondistressed community recovered quickly because they had prepared for the storm.\",\"p\":\"non-dis-TREST\",\"o\":\"Latin\",\"y\":9,\"bp\":23,\"sy\":\"nondis.tressed\",\"ps\":\"adjective\",\"t\":[\"emotions\",\"olatin\"]},{\"w\":\"nondistributed\",\"d\":\"Not spread out, shared, or allocated among multiple recipients or locations; remaining concentrated in one place.\",\"s\":\"The nondistributed profits stayed in the company's account rather than being paid to shareholders.\",\"p\":\"non-dis-TRIB-yoo-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"nondis.tribut.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondistributional\",\"d\":\"Not related to or following the patterns of statistical distribution; describing data or systems that do not conform to expected distributional models.\",\"s\":\"The researcher noted that the data had a nondistributional pattern that didn't fit standard models.\",\"p\":\"non-dis-trih-BYOO-shun-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"nondis.tri.bu.tion.al\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondisturbance\",\"d\":\"The absence of disruption, interference, or agitation; a state in which something remains undisturbed and at peace.\",\"s\":\"The meditation retreat guaranteed nondisturbance so participants could relax completely.\",\"p\":\"non-dis-TUR-buns\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"nondis.tur.bance\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nondisturbed\",\"d\":\"Not interfered with, upset, or thrown into disorder; remaining in its natural or original calm and undisturbed condition.\",\"s\":\"The nondisturbed soil layers gave scientists a clear record of ancient climates.\",\"p\":\"non-dis-TURBD\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"nondis.turbed\",\"ps\":\"adjective\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"nondisturbing\",\"d\":\"Not causing agitation, alarm, or disruption; unlikely to upset, bother, or interfere with the calm of a person or environment.\",\"s\":\"The nondisturbing hum of the air conditioner barely registered in the quiet room.\",\"p\":\"non-dis-TUR-bing\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nondis.turb.ing\",\"ps\":\"adjective\",\"t\":[\"ecology\",\"olatin\"]},{\"w\":\"nondithered\",\"d\":\"Not processed using dithering, a technique in digital imaging or audio that adds controlled noise to reduce the visibility of errors or color banding.\",\"s\":\"The nondithered image appeared sharp, with no blending tricks used to fake extra colors.\",\"p\":\"non-DITH-erd\",\"o\":\"Latin\",\"y\":8,\"bp\":34,\"sy\":\"non.dithered\",\"ps\":\"adjective\",\"t\":[\"colors\",\"olatin\"]},{\"w\":\"nondithering\",\"d\":\"Not applying the technique of dithering, meaning that no random or patterned noise is added to smooth out gradients or reduce artifacts in digital images or audio.\",\"s\":\"The nondithering display setting gave graphic designers the most accurate color representation.\",\"p\":\"non-DITH-er-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"non.dither.ing\",\"ps\":\"adjective\",\"t\":[\"ancient\",\"olatin\"]},{\"w\":\"nondiuretic\",\"d\":\"Not causing an increase in urine production; describing a substance or medication that does not promote the excretion of water through the kidneys.\",\"s\":\"The doctor prescribed a nondiuretic medication that would not increase the patient's need to urinate.\",\"p\":\"non-dy-yoo-RET-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"nondi.uret.ic\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nondiurnal\",\"d\":\"Not occurring during the daytime or not following a daily cycle; active or happening at night or at irregular intervals rather than during daylight hours.\",\"s\":\"Owls are nondiurnal creatures, preferring to hunt at night rather than during the day.\",\"p\":\"non-dy-UR-nul\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"nondi.ur.nal\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nondiverse\",\"d\":\"Lacking variety or difference; made up of elements that are very similar to one another rather than representing a range of types or backgrounds.\",\"s\":\"The committee was criticized for being nondiverse because all its members had the same background.\",\"p\":\"non-dy-VERS\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.di.verse\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondiversified\",\"d\":\"Not spread across a variety of different categories, investments, or types; concentrated in a single area rather than distributed among many.\",\"s\":\"The investor's nondiversified portfolio put all his money into a single risky stock.\",\"p\":\"non-dy-VER-sih-fyd\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.di.ver.si.fied\",\"ps\":\"adjective\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nondiversity\",\"d\":\"The absence of variety, difference, or inclusion of different kinds of people, ideas, or things; a state of uniformity without meaningful variation.\",\"s\":\"The school board addressed the nondiversity problem by recruiting teachers from many different communities.\",\"p\":\"non-dy-VER-sih-tee\",\"o\":\"Latin\",\"y\":8,\"bp\":39,\"sy\":\"non.di.ver.si.ty\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nondiverted\",\"d\":\"Not redirected or turned away from its original course or purpose; continuing along its intended path without interruption.\",\"s\":\"The nondiverted funds went directly to the charity as originally planned.\",\"p\":\"non-dy-VER-ted\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.di.vert.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondiving\",\"d\":\"Not engaging in or capable of diving; describing a bird, person, or object that does not plunge headfirst into water or downward through the air.\",\"s\":\"The nondiving seabirds stayed on the surface and snatched fish with their beaks.\",\"p\":\"non-DY-ving\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.div.ing\",\"ps\":\"adjective\",\"t\":[\"birds\",\"sports\",\"olatin\"]},{\"w\":\"nondivisibility\",\"d\":\"The quality or state of not being able to be divided evenly or broken into equal parts, especially in mathematics.\",\"s\":\"The mathematician proved the nondivisibility of the prime number by any integer other than one and itself.\",\"p\":\"non-dih-viz-ih-BIL-ih-tee\",\"o\":\"Latin\",\"y\":9,\"bp\":33,\"sy\":\"non.di.vis.i.bil.i.ty\",\"ps\":\"noun\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nondivisible\",\"d\":\"Not capable of being divided evenly into equal parts without a remainder; in mathematics, describing a number that cannot be divided by another specific number without leaving a remainder.\",\"s\":\"Seven is nondivisible by two, which is why it remains a prime number.\",\"p\":\"non-dih-VIZ-ih-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":39,\"sy\":\"non.di.vis.i.ble\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nondivision\",\"d\":\"The absence of division or separation; a state in which something is not split into parts, groups, or categories.\",\"s\":\"The nondivision of the cell was a sign that something had gone wrong in the experiment.\",\"p\":\"non-dih-VIZ-hun\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.di.vi.sion\",\"ps\":\"noun\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nondivisional\",\"d\":\"Not related to or organized around a division, whether a military unit, a section of a company, or a mathematical operation of dividing.\",\"s\":\"The troops operated as a nondivisional unit, reporting directly to headquarters rather than a larger division.\",\"p\":\"non-dih-VIZH-un-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.di.vi.sion.al\",\"ps\":\"adjective\",\"t\":[\"war\",\"numbers\",\"olatin\"]},{\"w\":\"nondivisor\",\"d\":\"A number that does not divide evenly into another number, leaving a remainder rather than producing a whole-number quotient.\",\"s\":\"In math class, we listed every nondivisor of twelve to understand which numbers leave a remainder.\",\"p\":\"non-dih-VY-zer\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.di.vi.sor\",\"ps\":\"noun\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nondivorced\",\"d\":\"Not having gone through a legal divorce; still married or never having legally ended a marriage through divorce proceedings.\",\"s\":\"The survey found that most nondivorced couples had regular communication as a key habit.\",\"p\":\"non-dih-VORST\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.di.vorced\",\"ps\":\"adjective\",\"t\":[\"law\",\"kinship\",\"olatin\"]},{\"w\":\"nondivorcing\",\"d\":\"Not in the process of obtaining a divorce; remaining in a legally intact marriage without pursuing its dissolution.\",\"s\":\"The counselor studied nondivorcing families to understand what keeps marriages strong.\",\"p\":\"non-dih-VOR-sing\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.di.vorc.ing\",\"ps\":\"adjective\",\"t\":[\"law\",\"kinship\",\"olatin\"]},{\"w\":\"nondocking\",\"d\":\"Not capable of or designed for docking; describing a spacecraft, vessel, or device that cannot connect or attach to a station or another craft.\",\"s\":\"The nondocking spacecraft floated nearby but never attached to the space station.\",\"p\":\"non-DOK-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.dock.ing\",\"ps\":\"adjective\",\"t\":[\"seafaring\",\"tools\",\"olatin\"]},{\"w\":\"nondoctor\",\"d\":\"A person who is not a licensed or trained doctor; someone lacking the medical degree or qualifications of a physician.\",\"s\":\"As a nondoctor, she was still able to give basic first aid at the scene of the accident.\",\"p\":\"non-DOK-ter\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.doc.tor\",\"ps\":\"noun\",\"t\":[\"body\",\"character\",\"olatin\"]},{\"w\":\"nondoctoral\",\"d\":\"Not at the level of or related to a doctoral degree; describing educational programs, positions, or individuals that do not hold or require a doctorate.\",\"s\":\"She enrolled in a nondoctoral graduate program that led to a master's degree in two years.\",\"p\":\"non-DOK-ter-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.doc.tor.al\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondoctrinaire\",\"d\":\"Not rigidly committed to a specific doctrine or set of beliefs; flexible and open-minded rather than strictly bound to a fixed ideological system.\",\"s\":\"The nondoctrinaire teacher encouraged students to question every idea rather than accept it blindly.\",\"p\":\"non-dok-trih-NAIR\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.doc.tri.naire\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nondocumentary\",\"d\":\"Not based on or presented in the style of a documentary; referring to films, programs, or content that are fictional or not grounded in factual real-world events.\",\"s\":\"The film festival screened nondocumentary shorts, including animated and dramatic fiction pieces.\",\"p\":\"non-dok-yoo-MEN-teh-ree\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.doc.u.men.tary\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondocumented\",\"d\":\"Not recorded in official documents or written records; lacking formal paperwork or evidence to confirm identity, status, or an event.\",\"s\":\"The historian was frustrated by the nondocumented gaps in the ancient city's records.\",\"p\":\"non-DOK-yoo-men-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.doc.u.ment.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondog\",\"d\":\"Not a dog; used to describe an animal or entity that does not belong to the canine species or does not qualify as a dog.\",\"s\":\"The shelter accepted every nondog animal, from cats and rabbits to turtles and birds.\",\"p\":\"NON-dog\",\"o\":\"Latin\",\"y\":8,\"bp\":18,\"sy\":\"non.dog\",\"ps\":\"adjective\",\"t\":[\"animals\",\"olatin\"]},{\"w\":\"nondoing\",\"d\":\"The absence of action or activity; a state in which nothing is being done or carried out.\",\"s\":\"The philosopher argued that nondoing, or simply being still, was its own form of wisdom.\",\"p\":\"NON-doo-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.do.ing\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nondolomitic\",\"d\":\"Not composed of or relating to dolomite; describing rock or mineral material that lacks the characteristics of dolomite limestone.\",\"s\":\"The geologist confirmed the rock was nondolomitic, meaning it lacked the magnesium-rich mineral dolomite.\",\"p\":\"non-dol-oh-MIT-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.dolomitic\",\"ps\":\"adjective\",\"t\":[\"minerals\",\"olatin\"]},{\"w\":\"nondomain\",\"d\":\"Not constituting or belonging to a specific domain, territory, or field of knowledge or authority.\",\"s\":\"The website operated on a nondomain address, making it harder for users to find.\",\"p\":\"non-doh-MAYN\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.do.main\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"logic\",\"olatin\"]},{\"w\":\"nondomestic\",\"d\":\"Not related to the home or household; referring to things, animals, or activities that are wild, foreign, or outside the domestic sphere.\",\"s\":\"The zoo housed many nondomestic animals that could never safely live as household pets.\",\"p\":\"non-doh-MES-tik\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.do.mes.tic\",\"ps\":\"adjective\",\"t\":[\"animals\",\"household\",\"olatin\"]},{\"w\":\"nondomesticable\",\"d\":\"Impossible to tame or adapt to living with humans; describing an animal or organism that cannot be made domestic.\",\"s\":\"The wild jaguar is considered nondomesticable because it retains its fierce instincts even in captivity.\",\"p\":\"non-doh-MES-tih-kuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":31,\"sy\":\"non.do.mes.ti.ca.ble\",\"ps\":\"adjective\",\"t\":[\"animals\",\"olatin\"]},{\"w\":\"nondomiciled\",\"d\":\"Not legally established or residing in a particular country or location; describing a person who has no official fixed home address in a given place.\",\"s\":\"The nondomiciled worker traveled between countries and had no fixed legal home address.\",\"p\":\"non-DOM-ih-syld\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"non.domi.ciled\",\"ps\":\"adjective\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"nondomiciliary\",\"d\":\"Not related to or associated with a person's place of permanent residence; describing services or individuals without a fixed domicile.\",\"s\":\"The nondomiciliary patient received treatment at a clinic rather than in a residential care facility.\",\"p\":\"non-dom-ih-SIL-ee-air-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.domi.cil.iary\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondominative\",\"d\":\"Not exerting control or dominance over others; lacking a dominating or controlling quality or nature.\",\"s\":\"The teacher used a nondominative approach, letting students guide the discussion themselves.\",\"p\":\"non-DOM-ih-nay-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.dom.i.na.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondonated\",\"d\":\"Not given as a donation or gift; describing something that was obtained, used, or transferred without being donated.\",\"s\":\"The nondonated supplies had to be purchased, stretching the charity's limited budget.\",\"p\":\"non-DOH-nay-tid\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.do.nat.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondonating\",\"d\":\"Not in the act of giving or contributing something as a donation; describing a person or group that does not donate.\",\"s\":\"Nondonating members were asked to reconsider supporting the food drive before the deadline.\",\"p\":\"non-DOH-nay-ting\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.do.nat.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondonor\",\"d\":\"A person or organization that does not contribute money, blood, organs, or other resources as a donation.\",\"s\":\"As a nondonor, he was surprised to learn how easy the blood-donation process actually was.\",\"p\":\"non-DOH-ner\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.donor\",\"ps\":\"noun\",\"t\":[\"body\",\"economy\",\"olatin\"]},{\"w\":\"nondoorman\",\"d\":\"A person who does not serve in the role of a doorman; one who is not employed or assigned to manage building entry.\",\"s\":\"The nondoorman building required residents to buzz in their own guests without any front-desk help.\",\"p\":\"non-DOOR-man\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.door.man\",\"ps\":\"noun\",\"t\":[\"buildings\",\"olatin\"]},{\"w\":\"nondopaminergic\",\"d\":\"Not involving or activated by dopamine; describing neurons, pathways, or systems that do not use dopamine as a neurotransmitter.\",\"s\":\"The scientist studied nondopaminergic neurons to understand brain pathways not linked to dopamine.\",\"p\":\"non-doh-pam-ih-NER-jik\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.dopamin.er.gic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondormancy\",\"d\":\"The state or condition of being active and not dormant; the absence of a resting or inactive biological phase.\",\"s\":\"The seeds showed nondormancy and sprouted immediately after being planted in warm soil.\",\"p\":\"non-DOR-man-see\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.dor.man.cy\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nondormant\",\"d\":\"Not in a state of dormancy or inactivity; describing an organism, seed, or process that remains active rather than resting.\",\"s\":\"The nondormant volcano continued to release small puffs of steam throughout the winter.\",\"p\":\"non-DOR-mant\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.dor.mant\",\"ps\":\"adjective\",\"t\":[\"botany\",\"olatin\"]},{\"w\":\"nondormitory\",\"d\":\"Not functioning as or relating to a dormitory; describing a building or room not used for communal sleeping quarters.\",\"s\":\"The college assigned first-year students to nondormitory apartments scattered around the campus.\",\"p\":\"non-DOR-mih-tor-ee\",\"o\":\"Latin\",\"y\":8,\"bp\":39,\"sy\":\"non.dor.mi.to.ry\",\"ps\":\"adjective\",\"t\":[\"buildings\",\"olatin\"]},{\"w\":\"nondorsal\",\"d\":\"Not located on or relating to the back or upper surface of an organism; pertaining to areas other than the dorsal side.\",\"s\":\"The researcher focused on nondorsal fin injuries, examining the underside of the shark's body.\",\"p\":\"non-DOR-sul\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.dor.sal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondouble\",\"d\":\"Not double in amount, size, or quantity; consisting of a single unit rather than two.\",\"s\":\"The coach substituted a nondouble player who preferred singles matches over doubles tennis.\",\"p\":\"non-DUB-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.dou.ble\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondrafted\",\"d\":\"Not selected or recruited through a formal draft process, especially in sports or military contexts.\",\"s\":\"The nondrafted athlete worked his way onto the professional team through open tryouts.\",\"p\":\"non-DRAF-tid\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.draft.ed\",\"ps\":\"adjective\",\"t\":[\"war\",\"sports\",\"olatin\"]},{\"w\":\"nondraggable\",\"d\":\"Unable to be dragged or moved by pulling; describing an object or interface element that resists being dragged.\",\"s\":\"The icon was nondraggable on the locked screen, so she had to use the menu to move it.\",\"p\":\"non-DRAG-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.drag.gable\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nondrainage\",\"d\":\"The absence or lack of a drainage system; a condition in which water or liquid does not flow away from a given area.\",\"s\":\"The nondrainage design of the planter caused water to pool at the roots and rot the plant.\",\"p\":\"non-DRAYN-ij\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nondrained\",\"d\":\"Not having been drained of liquid; describing soil, land, or a container from which water or fluid has not been removed.\",\"s\":\"The nondrained swamp was home to dozens of rare amphibians that needed standing water to survive.\",\"p\":\"non-DRAYND\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondream\",\"d\":\"A state of sleep or thought that does not involve dreaming; the absence of dream activity during sleep.\",\"s\":\"Scientists call certain deep sleep phases nondream states because no vivid imagery occurs in them.\",\"p\":\"non-DREEM\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.dream\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nondreamer\",\"d\":\"A person who does not dream during sleep or who claims never to recall or experience dreams.\",\"s\":\"She described herself as a nondreamer, saying she almost never remembered any dreams upon waking.\",\"p\":\"non-DREEM-er\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.dream.er\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nondreaming\",\"d\":\"Not in the state of having or experiencing dreams; describing a phase of sleep or a person in which no dreaming occurs.\",\"s\":\"The study measured brain activity during nondreaming sleep to compare it with REM cycles.\",\"p\":\"non-DREEM-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.dream.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondressed\",\"d\":\"Not smoothed, shaped, or finished; describing stone, lumber, or other material left in its raw, unprocessed state.\",\"s\":\"The nondressed stone walls of the old cottage gave it a rough, rustic appearance.\",\"p\":\"non-DREST\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.dressed\",\"ps\":\"adjective\",\"t\":[\"minerals\",\"olatin\"]},{\"w\":\"nondrilling\",\"d\":\"Not involving or related to the process of drilling; describing an activity, tool, or technique that does not use a drill.\",\"s\":\"The nondrilling crew was assigned to handle surface cleanup instead of operating the equipment.\",\"p\":\"non-DRIL-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"sy\":\"non.drilling\",\"ps\":\"adjective\",\"t\":[\"tools\",\"olatin\"]},{\"w\":\"nondrinking\",\"d\":\"Not consuming alcoholic beverages; describing a person who abstains from drinking alcohol.\",\"s\":\"As a nondrinking athlete, she stuck to water and sports drinks during the team celebration.\",\"p\":\"non-DRINK-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.drink.ing\",\"ps\":\"adjective\",\"t\":[\"dishes\",\"olatin\"]},{\"w\":\"nondrip\",\"d\":\"Designed or formulated so as not to drip; describing a paint, liquid, or coating that stays in place without running.\",\"s\":\"The painter chose a nondrip formula so the walls stayed clean during the project.\",\"p\":\"non-DRIP\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.drip\",\"ps\":\"adjective\",\"t\":[\"painting\",\"olatin\"]},{\"w\":\"nondripping\",\"d\":\"Not dripping or forming drops; describing a substance or surface that holds its liquid without allowing it to fall.\",\"s\":\"The nondripping candles made the fancy dinner table look elegant without any waxy mess.\",\"p\":\"non-DRIP-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.drip.ping\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondriving\",\"d\":\"Not engaged in or related to driving a vehicle; describing a person who does not operate a car or other motor vehicle.\",\"s\":\"The nondriving passengers were free to read or nap during the long road trip.\",\"p\":\"non-DRY-ving\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.driv.ing\",\"ps\":\"adjective\",\"t\":[\"vehicles\",\"tools\",\"olatin\"]},{\"w\":\"nondropout\",\"d\":\"A person who does not drop out of school, a program, or an organization; someone who completes or continues their enrollment.\",\"s\":\"The scholarship program celebrated every nondropout student who finished the school year.\",\"p\":\"non-DROP-owt\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.dropout\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nondrowsy\",\"d\":\"Not causing or experiencing drowsiness; describing a medication or person that does not produce sleepiness.\",\"s\":\"The label on the cold medicine proudly read 'nondrowsy,' so she could take it before school.\",\"p\":\"non-DROW-zee\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nondrug\",\"d\":\"Not involving or relating to drugs; describing a treatment, therapy, or approach that does not use pharmaceutical substances.\",\"s\":\"The doctor recommended a nondrug approach, such as exercise and meditation, to manage stress.\",\"p\":\"non-DRUG\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.drug\",\"ps\":\"adjective\",\"t\":[\"body\",\"pharmacy\",\"olatin\"]},{\"w\":\"nondrugged\",\"d\":\"Not under the influence of drugs; describing a person, animal, or state that has not been administered any drugs.\",\"s\":\"The researchers needed nondrugged animals for the control group of their experiment.\",\"p\":\"non-DRUGD\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.drugged\",\"ps\":\"adjective\",\"t\":[\"pharmacy\",\"animals\",\"olatin\"]},{\"w\":\"nondrunken\",\"d\":\"Not in a state of intoxication from alcohol; describing a person who is sober and unaffected by drinking.\",\"s\":\"The nondrunken driver was the designated hero who got everyone home safely.\",\"p\":\"non-DRUNK-en\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.drunk.en\",\"ps\":\"adjective\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nondrying\",\"d\":\"Not capable of drying or hardening when exposed to air; describing oils, paints, or substances that remain wet or pliable.\",\"s\":\"The artist used nondrying clay so she could keep reshaping her sculpture over several days.\",\"p\":\"non-DRY-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"nondry.ing\",\"ps\":\"adjective\",\"t\":[\"painting\",\"olatin\"]},{\"w\":\"nondual\",\"d\":\"Not characterized by duality or the division into two opposing parts; describing a philosophy or state that recognizes oneness rather than separation.\",\"s\":\"The philosophy class explored nondual thinking, where opposites like good and evil blend together.\",\"p\":\"non-DOO-ul\",\"o\":\"Latin\",\"y\":6,\"bp\":22,\"sy\":\"non.d.u.al\",\"ps\":\"adjective\",\"t\":[\"character\",\"logic\",\"numbers\",\"olatin\"]},{\"w\":\"nondualistic\",\"d\":\"Not based on or relating to dualism; describing a belief system or perspective that does not divide reality into two distinct, opposing forces or substances.\",\"s\":\"Her nondualistic worldview helped her see connections between ideas that others thought were opposites.\",\"p\":\"non-doo-uh-LIS-tik\",\"o\":\"Latin\",\"y\":8,\"bp\":41,\"sy\":\"non.d.u.al.is.tic\",\"ps\":\"adjective\",\"t\":[\"physics\",\"logic\",\"numbers\",\"olatin\"]},{\"w\":\"nondubbed\",\"d\":\"Describing audio or video content that has not been dubbed—meaning the original language or sound track has not been replaced with a translated or alternative version.\",\"s\":\"Film fans often prefer the nondubbed version of a foreign movie so they can hear the original voices.\",\"p\":\"non-DUBD\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.dubbed\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonducted\",\"d\":\"Not carried or transmitted through a duct or channel; describing airflow or substances that move without the use of pipes or conduits.\",\"s\":\"The nonducted airflow system spread cool air throughout the room without using any tubes or pipes.\",\"p\":\"non-DUK-tid\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.duct.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonductile\",\"d\":\"Not capable of being drawn out, stretched, or bent without breaking; lacking the property of ductility that allows metals to be shaped.\",\"s\":\"Glass is a nonductile material, meaning it shatters instead of bending when force is applied.\",\"p\":\"non-DUK-tyl\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.duc.tile\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonduplex\",\"d\":\"Describing a system or device that does not operate in duplex mode, meaning it cannot transmit and receive signals simultaneously or does not have two units combined.\",\"s\":\"The nonduplex printer could only print on one side of the paper at a time.\",\"p\":\"non-DOO-pleks\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"nondu.plex\",\"ps\":\"adjective\",\"t\":[\"tools\",\"olatin\"]},{\"w\":\"nondurability\",\"d\":\"The quality or state of not being durable; the tendency to wear out, break down, or deteriorate quickly rather than lasting a long time.\",\"s\":\"The toy's nondurability was obvious when it broke on the very first day.\",\"p\":\"non-dyoor-uh-BIL-ih-tee\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.dura.bil.i.ty\",\"ps\":\"noun\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nondurable\",\"d\":\"Not made to last a long time; describing goods or materials that are quickly consumed or that wear out rapidly under normal use.\",\"s\":\"Paper plates are nondurable and meant to be used just once before being thrown away.\",\"p\":\"nah-NDUH-ruh-buh-l\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"naa.nduh.rah.bah.l\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nondurational\",\"d\":\"Not relating to or measured by duration; describing something that exists or occurs outside the concept of time length or has no measurable time span.\",\"s\":\"The philosopher argued that certain mental states are nondurational, existing outside of time.\",\"p\":\"non-dyoo-RAY-shuh-nul\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.dura.tional\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"time\",\"olatin\"]},{\"w\":\"nondusty\",\"d\":\"Free from dust; describing a surface, environment, or substance that does not produce or accumulate dust particles.\",\"s\":\"The nondusty workshop impressed visitors because every surface was spotlessly clean.\",\"p\":\"non-DUS-tee\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.dusty\",\"ps\":\"adjective\",\"t\":[\"physics\",\"ecology\",\"olatin\"]},{\"w\":\"nondutiable\",\"d\":\"Not subject to a customs duty or import tax; describing goods that can be brought across a border without requiring payment of a tariff.\",\"s\":\"The customs officer waved them through because their souvenirs were nondutiable items.\",\"p\":\"non-DYOO-tee-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.du.tiable\",\"ps\":\"adjective\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nondyadic\",\"d\":\"Not involving or limited to a pair or two-part relationship; describing interactions, structures, or relationships that involve more than two elements or parties.\",\"s\":\"The therapist used a nondyadic approach, working with the entire family rather than just two people.\",\"p\":\"non-dy-AD-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondyed\",\"d\":\"Not having been treated with dye; describing fabric, fiber, or material that retains its original, uncolored state without any artificial coloring applied.\",\"s\":\"She preferred nondyed fabric because the natural color of linen felt more authentic to her.\",\"p\":\"non-DYED\",\"o\":\"Latin\",\"y\":8,\"bp\":17,\"ps\":\"adjective\",\"t\":[\"fabrics\",\"colors\",\"olatin\"]},{\"w\":\"nondying\",\"d\":\"Not subject to death or decay; describing something that does not fade, expire, or cease to exist over time.\",\"s\":\"In mythology, gods are often portrayed as nondying beings who live for eternity.\",\"p\":\"non-DY-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"nondy.ing\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nondysfunctional\",\"d\":\"Not characterized by impaired or abnormal functioning; describing a system, relationship, or group that operates properly without serious problems or breakdowns.\",\"s\":\"The counselor was pleased to describe the family as nondysfunctional after months of therapy.\",\"p\":\"non-dis-FUNK-shuh-nul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"nondys.func.tion.al\",\"ps\":\"adjective\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nondysgenic\",\"d\":\"Not causing or relating to the deterioration of genetic qualities in a population; describing factors or influences that do not harm hereditary traits across generations.\",\"s\":\"Scientists classified the breeding program as nondysgenic because it improved the population's health.\",\"p\":\"non-dis-JEN-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"sy\":\"nondys.genic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nondyslexic\",\"d\":\"Not affected by or relating to dyslexia; describing a person who does not have difficulty with reading, writing, or processing written language.\",\"s\":\"The nondyslexic students in the study read the passage quickly and without difficulty.\",\"p\":\"non-dis-LEK-sik\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"sy\":\"nondyslex.ic\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonbird\",\"d\":\"Any animal or creature that is not a bird; used in biological or comparative contexts to distinguish birds from all other forms of animal life.\",\"s\":\"The scientist explained that a bat is a nonbird that can still fly through the night sky.\",\"p\":\"NON-berd\",\"o\":\"Malay\",\"y\":8,\"bp\":15,\"sy\":\"non.bird\",\"ps\":\"noun\",\"t\":[\"animals\",\"birds\",\"opacific\"]},{\"w\":\"nonactivity\",\"d\":\"The state of not being active or engaged in any action; a period of inactivity or rest.\",\"s\":\"The coach criticized the team's nonactivity during the second half when they stopped pressing forward.\",\"p\":\"non-ak-TIV-ih-tee\",\"o\":\"French\",\"y\":8,\"bp\":38,\"sy\":\"non.ac.tiv.i.ty\",\"ps\":\"noun\",\"t\":[\"ofrench\"]},{\"w\":\"nonadherence\",\"d\":\"The failure to follow, stick to, or comply with a rule, plan, or guideline.\",\"s\":\"The patient's nonadherence to the medication schedule caused the treatment to fail.\",\"p\":\"non-ad-HEER-ents\",\"o\":\"French\",\"y\":8,\"bp\":38,\"sy\":\"non.ad.her.ence\",\"ps\":\"noun\",\"t\":[\"ofrench\"]},{\"w\":\"nonagrarian\",\"d\":\"Not relating to farming, agriculture, or rural land use; describing an economy or society that is not based on agriculture.\",\"s\":\"As the city expanded, more residents lived a nonagrarian lifestyle, far removed from farming.\",\"p\":\"non-ah-GRAIR-ee-an\",\"o\":\"French\",\"y\":8,\"bp\":37,\"sy\":\"nona.grar.i.an\",\"ps\":\"adjective\",\"t\":[\"farming\",\"economy\",\"ofrench\"]},{\"w\":\"nonalternative\",\"d\":\"A situation or choice that offers no other option or substitute; describing something for which there is no alternative.\",\"s\":\"The judge called it a nonalternative ruling, meaning there was simply no other legal option.\",\"p\":\"non-al-TUR-nah-tiv\",\"o\":\"French\",\"y\":9,\"bp\":29,\"sy\":\"non.al.ter.na.tive\",\"ps\":\"adjective\",\"t\":[\"ofrench\"]},{\"w\":\"nonappointment\",\"d\":\"The failure or refusal to appoint someone to a position or office; the state of not being appointed.\",\"s\":\"The committee's nonappointment of a new director left the organization without leadership for months.\",\"p\":\"non-ah-POINT-ment\",\"o\":\"French\",\"y\":9,\"bp\":27,\"sy\":\"non.ap.point.ment\",\"ps\":\"noun\",\"t\":[\"ofrench\"]},{\"w\":\"nonaquatic\",\"d\":\"Not living in, found in, or relating to water; describing organisms or environments that are land-based rather than water-based.\",\"s\":\"Frogs are amphibians, meaning they can survive in both aquatic and nonaquatic environments.\",\"p\":\"non-ah-KWAT-ik\",\"o\":\"French\",\"y\":9,\"bp\":29,\"sy\":\"non.aquat.ic\",\"ps\":\"adjective\",\"t\":[\"ecology\",\"ofrench\"]},{\"w\":\"nonaqueous\",\"d\":\"Not containing, dissolving in, or using water as a solvent; describing a substance or solution that is not water-based.\",\"s\":\"The chemist used a nonaqueous solvent because water would have ruined the reaction.\",\"p\":\"non-AY-kwee-us\",\"o\":\"French\",\"y\":9,\"bp\":29,\"sy\":\"non.aque.ous\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"ofrench\"]},{\"w\":\"nonaromatic\",\"d\":\"Lacking a distinct or pleasant smell; in chemistry, describing a compound that does not have the special ring structure associated with aromatic compounds.\",\"s\":\"The nonaromatic compound lacked the pleasant smell the students expected from the lab sample.\",\"p\":\"non-air-oh-MAT-ik\",\"o\":\"French\",\"y\":8,\"bp\":35,\"sy\":\"nonaro.mat.ic\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"ofrench\"]},{\"w\":\"nonbattery\",\"d\":\"Not constituting or relating to the legal offense of battery, which involves the unlawful physical striking of another person.\",\"s\":\"The lawyer argued the charge was nonbattery since no physical contact had actually occurred.\",\"p\":\"non-BAT-er-ee\",\"o\":\"French\",\"y\":9,\"bp\":29,\"sy\":\"non.bat.tery\",\"ps\":\"adjective\",\"t\":[\"culinary\",\"law\",\"ofrench\"]},{\"w\":\"nonbias\",\"d\":\"The absence of prejudice or favoritism; treating all people or ideas fairly without leaning toward one side.\",\"s\":\"The judge was praised for her nonbias approach when deciding the controversial case.\",\"p\":\"non-BY-as\",\"o\":\"French\",\"y\":8,\"bp\":19,\"sy\":\"non.bias\",\"ps\":\"noun\",\"t\":[\"ofrench\"]},{\"w\":\"nonbowel\",\"d\":\"Not relating to or involving the bowel or intestines; describing a condition, procedure, or symptom that does not affect the digestive tract.\",\"s\":\"The doctor confirmed the patient's pain was nonbowel in origin, pointing to a muscle issue instead.\",\"p\":\"non-BOW-el\",\"o\":\"French\",\"y\":8,\"bp\":21,\"sy\":\"non.bow.el\",\"ps\":\"adjective\",\"t\":[\"body\",\"disease\",\"ofrench\"]},{\"w\":\"noncash\",\"d\":\"Not involving physical currency; relating to transactions or payments made through checks, credit, or other non-monetary means.\",\"s\":\"The charity accepted noncash donations like clothing, food, and furniture.\",\"p\":\"NAH-NKA-sh\",\"o\":\"French\",\"y\":6,\"bp\":19,\"sy\":\"naa.nkae.sh\",\"ps\":\"adjective\",\"t\":[\"economy\",\"ofrench\"]},{\"w\":\"noncompatible\",\"d\":\"Not able to exist, work, or be used together without conflict or problems; incompatible.\",\"s\":\"The two software programs were noncompatible, causing the computer to crash every time.\",\"p\":\"non-kom-PAT-ih-bul\",\"o\":\"French\",\"y\":9,\"bp\":40,\"sy\":\"non.com.pat.i.ble\",\"ps\":\"adjective\",\"t\":[\"ofrench\"]},{\"w\":\"nondemocracy\",\"d\":\"A system of government or organization that is not based on democratic principles, such as free elections or the rule of the majority.\",\"s\":\"Citizens living under a nondemocracy rarely get to vote for their own leaders.\",\"p\":\"non-deh-MOK-rah-see\",\"o\":\"French\",\"y\":8,\"bp\":38,\"sy\":\"non.democ.ra.cy\",\"ps\":\"noun\",\"t\":[\"politics\",\"logic\",\"ofrench\"]},{\"w\":\"nondisaster\",\"d\":\"A situation or event that, despite concerns or predictions, does not result in serious harm, loss, or catastrophe.\",\"s\":\"Despite all the worry, the school play turned out to be a nondisaster and everyone cheered.\",\"p\":\"non-dih-ZAS-ter\",\"o\":\"French\",\"y\":8,\"bp\":35,\"sy\":\"nondis.as.ter\",\"ps\":\"noun\",\"t\":[\"ofrench\"]},{\"w\":\"nondomicile\",\"d\":\"The status of not having an official or legal place of permanent residence in a particular location or country.\",\"s\":\"The athlete was classified as a nondomicile resident for tax purposes because he lived abroad most of the year.\",\"p\":\"non-DOM-ih-syl\",\"o\":\"French\",\"y\":9,\"bp\":35,\"sy\":\"non.domi.cile\",\"ps\":\"noun\",\"t\":[\"law\",\"ofrench\"]},{\"w\":\"nondominant\",\"d\":\"Not being the most powerful, controlling, or frequently used; referring to the side, group, or factor that has less influence or strength.\",\"s\":\"She practiced writing with her nondominant hand to strengthen her coordination.\",\"p\":\"non-DOM-ih-nant\",\"o\":\"French\",\"y\":7,\"bp\":37,\"sy\":\"non.dom.i.nant\",\"ps\":\"adjective\",\"t\":[\"ofrench\"]},{\"w\":\"nonachievement\",\"d\":\"an act that does not achieve its intended goal\",\"s\":\"The team felt discouraged after another nonachievement in their efforts to break the record.\",\"p\":\"non-uh-CHEEV-munt\",\"o\":\"French\",\"y\":9,\"bp\":24,\"sy\":\"nonachieve.ment\",\"ps\":\"noun\",\"t\":[\"sports\",\"ofrench\"]},{\"w\":\"nonacquaintance\",\"d\":\"The state of having no prior knowledge of or familiarity with a person, place, or subject.\",\"s\":\"His nonacquaintance with the new student made the first day awkward for both of them.\",\"p\":\"non-uh-KWAYN-tuns\",\"o\":\"French\",\"y\":9,\"bp\":27,\"sy\":\"nonac.quain.tance\",\"ps\":\"noun\",\"t\":[\"logic\",\"ofrench\"]},{\"w\":\"nonagreement\",\"d\":\"The absence of a mutual agreement or understanding between two or more parties; a failure to reach a consensus.\",\"s\":\"The nonagreement between the two teams led to the tournament being postponed.\",\"p\":\"non-uh-GREE-munt\",\"o\":\"French\",\"y\":8,\"bp\":36,\"sy\":\"nona.gree.ment\",\"ps\":\"noun\",\"t\":[\"ofrench\"]},{\"w\":\"nonaid\",\"d\":\"The absence or withholding of assistance, support, or aid to a person, group, or cause.\",\"s\":\"The organization criticized the government's nonaid policy toward flood victims.\",\"p\":\"NON-ayd\",\"o\":\"French\",\"y\":8,\"bp\":18,\"sy\":\"non.aid\",\"ps\":\"noun\",\"t\":[\"ofrench\"]},{\"w\":\"nonalien\",\"d\":\"A person who is not a foreigner; someone who is a native citizen or resident rather than a foreign national.\",\"s\":\"The lawyer confirmed that the resident was a nonalien and had full citizenship rights.\",\"p\":\"non-AY-lee-un\",\"o\":\"French\",\"y\":8,\"bp\":19,\"sy\":\"non.alien\",\"ps\":\"noun\",\"t\":[\"politics\",\"character\",\"ofrench\"]},{\"w\":\"nonalienation\",\"d\":\"The condition or state in which a person is not estranged, isolated, or separated from their community, rights, or property.\",\"s\":\"The policy of nonalienation ensured that community members always felt included.\",\"p\":\"non-ay-lee-uh-NAY-shun\",\"o\":\"French\",\"y\":9,\"bp\":37,\"sy\":\"non.alien.ation\",\"ps\":\"noun\",\"t\":[\"ofrench\"]},{\"w\":\"nonallowable\",\"d\":\"Not permitted, accepted, or sanctioned under a given set of rules, regulations, or guidelines.\",\"s\":\"The referee declared the disputed goal nonallowable after reviewing the footage.\",\"p\":\"non-uh-LOW-uh-bul\",\"o\":\"French\",\"y\":9,\"bp\":38,\"sy\":\"non.al.low.able\",\"ps\":\"adjective\",\"t\":[\"ofrench\"]},{\"w\":\"nonalloy\",\"d\":\"Describing a metal or material that is pure and has not been combined or mixed with any other metals or elements to form an alloy.\",\"s\":\"The manufacturer used nonalloy steel because it was easier to weld.\",\"p\":\"non-AL-oy\",\"o\":\"French\",\"y\":9,\"bp\":21,\"sy\":\"non.al.loy\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"ofrench\"]},{\"w\":\"nonancestral\",\"d\":\"Not relating to or inherited from one's ancestors; having no connection to ancestral origin or lineage.\",\"s\":\"The family moved to a nonancestral land, far from their original homeland.\",\"p\":\"non-an-SES-trul\",\"o\":\"French\",\"y\":8,\"bp\":35,\"sy\":\"nonances.tral\",\"ps\":\"adjective\",\"t\":[\"kinship\",\"ofrench\"]},{\"w\":\"nonangelic\",\"d\":\"Not having the qualities of an angel; lacking goodness, purity, or a heavenly nature.\",\"s\":\"The mischievous puppy's behavior was decidedly nonangelic during the holiday gathering.\",\"p\":\"non-an-JEL-ik\",\"o\":\"French\",\"y\":8,\"bp\":29,\"sy\":\"nonan.gel.ic\",\"ps\":\"adjective\",\"t\":[\"ofrench\"]},{\"w\":\"nonarable\",\"d\":\"Describing land that is not suitable or capable of being used for farming or growing crops.\",\"s\":\"The rocky hillside was nonarable, so the farmers could not plant crops there.\",\"p\":\"non-AIR-uh-bul\",\"o\":\"French\",\"y\":9,\"bp\":25,\"ps\":\"adjective\",\"t\":[\"farming\",\"ofrench\"]},{\"w\":\"nonasbestos\",\"d\":\"Describing a material or product that contains no asbestos fibers, often used to indicate a safer, asbestos-free alternative.\",\"s\":\"The new building materials were certified nonasbestos, making the renovation safer.\",\"p\":\"non-az-BES-tus\",\"o\":\"French\",\"y\":8,\"bp\":34,\"sy\":\"nonas.bestos\",\"ps\":\"adjective\",\"t\":[\"ofrench\"]},{\"w\":\"nonassignment\",\"d\":\"The act or condition of not assigning, transferring, or delegating a task, right, or property to another party.\",\"s\":\"The teacher's nonassignment of homework on Fridays made students cheer every week.\",\"p\":\"non-uh-SYN-munt\",\"o\":\"French\",\"y\":9,\"bp\":37,\"sy\":\"nonas.sign.ment\",\"ps\":\"noun\",\"t\":[\"ofrench\"]},{\"w\":\"nonattentive\",\"d\":\"Not paying close attention or being alert; lacking the quality of attentiveness or focus.\",\"s\":\"The nonattentive student missed the instructions and had to ask a classmate for help.\",\"p\":\"non-uh-TEN-tiv\",\"o\":\"French\",\"y\":9,\"bp\":36,\"sy\":\"nonat.ten.tive\",\"ps\":\"adjective\",\"t\":[\"ofrench\"]},{\"w\":\"noncard\",\"d\":\"Describing a system, process, or identification method that does not require or involve the use of a physical card.\",\"s\":\"The library offered a noncard checkout option for guests visiting for the day.\",\"p\":\"NON-kard\",\"o\":\"French\",\"y\":8,\"bp\":19,\"sy\":\"non.card\",\"ps\":\"adjective\",\"t\":[\"ofrench\"]},{\"w\":\"nonchess\",\"d\":\"Referring to games, activities, or competitions that are not the game of chess; anything outside the realm of chess.\",\"s\":\"The club welcomed nonchess players who just wanted to enjoy board games.\",\"p\":\"NON-ches\",\"o\":\"French\",\"y\":9,\"bp\":18,\"ps\":\"adjective\",\"t\":[\"sports\",\"ofrench\"]},{\"w\":\"nonclosure\",\"d\":\"The absence of a final conclusion, resolution, or formal closing of a matter, process, or discussion.\",\"s\":\"The nonclosure of the factory meant hundreds of workers kept their jobs.\",\"p\":\"non-KLOH-zhur\",\"o\":\"French\",\"y\":9,\"bp\":29,\"sy\":\"non.clo.sure\",\"ps\":\"noun\",\"t\":[\"logic\",\"ofrench\"]},{\"w\":\"noncolleague\",\"d\":\"A person who is not a fellow worker, associate, or professional colleague; someone outside one's professional circle.\",\"s\":\"He was a noncolleague at the conference, attending as an outside observer.\",\"p\":\"non-KOL-eeg\",\"o\":\"French\",\"y\":9,\"bp\":36,\"sy\":\"non.col.league\",\"ps\":\"noun\",\"t\":[\"character\",\"numbers\",\"ofrench\"]},{\"w\":\"noncollege\",\"d\":\"Not related to or requiring a college education; describing a path, career, or program that does not involve attending college.\",\"s\":\"The program offered noncollege training paths for students interested in skilled trades.\",\"p\":\"non-KOL-ij\",\"o\":\"French\",\"y\":9,\"bp\":29,\"sy\":\"non.col.lege\",\"ps\":\"adjective\",\"t\":[\"ofrench\"]},{\"w\":\"noncommunication\",\"d\":\"The failure or absence of communication between individuals or groups; a state in which information or messages are not exchanged.\",\"s\":\"The team's noncommunication led to a misunderstanding that delayed the project.\",\"p\":\"non-kuh-myoo-nih-KAY-shun\",\"o\":\"French\",\"y\":9,\"bp\":32,\"sy\":\"non.com.mu.ni.ca.tion\",\"ps\":\"noun\",\"t\":[\"ofrench\"]},{\"w\":\"noncommunity\",\"d\":\"A group or setting that lacks the shared values, cooperation, and social bonds that define a true community.\",\"s\":\"The isolated settlement existed as a noncommunity, with residents rarely interacting.\",\"p\":\"non-kuh-MYOO-nih-tee\",\"o\":\"French\",\"y\":9,\"bp\":39,\"sy\":\"non.com.mu.ni.ty\",\"ps\":\"noun\",\"t\":[\"ofrench\"]},{\"w\":\"noncomposite\",\"d\":\"Not made up of multiple distinct parts or materials; describing something that is a single, uniform substance rather than a blend or combination.\",\"s\":\"The math teacher explained that a prime number is noncomposite because it has no factors.\",\"p\":\"non-KOM-puh-zit\",\"o\":\"French\",\"y\":9,\"bp\":38,\"sy\":\"non.com.pos.ite\",\"ps\":\"adjective\",\"t\":[\"ofrench\"]},{\"w\":\"nonconnection\",\"d\":\"The absence of a link, relationship, or association between two or more things, people, or ideas.\",\"s\":\"The detective noted the nonconnection between the two suspects, ruling out a conspiracy.\",\"p\":\"non-kuh-NEK-shun\",\"o\":\"French\",\"y\":9,\"bp\":38,\"sy\":\"non.con.nec.tion\",\"ps\":\"noun\",\"t\":[\"ofrench\"]},{\"w\":\"noncontent\",\"d\":\"Lacking meaningful subject matter or substance; describing material that has no significant informational or creative value.\",\"s\":\"The editor flagged the noncontent pages, such as blank filler sections, for removal.\",\"p\":\"non-KON-tent\",\"o\":\"French\",\"y\":8,\"bp\":29,\"sy\":\"non.con.tent\",\"ps\":\"adjective\",\"t\":[\"ofrench\"]},{\"w\":\"noncouple\",\"d\":\"Two individuals who are not in a romantic partnership or paired relationship with each other.\",\"s\":\"At the party, the noncouple arrived separately and insisted they were just friends.\",\"p\":\"non-KUP-ul\",\"o\":\"French\",\"y\":9,\"bp\":28,\"sy\":\"non.cou.ple\",\"ps\":\"noun\",\"t\":[\"ancient\",\"ofrench\"]},{\"w\":\"noncourageous\",\"d\":\"Lacking bravery or courage; not willing to face danger, difficulty, or challenges with boldness.\",\"s\":\"His noncourageous response to the challenge disappointed his teammates.\",\"p\":\"non-kuh-RAY-jus\",\"o\":\"French\",\"y\":9,\"bp\":38,\"sy\":\"non.cour.a.geous\",\"ps\":\"adjective\",\"t\":[\"ofrench\"]},{\"w\":\"noncourt\",\"d\":\"Not pertaining to or taking place within a court of law; describing a resolution or process that occurs outside legal proceedings.\",\"s\":\"The dispute was settled through a noncourt mediation process.\",\"p\":\"NON-kort\",\"o\":\"French\",\"y\":9,\"bp\":19,\"sy\":\"non.court\",\"ps\":\"adjective\",\"t\":[\"law\",\"ofrench\"]},{\"w\":\"noncousin\",\"d\":\"A person who is not related as a cousin; someone outside one's family who has no cousinly blood relationship.\",\"s\":\"She introduced her best friend as a noncousin who felt like family anyway.\",\"p\":\"non-KUZ-in\",\"o\":\"French\",\"y\":9,\"bp\":26,\"sy\":\"non.cousin\",\"ps\":\"noun\",\"t\":[\"body\",\"character\",\"kinship\",\"ofrench\"]},{\"w\":\"nondebate\",\"d\":\"A situation or issue that requires no formal argument or discussion because it is already settled or obvious.\",\"s\":\"The principal called it a nondebate topic since everyone agreed on the new rule.\",\"p\":\"non-dih-BAYT\",\"o\":\"French\",\"y\":9,\"bp\":28,\"sy\":\"non.de.bate\",\"ps\":\"noun\",\"t\":[\"logic\",\"ofrench\"]},{\"w\":\"nondecrease\",\"d\":\"The state of not diminishing or getting smaller; a condition in which a quantity remains the same or grows but does not decline.\",\"s\":\"The scientists confirmed a nondecrease in temperature over the past decade.\",\"p\":\"non-dih-KREES\",\"o\":\"French\",\"y\":9,\"bp\":35,\"sy\":\"non.de.crease\",\"ps\":\"noun\",\"t\":[\"ofrench\"]},{\"w\":\"nondegree\",\"d\":\"Describing a course of study, program, or certificate that does not lead to a formal academic degree.\",\"s\":\"She enrolled in a nondegree program to learn coding without committing to a full diploma.\",\"p\":\"non-dih-GREE\",\"o\":\"French\",\"y\":9,\"bp\":28,\"sy\":\"non.de.gree\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"ofrench\"]},{\"w\":\"nondemand\",\"d\":\"The absence of an urgent request, requirement, or claim; a situation in which nothing is being actively demanded.\",\"s\":\"The landlord's nondemand for rent during the crisis gave tenants a much-needed break.\",\"p\":\"non-dih-MAND\",\"o\":\"French\",\"y\":8,\"bp\":28,\"sy\":\"non.de.mand\",\"ps\":\"noun\",\"t\":[\"ofrench\"]},{\"w\":\"nondesign\",\"d\":\"The absence of intentional planning, structure, or artistic arrangement; something that came about without deliberate design.\",\"s\":\"The chaotic arrangement of furniture was pure nondesign, with no plan or purpose behind it.\",\"p\":\"non-dih-ZYN\",\"o\":\"French\",\"y\":8,\"bp\":28,\"sy\":\"non.de.sign\",\"ps\":\"noun\",\"t\":[\"painting\",\"ofrench\"]},{\"w\":\"nondiamond\",\"d\":\"Describing something that is not a diamond or does not have the properties of a diamond, such as hardness or crystal structure.\",\"s\":\"The jeweler explained that cubic zirconia is a nondiamond gemstone that looks similar but costs far less.\",\"p\":\"non-DY-uh-mund\",\"o\":\"French\",\"y\":8,\"bp\":30,\"sy\":\"non.di.a.mond\",\"ps\":\"adjective\",\"t\":[\"minerals\",\"ofrench\"]},{\"w\":\"nondiet\",\"d\":\"Not relating to or involving a special diet; describing foods, drinks, or behaviors that are not part of a restricted eating plan.\",\"s\":\"She chose a nondiet approach to eating, focusing on balance rather than strict calorie counting.\",\"p\":\"non-DY-et\",\"o\":\"French\",\"y\":8,\"bp\":19,\"sy\":\"nondi.et\",\"ps\":\"adjective\",\"t\":[\"ofrench\"]},{\"w\":\"nondiminutive\",\"d\":\"Not small or reduced in size; describing something that is not a diminutive form or does not convey smallness.\",\"s\":\"The professor noted that the suffix '-ness' is nondiminutive, meaning it doesn't make a word sound smaller or lesser.\",\"p\":\"non-dih-MIN-yuh-tiv\",\"o\":\"French\",\"y\":9,\"bp\":35,\"sy\":\"nondiminu.tive\",\"ps\":\"adjective\",\"t\":[\"ofrench\"]},{\"w\":\"nondivorce\",\"d\":\"The state or condition of not being divorced; referring to a situation in which a marriage has not ended in divorce.\",\"s\":\"The counselor recorded the outcome as a nondivorce after the couple decided to stay together.\",\"p\":\"non-dih-VORS\",\"o\":\"French\",\"y\":9,\"bp\":29,\"sy\":\"non.di.vorce\",\"ps\":\"noun\",\"t\":[\"kinship\",\"ofrench\"]},{\"w\":\"nonbarbecue\",\"d\":\"Describing food, events, or cooking methods that do not involve barbecuing or grilling over open flame or smoke; the absence of traditional barbecue preparation.\",\"s\":\"The vegetarian restaurant proudly advertised its nonbarbecue menu, featuring grilled vegetables and grain bowls.\",\"p\":\"non-BAR-beh-kyoo\",\"o\":\"Spanish\",\"y\":9,\"bp\":33,\"sy\":\"non.bar.be.cue\",\"ps\":\"adjective\",\"t\":[\"culinary\",\"festivals\",\"oiberian\"]},{\"w\":\"noncannibal\",\"d\":\"describing a person or animal that does not eat others of its own kind\",\"s\":\"The scientist was pleased to find the new fish was noncannibal and left the smaller fry alone.\",\"p\":\"non-KAN-ih-bul\",\"o\":\"Spanish\",\"y\":9,\"bp\":33,\"sy\":\"non.can.ni.bal\",\"ps\":\"noun\",\"t\":[\"animals\",\"oiberian\"]},{\"w\":\"nonchocolate\",\"d\":\"Describing a food, beverage, or product that does not contain chocolate or cocoa in any form, often used to label confections or desserts made without cocoa-based ingredients.\",\"s\":\"The bakery offered a nonchocolate dessert section for customers who preferred vanilla or fruit-based sweets.\",\"p\":\"non-CHOK-uh-lit\",\"o\":\"Spanish\",\"y\":9,\"bp\":32,\"sy\":\"non.choco.late\",\"ps\":\"adjective\",\"t\":[\"culinary\",\"dishes\",\"oiberian\"]},{\"w\":\"nonbanana\",\"d\":\"Something that is not a banana; used to distinguish a fruit or object from being classified as a banana.\",\"s\":\"The store labeled the yellow plantains as nonbanana to avoid confusing shoppers.\",\"p\":\"non-buh-NAN-uh\",\"o\":\"Wolof\",\"y\":9,\"bp\":22,\"sy\":\"non.banana\",\"ps\":\"adjective\",\"t\":[\"spices\",\"oworld\"]}]",h:"[]"};
